	["tid#ArtifactDes9"]="完成蓬莱地区全部主线任务后获得",
	["tid#ArtifactEvent1"]="年来鞍马困尘埃，赖有青山豁我怀。日暮北风吹雨去，数峰清瘦出云来。",
	["tid#ArtifactEvent2"]="自在悬空无二寺，公输神木赖撑持。释香儒道同庐享，争看千年信者痴。",
	["tid#ArtifactEvent3"]="万丈融峰插紫霄，路当穷处架仙桥。上观碧落星辰近，下视红尘世界遥。",
	["tid#ArtifactEvent4"]="岱宗夫如何，齐鲁青未了。造化钟神秀，阴阳割昏晓。荡胸生层云，决眦入归鸟。会当凌绝顶，一览众山小。",
	["tid#ArtifactEvent5"]="云起太华山，云山互明灭。东峰始含景，了了见松雪",
	["tid#ArtifactEvent6"]="玉露篙莱翠色添，遥看海角化桑田。潮生明月珠盘落，浪起汪洋白鹭翩。",
	["tid#ArtifactEvent7"]="渤海三千里，泥沙几万重。似舟飘不定，如梗泛何从。仙客终难托，良工岂易逢。徒怀万乘器，谁为一先容。",
	["tid#ArtifactEvent8"]="白浪茫茫与海连，平沙浩浩四无边。暮去朝来淘不住，遂令东海变桑田",
	["tid#ArtifactEvent9"]="风从北海起，至此南海上。问风来何事，去复欲何向。谁遣汝而号，谁应汝而唱。\n汝於何时息，汝作无乃妄。风初无一言，试以问云将。",
