	["tid#ArtifactSkillDes101"]="战斗中，装备该神兵的侠客在释放绝技时，会获得一个持续5秒的护盾,至多抵消120%攻击力的伤害",
	["tid#ArtifactSkillDes103"]="战斗中，装备该神兵的侠客在释放绝技时，会获得一个持续5秒的护盾,至多抵消170%攻击力的伤害",
	["tid#ArtifactSkillDes106"]="战斗中，装备该神兵的侠客在释放绝技时，会获得一个持续5秒的护盾,至多抵消220%攻击力的伤害，并提供3秒的控制免疫效果",
	["tid#ArtifactSkillDes201"]="战斗中，装备该神兵的侠客在暴击时会获得15%攻击速度加成,持续3秒",
	["tid#ArtifactSkillDes203"]="战斗中，装备该神兵的侠客在暴击时会获得20%攻击速度加成,持续3秒",
	["tid#ArtifactSkillDes206"]="战斗中，装备该神兵的侠客在暴击时会获得20%攻击速度加成,持续3秒，且暴击伤害额外增加30%",
	["tid#ArtifactSkillDes301"]="战斗中，装备该神兵的侠客每秒获得10点内力",
