	["tid#ArtifactSkillDes401"]="战斗中，装备该神兵的侠客受到生命回复效果+10%",
	["tid#ArtifactSkillDes403"]="战斗中，装备该神兵的侠客受到生命回复效果+15%",
	["tid#ArtifactSkillDes406"]="战斗中，装备该神兵的侠客受到生命回复效果+15%，且生命值越低获得的生命效果越高,最高至+30%",
	["tid#ArtifactSkillDes501"]="战斗中，装备该神兵的侠客每3秒增加1%攻击力",
	["tid#ArtifactSkillDes503"]="战斗中，装备该神兵的侠客每3秒增加1%攻击力和2命中",
	["tid#ArtifactSkillDes506"]="战斗中，装备该神兵的侠客每3秒增加1.5%攻击力和3命中",
