	["tid#ArtifactSkillDes603"]="战斗中，装备该神兵的侠客附近没有敌方单位时,增加7%的攻击力",
	["tid#ArtifactSkillDes606"]="战斗中，装备该神兵的侠客附近没有敌方单位时,增加7%的攻击力，且每隔15秒,持有者会击退附近敌人",
	["tid#ArtifactSkillDes701"]="战斗开始后的30秒内,装备该神兵的侠客每秒回复生命上限1%的生命",
	["tid#ArtifactSkillDes703"]="战斗开始后的45秒内,装备该神兵的侠客每秒回复生命上限1%的生命",
	["tid#ArtifactSkillDes706"]="战斗开始后的45秒内,装备该神兵的侠客每秒回复生命上限1.5%的生命",
	["tid#ArtifactSkillDes801"]="战斗中，装备该神兵的侠客首次释放的绝技伤害提升20%，并永久提升自身10点急速和8点生命吸取",
	["tid#ArtifactSkillDes803"]="战斗中，装备该神兵的侠客首次释放的绝技伤害提升30%，并永久提升自身10点急速和8点生命吸取",
	["tid#ArtifactSkillDes806"]="战斗中，装备该神兵的侠客首次释放的绝技伤害提升30%，并永久提升自身15点急速和12点生命吸取",
	["tid#ArtifactSkillDes901"]="战斗开始时，装备该神兵的侠客立即获得200点内力，第一次释放绝技后，后续5秒每秒失去40点内力",
	["tid#ArtifactSkillDes903"]="战斗开始时，装备该神兵的侠客立即获得250点内力，第一次释放绝技后，后续5秒每秒失去40点内力",
	["tid#ArtifactSkillDes906"]="战斗开始时，装备该神兵的侠客立即获得300点内力，第一次释放绝技后，后续5秒每秒失去40点内力",
	["tid#ArtifactStory1"]="年来鞍马困尘埃，赖有青山豁我怀。日暮北风吹雨去，数峰清瘦出云来。",
	["tid#ArtifactStory2"]="自在悬空无二寺，公输神木赖撑持。释香儒道同庐享，争看千年信者痴。",
	["tid#ArtifactStory3"]="万丈融峰插紫霄，路当穷处架仙桥。上观碧落星辰近，下视红尘世界遥。",
	["tid#ArtifactStory4"]="岱宗夫如何，齐鲁青未了。造化钟神秀，阴阳割昏晓。荡胸生层云，决眦入归鸟。会当凌绝顶，一览众山小。",
	["tid#ArtifactStory5"]="云起太华山，云山互明灭。东峰始含景，了了见松雪",
	["tid#ArtifactStory6"]="玉露篙莱翠色添，遥看海角化桑田。潮生明月珠盘落，浪起汪洋白鹭翩。",
	["tid#ArtifactStory7"]="渤海三千里，泥沙几万重。似舟飘不定，如梗泛何从。仙客终难托，良工岂易逢。徒怀万乘器，谁为一先容。",
	["tid#ArtifactStory8"]="白浪茫茫与海连，平沙浩浩四无边。暮去朝来淘不住，遂令东海变桑田",
	["tid#ArtifactStory9"]="风从北海起，至此南海上。问风来何事，去复欲何向。谁遣汝而号，谁应汝而唱。\n汝於何时息，汝作无乃妄。风初无一言，试以问云将。",
