	["tid#DeployDes1"]="江湖上流传最广的基础阵法，虽然没有什么特殊的功效，但胜在简单好用。",
	["tid#DeployDes101"]="数百年前，江湖中的一位高人观北斗七星时悟出的阵法，按照此阵法进行战斗时，可借用北斗七星的威能，使全队攻击提升5%，位于阵眼的侠客更是能发挥出双倍的效果。",
	["tid#DeployDes102"]="数百年前，江湖中的一位高人观中央钧天星图时悟出的阵法，按照此阵法进行战斗时，可借用中央钧天的威能，使全队最大生命值提升10%，位于阵眼的侠客更是能发挥出双倍的效果。",
	["tid#DeployDes103"]="数百年前，江湖中的一位高人观西方白虎七宿时悟出的阵法，按照此阵法进行战斗时，可借用白虎七宿的威能，使全队外攻提升12%，位于阵眼的侠客更是能发挥出双倍的效果。",
	["tid#DeployDes104"]="数百年前，江湖中的一位高人观北方玄武七宿时悟出的阵法，按照此阵法进行战斗时，可借用玄武七宿的威能，使全队外防提升15%，位于阵眼的侠客更是能发挥出双倍的效果。",
	["tid#DeployDes105"]="数百年前，江湖中的一位高人观南方朱雀七宿时悟出的阵法，按照此阵法进行战斗时，可借用朱雀七宿的威能，使全队内攻提升12%，位于阵眼的侠客更是能发挥出双倍的效果。",
	["tid#DeployDes106"]="数百年前，江湖中的一位高人观东方苍龙七宿时悟出的阵法，按照此阵法进行战斗时，可借用苍龙七宿的威能，使全队内防提升15%，位于阵眼的侠客更是能发挥出双倍的效果。",
