	["tid#EquipDes100101"]="<size=22>适用门派：<color=#AF6C40>梁山泊、天龙门、玄甲军、金钱帮、名剑山庄、锦衣卫、金山派、飞雪刀、一丈青、神剑门、开封府</color></size>\n\n相传为楼兰古国的镇国之宝，刀柄以五彩琉璃雕刻而成，刀身寒气摄人，表面乌黑，唯有在月光照射下会闪烁银光。",
	["tid#EquipDes100102"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes100103"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes100104"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes100105"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes100201"]="<size=22>适用门派：<color=#AF6C40>崆峒派、天山派、峨眉派、桃花岛、华山派、纯阳宫、灵鹫宫、陷空岛、月寒宫</color></size>\n\n始皇帝曾经的佩剑，相传太阿乃威道之剑，持有者的内心越是坚定不屈，其剑意越是威猛，剑气激射可令风云变色。",
	["tid#EquipDes100202"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes100203"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes100204"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes100205"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes100301"]="<size=22>适用门派：<color=#AF6C40>花间派、天师门、逍遥派、红夷军、嵩山派、武当派、苍火门、百花派、及时雨、滅境、锻瑛谷</color></size>\n\n少林方丈主持水陆法会时，掷一莲子入水，顷刻间白莲盛开。丹青圣手将此场面绘于一玉扇之上，后被花间派所得，每每挥舞，便有佛音低唱。",
	["tid#EquipDes100302"]="算天算地，算尽天下事，观日观月，观览万人心。",
	["tid#EquipDes100303"]="算天算地，算尽天下事，观日观月，观览万人心。",
	["tid#EquipDes100304"]="算天算地，算尽天下事，观日观月，观览万人心。",
	["tid#EquipDes100305"]="算天算地，算尽天下事，观日观月，观览万人心。",
	["tid#EquipDes10101"]="侠隐村老镖师的砍刀，看着破烂却又用不坏，难道是个宝贝？",
	["tid#EquipDes10102"]="用来固定发型的抹额，粗麻布制成。",
	["tid#EquipDes10103"]="码头搬运工常穿的麻布衣服，坚固耐用。",
	["tid#EquipDes10104"]="款式简单的布靴，比穿草鞋强一些。",
	["tid#EquipDes10105"]="麻布制成的长裤，透气易干。",
	["tid#EquipDes101101"]="<size=22>适用门派：<color=#AF6C40>墨家、少林、天下会、南宫派、形意门、霹雳堂、九天、麒麟甲、蒙武堂</color></size>\n\n形意门门主所持拳甲，由百炼精钢铸造，势大力沉，出拳时其声似怒雷滚滚，犹如神人擂鼓于苍天之上。",
	["tid#EquipDes101201"]="<size=22>适用门派：<color=#AF6C40>六扇门、唐门、万兽庄、绝张门、天鹰教、启灵派、清风寨、羽人非獍、太学宫</color></size>\n\n墨家名匠打造的轻弩，弩身嵌有火石，一经上弦可连发十数次，射程远威力大，连射时箭矢附着火焰如天降流星，因威力过大被藏于地宫当中。",
	["tid#EquipDes101301"]="<size=22>适用门派：<color=#AF6C40>五毒教、昆仑派、太极门、合欢派、鬼谷派、邪极坊、飞龙堡、罗袖阁、大理寺、平虏伯</color></size>\n\n曾为杨贵妃钟爱的琵琶，贵妃殁，琵琶夜间会不弹自响，听者将无故大喜大悲，宫中视之为不祥，后锁于大雁塔中。",
	["tid#EquipDes10201"]="王二狗的铁剑，剑身斑驳有许多缺口，又名狗齿剑。",
	["tid#EquipDes10202"]="粗布头巾，戴在头上一点防御作用都没有，带了个寂寞。",
	["tid#EquipDes10203"]="轻快的短衫，适合练功时穿戴。",
	["tid#EquipDes10204"]="练武之人常规穿着，鞋底厚实。",
	["tid#EquipDes10205"]="练功时常常穿着的短裤，轻便耐磨。",
	["tid#EquipDes102101"]="<size=22>适用门派：<color=#AF6C40>古墓、金刚教、天策府、海沙派、丐帮、霸王枪、天墉城、飞将军、汉寿亭侯、绛衣军</color></size>\n\n枪头小巧细长，侧有尖钩，攻伐时十分灵动，一招出手犹如瑞雪飞舞、梨花纷飘，锋刃所过无人可挡。",
	["tid#EquipDes102201"]="<size=22>适用门派：<color=#AF6C40>衡山派、绝情谷、探花门、明教、八卦门、蜀山、独孤一门、豹子头、龙胆枪、御竞堂</color></size>\n\n长三寸，通体银白，形似发簪，器身不染尘垢。由昆仑邪兵王铸造，原铸有四对，如今江湖只余一对。",
	["tid#EquipDes102301"]="<size=22>适用门派：<color=#AF6C40>九黎、恒山派、慈航教、药王谷、落英轩、神水宫、密宗、娲皇神殿、凤仪亭、神都上阳宫、太极内家拳、天香阁、神·九黎</color></size>\n\n江湖有一妖人，持猩红宝刀，百无禁忌为祸四方。传言其梦中与达摩相见，被达摩点化，熔宝刀铸成禅杖，刻十戒于杖上，余生只行善事。",
	["tid#EquipDes10301"]="说书先生常备的纸扇，容易损坏，多用来扇风纳凉。",
	["tid#EquipDes10302"]="简易的竹簪，用以辅助整理头发。",
	["tid#EquipDes10303"]="修长的布袍，多为灰色。",
	["tid#EquipDes10304"]="简易的布鞋，容易沾染泥土。",
	["tid#EquipDes10305"]="单薄但干净的纯棉裤子，穿起来有些显胖，但是比没有强。",
	["tid#EquipDes110101"]="<size=22>适用门派：<color=#AF6C40>梁山泊、天龙门、玄甲军、金钱帮、名剑山庄、锦衣卫、金山派、飞雪刀、一丈青、神剑门、开封府</color></size>\n\n相传为楼兰古国的镇国之宝，刀柄以五彩琉璃雕刻而成，刀身寒气摄人，表面乌黑，唯有在月光照射下会闪烁银光。",
	["tid#EquipDes110102"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes110103"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes110104"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes110105"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes110201"]="<size=22>适用门派：<color=#AF6C40>崆峒派、天山派、峨眉派、桃花岛、华山派、纯阳宫、灵鹫宫、陷空岛、月寒宫</color></size>\n\n始皇帝曾经的佩剑，相传太阿乃威道之剑，持有者的内心越是坚定不屈，其剑意越是威猛，剑气激射可令风云变色。",
	["tid#EquipDes110202"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes110203"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes110204"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes110205"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes110301"]="<size=22>适用门派：<color=#AF6C40>花间派、天师门、逍遥派、红夷军、嵩山派、武当派、苍火门、百花派、及时雨、滅境、锻瑛谷</color></size>\n\n少林方丈主持水陆法会时，掷一莲子入水，顷刻间白莲盛开。丹青圣手将此场面绘于一玉扇之上，后被花间派所得，每每挥舞，便有佛音低唱。",
	["tid#EquipDes110302"]="算天算地，算尽天下事，观日观月，观览万人心。",
	["tid#EquipDes110303"]="算天算地，算尽天下事，观日观月，观览万人心。",
	["tid#EquipDes110304"]="算天算地，算尽天下事，观日观月，观览万人心。",
	["tid#EquipDes110305"]="算天算地，算尽天下事，观日观月，观览万人心。",
	["tid#EquipDes111101"]="<size=22>适用门派：<color=#AF6C40>墨家、少林、天下会、南宫派、形意门、霹雳堂、九天、麒麟甲、蒙武堂</color></size>\n\n形意门门主所持拳甲，由百炼精钢铸造，势大力沉，出拳时其声似怒雷滚滚，犹如神人擂鼓于苍天之上。",
	["tid#EquipDes111201"]="<size=22>适用门派：<color=#AF6C40>六扇门、唐门、万兽庄、绝张门、天鹰教、启灵派、清风寨、羽人非獍、太学宫</color></size>\n\n墨家名匠打造的轻弩，弩身嵌有火石，一经上弦可连发十数次，射程远威力大，连射时箭矢附着火焰如天降流星，因威力过大被藏于地宫当中。",
	["tid#EquipDes111301"]="<size=22>适用门派：<color=#AF6C40>五毒教、昆仑派、太极门、合欢派、鬼谷派、邪极坊、飞龙堡、罗袖阁、大理寺、平虏伯</color></size>\n\n曾为杨贵妃钟爱的琵琶，贵妃殁，琵琶夜间会不弹自响，听者将无故大喜大悲，宫中视之为不祥，后锁于大雁塔中。",
	["tid#EquipDes112101"]="<size=22>适用门派：<color=#AF6C40>古墓、金刚教、天策府、海沙派、丐帮、霸王枪、天墉城、飞将军、汉寿亭侯、绛衣军</color></size>\n\n枪头小巧细长，侧有尖钩，攻伐时十分灵动，一招出手犹如瑞雪飞舞、梨花纷飘，锋刃所过无人可挡。",
	["tid#EquipDes112201"]="<size=22>适用门派：<color=#AF6C40>衡山派、绝情谷、探花门、明教、八卦门、蜀山、独孤一门、豹子头、龙胆枪、御竞堂</color></size>\n\n长三寸，通体银白，形似发簪，器身不染尘垢。由昆仑邪兵王铸造，原铸有四对，如今江湖只余一对。",
	["tid#EquipDes112301"]="<size=22>适用门派：<color=#AF6C40>九黎、恒山派、慈航教、药王谷、落英轩、神水宫、密宗、娲皇神殿、凤仪亭、神都上阳宫、太极内家拳、天香阁、神·九黎</color></size>\n\n江湖有一妖人，持猩红宝刀，百无禁忌为祸四方。传言其梦中与达摩相见，被达摩点化，熔宝刀铸成禅杖，刻十戒于杖上，余生只行善事。",
	["tid#EquipDes120101"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n长四尺，重百斤，锋利至极，无坚不摧。先贤曾持此刀，保家卫国力竭而亡，故后人持此刀者，可号令群雄。有道是：武林之峰，宝刀屠龙，天下英雄，莫敢不从！",
	["tid#EquipDes120102"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n能工巧匠以精金铸造，以神兵利器劈砍也难伤其分毫，被尊为古往今来第一盔，故名为八荒六合。",
	["tid#EquipDes120103"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n古代传承至今的宝甲，甲片形似龙鳞，分则轻盈灵动，合则坚不可摧，遇风隐隐有龙吟声传出。",
	["tid#EquipDes120104"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n西域降王的贡品，由玄铁打造，常人穿上寸步难动。其本想看中原笑话，未想一猛将腿力过人，穿此靴有天崩地裂之威，降王遂不敢有二心。",
	["tid#EquipDes120105"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n前朝四皇子率军抗击外敌，铸定国破虏玄甲和暴雨梨花枪，战后长枪赠予边关守将，玄甲藏于宫中。如今部分玄甲已遗失，只余一具腿铠。",
	["tid#EquipDes120201"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n古有霸王铸剑，搜集天下神兵利器，销数十把以炼神兵精金，聘请工匠铸长剑一柄，剑成之日，有地光冲天，因剑带云纹，暗放蓝光，故名倚天。",
	["tid#EquipDes120202"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n古有美玉和氏璧，后碎为四块，天子峰名士得其一，悉心打磨，又取天罗绸缎，缝制头冠，君子佩之，风度翩翩。",
	["tid#EquipDes120203"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n有奇兽名为飞廉，擅控风，行动神速。传言以飞廉皮制作皮甲，可有御风的功效，擅轻功者穿戴，可日行数百里。",
	["tid#EquipDes120204"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n蓬莱有宝靴，以蛟怪鳞片制成，鳞片质轻柔韧，寻常刀剑难以切割。靴身可避水，且有避毒虫的功效。",
	["tid#EquipDes120205"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n南溟之海著有鲛人，泣泪成珠，缫水成丝，织以为绡，是为鲛绡，裁剪此绡制成衣裤，轻盈无碍，能平步青云。",
	["tid#EquipDes120301"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n奇兵之首，曾为逍遥子佩戴，扇身以寒铁铸造，扇面镶有十二颗避火珠，持此扇者可不畏酷暑。",
	["tid#EquipDes120302"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n前朝传闻崆峒山有仙人羽化，曾云游九州观天下之势，而后留下衣冠与拂尘，乘鹤而归，虽传闻之言不可考证，拂尘衣物也已遗失，独留一顶宝冠。",
	["tid#EquipDes120303"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n前代大法师西行归来，曾带回天竺国王所赠九九八十一片精美琉璃，天朝大能工匠将其尽数镶嵌在大法师宝衣之上，使穿着者法相庄严，圣光熠熠。",
	["tid#EquipDes120304"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n龙虎山天师历代所传，由罕见的织云丝所制，穿之如无物缚脚，施展轻功如乘云而上，故称“踏天”，后为大盗空空儿所窥，致使流落江湖。",
	["tid#EquipDes120305"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n纯阳子曾为武皇开坛祭天，武皇亲自主持为纯阳子所制一身华贵道衣，其中下衣更是以金缕丝线贯穿期间，远观之下犹如神人降世。",
	["tid#EquipDes20101"]="厚重的生铁大刀，分量十足，利于砍砸。",
	["tid#EquipDes20102"]="乡镇武师的同款护额，有一定的防御作用。",
	["tid#EquipDes20103"]="乡镇武师钟爱的木甲，用硬木护住关键部位。",
	["tid#EquipDes20104"]="走南闯北的不二之选，坚固耐用的靴子。",
	["tid#EquipDes20105"]="厚实布料缝制的裤子，但不是太舒适。",
	["tid#EquipDes20201"]="生铁打造的利剑，但剑身过刚，容易折断。",
	["tid#EquipDes20202"]="主要是棉布编制而成，防御力一般。",
	["tid#EquipDes20203"]="猎户常见的装束，注重轻便型和保暖性。",
	["tid#EquipDes20204"]="质地非常轻巧舒适，而且轻便。",
	["tid#EquipDes20205"]="猎户们的基础装束，兼顾保暖和行动的便利性。",
	["tid#EquipDes20301"]="以铁打造其扇骨，展开时可格挡兵器，合拢时可用以击打。",
	["tid#EquipDes20302"]="质地轻柔的头冠，多为书生佩戴。",
	["tid#EquipDes20303"]="青色长衫，书生意气，一表人才。",
	["tid#EquipDes20304"]="质地轻柔的布履，助你平步青云。",
	["tid#EquipDes20305"]="搭配长衫穿着的下装，比较透风。",
	["tid#EquipDes30101"]="蓬莱铁匠铺出品的制式长刀，其刀身反复锻打数百次，故名百炼。",
	["tid#EquipDes30102"]="嵌有鱼鳞状甲片的头盔，有较好的防御作用。",
	["tid#EquipDes30103"]="精铁打造的细鳞铠，因甲片形状似鱼鳞而得名。",
	["tid#EquipDes30104"]="在步卒靴子的基础上，添加了额外的护甲片，有了更强的防御力。",
	["tid#EquipDes30105"]="精铁打造的胫甲，裆部有额外的护甲片进行防护。",
	["tid#EquipDes30201"]="剑身长三尺，以精铁打造，周身泛青光，其刃锋利无匹。",
	["tid#EquipDes30202"]="绘有飞云图案的头带，多见于浩气盟弟子佩戴。",
	["tid#EquipDes30203"]="合身的劲衣，绘有云纹，其肩、腹有精铁甲片防护。",
	["tid#EquipDes30204"]="绘有云纹的长靴，轻便合脚，方便施展轻功。",
	["tid#EquipDes30205"]="合身的皮裤，绘有云纹，方便施展腿功。",
	["tid#EquipDes30301"]="江南官场流行的扇子，扇骨镶嵌白玉，扇面为沧海图。",
	["tid#EquipDes30302"]="国子监学生佩戴的玉簪，民间多为仿制。",
	["tid#EquipDes30303"]="国子监学生穿戴的长袍，剪裁合身。",
	["tid#EquipDes30304"]="国子监学生穿戴的步履，绣有银色花纹。",
	["tid#EquipDes30305"]="国子监学生穿戴的长裤，腰部极为修身。",
	["tid#EquipDes40101"]="黑风寨大当家成名武器，两刀配重得当，可成连环之势。",
	["tid#EquipDes40102"]="精铁铸造的重盔，对额头有极强的保护作用。",
	["tid#EquipDes40103"]="朝廷赏赐游骑将军的重甲，身怀巨力者方可穿戴。",
	["tid#EquipDes40104"]="以皮革缝制的靴子，靴面上嵌着软甲，具备一定的防御力。",
	["tid#EquipDes40105"]="精铁铸造的胫甲，防御力极强，但会妨碍穿戴者移动。",
	["tid#EquipDes40201"]="产自龙泉山庄的宝剑，有吹毛刃断，斩金截玉的美名。",
	["tid#EquipDes40202"]="样式华丽的头带，额头镶有宝珠。",
	["tid#EquipDes40203"]="由软金打造的轻甲，有不俗的防御力。",
	["tid#EquipDes40204"]="穿此靴可日行百里，行路无痕，故有乘风的美名。",
	["tid#EquipDes40205"]="由软金打造的轻甲，对腿部有极好的保护作用，又不限制侠客活动。",
	["tid#EquipDes40301"]="相传为神水宫二宫主所持，扇动间可翻云覆雨。",
	["tid#EquipDes40302"]="镶嵌有青玉的头冠，样式庄重。",
	["tid#EquipDes40303"]="国子监学士的长衣，其衣领为青色，腰佩玉环。",
	["tid#EquipDes40304"]="青绿色绸缎缝制的长靴，穿者脚底生风。",
	["tid#EquipDes40305"]="青绿色绣银纹的长裤，花纹素雅大气。",
	["tid#EquipDes50101"]="刀身笔直刃薄背宽，刀背镶金，其势凶猛有开山之威。",
	["tid#EquipDes50102"]="精钢打造的头盔，镶金带玉，令人显得英武不凡。",
	["tid#EquipDes50103"]="内衬以冰蚕丝所制，周身甲片以钨钢打造，箭矢难以穿透。",
	["tid#EquipDes50104"]="以精钢打造的重靴，寻常人穿戴难以行走，若是习得千斤顶，下踏时有裂地之威。",
	["tid#EquipDes50105"]="用精钢铸造的裙甲，针对腰胯部位做了额外的防护。",
	["tid#EquipDes50201"]="纯阳宫名剑，由玄铁打造，剑身散发寒气，纯阳七子曾用此剑截断瀑布。",
	["tid#EquipDes50202"]="天下会影卫所配面甲，坚不可摧，形象可怖，令敌人不敢对视。",
	["tid#EquipDes50203"]="天下会影卫所配短衣，內衬为金丝软甲，有极强的防御力。",
	["tid#EquipDes50204"]="天下会影卫所配短靴，鞋底藏有毒刃，令人难以防备。",
	["tid#EquipDes50205"]="天下会影卫所配护腿，膝处藏有铁钉，攻击时容易重伤敌人。",
	["tid#EquipDes50301"]="扇面由火蚕丝编织而成，附着有微弱的火毒，心神不定者持此扇容易走火入魔。",
	["tid#EquipDes50302"]="纯银打造的华美头冠，阳光下泛有紫色光泽。",
	["tid#EquipDes50303"]="曾是星宿派长老们独有法袍，天工坊成立后，江湖上便有了诸多仿制品。",
	["tid#EquipDes50304"]="青紫色的长靴，制作时以药水泡制，可以驱除毒虫。",
	["tid#EquipDes50305"]="武林邪派钟爱的下装，不得不说其质量相当出色。",
	["tid#EquipDes60101"]="其身极重，其刃极钝，一刀劈下，骨肉分离，见甲破甲，见山摧山。",
	["tid#EquipDes60102"]="雁门关守将历代相传的宝甲，其盔有极强的防御力。",
	["tid#EquipDes60103"]="雁门关守将历代相传的宝甲，其甲较为轻便，方便持续作战。",
	["tid#EquipDes60104"]="雁门关守将历代相传的宝甲，其靴身坚不可摧。",
	["tid#EquipDes60105"]="雁门关守将历代相传的宝甲，腿甲分为三瓣，方便在马上作战。",
	["tid#EquipDes60201"]="桃花岛名剑，剑长二尺三寸，剑身柔韧，出剑时轨迹多变，令人无法招架。",
	["tid#EquipDes60202"]="大食国贡品，由异兽皮毛制成，周边由软金固定，价值连城。",
	["tid#EquipDes60203"]="大食国贡品，由异兽皮毛制成，周边由软金固定，价值连城。",
	["tid#EquipDes60204"]="大食国贡品，由异兽皮毛制成，周边由软金固定，价值连城。",
	["tid#EquipDes60205"]="大食国贡品，由异兽皮毛制成，周边由软金固定，价值连城。",
	["tid#EquipDes60301"]="绘有烈日焚天图的宝扇，扇骨由赤铁打造，是内功高手的心仪兵器。",
	["tid#EquipDes60302"]="为仁者，当求四海升平。",
	["tid#EquipDes60303"]="为君者，当求四海一家。",
	["tid#EquipDes60304"]="为学者，当求云游四海。",
	["tid#EquipDes60305"]="为侠者，当求名扬四海。",
	["tid#EquipDes70000"]="<size=22><color=#AF6C40>不可强化</color></size>\n由小掌柜阿闲主持铸造的“闲”侠大宝剑，相传在铸造之时有大威天龙之力与饶舌神功加持其中，是传说中的神奇武器，获得宝剑认可的闲侠，随手一挥就能瓦解敌人的攻势。",
	["tid#EquipDes70001"]="<size=22><color=#AF6C40>不可强化</color></size>\n名剑龙泉，剑长三尺，剑锋寒芒夺人，精光闪烁犹如龙鳞，敲击剑身低鸣之声如同龙吟，听闻剑成之日紫气冲天，氤氲之中似有巨龙盘卧，是天下武林共奉的剑中至尊。\n<color=#AF6C40>道具可在赛季活动中进行升级，敬请期待</color>",
	["tid#EquipDes70101"]="刀身取自“青龙偃月刀”，重铸后截去长杆，全刀浑然一体。刀身嵌有一颗定神珠，使持有者保持头脑清明。",
	["tid#EquipDes70102"]="天降赤色陨铁，分裂为三，其一刚硬且沉重，入手温热，恶人谷巧匠得之铸为一幅盔甲，周身雕有飞龙，名磐龙。",
	["tid#EquipDes70103"]="天降赤色陨铁，分裂为三，其一刚硬且沉重，入手温热，恶人谷巧匠得之铸为一幅盔甲，周身雕有飞龙，名磐龙。",
	["tid#EquipDes70104"]="天降赤色陨铁，分裂为三，其一刚硬且沉重，入手温热，恶人谷巧匠得之铸为一幅盔甲，周身雕有飞龙，名磐龙。",
	["tid#EquipDes70105"]="天降赤色陨铁，分裂为三，其一刚硬且沉重，入手温热，恶人谷巧匠得之铸为一幅盔甲，周身雕有飞龙，名磐龙。",
	["tid#EquipDes70201"]="铸造于昆仑冰川，内含玄冰剑意，剑长三尺，霜冻六尺，九尺之内罕逢敌手。",
	["tid#EquipDes70202"]="天降赤色陨铁，分裂为三，其一柔韧且轻便，入手冰凉，为纯阳宫所得，作轻甲一幅，周身赤红绘有红日，名灼日。",
	["tid#EquipDes70203"]="天降赤色陨铁，分裂为三，其一柔韧且轻便，入手冰凉，为纯阳宫所得，作轻甲一幅，周身赤红绘有红日，名灼日。",
	["tid#EquipDes70204"]="天降赤色陨铁，分裂为三，其一柔韧且轻便，入手冰凉，为纯阳宫所得，作轻甲一幅，周身赤红绘有红日，名灼日。",
	["tid#EquipDes70205"]="天降赤色陨铁，分裂为三，其一柔韧且轻便，入手冰凉，为纯阳宫所得，作轻甲一幅，周身赤红绘有红日，名灼日。",
	["tid#EquipDes70301"]="千秋一场大梦，世事一枕黄粱。你家欢喜他家愁，换与柯人下酒。今宵明月恰好，南山秋意正浓。玉盘珍羞兰陵酒，何妨一醉忘忧？",
	["tid#EquipDes70302"]="天降赤色陨铁，分裂为三，其一小巧且透明，具有提神醒脑的功效，朝廷请工匠打磨二十八颗宝珠，缝制于华服之上，名朝凤。",
	["tid#EquipDes70303"]="天降赤色陨铁，分裂为三，其一小巧且透明，具有提神醒脑的功效，朝廷请工匠打磨二十八颗宝珠，缝制于华服之上，名朝凤。",
	["tid#EquipDes70304"]="天降赤色陨铁，分裂为三，其一小巧且透明，具有提神醒脑的功效，朝廷请工匠打磨二十八颗宝珠，缝制于华服之上，名朝凤。",
	["tid#EquipDes70305"]="天降赤色陨铁，分裂为三，其一小巧且透明，具有提神醒脑的功效，朝廷请工匠打磨二十八颗宝珠，缝制于华服之上，名朝凤。",
	["tid#EquipDes80101"]="<size=22>适用门派：<color=#AF6C40>梁山泊、天龙门、玄甲军、金钱帮、名剑山庄、锦衣卫、金山派、飞雪刀、一丈青、神剑门、开封府</color></size>\n\n相传为楼兰古国的镇国之宝，刀柄以五彩琉璃雕刻而成，刀身寒气摄人，表面乌黑，唯有在月光照射下会闪烁银光。",
	["tid#EquipDes80102"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes80103"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes80104"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes80105"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes80201"]="<size=22>适用门派：<color=#AF6C40>崆峒派、天山派、峨眉派、桃花岛、华山派、纯阳宫、灵鹫宫、陷空岛、月寒宫</color></size>\n\n始皇帝曾经的佩剑，相传太阿乃威道之剑，持有者的内心越是坚定不屈，其剑意越是威猛，剑气激射可令风云变色。",
	["tid#EquipDes80202"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes80203"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes80204"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes80205"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes80301"]="<size=22>适用门派：<color=#AF6C40>花间派、天师门、逍遥派、红夷军、嵩山派、武当派、苍火门、百花派、及时雨、滅境、锻瑛谷</color></size>\n\n少林方丈主持水陆法会时，掷一莲子入水，顷刻间白莲盛开。丹青圣手将此场面绘于一玉扇之上，后被花间派所得，每每挥舞，便有佛音低唱。",
	["tid#EquipDes80302"]="算天算地，算尽天下事，观日观月，观览万人心。",
	["tid#EquipDes80303"]="算天算地，算尽天下事，观日观月，观览万人心。",
	["tid#EquipDes80304"]="算天算地，算尽天下事，观日观月，观览万人心。",
	["tid#EquipDes80305"]="算天算地，算尽天下事，观日观月，观览万人心。",
	["tid#EquipDes81101"]="<size=22>适用门派：<color=#AF6C40>墨家、少林、天下会、南宫派、形意门、霹雳堂、九天、麒麟甲、蒙武堂</color></size>\n\n形意门门主所持拳甲，由百炼精钢铸造，势大力沉，出拳时其声似怒雷滚滚，犹如神人擂鼓于苍天之上。",
	["tid#EquipDes81201"]="<size=22>适用门派：<color=#AF6C40>六扇门、唐门、万兽庄、绝张门、天鹰教、启灵派、清风寨、羽人非獍、太学宫</color></size>\n\n墨家名匠打造的轻弩，弩身嵌有火石，一经上弦可连发十数次，射程远威力大，连射时箭矢附着火焰如天降流星，因威力过大被藏于地宫当中。",
	["tid#EquipDes81301"]="<size=22>适用门派：<color=#AF6C40>五毒教、昆仑派、太极门、合欢派、鬼谷派、邪极坊、飞龙堡、罗袖阁、大理寺、平虏伯</color></size>\n\n曾为杨贵妃钟爱的琵琶，贵妃殁，琵琶夜间会不弹自响，听者将无故大喜大悲，宫中视之为不祥，后锁于大雁塔中。",
	["tid#EquipDes82101"]="<size=22>适用门派：<color=#AF6C40>古墓、金刚教、天策府、海沙派、丐帮、霸王枪、天墉城、飞将军、汉寿亭侯、绛衣军</color></size>\n\n枪头小巧细长，侧有尖钩，攻伐时十分灵动，一招出手犹如瑞雪飞舞、梨花纷飘，锋刃所过无人可挡。",
	["tid#EquipDes82201"]="<size=22>适用门派：<color=#AF6C40>衡山派、绝情谷、探花门、明教、八卦门、蜀山、独孤一门、豹子头、龙胆枪、御竞堂</color></size>\n\n长三寸，通体银白，形似发簪，器身不染尘垢。由昆仑邪兵王铸造，原铸有四对，如今江湖只余一对。",
	["tid#EquipDes82301"]="<size=22>适用门派：<color=#AF6C40>九黎、恒山派、慈航教、药王谷、落英轩、神水宫、密宗、娲皇神殿、凤仪亭、神都上阳宫、太极内家拳、天香阁、神·九黎</color></size>\n\n江湖有一妖人，持猩红宝刀，百无禁忌为祸四方。传言其梦中与达摩相见，被达摩点化，熔宝刀铸成禅杖，刻十戒于杖上，余生只行善事。",
	["tid#EquipDes90101"]="<size=22>适用门派：<color=#AF6C40>梁山泊、天龙门、玄甲军、金钱帮、名剑山庄、锦衣卫、金山派、飞雪刀、一丈青、神剑门、开封府</color></size>\n\n相传为楼兰古国的镇国之宝，刀柄以五彩琉璃雕刻而成，刀身寒气摄人，表面乌黑，唯有在月光照射下会闪烁银光。",
	["tid#EquipDes90102"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes90103"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes90104"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes90105"]="三岁习武，十二小成，十七扬名天下。敌犯边境，丈夫许国，醉别红颜，一去三十寒暑，直至玄甲褪色，鬓角生白。此甲后传于武林盟中，名曰山河。",
	["tid#EquipDes90201"]="<size=22>适用门派：<color=#AF6C40>崆峒派、天山派、峨眉派、桃花岛、华山派、纯阳宫、灵鹫宫、陷空岛、月寒宫</color></size>\n\n始皇帝曾经的佩剑，相传太阿乃威道之剑，持有者的内心越是坚定不屈，其剑意越是威猛，剑气激射可令风云变色。",
	["tid#EquipDes90202"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes90203"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes90204"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes90205"]="卿本君子，十年苦读，十年为官。奈何污吏横行，挟持朝政。弃笔提剑，诛灭天下不公，唯余浩然正气。",
	["tid#EquipDes90301"]="<size=22>适用门派：<color=#AF6C40>花间派、天师门、逍遥派、红夷军、嵩山派、武当派、苍火门、百花派、及时雨、滅境、锻瑛谷</color></size>\n\n少林方丈主持水陆法会时，掷一莲子入水，顷刻间白莲盛开。丹青圣手将此场面绘于一玉扇之上，后被花间派所得，每每挥舞，便有佛音低唱。",
