	["tid#EquipDes91301"]="<size=22>适用门派：<color=#AF6C40>五毒教、昆仑派、太极门、合欢派、鬼谷派、邪极坊、飞龙堡、罗袖阁</color></size>\n\n曾为杨贵妃钟爱的琵琶，贵妃殁，琵琶夜间会不弹自响，听者将无故大喜大悲，宫中视之为不祥，后锁于大雁塔中。",
	["tid#EquipDes92101"]="<size=22>适用门派：<color=#AF6C40>古墓、金刚教、天策府、海沙派、丐帮、霸王枪、天墉城、飞将军、汉寿亭侯、绛衣军</color></size>\n\n枪头小巧细长，侧有尖钩，攻伐时十分灵动，一招出手犹如瑞雪飞舞、梨花纷飘，锋刃所过无人可挡。",
	["tid#EquipDes92201"]="<size=22>适用门派：<color=#AF6C40>衡山派、绝情谷、探花门、明教、八卦门、蜀山、独孤一门、豹子头、龙胆枪、御竞堂</color></size>\n\n长三寸，通体银白，形似发簪，器身不染尘垢。由昆仑邪兵王铸造，原铸有四对，如今江湖只余一对。",
	["tid#EquipDes92301"]="<size=22>适用门派：<color=#AF6C40>九黎、恒山派、慈航教、药王谷、落英轩、神水宫、密宗、娲皇神殿、凤仪亭、神都上阳宫、太极内家拳、天香阁、神·九黎</color></size>\n\n江湖有一妖人，持猩红宝刀，百无禁忌为祸四方。传言其梦中与达摩相见，被达摩点化，熔宝刀铸成禅杖，刻十戒于杖上，余生只行善事。",
	["tid#EquipDes121101"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n拳法，有八极。内修神极、意极、气极、力极，外修极速、极准、极狠、极稳。八极贯通，天下无敌。",
	["tid#EquipDes121201"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n朝廷搜集诸葛弩图纸，铸一精金重弩，可连发五十矢，百步之内无甲可防，但因造价极高且重量偏大，铸造一柄后便停滞了。",
	["tid#EquipDes121301"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n西有一座魔山百草不生，唯山巅之上有一独木，有制琴师取之一段雷火焦木制琴，其音靡靡，如他化天魔惑众，故名“天魔”。",
	["tid#EquipDes122101"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n汉代高祖围困霸王于乌江之畔，感霸王之威，便将其兵器封存长安未央之下以镇其锋，百年之后锋芒丝毫不减，而后王莽篡政，至此遗落辗转数百年，后被一良匠得之，重新锻造，霸王之戟因而重现江湖。",
	["tid#EquipDes122201"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n状如一支孔雀花翎，实为一支陨铁而制的精金钢针，辅以盘龙丝装点，浸以秘药而成孔雀之色，高手可以真气御动，无坚不摧无往不利。",
	["tid#EquipDes122301"]="<size=22><color=#AF6C40>江湖神兵</color></size>\n达摩祖师曾往来南北传扬禅法，曾手持一杖，其杖浸润禅宗之义，使之有伏魔之威，宵小淫邪立于其旁便会戚戚而栗。",
