	["tid#EquipHeroDes208_4"]="占位符",
	["tid#EquipHeroDes210_1"]="战斗中，每消灭一个敌人，衡山便获得一层强化效果，该效果最多叠加3层，且会一直持续到战斗结束。1层时：衡山获得20%攻击力提升；2层时：额外获得60点攻速提升；3层时：额外获得20%的暴击率提升",
	["tid#EquipHeroDes210_2"]="强化效果现在最多可以叠加4层，在叠加到4层时，衡山会额外获得35%攻击回复效果；",
	["tid#EquipHeroDes210_3"]="强化效果现在最多可以叠加5层，在叠加到5层时，衡山会额外获得50%的减伤效果；",
	["tid#EquipHeroDes210_4"]="占位符",
	["tid#EquipHeroDes211_1"]="若鬼谷打败了添加有“诛邪”印记的敌人，会为全体队友恢复160%自身攻击力的生命值。",
	["tid#EquipHeroDes211_2"]="攻击具有“诛邪”印记的敌人时，鬼谷造成的伤害提升10%",
