	["tid#EquipHeroDes211_4"]="占位符",
	["tid#EquipHeroDes212_1"]="场上每有一个施加了“裂伤”效果的敌方侠客，纯阳便获得5%的暴击率提升",
	["tid#EquipHeroDes212_2"]="每个施加了“裂伤”效果的敌方侠客，还会使纯阳的暴击伤害提升10%",
	["tid#EquipHeroDes212_3"]="每当被施加“裂伤”效果的敌方侠客阵亡时，纯阳便获得5%的暴击率和10%的暴击伤害提升，该效果会一直持续到战斗结束。",
