	["tid#Herocharacteristic_101"]="从不动心女",
	["tid#Herocharacteristic_102"]="不被烧伤",
	["tid#Herocharacteristic_103"]="善于隐藏自己的真实情绪",
	["tid#Herocharacteristic_104"]="绝对禁锢",
	["tid#Herocharacteristic_105"]="不会被催眠",
	["tid#Herocharacteristic_106"]="拥有常人难以企及的速度和出神入化的刀法",
	["tid#Herocharacteristic_107"]="有很强的气场和领导能力",
	["tid#Herocharacteristic_108"]="摆放东西非常整齐",
	["tid#Herocharacteristic_109"]="很擅长找敌人的弱点。有很优秀的夜视能力",
	["tid#Herocharacteristic_110"]="暂缺",
	["tid#Herocharacteristic_111"]="暂缺",
	["tid#Herocharacteristic_114"]="暂缺",
	["tid#Herocharacteristic_115"]="能用人话和鹰顺利沟通",
	["tid#Herocharacteristic_181"]="打架永远要当最后一个倒下的！",
	["tid#Herocharacteristic_182"]="唱歌可以鼓舞人心也可以暗藏刀锋",
	["tid#Herocharacteristic_183"]="对于虚弱的人，可以一击绝命，百分百击中，不会被闪避",
	["tid#Herocharacteristic_184"]="能用人话和鹰顺利沟通",
	["tid#Herocharacteristic_191"]="暂缺",
	["tid#Herocharacteristic_192"]="暂缺",
	["tid#Herocharacteristic_193"]="暂缺",
	["tid#Herocharacteristic_194"]="暂缺",
	["tid#Herocharacteristic_195"]="暂缺",
	["tid#Herocharacteristic_201"]="就算是武力值比他高很多的人，一看到他也会吓一跳，百分百使别人被吓一跳",
	["tid#Herocharacteristic_202"]="能和任何人成为朋友，包括敌人。唱歌跑调。百分百唱歌跑调",
	["tid#Herocharacteristic_203"]="不管是对方是多么牛逼的人，他都有信心一刀毙命",
	["tid#Herocharacteristic_205"]="能和动物亲近，尤其是小动物",
	["tid#Herocharacteristic_206"]="喝了酒神志还能保持清醒",
	["tid#Herocharacteristic_207"]="心脏长在左边，一辈子就学会了三剑。",
	["tid#Herocharacteristic_208"]="头发每次剃光又会很快重新长出来。",
	["tid#Herocharacteristic_210"]="暂缺",
	["tid#Herocharacteristic_211"]="长寿",
	["tid#Herocharacteristic_212"]="说自己是个流浪剑客，没什么剑法，但是使的不是一般人能获得的武器。",
	["tid#Herocharacteristic_213"]="看起来不是很壮但是特别能打",
	["tid#Herocharacteristic_281"]="混迹边关，黑白通吃，没有几手功夫怎能八面玲珑",
	["tid#Herocharacteristic_282"]="天生的力大无穷，表现在日常各个方面，不是很能理解孱弱无力的其他人的生活状态",
	["tid#Herocharacteristic_283"]="暂缺",
	["tid#Herocharacteristic_291"]="暂缺",
	["tid#Herocharacteristic_292"]="暂缺",
	["tid#Herocharacteristic_293"]="暂缺",
	["tid#Herocharacteristic_294"]="暂缺",
	["tid#Herocharacteristic_295"]="暂缺",
	["tid#Herocharacteristic_301"]="惊人的医术，几乎没有什么病是治不好的",
	["tid#Herocharacteristic_302"]="可攻可守，是菩萨和战神的化身，额能够在危险时候化险为夷",
	["tid#Herocharacteristic_304"]="只要她愿意，所有人都能相信她是无辜的，可以催眠任何人",
	["tid#Herocharacteristic_305"]="暂缺",
	["tid#Herocharacteristic_306"]="暂缺",
	["tid#Herocharacteristic_307"]="特别幸运",
	["tid#Herocharacteristic_308"]="力量奇大",
	["tid#Herocharacteristic_309"]="基本不会生气，生气了的话就有人倒霉了",
	["tid#Herocharacteristic_310"]="暂缺",
	["tid#Herocharacteristic_311"]="肌肉具有良好的承伤和应变能力。",
	["tid#Herocharacteristic_312"]="有一条从小养大的狼；",
	["tid#Herocharacteristic_383"]="琴音能影响别人的情绪",
	["tid#Herocharacteristic_386"]="能够过目不忘",
	["tid#Herocharacteristic_387"]="暂缺",
	["tid#Herocharacteristic_391"]="暂缺",
	["tid#Herocharacteristic_392"]="暂缺",
	["tid#Herocharacteristic_393"]="暂缺",
	["tid#Herocharacteristic_394"]="暂缺",
	["tid#Herocharacteristic_395"]="暂缺",
	["tid#Herocharacteristic_401"]="其实也没有变永生。只是现在生命值比较厚，所以是个盾。",
	["tid#Herocharacteristic_402"]="精通药学与毒理学，擅长毒药。因为力气很小，无法近身作战，但善于制作毒素来弥补力量的不足。",
	["tid#Herocharacteristic_403"]="能够让别人无法抗拒他的赌约",
	["tid#Herocharacteristic_404"]="暂缺",
	["tid#Herocharacteristic_405"]="暂缺",
	["tid#Herocharacteristic_406"]="乌鸦嘴特别灵验",
	["tid#Herocharacteristic_407"]="暂缺",
	["tid#Herocharacteristic_409"]="暂缺",
	["tid#Herocharacteristic_410"]="挥舞轻纱的时候会让人认不出自己",
	["tid#Herocharacteristic_411"]="力量奇大",
	["tid#Herocharacteristic_412"]="为了赢，什么的豁得出去",
	["tid#Herocharacteristic_481"]="凭借手中的笔可以封人穴位，断人经脉，甚至致人与死地。",
	["tid#Herocharacteristic_484"]="有一定的海洋力量。能够改变水的密度和质量，能够控制鱼群",
	["tid#Herocharacteristic_485"]="磨刀之后的刀会有灵性",
	["tid#Herocharacteristic_491"]="暂缺",
	["tid#Herocharacteristic_492"]="暂缺",
	["tid#Herocharacteristic_493"]="暂缺",
	["tid#Herocharacteristic_494"]="暂缺",
	["tid#Herocharacteristic_495"]="暂缺",
	["tid#Herocharacteristic_501"]="暂缺",
	["tid#Herocharacteristic_502"]="暂缺",
	["tid#Herocharacteristic_503"]="暂缺",
	["tid#Herocharacteristic_504"]="死了之后会复活",
	["tid#Herocharacteristic_505"]="暂缺",
	["tid#Herocharacteristic_506"]="音痴，无法分辨乐曲的好坏，对唱歌跑调的曲子也会因为面子认为是天籁之音",
