	["tid#HeroDes_101"]="多面均衡的外功型前排战士，无论是生存、输出还是辅助方面，都有着不俗的能力。",
	["tid#HeroDes_102"]="擅长攻击的内功型后排输出，既能提高队友输出能力，又能造成高额范围伤害。",
	["tid#HeroDes_103"]="攻辅均衡的外功型后排辅助，技能迅速消灭敌方虚弱目标，又能快速为队友回复内力。",
	["tid#HeroDes_104"]="擅长控制的外功型前排输出，在面对单体敌人时有着极强的伤害和控制效果。",
	["tid#HeroDes_105"]="擅长防守的外功型前排战士，不仅能治疗单体友军，还能为全体队友提供大量护盾。",
	["tid#HeroDes_106"]="擅长攻击的外功型前排隐者，绝技在暴击使能够获得巨额增强。",
	["tid#HeroDes_107"]="擅长防守的外功型前排战士，能够为后排队友抵御伤害并保护其免于阵亡。",
	["tid#HeroDes_108"]="擅长辅助的内功型后排侠客，不仅能为队友提供多种增益效果，更能为队友快速回复内力。",
	["tid#HeroDes_109"]="擅长攻击的外功型后排输出，不仅能狙击自己对位的敌人，更对敌方后排有着极大的破坏力。",
	["tid#HeroDes_110"]="",
	["tid#HeroDes_111"]="擅长攻击的外功型前排隐者，擅长直取对位敌人并造成高额单体伤害和控制效果。",
	["tid#HeroDes_114"]="占位符",
	["tid#HeroDes_115"]="擅长攻击的内功型后排输出，绝技可以对大范围内的敌人造成高额伤害。",
	["tid#HeroDes_181"]="擅长防守的外功型前排战士，健硕的体格可以为后排抵御伤害，霸道的刀法可以对敌人造成一定控制效果。",
	["tid#HeroDes_182"]="攻辅均衡的内功型后排辅助，即可攻击敌人又可治愈队友，还能在限制敌方输出。",
	["tid#HeroDes_183"]="擅长攻击的外功型后排输出，对敌方虚弱的单位造成额外伤害。",
	["tid#HeroDes_184"]="擅长攻击的内功型后排输出，绝技可以对大范围内的敌人造成高额伤害。",
