	["tid#HeroDes_195"]="军威营",
	["tid#HeroDes_201"]="擅长攻击的外功型前排战士，生命值越低时伤害越高，受到致命伤害时能够在数秒内免疫阵亡，继续战斗。",
	["tid#HeroDes_202"]="擅长攻击的外功型混合输出，拥有前排和后排两种攻击模型，能够造成大量范围伤害。",
	["tid#HeroDes_203"]="擅长攻击的外功型后排输出，普攻能对直线上的所有敌人造成伤害，且在战斗中有飘忽不定的走位。",
	["tid#HeroDes_205"]="攻防均衡的外功型前排战士，能够对敌人造成多段击飞和击退，擅长压缩敌人阵线。",
	["tid#HeroDes_206"]="攻防均衡的外功型前排战士，能够在战斗中不断提升自身属性，并且拥有免控能力。",
	["tid#HeroDes_207"]="擅长攻击的外功型前排输出，在对单体敌人造成大量伤害的同时还能够治疗自身。",
	["tid#HeroDes_208"]="攻辅均衡的内功型后排侠客，不仅能为己方后排带来保护和属性提升，绝技更能在蓄力完成后造成巨额伤害。",
	["tid#HeroDes_210"]="擅长攻击的外功型前排侠客，会追击敌方虚弱侠客，并令敌人陷入恐惧四散奔逃。",
	["tid#HeroDes_211"]="擅长攻击的内功型后排输出，能够改变战场的天气和地形，对敌方造成削弱效果和大量伤害。",
	["tid#HeroDes_212"]="擅长攻击的外功型后排输出，通过消耗自身生命值，可以获得高额的攻击力和攻击速度加成。",
	["tid#HeroDes_213"]="攻防均衡的外功型前排战士，能够在削弱敌人的同时强化自身，绝技能对大范围内的敌人造成伤害。",
	["tid#HeroDes_281"]="擅长控制的内功型后排输出，可以造成多种负面状态和控制效果，大幅度限制敌方输出。",
	["tid#HeroDes_282"]="擅长防守的外功型前排战士，自身生命值越低时，防御能力越强。",
