	["tid#HeroDes_302"]="擅长攻击的外功型前排隐者，在对敌人造成伤害的同时还能够闪避敌人的攻击。",
	["tid#HeroDes_304"]="擅长控制的内功型后排辅助，不仅能频繁控制敌方单体，绝技更能控制所有敌方侠客。",
	["tid#HeroDes_305"]="攻防兼备的外功型混合侠客，释放绝技后，普通攻击会从前排攻击变为威力更强的后排攻击。",
	["tid#HeroDes_306"]="擅长攻击的内功型前排隐者，开场时能够与地方目标互换位置，阵亡时可以化作幻影继续战斗。",
	["tid#HeroDes_307"]="擅长攻击的外功型前排战士，使用冰风双剑的特殊剑气对敌人造成高额伤害，对有护盾的敌人有额外的伤害加成。",
	["tid#HeroDes_308"]="擅长防守的外功型前排战士，能够嘲讽敌人，并反弹自身所受的伤害。",
	["tid#HeroDes_309"]="攻辅兼备的内功型后排侠客，不仅能造成高额伤害，更能为敌方施加强力削弱诅咒。",
	["tid#HeroDes_310"]="擅长攻击的内功型后排输出，释放绝技后能够强化自身技能，使技能拥有额外的强力效果。",
	["tid#HeroDes_311"]="擅长防守的外功型前排战士，可以为自身施加高额护盾，抵御大量伤害。",
	["tid#HeroDes_312"]="擅长攻击的外功型后排输出，绝技在面对单体敌人时有额外伤害加成。",
	["tid#HeroDes_383"]="擅长攻击的内功型中排输出，技能使用琴音扰乱敌方输出，又能对大范围内敌人造成爆发伤害。",
	["tid#HeroDes_386"]="攻辅均衡的内功型后排侠客，不仅能对敌方造成大量伤害和削弱效果，还能够为全体友军提供增益效果。",
	["tid#HeroDes_387"]="擅长防御的外功型前排战士，拥有非常强的自我恢复内力，非常擅长持久作战。",
