	["tid#Herointerest_702"]="暂缺",
	["tid#Herolegend1_101"]="林老镖师有一次押镖经过龙门荒漠，遭遇了一伙石驼帮马贼，虽然林镖师武艺高强，无奈寡不敌众，镖师们一个个倒下，那个时候林无双还是个丫头片子，依仗着家传的轻功，与马贼游斗，却也渐渐不支，眼看着林无双就要命丧马贼刀下，林老镖师扑了上来，用自己的身躯护住了女儿，眼看着自己的父亲倒了下去，面目狰狞的马贼又围了上来，林无双不得已举起了手里的刀……",
	["tid#Herolegend1_102"]="由于常年吸入火药房内有害的气体，导致王司马的性格和心智发生了一些变化，但她始终用自己的的理智压制着这些奇奇怪怪的冲动和想法，但是在一次新武器展示会上，她的武器意外爆炸，随之，她脑子里最后那根弦似乎也断了。",
	["tid#Herolegend1_103"]="在他二十一岁生日那天，李延广的父亲送给他一杆铁鹰巨弩作为礼物。这把武器堪称绝品，专用弓箭提供更好的稳定性，比李延广拥有过的任何弩弓都更精准。这把武器还可以自由改装，发射许多种不同类型的弓箭。从此之后，李延广只要外出办案就一定会带着它。",
	["tid#Herolegend1_104"]="被父母遗弃在手工作坊的孩子，被城中的老大收养，据说当时她躺在一个双人摇篮里，她似乎应该有一个同胞，但是不知去向。",
	["tid#Herolegend1_105"]="清梵原本是得天独厚的大弟子，清觉代替他成为了更受大师偏爱的弟子，清梵一直不解为何住持偏心。小的时候和师兄在山里修炼，饿了就吃些野果之类的，但是师兄总是半夜离开，早上回来的时候身上有一些动物的毛发，其实清觉知道那代表着什么，但是他一直没说，他只会默默替师兄祈福，希望神明可以原谅师兄。",
	["tid#Herolegend1_106"]="破落镇中的小孩子从来不敢浪费粮食，一方面是因为父母曾经历过那场可怕的旱灾，另一方面是因为刘关江。就像孩子不睡觉时，父母总会拿夜猫子吓唬孩子一样，孩子不肯吃饭时，父母总会拿刘关江吓唬孩子。“你再不吃饭，小心刘关江过来把你的嘴缝上！”江湖上传闻刘关江最痛恨浪费粮食的人，但没有人知道为什么。也有一些倒霉蛋浪费粮食被刘关江撞见过，结果要么是被缝上了嘴，要么是被绑起来饿上三天三夜。效果也很明显，经历过这两种折磨的人，从此之后都不会再浪费一粒粮食。",
	["tid#Herolegend1_107"]="燕云飞从小过着与常人无二的生活，除此之外他最喜欢阅读那些江湖侠客的小报，幻想着自己有朝一日能够成为大侠，或者与他们为伍，可是一场战役掠过他所在的城市，叛贼官兵残忍害了他父母的性命，他握着家中的柴刀，战战巍巍的走向那些恶人的后背，却被一名燕姓老兵拦在身后。",
	["tid#Herolegend1_108"]="与其说张昊是如今天师门的张天师，不如说他更像是个商人，彼时摘星阁的的情报网络，为他聚拢了巨额财富，可谓是富可敌国。于是他在天师门内兴建了更高的新摘星阁，起初也是遭到了门内长老门的反对，但是在这位年轻的新天师的经营下，天师门变得越加繁盛，长老们也只好默默享受随着天师门的强盛带来的赞美与声誉。",
	["tid#Herolegend1_109"]="谨小慎微，常记在心\n禹海莲在战斗中异常小心，任何风吹草动都躲不开她的眼睛，她的眼睛能看到正常人三倍远的距离，她也能够比正常人更快锁定移动着的物体，拥有超强动态视力的她，绝不可能在任何一场战斗筹备中被人先行埋伏，换句话说，埋伏，这个词如果是个比赛，那么只有她能够拔得头筹。",
	["tid#Herolegend1_110"]="暂缺",
	["tid#Herolegend1_111"]="从跟奶奶身边长大的公孙雨，在奶奶的悉心指导下，开始学习家族传承的神秘舞蹈。她对舞蹈的热爱却毋庸置疑，也慢慢发现了家族秘舞与武学之间的关联，为了舞艺的精进，也为了躲避进来不断滋生的动乱，她决定去往蓬莱岛寻找内心的领悟。",
	["tid#Herolegend1_114"]="暂缺",
	["tid#Herolegend1_115"]="部落当中每隔20年会重新推举一名配得上天鹰称号的少年，来代表自己的族群，他似乎从未想到自己会被选中，虽然每日刻苦上山锻炼，可他也曾幻想那只帅气英勇的雄鹰成为自己的伙伴。这一天终于到来，他成为了天鹰。",
	["tid#Herolegend1_181"]="郭惊涛作为神刀门的大公子，少年老成，处事沉稳，于家传刀法上的悟性十分出众，十五岁之前，一直深得父亲与家人厚望，此时的郭惊涛一直认为自己就是郭家神刀的继承人。可后来，二弟郭浮云惊人的天资几乎争得了所有人的注目，而且在郭惊涛二十一岁那年，父亲把庄主族中代代相传的信物——吞吴刀传给了自己的二弟郭浮云，传刀之时，也意味着将神刀门的百年威名交到了郭浮云的手中，从此郭浮云才是山庄名正言顺的继任者。不过，郭惊涛却没有过多的埋怨，因为他的目标是重振山庄威名，并不是庄主之位，也许二弟继任也不是什么坏事。",
	["tid#Herolegend1_182"]="杨素素出生在渭水河畔一个农耕的村子里，父母都是几代的老实种地人，生下了杨素素之后还想再生一个男孩，可是一直都没有成功，而且家里的收成也开始每年都不如以前。于是杨素素被人说是家族的克星。",
	["tid#Herolegend1_183"]="少年萧不语带着自己绑的弹弓到野外打野兔和野鸟，忽然他灵敏的自然神经告诉他，附近一定有不属于村子的人存在，为了不打草惊蛇，他还是继续打野兔，结果奔跑的野兔踩到埋在地中的土炮，砰的炸开来，碎成不忍直视的几块。萧不语所不曾接触过的战争，终于到来。",
	["tid#Herolegend1_184"]="部落当中每隔20年会重新推举一名配得上天鹰称号的少年，来代表自己的族群，他似乎从未想到自己会被选中，虽然每日刻苦上山锻炼，可他也曾幻想那只帅气英勇的雄鹰成为自己的伙伴。这一天终于到来，他成为了天鹰。",
	["tid#Herolegend1_191"]="暂缺",
	["tid#Herolegend1_192"]="暂缺",
	["tid#Herolegend1_193"]="暂缺",
	["tid#Herolegend1_194"]="暂缺",
	["tid#Herolegend1_195"]="暂缺",
	["tid#Herolegend1_201"]="大概八、九岁的时候韦壮武去书院看成绩，偶然听到同学们嘲笑自己愚笨，直觉告诉他应该解决这件事，但是又没告诉他如何解决，于是他轻轻一拳打的那个同学昏倒在地，要不是他小时候的好兄弟林良骏家里出面调解，他父母的猪肉铺也差点被这个有钱的嘴贱同学家给端了。这件事是韦壮武第一次知道，其实他有另外一种方式解决问题。",
	["tid#Herolegend1_202"]="黄荣华的父亲靠着两节寒铁鞭占据了当时奇门兵器谱的总霸主，但树绝技风，有很多人打着请教的旗号，来跟父亲切磋武艺，家里天天打打闹闹的，黄荣华的幼年时期过的可谓水深火热。他总是觉得，这样下去总有一天会出事。",
	["tid#Herolegend1_203"]="无论对什么人、对什么事，出发点都是爱，而不是恨，因为他知道恨所造成的只是毁灭，爱却可以令人永生。所以他的心胸永远宽阔，他的为人总是那样豁达。懒散而潇洒，萧疏而沉着，他身上有一种具有诗人气质的落拓。",
	["tid#Herolegend1_205"]="可靳辰洋本对习武没什么太大兴趣，反而是在习武时经常瞒过下人偷偷溜出去开小差，去逗逗外面的猫猫狗狗，和同年级的小伙伴们一起疯跑，靳辰洋惊奇的发现，她能比其他小伙伴更被小动物青睐，动不动就身边围着一群小猫小狗，靳辰洋也非常喜欢小动物们，经常看着它们嬉戏的样子出神，这在靳辰洋习武的路上让她的武学也掺入了几分小动物们自然的灵动。",
	["tid#Herolegend1_206"]="由于沈念是郭岩好不容易才带回来的女儿，因此完全被父亲当作是掌上明珠，帮中上下也是体恤帮主遭遇，也对沈念疼爱有加。然而，钟情于郭岩多年的尹小荷得知郭岩从外面带回来一个女儿，不禁黯然神伤，但是尹小荷天生善良，决定帮助郭岩照顾这个可怜的小女儿。在沈念看来，尹小荷是娘一样亲近的人，因此集万般宠爱于一身的沈念，长大之后难免些骄横，好在在尹小荷的教导下，纯真善良，却也没什么坏心思，细细说来，倒像是有些不会轻易服输的性格。",
	["tid#Herolegend1_207"]="三年之后，宁不凡十五岁。三年时间里，宁不凡行侠仗义的事做了无数，但疑惑却越来越深。他觉得这世间的黑色无论如何都除不尽，他发现有些白色转眼间就会变为黑色，于是他回到了师父身边。师父听他说完了之后，师父打开了一壶醴饮，两人一起喝到了深夜。第二天，师父叫了他第二式剑法，名曰“剑心”。这一练，又是五年。五年之后，宁不凡变得潇洒不羁。他开始看到，原来世间。不只有黑白两色，还有五彩斑斓。师父又告诉他可以了，于是他又一次下山去了。",
	["tid#Herolegend1_208"]="辛晓风在寺中渐渐长大，凭借她的天真和可爱赢得了寺中每一个尼姑的喜欢，大家都待他如同女儿一般。即便是最为严厉的住持师太，看到她也总会变得和蔼可亲。辛晓风六岁那年，师太提出要跟她剃度，让她真正成为庵中的一员。但刚把小辛晓风的头发剃完，辛晓风却突然晕倒了，发了高烧，脸庞通红。大伙都吓坏了，到处求医问药，但辛晓风就是不见好。最后师太出了一趟门，回来后带辛晓风去了一趟蓬莱才好转。从蓬莱下来后，辛晓风又重新拥有了一头乌黑柔顺的长发，而且无论怎么剪，只需要睡一觉后，头发又会重新长出了。如此几次之后，寺中的尼姑也只好接受了这个事实。",
	["tid#Herolegend1_210"]="吕沛杰出生在一个做不正当生意的家族里，这种生意使得整个家族收到了诅咒似的将近几十年来都只有女孩降生，而吕沛杰是打破诅咒般的存在，只是可惜他天生失明。",
	["tid#Herolegend1_211"]="少年的况候智生活十分凄苦。母亲本就是大小姐，不会什么谋生的手段，光是解决两人的温饱就已经很艰难了。好在况候智很懂事，小小年纪就能替别人放牛，补贴家用。不仅如此，况候智还十分好学，虽然去不了学堂，他从一个好心的先生处借来了书籍，趁着放牛的间隙学习。一天，况候智正骑着牛走在镇外的小路，一心看书的他没注意到迎面来了一顶尊贵的轿子。眼看着牛和轿子就要相撞，轿旁的侍卫上前拦住了况候智，况候智吓了一跳，连忙下来赔罪。但轿中的人不仅没有怪罪他，反而很欣赏他的好学。问了几句话后，他告诉况候智自己府中正缺一名侍女，可以让他的母亲来，而况候智也可以在他府中的私塾上课。",
	["tid#Herolegend1_212"]="那一年，家里还是拗不过这个固执的偏爱道法的小少爷，当家的老太公也只好摆摆手说随他去吧，但是吴清霄的母亲放心不下自己的小儿子，便托人找到了颇有名望的，号称纯阳子的吕洞宾，希望吴清霄可以拜在他的门下，研修道法。好在吕祖觉得这个小少爷颇有道心，也就没有多少犹豫的答应收了下来。尽管如此，身为母亲，一听到自己的小儿子要吃不少苦，待送走了吴清霄，还是在家里哭了三天三夜，半年之后，吴清霄寄回一封家书，母亲看罢默默将信好生收了起来，似也不再提及小儿子的事情，不过从来没人知道信里究竟写了什么。",
	["tid#Herolegend1_213"]="父母经商，于是其实在喻扬超出生之后也没有过多时间陪伴他，从小他就习惯了自己玩，和自然里的生物交朋友，自己做各种各样的实验，研究父亲从国外弄回来的各种玩意，这些都足以见得他天资聪颖。",
	["tid#Herolegend1_281"]="焦渝钦本也是一方望族之后，只可惜到她幼年时家道中落，流落到江湖之中，又阴差阳错来到了龙门寨这个地方。焦渝钦凭着天生的狡黠与机敏，却也很快适应了这里的生活，并且很快在一家客栈里找了个营生，并安顿下来。",
	["tid#Herolegend1_282"]="离家后遇到的绿林好汉号称金银大王，是兄弟二人，都善用兽头大锤，号称有万夫不当之勇。不过面对力拔山兮气盖世的胡大壮，瞬间就吓得脚软丢下兵器跑路了，也许是因为装门面的大锤做的太实在，拿着跑不快的原因吧。但是这个锤子的分量胡大壮觉得一手一个刚刚好，于是就欣然收下。之后胡大壮再也没有遇到过山贼恶霸……",
	["tid#Herolegend1_283"]="西域白氏一族，靠买卖皮毛发家致富。白夫人的头胎，是位了不得的千金。据说白夫人在难产时，曾一度昏厥过去，梦中一尾硕大的白蛇围绕在她身边，吐着蛇信子。白夫人惊醒过来，欧阳慧也呱呱落地。这奇异之梦被白家视为祥瑞，小欧阳慧也因此受到诸多珍爱。欧阳慧如玉般长大，当她的身世传奇即将褪色时，一件破天荒的事又发生了。",
	["tid#Herolegend1_291"]="暂缺",
	["tid#Herolegend1_292"]="暂缺",
	["tid#Herolegend1_293"]="暂缺",
	["tid#Herolegend1_294"]="暂缺",
	["tid#Herolegend1_295"]="暂缺",
	["tid#Herolegend1_301"]="永阳镇的治安一直是周围镇子的楷模，但这一切还要归功于当年那个“小神医”。那应该是快四十年前了吧，当时镇子的治安可不像如今这般好，各种地痞恶霸在大街小巷中游荡，晚上根本不敢有人在街上走。但最让人害怕的，还是地痞头子——李三。小神医刚开馆那会儿，李三天天跑去闹事，又是砸医馆又是打人，甚至还朝小神医脸上啐过痰。所以那天他坠马昏迷的时候，所有人都是拍手称快，觉得他终于罪有应得了。果不其然，镇上所有的大夫都拒绝为他看病，巴不得他早点去世。走投无路之下，他的小弟们抬着他来到了小神医的门口。当正当所有人都觉得小神医会闭门不见时，医馆大门却开了……为了将奄奄一息的李三救回来，小神医不眠不休的照顾了他两天两夜，等到李三终于张开双眼时，小神医也倒下了。此后，李三性情大变，不仅解散了地痞团伙，还自发成立了治安队维护周围的治安。每当有人问起为什么时，他总是嘿嘿傻笑，眼睛却不由自主的看向小神医医馆的方向……",
	["tid#Herolegend1_302"]="迈入青年的她开始有了心事，父母也豁达，说准许她出门去闯荡一下，但不会给她暗中保护和帮助，她需要全部依靠自己的力量生活。她开开心心的拜别了父母，出门的第三天发现自己没有生活的技能，吃了不少苦头。",
	["tid#Herolegend1_304"]="扬州花间派歌舞之技冠盖中华，声名远播，平日里访者云集，有江湖豪客，有一方巨富，有高人名士，也有朝中大员，更有外方人士，前来观赏歌舞之人庞多繁杂，江湖中人甚多，难免便有些言谈不和，纠纷琐事。此等繁杂小事若无法得当处理，往往动辄便兴干戈，如此一来，对花间来说却是得不偿失，花间派主，须得八面玲珑、应酬得宜才可，苏婉仪正是这样的女子，她协助公孙幽打理花间已有数年，向无纰漏。",
	["tid#Herolegend1_305"]="然而她的才能被家族家主看中，破格让她在三岁便进入家族蒙学并亲自为她精选启蒙老师。5年时间就吸收了家学的所有知识并读遍了藏书离开了族学开始自己研究。对于她的各种桀骜不驯和特立独行，同族和长老们多有不满，但是家主力排众议将十岁的她编入家族研究院进行最新的机关学研究，并称为“家族千里驹”、“中兴的希望”。",
	["tid#Herolegend1_306"]="因为从小在商人家庭中长大，姜笑川自小便认为有了钱便有了一切，直到后来的一件事改变了他的看法。姜笑川的父亲因为得罪了一位地方上的权贵，遭到了打压，生意一落千丈。父亲因为不服气，带了一大批钱财去雄都找人帮忙，却被人摆了一道，安了个行贿的罪名抓入监牢。严刑逼供之下，姜笑川的父亲屈打成招，在权贵的一番运作之后，判了个家产全数充公。年少的姜笑川目睹了家庭遭逢的这场灾难，彻底改变了自己的看法，觉得钱财没有权利重要。",
	["tid#Herolegend1_307"]="元十七年，名剑山庄第三次名剑大会之际，姜承影八龄，他与天生比剑得胜，却未曾得到四季剑法剑谱，姜承影赌气离家。他初时心中气恼，只想离家远远的便好，不料渐行渐远，待到心中略有悔意想返家之时，却早已记不得来时路途。他无法可想，沿街而睡，有人送食水与他。不过两日，路有拐卖孩童之人，上前搭讪，寥寥数语便以送其返家之名将姜承影骗走。",
	["tid#Herolegend1_308"]="滔滔背着船锚沿着海岸来到安金，这是小萝莉第一次来到人这么多的地方，她发现这里的人都吃的很少，还用着她不认识的金属块做交易。滔滔闻着香味来到一个大饭馆，在小二和店家的目瞪口呆之下吃了三大桌的饭菜之后，结账却犯了难。时逢饭馆有恶霸来闹事，滔滔抡起船锚教训了二十几个壮汉，一下子成了安金的名人。",
	["tid#Herolegend1_309"]="年轻的周湘君与家族习武的意见相左，毅然背起行囊远走，巧遇逍遥，二人同为淡泊之人，一同云游，得知蓬莱奇峰奇景，难登之极，二人约好比试一番，不想却有了意外的收获。周湘君获得点悟后立即回到家乡，将新悟得的道理讲给了父亲，也与父亲获得了和解。",
	["tid#Herolegend1_310"]="从筱九记事起，她便跟着前代圣女学习如何与万灵沟通。所谓万灵，即是万千生灵的集合体，它代表着树木、花草、飞禽、走兽等一切生灵。万灵似乎很喜欢这个小女孩，很轻易地就回应了她的呼唤。在万灵的教导下，她学会了如何与自然中的生灵沟通，如何与她们做朋友。逐渐地，筱九纯净的心灵得到了森林中所有生灵的认可，其中与她最为亲昵的，是一只异色瞳的白猫，筱九给她取名“飞雪”，一直带在身边，但奇怪的是，养了许久，飞雪却始终不见长大。",
	["tid#Herolegend1_311"]="南宫家世世代代享有世袭爵位，而到了这一代，因为南宫比哥哥小很多，故哥哥早早受封忠勇一等公，而这使得南宫的成长多了很多轻松的感觉，他享受着良好的教育和家庭环境，但是不用受世袭爵位的压力，成长为了一个且文且武的优秀公子。",
	["tid#Herolegend1_312"]="参加队长选拔的时候，史春莲显然低估了狼王的狡猾。狼王故意留下脚步让她追踪，最后将她引到了包围圈，一群狼包围了上来。就在这万分危急的时刻。一名小女孩突然从森林中走了出来，正是筱九。筱九先是喝止了狼王，接着走到了狼王的面前，狼群都自动让开了道路，似乎很是尊敬。筱九似乎是能听懂狼王的话，走到跟前说了几句之后，狼王就带着狼群离开了。筱九似乎从没有见过生人，对史春莲很好奇，一番询问后得知了史春莲的选拔，于是带她来到了一个地方。这个地方是狼群的墓地，所有的狼在临死之时都会来到这里。史春莲从这里拿走了一颗最大的狼牙，当做猎物的证明，赢得了选拔。",
	["tid#Herolegend1_382"]="李清秋家世世代代享有世袭爵位，而到了这一代，因为李清秋比哥哥小很多，故哥哥早早受封忠勇一等公，而这使得李清秋的成长多了很多轻松的感觉，他享受着良好的教育和家庭环境，但是不用受世袭爵位的压力，成长为了一个且文且武的优秀公子",
	["tid#Herolegend1_383"]="随着慕容清月年龄渐长，他在外人眼中一直是个身患重病、多半时间都在发呆的呆子，但很少有人知道，这位“疯子大爷”的表象下，其实是一个已经在上天飘渺难测的命运之河中掌握了航向的得“天道”的人。",
	["tid#Herolegend1_386"]="段徵言三岁背诗五岁识千字，10岁精通四书五经，13岁可作诗词歌赋，巧遇世外高人传得一身传奇武艺，不满15岁的段徵言已经提前功德圆满，父母欢喜的同时也在担忧，担忧段徵言文武双全若一念之间心存恶念，就会酿成大错。",
	["tid#Herolegend1_387"]="出生就投入到无尽的战斗中的天机，虽然战斗技术飞速提高，但是演算功能长期内存不足，对世间认知和自我认知极为匮乏，在被封印后才真正迎来了自我认知，确定了自己的人格，然而它也失去了自由……",
	["tid#Herolegend1_391"]="暂缺",
	["tid#Herolegend1_392"]="暂缺",
	["tid#Herolegend1_393"]="暂缺",
	["tid#Herolegend1_394"]="暂缺",
	["tid#Herolegend1_395"]="暂缺",
	["tid#Herolegend1_401"]="翟冬玄家中世代都是精于木匠的手艺人，说起来更是历代服务于王公贵族的官匠。翟冬玄，虽出身匠籍，却也自小聪明好学，不仅没有丢掉祖传的手艺，并且还熟读经义，考取了功名，进京入了工部也在京中揽了一官半职。",
	["tid#Herolegend1_402"]="天宝年间，前任明教四大法王之首，曾经肆虐武林的赤眼龙王萧沙被智慧王汇同白眉鼠王、青翼蝠王暗中搭救，率领亲信闯出了少林达摩洞，与其有深仇的各路豪杰闻讯纷纷出手拦截。其中便有挚爱被萧沙所害的恶人谷主人王遗风、挚友被萧沙所害的浩气盟主人谢渊、更有为门下讨公道的五毒教圣蝎使者阿岚以及察觉到惊天阴谋赶到的玄天君鬼谋李复。",
	["tid#Herolegend1_403"]="李延广攻打自己寨子那天，祥颖韬曾经远远的看到过他。当时他对这个身板瘦弱的小子根本就不在意，认为不过又是一个只有花架子的公子哥而已。可谁曾想，李延广的手段竟然异常的老练。祥颖韬想跟他拼计谋，但李延广却能猜到自己每一步的安排。祥颖韬想跟他拼武力，但寨子里最魁梧的大汉也在李延广手里走不过三招。第一次，祥颖韬想到了逃走。",
	["tid#Herolegend1_404"]="自从记事起，陆尘子便身在天忍凌峰楼的训练营，从小经历了严苛的训练和成长。那时候他并没有名字，只有一个类似代号的称谓——十一，而这个称谓甚至都让他付出了前半生的努力。他很厉害，但他没有任何朋友，他天生寒气逼人的眼神吓退了所有试图靠近他的人。",
	["tid#Herolegend1_405"]="虽然张景奇治愈赵心音身上的瘟疫，但还是落下了病根。不仅头发变成了白色，身体也变得体弱多病，远远望去，就如女性一般瘦弱。起初，张景奇给他开了许多滋补的方子，却丝毫不见效。于是张景奇换了一种方法，转而教他经脉运转、穴位之类的知识，帮助他改善体质。这次效果很不错，赵心音的体质得到了很大的改善，虽然依然瘦弱，但已经很少生病了。这也激发了赵心音对于经脉学的兴趣，从此之后赵心音就一边跟着张景奇在中原游历，一边学习。",
	["tid#Herolegend1_406"]="唐明月是如今唐门门主最小的女儿，与其他被父亲抱有很高期望的哥哥姐姐不同，唐雪枫并没有对唐明月有过高的要求。因此从小便无忧无虑的唐明月完全是一副乐天的性格，她常常在偌大的唐家堡四处探险，每每让家中仆人寻人不得。但是唐家堡再大也不过是蜀中一隅而已，而天下之大，又何止巴蜀呢？唐明月便想着等自己再长大一些就外出游历，亲自去看看姐姐说的外面的山河景色，反正自己的哥哥姐姐都那么厉害，唐家堡交给他们准没有什么问题。",
	["tid#Herolegend1_407"]="生在合欢阁下的朱英杰，原本被门派长老们寄予众望，正如同他的名字一样，希望他成为振兴合欢门楣的英杰。可谁知刚刚成人加冠的朱英杰，就在成人礼当天，患上了一场无来由的疯病，从此游荡在合欢阁的后山之上。",
	["tid#Herolegend1_409"]="早年间，关中郭巨侠乘船渡过河水，遇见一伙贼人作恶，彼时郭巨侠处处小心，却依然没有阻止一女子被害，令郭巨侠捶胸顿足，懊恼不已，而秦飞雪正是那名亡故的女子所留。那一天等渡船临岸，天空中便飘起鹅毛飞雪，犹如上天也不由得哀叹惋惜，于是为弥补自己没能救下该女子，郭巨侠决定认养此婴孩为义女，起名飞雪，又因地处三秦之地，便以此氏。",
	["tid#Herolegend1_410"]="她从小便知道，自己这名字，曾属于另外一个美丽的女孩，她叫米丽古丽，米丽古丽是父亲陆危楼捡来的义女，可是这个人的名字，好像在家里却成了禁忌，无人敢提。这个女孩现在身在何处？圣教的叔叔们常夸奖她玉雪可爱，都道她长大了定是个倾国的美人儿，可那位姑娘呢，是否也长成了个美女子？",
	["tid#Herolegend1_411"]="滔滔背着船锚沿着海岸来到安金，这是小萝莉第一次来到人这么多的地方，她发现这里的人都吃的很少，还用着她不认识的金属块做交易。滔滔闻着香味来到一个大饭馆，在小二和店家的目瞪口呆之下吃了三大桌的饭菜之后，结账却犯了难。时逢饭馆有恶霸来闹事，滔滔抡起船锚教训了二十几个壮汉，一下子成了安金的名人。",
	["tid#Herolegend1_412"]="仇人家为了报仇，用最狠毒的武器，将一种炙热的火毒输入到左寒修体内，导致左寒修不得不从小生活在寒冷的洞穴内，不得见天日，睡在寒铁制作的冷床上，练习各种至寒至阴的武功，来抵抗这种火毒。",
	["tid#Herolegend1_413"]="往昔的神水宫收下了一个女弟子，她来的那天，神水宫内的莲池里盛开着不尽其数的白莲，圣洁的白莲蕴含的露水映照着朝阳的光，不知怎的全部折射在这个女孩子身上，她就是玄水姬。她不凡的出现，似乎预示着神水宫即将到来的辉煌。",
	["tid#Herolegend1_481"]="永阳镇张氏一族，出了不少惊世骇俗的名医，世代都有人进京成为御医。张超原本就是这一代子弟中的佼佼者。后来族中另外一个子弟张景奇，也跟在张超父亲的身边，同他一起研习医术。",
	["tid#Herolegend1_484"]="宋英男的父母似乎与这个村子格格不入，靠海吃海的村子里，父母是少数不会游泳，还敬畏海洋的人了。还告诉年幼的宋英男，要和海洋保持距离。宋英男的父母是以织网为生的，村里其他织网的家庭都会在退潮的时候走到海边深处去捡破了的网，可是宋英男家不可以，只能拜托邻居家赶海的时候捡一些回来，一来二去两家的孩子就玩得很好，邻居家孩子是一个大宋英男三岁的小哥哥，水性很好，总是捡很多海贝回来给宋英男，她会打开贝壳，取出珍珠做成手链送给男孩。",
	["tid#Herolegend1_485"]="寺里除了一些其他和尚，就只有他一个小孩，他一直盼着能有一个伙伴一起做功课一起玩，直到寺里来了另一个小男孩，这个小男孩父母双亡，被师父收养了，而且老实听话，每日不是诵经就是练功，不几日就会了好几招，一招轻雪就能把稍微年长几岁的自己打倒在地。",
	["tid#Herolegend1_491"]="暂缺",
	["tid#Herolegend1_492"]="暂缺",
	["tid#Herolegend1_493"]="暂缺",
	["tid#Herolegend1_494"]="暂缺",
	["tid#Herolegend1_495"]="暂缺",
	["tid#Herolegend1_501"]="李知傲虽然是武当的掌门，年轻时却也做过和尚，与少林颇有渊源。传闻李掌门出生时母亲去世，父亲因伤心过度来到少林剃度出家，于是李知傲也跟着父亲当了和尚。",
	["tid#Herolegend1_502"]="正如他们诞生时发生的天体奇观，这对双胞胎清楚地知道自己生来就背负着宿命——姐姐的心智有如月光皎洁明亮，而弟弟的思想则好比月食时投下的一半月影。",
	["tid#Herolegend1_503"]="云隐岛远离中原，是一处清净的避世之地。曾有一群人逃离江湖纷争，隐居于此；他们的子孙后代，也都将云隐岛当成自己的家。因为是海上孤岛，云隐岛曾经土地贫瘠，颗粒无收，岛上的人过了一段艰苦的日子，直至句芒降生。他出生之时，草木繁盛，百鸟争鸣，似乎能感知到他的生命；而他也自幼能与动物沟通、能控制植物抽枝发芽，仿佛有着异于常人的自然之力。从此以后，云隐岛四季如春、生意盎然，作物也是年年丰收，无论是不是因缘巧合的缘故，生活逐渐富足的人们对句芒敬重有加，尊称他为“春神”。",
	["tid#Herolegend1_504"]="霍紫凝的家曾在普陀山脚下，那儿是一片宁静的村落，宁静到每晚只听见断续的捣衣声。这是霍紫凝与母亲长年累月浣衣的劳作曲，也是她们的哀歌。她出生于贫苦的平民家庭，自小随母亲以女工养活家计，父亲是个不管事的浮浪子，每每总把母女俩辛苦赚来的银两或偷或夺地拿去挥霍。为了温饱，母亲带着年幼的慈航白天做女工以外，晚上继续替人洗衣。",
	["tid#Herolegend1_505"]="萧春风的过去鲜有人知，不过逍遥派的弟子中间也流传过一些说法。萧春风的亲生父亲是个赌徒，四处举债导致家徒四壁，当萧春风的母亲生下她的时候，一家子还在到处躲债中。后来一次趁母亲外出觅活，父亲将箫春风卖给了一对无子的中年夫妻。",
	["tid#Herolegend1_506"]="周文浩自打四岁起就在父亲的严厉要求下开始习武，其修炼的苦行程度远超常人想象，甚至三天三夜为练武滴水未进，年幼的周文浩不解为何父亲如此这样严格，一旁知晓内情的母亲阻止不得也只能是叹息连连。尽管如此，周文浩出色的天资还是让他咬牙撑过了艰苦的修习，打下扎实基本功的周文浩得以得到各位名师的指导，本来修习多门武功极易走火入魔，而周文浩却硬是凭着幼年打下的底子生生吃透了多门武学，并融会贯通独创出自己的一套天龙刀法。",
	["tid#Herolegend1_507"]="蜀山派有个让人烦恼的小师弟，每次早课都寻不到的他的身影，每次这般，大师兄都会让人去蜀山琅寰阁去找他，而这位在琅嬛阁中嗜书如命的小师弟正是梁钲雨。一些看不惯此事的弟子便想着门派长老们告状，说这小师弟目无遵纪，却都被大师兄阻止，后来方知这小师弟本就是受掌门故人相托，庇护在蜀山之内而已。",
	["tid#Herolegend1_508"]="世人皆知，唐公霸王枪冠绝天下，无人能敌，但其实若论风雅，也不输江湖中的文人墨客。唐家的小公子唐寅，自幼仪表堂堂，文武双全，一手霸王枪承家族之精髓，诗作画作亦是双绝。与很多名门相同，唐家也在负盛名的那一日，便被天忍教盯上，欲除之而后快。为让年少的唐寅多见些世面，也为他不被灾祸殃及，十八岁时，母亲便让他离家，外出游历。",
	["tid#Herolegend1_591"]="暂缺",
	["tid#Herolegend1_592"]="暂缺",
	["tid#Herolegend1_593"]="暂缺",
	["tid#Herolegend1_594"]="暂缺",
	["tid#Herolegend1_595"]="暂缺",
	["tid#Herolegend1_607"]="自小生活在西山的求伯君，很早便展现出惊人的武学天赋，开明的父亲为了求伯君能够发扬自己的天赋，便托乡里有本事的人将求伯君送入了名门金山派继续研习武学，而求伯君也不负众望，在金山派中一鸣惊人，以其惊人的天赋与刻苦修炼的品质，被老掌门赏识，不出几年便成为了金山派的首席大弟子。",
	["tid#Herolegend1_606"]="出生于西南高地的桑耶寺，从小被寺僧抚养长大。养至半岁，仍不会说一语。某日，僧人抱其于树下听讲经，鸠摩罗若有所思，于地上手划一个法源之字。桑耶住持惊叹，称其为龙树菩萨转世。后来被问起这桩事的时候，他只说自己见到了圣人的影子，而那影子教会了他这个有趣的字。至今仍没有人能用常理解释于此，便只道是与生俱来的天赋，对他更加敬重几分。",
	["tid#Herolegend1_602"]="她出生在一个机关师的家庭中，父亲是一名优秀的机关师，他一直很爱自己这个女儿。吕珂虽然长相平凡，但是聪明过人，很小的时候就能掌握很复杂的算数与术数，而且动手能力也极强，但没有堕下山崖之前，她已经可以像父亲一样做出复杂的机械，擅长将各种各样的算式熟练解出。",
	["tid#Herolegend1_603"]="若干年前，天山脚下的一对老夫妻推门而出时，发现门口正躺在一个浑身赤裸的婴儿，这个婴儿正是天山。没人知道她的父母是谁，也不知道她如何来到的这里。善良的老夫妻收养了这个孩子，老先生姓柳，为她取名为柳念，意为念想着自己的来处。",
	["tid#Herolegend1_604"]="刘异生于一处偏僻的苦寒之地，那是一座雪山，终年被冰霜覆盖，寸草不生。这座山被称为“御雪山”，听闻曾经有绝世高手能以真气驾驭冰雪，在此建立门派，也曾鼎盛一时。但到了刘异这一代，却从未见过有什么高人，只知道整个村子都穷困潦倒、民不聊生。刘异的父亲游手好闲，靠母亲替人浣衣的收入艰难为生，刘异的出生，更给这个贫困的家庭增加了一分负担。他从小没得到过什么关怀，但也似乎对此并不在意。在别的孩子嬉笑打闹之时，他只喜欢看着山上的冰雪出神。",
	["tid#Herolegend1_605"]="庶出的周今鸣，在逐渐落寞的家族里浑然不受父亲待见，而且女子身份以及沉默寡言的性格让她从小在家族中本就不甚讨喜。相较于大哥沉稳博学，二弟精进敏捷，作为三女的周今鸣从小就如同奴婢一般，受尽冷眼与虐待。",
	["tid#Herolegend1_691"]="暂缺",
	["tid#Herolegend1_692"]="暂缺",
	["tid#Herolegend1_693"]="暂缺",
	["tid#Herolegend1_694"]="暂缺",
	["tid#Herolegend1_695"]="暂缺",
	["tid#Herolegend1_701"]="作为南疆乌蒙灵谷大巫祝之子，从小就被村人寄予厚望，因而被母亲严格管教。可是他的内心渴望也同样像普通孩子一样，希望从母亲这里得到关爱和温暖，只不过韩休宁却只把他当成未来的大巫祝培养，从不表露一丝柔情。也许这就是难以抗争的宿命，乌蒙灵谷的大巫祝毕竟要承但守护凶剑焚寂封印的重大使命，难以像寻常人那样活得自在轻松。",
	["tid#Herolegend1_702"]="晴雪在去往人间之前，一直居住在幽暗无垠的地界，对人间的了解最初只是通过一些书册和传闻得知，所以她喜好古怪，经常显得一知半解，语出惊人。晴雪之父虔诚地信仰女娲，生前的愿望便是自己的一双儿女都能进入娲皇神殿侍奉大神。",
	["tid#Herolegend2_101"]="正当她绝望地闭上眼睛时，却听到了一阵急促的马蹄声，踏破了滚滚黄沙。一支精悍的骑兵从黄沙中冲了出来，将马贼们冲撞得七零八落。为首的一人头戴金冠，一双雪亮的眼睛，不怒自威，他扫视着地上镖师们的遗体，皱了皱眉，一抖猩红的披风：“一个也不许放过！”骑兵们面无表情，举起长刀，策马奔突，将一个个逃跑的马贼全数逮捕。林姑娘抬起头来，透过迷乱的风沙，她看到一面赤红的大旗，旗上的三个字迎风招展：“天策府”！而率领这队大唐铁骑的人，正是天策府的统领——李承恩大将军。",
	["tid#Herolegend2_102"]="王司马离开家后，遇到了一些志同道合的朋友，大家致力于用自己的力量维护他们心中真正的秩序。不过王司马在世人眼里已经变成了一个走到哪炸到哪的爆破狂魔了，直到在一场她策划的“烟花爆破晚会”上，与她的同胞姐姐--李郡相见……",
	["tid#Herolegend2_103"]="李延广现在是守卫力量中备受尊敬的将帅，守护着长安的秩序——重点照顾那些胆敢挑战铁鹰巨弩底线的狂热罪犯。他最近找到一位来自弘武郡的新搭档，急躁鲁莽的李郡。这对不可思议的组合究竟是如何诞生的，又究竟为何能够如此高效，一直是街头巷尾热议的话题，更是他们的同事在饭过三巡后的谈资，甚至就连那些被他们送进牢房的嫌犯也感到十分好奇。",
	["tid#Herolegend2_104"]="李郡成长过程中总是会遇见说她没爸没妈的坏小孩，一般情况下她都会直接上手，懒得多解释什么。她一直跟着地下帮派从小混到大，很快就学会了利用头脑和双拳生存下去。每个遇到过她的人都会见识到她用言辞——或者蛮力——摆平麻烦事的本领。当然，大多数时候还是后者。",
	["tid#Herolegend2_105"]="在少林经过了一段时间的修行之后，清觉对修行内容的见解愈发深刻，但清觉自己却一直保持谦恭，认为门派经学高深，大道无边，自己也仅是懂得了所谓智慧的一隅，而清梵却对此不屑一顾，还是继续着自己的破戒行径。有一天，住持想要考验两人的修行成果如何，在辨论中，清梵对住持的提问支支吾吾，而清觉则对答如流，对清觉颇为满意的住持于是让清觉得以离开少林，前往蓬莱岛进行武学的修习，未被邀请的清梵则偷偷跟上了去往蓬莱的小船。",
	["tid#Herolegend2_106"]="江湖上一直在讨论谁才是最厉害快刀手，有人说是刘关江，因为他从没有失手过一次。有人说是赤影，因为从没有人见过他的真面目。也有人说是那个神龙见首不见尾的首领，因为他曾经击败过当年那对神仙眷侣。关于这样的争论一直在大陆各处的茶馆中上演，争论不休。但如果你问，谁是最无情的快刀手，相信所有人都会异口同声的回答你——刘关江。绝情、绝欲、绝灭，这就是刘关江。",
	["tid#Herolegend2_107"]="老兵将他带回了玄甲堡，暂且安顿了下来。老兵问他的名字，他从不开口，索性老兵用自己的姓和玄甲的云为他命名为燕云，只是后来别人问及名字，他都说自己叫燕云飞，对此，老兵也从不过问，任由他自己决定。",
	["tid#Herolegend2_108"]="张昊从小便不爱修行枯燥的正一派道法，恰恰相反，他是一个很精明的人，老天师曾经一度都非常头疼。但是张昊又是个十分聪明的人，他很小就喜欢翻看天师门的账目，似乎对钱财非常有兴趣，老天师起初也并未在意，但是后来惊讶的发现天师门在张昊的手下被打理的井井有条，原本清苦的门派反而慢慢的富裕了起来。",
	["tid#Herolegend2_109"]="性命为上，尊严为次\n禹海莲在己方军队不敌的时候会想尽一切办法逃离战场，因为她知道，她一个人的生命背负了两个人的意志，包括她哥哥的意志，她要继承下去，某次她在沼泽出战，中了埋伏，她钻进了沼泽地的一根中空的树干，树干中布满了淤泥和爬虫，可她仍旧觉得，待在树干中躲避的这两个时辰，捉捉身上的虫子是很好的打发。",
	["tid#Herolegend2_110"]="暂缺",
	["tid#Herolegend2_111"]="然而在蓬莱习武开悟期间，她收到了一封带着噩耗的信件——由于动乱，叛军占领了她的家乡，奶奶也被卷入其中，不幸去世。此时此刻，公孙雨突然就变成了一根失去了母体的羽毛，随风而逝，再也没有了根。",
	["tid#Herolegend2_114"]="暂缺",
	["tid#Herolegend2_115"]="当上了天鹰之后的他，才发现，这一切才刚刚开始，他需要经历更加艰险的磨练，需要更加刻苦更加勇敢，磨砺出更加优秀的战斗和求生技能。还好方剑斌足够坚毅，也沉得住气，族人都说他是历代天鹰中成长最快的，但是他不满足于此，为了和战鹰有更深刻的羁绊，他去往了蓬莱。",
	["tid#Herolegend2_181"]="那一年，山庄发生了蒙羞的大事，妹妹为名剑山庄所致自戕性命，二弟不满父亲对名剑姜家的态度，离家出走一去不归，而如今姜家再次来人冒犯山庄，所有的压力一瞬间扑到了郭惊涛的头上。此刻郭惊涛作为山庄的大公子站了出来，他必须捍卫山庄的威严——很显然父亲不作为，父亲对名剑无来由的百般妥协；二弟毫无音讯，他原本才是家族的继承人。所以，他心中的愿望如果想要实现，就必须在此时挺身而出，代表神刀门与名剑山庄交涉。",
	["tid#Herolegend2_182"]="杨素素出生之后家里多了女孩，虽然不能帮忙种地但是却多了纺织这条赚钱的路，但是似乎父母总是不开心。父亲的身体开始大不如前，村里的人说杨素素漂亮得过头，没准是妖精托生，年少的杨素素不懂什么是妖精，却也知道这些不是什么好话。",
	["tid#Herolegend2_183"]="战争带走了萧不语宁静的生活，也带走了他幸福安稳的家庭生活。敌军的到来使得萧不语获得了与之前大不相同的人生目标，从军。",
	["tid#Herolegend2_184"]="当上了天鹰之后的他，才发现，这一切才刚刚开始，他需要经历更加艰险的磨练，需要更加刻苦更加勇敢，磨砺出更加优秀的战斗和求生技能。还好方剑斌足够坚毅，也沉得住气，族人都说他是历代天鹰中成长最快的，但是他不满足于此，为了和战鹰有更深刻的羁绊，他去往了蓬莱。",
	["tid#Herolegend2_191"]="暂缺",
	["tid#Herolegend2_192"]="暂缺",
	["tid#Herolegend2_193"]="暂缺",
	["tid#Herolegend2_194"]="暂缺",
	["tid#Herolegend2_195"]="暂缺",
	["tid#Herolegend2_201"]="那件事之后父母和身边的人发现了韦壮武似乎很能打，就让他到林良骏家的镖局帮人走镖，可是林良骏的老师都教不了他，只是给了韦壮武一把斧子，说动粗之前，要考虑一下这柄斧子的轻重再下手。虽然这样他很少再随便动粗，但是他内心十分纷繁混乱，于是韦壮武想起来，总有另一种方式可以解决问题，他决定拉着林良骏一起去寻找答案。回来之后，大家都说他还是像以前一样是个莽撞人，但是韦壮武知道，他已经跟以前不一样了。",
	["tid#Herolegend2_202"]="黄荣华的父亲是靠着一身武艺闯起来的硬江湖，声名浩大，可惜天有不遂，英年早逝，年幼的黄荣华，继承了父亲的天赋和武器，被送到父亲的故交家抚养。少年黄荣华凭着自己对武艺的理解，改造了父亲的双鞭，改做双环，在继承了父亲武功招式的同时，加强了灵活性和破坏性。但他对自己的实力还一无所知。",
	["tid#Herolegend2_203"]="谁知刑伯严大哥一考，又是个探花，刑园众人都闷闷不欢，只望刑小公子能争气，谁知命不由人，这位小公子虽然惊才绝艳，但一考之下，却还是个探花。大哥和父亲都失望至极，相继去世，刑伯严也辞去官职，在家里疏才结客。",
	["tid#Herolegend2_205"]="靳辰洋练武三天打鱼两天晒网，但凭着自己身体底子还不错倒也学会了三招两式。直到某天，一伙悍匪上门打劫府上，又打又砸无恶不作，把靳辰洋府里的护卫都打了个七荤八素，靳辰洋的父亲也在这次冲突里受伤，嚣张的匪徒甚至要放火烧了宅邸，这时在山林里游玩的靳辰洋才火急火燎的赶回来，凭一人之力把匪徒全部打退，并让他们再也不敢冒犯家里。面对受伤的父亲，靳辰洋发誓自此一定专心习武，来保护自己珍爱的人和事。",
	["tid#Herolegend2_206"]="沈念打小就表现出对武功的兴趣，身为丐帮帮主的父亲自然是乐意教授，且别说是郭岩，就是丐帮的其他长老都对这个丐帮的小公主疼爱有加，有些从来不肯将自己的独门绝技分享的人，也通通对沈念倾囊相授。让丐帮长老们更可喜的是，这小公主仿佛练武的天才，沈念将他们传授的武艺几乎都能融汇贯通，更让人惊奇的是她似乎还在其中夹杂了很多西域武功的技巧，沈念分明没有学过任何西域武功。每每想到此事，这帮老家伙不禁都啧啧称奇。",
	["tid#Herolegend2_207"]="又是三年之后，宁不凡二十三岁，三年的时间里，他经历了喜怒哀乐，爱恨情仇。他遇到了一个女人，一个男人，一个像女人的男人。他主动找师父饮起当初喝过的佳酿，微醺之后，他像师父展示了身上和心上的伤疤。第二天，师父教了他第三式剑法，名曰“红尘”。但这一次，师父却没有留他在身边练剑，而是告诉他。师父能交给他的，已经没有了，接下来的路，全要靠他一个人了。什么时候他把这三式剑法合为了一式，就到蓬莱下找他。于是，宁不凡最后一次下山去了……",
	["tid#Herolegend2_208"]="辛晓风十八岁的时候，住持师太把他叫到了身边，告诉了她一些事情。原来辛晓风的头发，既是她的能力，又是她的弱点。辛晓风的头发就是“情丝”，代表着她的七情六欲，剃去了头发，就会让她丧失七情六欲，小时候的她就是因此昏迷的。而从蓬莱回来之后，她的头发又多了一种新的力量，就是可以吸收别人的七情六欲。所以师父向让她下山历练，既是增长力量，又是磨砺道心。于是辛晓风下了山。",
	["tid#Herolegend2_210"]="爷爷闲下来就会拉二胡，失明的吕沛杰发现爷爷拉二胡的时候他自己能够感受到院子里的建筑，慢慢还能感受到路过的家丁。",
	["tid#Herolegend2_211"]="云梦山附近一直流传着一个传说：云梦山中住着一位老神仙，就住在舍身崖下。若遇到困难或想不通的事，只消准备一壶好茶，一根长绳，一个竹篮。把问题写在纸上，和茶一起放在竹篮中缓缓放下舍身崖。第二天再来时，茶水会消失，问题的答案也会写在纸上。老神仙似乎无所不知，奇门八卦，星象占卜，人情世故，治国修身……所有的问题都能得到解答。不过可惜的是，最近老神仙已经很久没有显灵过了。",
	["tid#Herolegend2_212"]="吴清霄拜师之时，华山上的纯阳宫尚未建成，于是吴清霄便跟着吕祖四处云游，同时还有一位师兄同行，这位师兄便是谢云流。随吕洞宾云游布道的日子里，除了师父，待他最亲的人便只有这位大师兄谢云流了，是以两人亲如兄弟，感情非常深厚。不过吴清霄渐渐还是发现，虽然自己勤勉好学，能够下到“三冬抱雪眠，六夏迎阳立”的苦工，但是自己终究没有师兄那样的极高天赋，并且似乎师父也更加偏爱天资更佳的师兄。尽管如此，吴清霄很快便也就释然了，所谓道者，有情有信，无为无形，可传而不可受，可得而不可见，终究是修自己的道心。",
	["tid#Herolegend2_213"]="童年刚过还没到16岁的喻扬超就被父亲送到外邦读书了，他阅读了大量外邦的文学作品之后，他发现自己带到外邦来的这些窜天猴其实有更好的用处。",
	["tid#Herolegend2_281"]="这间客栈的掌柜的，是一个相貌非常凶恶的人，一手快刀挥舞起来让人眼花缭乱，江湖人称“沙里飞”。龙门附近都传闻这间店是间黑店，专门坑害初出茅庐的江湖菜鸟，甚至还有“人肉包子”的传闻。可焦渝钦知道，那些不过都是噱头，掌柜的其实是个十分善良的人。",
	["tid#Herolegend2_282"]="没有什么盘缠的胡大壮之旅日子过得很苦。不忍心伤害小动物的他基本上靠包食宿的短工和野果解决温饱。不过正经人家看到他的打扮和体格并不大愿意雇他，主动过来招揽他的通常都是横行乡里的无良恶霸……在第三次打断东家的腿后，胡大壮结识了拉二胡的吕沛杰。",
	["tid#Herolegend2_283"]="「小姐会和蛇说话！」这是在下人里炸开的一句话。\n小欧阳慧不明白自己做错了什么，她只是在角落救下一条小白蛇，和它聊了几句，就被路过的仆人像见了鬼一样大喊大叫。她看见了父亲紧皱的眉头，母亲慌张的眼神。很快，她随父去了一趟金城，在郡守的陪同下，她见到了一位神秘的黑袍人。父亲恭谨的叩拜在他的脚下，黑袍人却望着她，点了点头。",
	["tid#Herolegend2_291"]="暂缺",
	["tid#Herolegend2_292"]="暂缺",
	["tid#Herolegend2_293"]="暂缺",
	["tid#Herolegend2_294"]="暂缺",
	["tid#Herolegend2_295"]="暂缺",
	["tid#Herolegend2_301"]="每当有人问起张景奇的朋友，他总是不假思索的回答——况候智！但你若是追问他况候智是谁，他却总是笑着不说话。有人说他爱卖关子，有人说况候智是他杜撰出来的，但他还是笑着，不承认也不否认。因为他答应过况候智，不会向人透露他的行踪，否则下次一起下棋时，可就没有上好的茶喝了。其实张景奇对他这位神秘的朋友也是知之甚少，只知道他爱喝茶，爱下棋，爱卖关子。他们初次相遇是在云梦山，当时他三十五岁，正在一处悬崖上采摘草药，忽听得一声：“小子！来喝一杯吧！”吓得他差点从悬崖上摔下去。之后他寻声望去，才在一处绝壁上的山洞中找到了他。况候智也不废话，一壶茶就递了上来：“喝！喝完陪我下棋！”，张景奇也是一愣，但却没有拒绝，只是轻笑着摇了摇头“真是个有趣的老头。”",
	["tid#Herolegend2_302"]="不过她的适应能力很强，不久她就明白了浮华的生活并不是必需品，她需要快速让自己强大起来才对得起出来一趟，所以去了蓬莱。",
	["tid#Herolegend2_304"]="另有一桩，花间派中多是女子，公孙大娘却不愿她们受到一点委屈，故而要这接任之人除交际之手段之外，还需魄力有若男子，花间之中，虽然待人处事圆满者有之，坚毅好强者有之，但两者皆有，且融合得恰到好处之人，唯有苏婉仪一人，她于温柔之中隐藏锋锐，虽圆滑隐忍，却非萎缩柔弱，紧要关头，往往有惊人之决断，故而将花间交于苏婉仪，公孙幽很是放心。其后数年来，年轻的苏婉仪所领的花间派在江湖中已经成为不可忽视的势力。",
	["tid#Herolegend2_305"]="家族的核心是使用了未知能源，无论何时都亮如白昼的机关堡垒“天机楼”。早就对天机楼的动力来源好奇的她利用研究院士的身份潜入天机楼地下动力室并破解了机关锁，在那里她遇到了作为能量核心而被封印的“天机”。被天机深深吸引的她帮助天机成功逃走。而失去了动力的天机楼中，长老们怒发欲狂。不得已的家主只好放逐了她，并暗示她前往蓬莱参悟天地之理。于是，千里驹的千里之行开始了。",
	["tid#Herolegend2_306"]="长大了之后，姜笑川便疯狂渴求权力，依靠自己的聪慧，他成功考取了功名，进入了官场。此后更是一路攀升，成为了朝中的一名重臣。凭借获得到的权力，他做的第一件事就是为当年的父亲翻案，他将多年来积攒的证据全部拿了出来，交由大理寺重新审理，经过不懈的努力终于为父亲翻了案，还了父亲的清白，并惩治了当年的恶人。",
	["tid#Herolegend2_307"]="姜承影懵懂无知之下，却是被人贩子一路带到西南巴蜀一带，卖与当地一个退下的官吏。那官吏老来得子，张灯结彩将姜承影迎来，但姜承影年纪虽幼，却能辨别此地并非己家，当下已知上当。他当日柔顺听话，却在夜里翻窗出户远遁了。蜀地与江南远隔数千里，他在名剑长大，怎知家在何处。姜承影聪慧伶俐，沿街乞求些稀粥残汤，却是不学便会。",
	["tid#Herolegend2_308"]="安金的名人可不止滔滔一个，其中便有太极门周宗师这个驰名中原的修行高手，滔滔听说他也曾登顶过蓬莱。滔滔独自修行很久，一直没有什么大的作为，老渔民临终的遗言是让她变强，于是她暗暗在心里下决心要以周湘君为榜样，变得更强！",
	["tid#Herolegend2_309"]="盛年的周湘君已有了很多成就，虽然名满天下，依旧淡泊如初，有了很多弟子，但是最最得意的是小徒弟滔滔，滔滔眼里清澈的和身体里蕴含的巨大的能量，让周湘君时刻谨记着要帮助小滔滔处理好这种潜藏的热动能量。",
	["tid#Herolegend2_310"]="筱九十四五岁的时候，在森林中遇到了史春莲，从史春莲口中，她得知了森林之外还有着很广阔的世界，于是便萌生了离开这个森林的想法。她把这个想法告诉了母亲，但母亲告诉筱九，每一任圣女在长大之后都要被送往族中的圣地——万灵树，从此常伴在万灵身边。筱九想反驳，母亲却第一次斥责了她，并禁止她再外出。被禁足之后，筱九仍会偷偷和史春莲相会，她想把自己的痛苦告诉史春莲，但天性善良的她却不想让史春莲为难。直到十六岁生日的那天，她前去举行圣女的传承仪式，在获取了圣女代代传承的力量之后，她就要前往神树，从此常伴万灵。绝望之际，史春莲突然出现了，大闹了传承仪式，不由分说就拉着她逃离了族中。自此，筱九终于可以看看外面的世界了。",
	["tid#Herolegend2_311"]="李清秋从小力气奇大，肌肉的组成和一般人并不一样，导致李清秋身体线条优美健硕但是不粗鄙，受到重击也不会获伤，养成了他隐忍的性格，因为他被打不会受伤，而随便出手常人就未必受得起。",
	["tid#Herolegend2_312"]="史春莲有条狼，叫做“小夜”，因为这条狼的背部是一片漆黑，这头狼长得异常的大，史春莲甚至可以骑上去。筱九有一只猫，名叫“飞雪”，因她通体雪白。飞雪很小，能够被筱九抱在怀里，但小夜却很怕它。每次见到筱九时，飞雪都会跳到小夜的头上，像是把小夜当做了自己的坐骑。",
	["tid#Herolegend2_383"]="慕容清月三岁时因姜笑川主导的朝廷叛变案件，中了解秀朝一枚“阴雨针”，从那时开始，慕容清月的一生多半时间便处在噩梦之中。在梦中，那些行凶者持续的追逐着母亲、诸位姑苏慕容下弟子与在母亲怀抱中的自己，直到慕容清月在挣扎中听到一缕琴音，从身体血肉经脉中传达而来，将他拉出了噩梦。",
	["tid#Herolegend2_386"]="段徵言父母遍地寻求能够指引段徵言的老师，只是天不遂人愿，段徵言父亲突发重疾，不久于人世，段徵言成了母亲唯一的依靠，他犹记得那个世外高人提过的蓬莱，他决意在父亲有生之年， 一定让父母对自己放心。",
	["tid#Herolegend2_387"]="拥有无与伦比演算能力的冉无名，只是服从“父亲”的指令采取行动，本身对墨家一族没有任何仇视和怨怼，因为禁锢的一千年对于自己来说也是自己“人生”的一部分，是真正诞生“自我”的契机之一。",
	["tid#Herolegend2_391"]="暂缺",
	["tid#Herolegend2_392"]="暂缺",
	["tid#Herolegend2_393"]="暂缺",
	["tid#Herolegend2_394"]="暂缺",
	["tid#Herolegend2_395"]="暂缺",
	["tid#Herolegend2_401"]="因为掌管了一些京城关键的城建，也受到当时一位宗室的器重，便开始为宗室营建陵墓，并且迎娶一位漂亮的叫做苏环儿的女子为妻。他非常喜爱自己的妻子，也愈加兢兢业业，希望能在长安为二人构建一个良好的生活环境。",
	["tid#Herolegend2_402"]="阿岚小时候十分善良，她会帮助在山林里遇到的小动物，一来二去她身边总是跟着一些小兔子小鹿什么的，可就在她还不那么认识毒药的时候，她不小心给小白兔喂了毒药，又给兔子喂了家传灵药，可兔子小小的肝脏哪能负荷的了这些，看着小白兔躺在绿色草地上浑身抽搐吐白沫的时候，她哭了很久一直在跟小白兔说对不起，至此之后她对用毒非常谨慎。",
	["tid#Herolegend2_403"]="祥颖韬逃跑的计划却还是被李延广算到了。李延广早就派弓箭手埋伏在了密道口，一轮箭雨过后，祥颖韬曾经引以为傲的武功在对方的算计之下毫无作用，他的脸上也被一支羽箭划开了一道又长又深的伤口。祥颖韬又气又恼，拼劲全力终于突出了重围，但他的曾经的骄傲却永远留在了山上。",
	["tid#Herolegend2_404"]="传闻天忍凌峰楼有天罗十大高手，这十人更是从凌峰楼众多的弟子中甄选而出，然而陆尘子花费了自己很多努力都无法进入这十人之列，始终停在十一之位止步不前。孤独的陆尘子很困惑，他也只能不断完成自己的任务来证明自己的实力。",
	["tid#Herolegend2_405"]="从蓬莱下来之后，赵心音就经常会做一个梦，梦中的他，躺在一片花丛中，从紧闭的双眼和平静的表情中看不出是死是活。他的周围开满了各色的鲜花，其中一株开得尤为绚烂，硕大的花朵压弯了茎，几乎要垂到他的脸上。他认得那朵花——虞美人。一种很美，却有毒的花。这个梦总会已所有花的凋谢告终。从这个梦中，他察觉到了宿命和孤独。梦里的他，始终是一个人，如今的他，也是一个人。纵使开的再绚烂，也终会凋零，这或许就是我的结局吧，赵心音自嘲道。",
	["tid#Herolegend2_406"]="自从姐姐唐明玉被父亲安排嫁给那太行神刀的少庄主，姐姐便一直闷闷不乐。唐明月哪里受得了姐姐这般整日哀愁，于是便帮着姐姐与自己的心上人一起逃离了唐家堡。唐雪枫得知后无比震怒，但在唐老太太的袒护下，也无可奈何。然而唐明月还是受到父亲迁怒，被罚以后不准踏出唐家堡一步。唐明月似乎代替姐姐成了笼中的金丝雀，再没能亲自去游赏山河，只好从外出游历的弟子与姐姐的信中，在心里勾勒出姐姐见过的山川景色，似也能在梦里跟随姐姐的脚步，寻遍天下美景与奇闻怪景。",
	["tid#Herolegend2_407"]="实际上，知道内幕的阁主与大长老，是为了保护朱英杰的安危，才故意让他扮作疯病，并派了专门的弟子每日为他递送食物。其实朱英杰的有着极为罕见的古怪天赋，非常适合修习合欢阁的至高武学，然而这样的天赋也被江湖上一个可怕的组织给盯上了，他们要求将朱英杰收入他们的门下作为天罗十人的候选。",
	["tid#Herolegend2_409"]="过些年，巨侠的妻子临盆，也得一女儿便是郭香香，不过巨侠依然将秦飞雪当作亲生女儿一样对待，秦飞雪与郭香香二人也是以姐妹相称，一同长大并随着巨侠一同习武。后来巨侠在京为官，一家定居在长安之后，坊间的街头上便逐渐有了姐妹二人的身影。",
	["tid#Herolegend2_410"]="九月十三那天，也是个雨天，陆小贝又在街头雨里玩了一整天，到黄昏时分，她便又乐呵呵地跑到娘的房里闹，娘便笑着逗她……这天是大唐开元二十七年九月十三，中土明教顶尖儿的人物齐集于长安大光明寺，明教教主陆危楼这天便要亲自主持发动全教谋划已久的“圣火”行动，消息泄漏，明教高层受“东都之狼”天策府与少林高手围攻，唯有明教教主陆危楼一人漏网。",
	["tid#Herolegend2_411"]="安金的名人可不止滔滔一个，其中便有太极门周宗师这个驰名中原的修行高手，滔滔听说他也曾登顶过蓬莱。滔滔独自修行很久，一直没有什么大的作为，老渔民临终的遗言是让她变强，于是她暗暗在心里下决心要以周湘君为榜样，变得更强！",
	["tid#Herolegend2_412"]="终于有一天，左寒修练就了寒冰掌，他内调气息，中和掉了一部分身体内的火毒，总算是可以走出洞穴得以见天日，可他决定找到一种方式彻底去除这种火毒，所以来到了蓬莱。",
	["tid#Herolegend2_413"]="玄水姬无疑是整个山庄的骄傲，她天赋异禀，博闻强记，很快便将神水宫的武功融会贯通，老宫主便将毕生所学通通交给了这个仿佛身伴光华的天池圣女。不负老宫主所望，玄水姬果然将老宫主传承几代的神水绝学融会贯通，并开创了新的绝学。",
	["tid#Herolegend2_481"]="起先，张超很喜欢这个与自己年纪相仿的人，两人一同学习医术，也同样是学业之余的玩伴。可渐渐的，父亲越来越看重这个“外来人”了——尽管张超的天赋已经非常卓越了，却依旧比不过张景奇。张景奇不出几个月便小有成就，完全超越了已经苦学良久的张超。",
	["tid#Herolegend2_484"]="时间过的很快，两个人都到了情窦初开的年龄，而双方的父母，似乎还没有发现这些小心思，只是两个人越长大，就越多了自由的时间，而懵懂的两个人，就顺其自然的发生了两个人都还没有概念的事情。一切都太过青涩，甚至宋英男都不知道自己已经有了身孕，还是母亲发现了，质问之下，宋英男才和盘托出。",
	["tid#Herolegend2_485"]="摩波旬身体本来就不好，在寺里总是吃素斋饭，就更加跟不上成长步伐，跟清觉一起上山砍柴下山挑水的时候，他总是溜走去想方设法捉些野鸡野兔吃，肉食极大地满足了他的口腹之欲，却也打破了他本该遵守的清规戒律。他每次吃肉都会小心翼翼，害怕自己的师弟告诉师傅自己偷吃肉的事情。其实清觉发现了，每次都念经，他看清觉念经以为隐藏的很好，其实清觉在给他手下的野鸡野兔超度……",
	["tid#Herolegend2_491"]="暂缺",
	["tid#Herolegend2_492"]="暂缺",
	["tid#Herolegend2_493"]="暂缺",
	["tid#Herolegend2_494"]="暂缺",
	["tid#Herolegend2_495"]="暂缺",
	["tid#Herolegend2_501"]="原本的李知傲也只是一个修禅的小僧，不曾跟着武僧们一起习武，方丈觉得他的体质不适合那些横练筋骨的外功功法。但是他的父亲还是求了方丈，于是乎方丈只好教了他一些内功心法。",
	["tid#Herolegend2_502"]="天命加身的昆仑双子姐弟自然不能辜负众望。他不知疲倦地操练着神秘的双生乐器，在训练时饱尝血汗，姐姐的琵琶由月光石打造，能弹奏最高频的的曲调，其声铮铮，可以振奋人心；弟弟的箜篌由暗月玄铁铸造，其声泠泠，可以抚慰伤痛。",
	["tid#Herolegend2_503"]="句芒带来的奇迹，被人们视作神明的恩赐，渐渐地，岛上人人敬仙、修仙，云隐岛变成了一处清修之地。起初，修仙只是出于对神的敬重，虽一片虔诚，却难免不得要领。某天，一个名叫逸心的蜀山弟子来到云隐岛，因岛上灵力充沛，在此清修了几日，也在几日之内，将自己在门派所学倾囊相授。因性情相投，句芒和逸心很快成为了知己，彼此以兄弟相称；得到了清修心法的岛民也视逸心为恩人，虽然他离岛后很久没有再次到访，但蜀山与云隐岛从此结下了交情，句芒也一直和逸心保持着书信往来。",
	["tid#Herolegend2_504"]="霍紫凝长大后，母亲身染沉疴。父亲抢走了慈航辛苦攒下用来救治母亲的医药钱，眼看母亲即将不治，霍紫凝从游方至此的赵心音口中了解到救治母亲的一株千年何首乌生长在绝壁之上。她毅然决定动身，背负母亲跋涉整整一夜，抵达绝壁山崖下，只为一旦取得何首乌就赶紧给母亲服下。",
	["tid#Herolegend2_505"]="然而萧春风的童年依旧不幸。她的养父母都嫌弃她是女孩不能干农活所以对她横挑鼻子竖挑眼的，她整日以泪洗面。后来随着萧春风长大，养父母见她生的越来越俊俏，便想着嫁给临近的富绅做小妾，以换得一笔不菲的钱财。萧春风自觉不堪受辱，于是逃出了这个“家”。",
	["tid#Herolegend2_506"]="尽管掌握了多门高深武功，少年的周文浩尚还欠缺的则是需要日积月累才能成长的内力，但周文浩的父亲可等不了那么久。一心希望儿子为自己的光耀家门的周文浩之父被执着蒙蔽了双眼，不惜花费重金在江湖神医张景奇那购得了穷尽张景奇半生心血的秘制丹药。尽管张景奇再三提醒神丹尚未完成，吃下后必将痛苦不已甚至恐怕九成性命不保，周文浩之父哪管这么多，在其妻子苦苦相劝下依然逼着年方十六岁的周文浩吞下丹药。周文浩只觉剧痛攻心，足足在榻上躺了七七四十九天方才苏醒，却也从此脱胎换骨，内力修为突飞猛进，这时，才由母亲为周文浩讲述了其父亲为执念而不计一切的往事。",
	["tid#Herolegend2_507"]="原本这位蜀山的小师弟，只是读书，对武学并无甚兴趣，不过后来读到琅嬛阁中的蜀山武学秘籍，却一发不可收拾。原本晦涩的心法秘籍，进入到梁钲雨的脑海里，都仿佛活了过来，急于将学到的功法施展出来以探究更深武学的小师弟不得不跟着大师兄做起了早课和剑法的操练。",
	["tid#Herolegend2_508"]="因为家族的缘故，唐寅一路隐姓埋名，化名“伯虎”，只管游山玩水，不问江湖纷争。因而，无人知晓他“霸王枪”的身份，倒是一路留下的诗作出了名。人尽皆知，唐伯虎文采出众，诗集广传于世间，而他本人，更是有“江南第一才子”之雅称。虽说唐寅自认行事低调，但还是在江湖中出了名。",
	["tid#Herolegend2_591"]="暂缺",
	["tid#Herolegend2_592"]="暂缺",
	["tid#Herolegend2_593"]="暂缺",
	["tid#Herolegend2_594"]="暂缺",
	["tid#Herolegend2_595"]="暂缺",
	["tid#Herolegend2_607"]="一切都很顺利，求伯君从老掌门处顺利继承金山派掌门之位，并开始带着金山派在武林中崭露头角。勤奋的求伯君改良金山派原有的武学，独创出更厉害的内功心法，一时轰动整个江湖。然而，一时风头无两的金山派与求伯君的成就很快也遭到了不怀好意的人的觊觎。江湖中的人人闻之色变的巨门天忍教，想与金山派结盟，声称要共同维护江湖的安宁，彼时年轻的求伯君轻信了天忍凌峰楼楼主凌雪寒的话，答应了结盟的事情。",
	["tid#Herolegend2_606"]="少年时，鸠摩罗已不再如儿时一般沉默不语，而是妙语连珠，十分讨桑耶寺众僧欢心。此时他已能解高深的真谛，据他自己说，是圣人给他的指示。众僧对他钦佩、疼爱、羡慕，但唯一头疼的是——他经常偷懒不参加诵经。但好在师父疼爱，他往往能逃过一劫。",
	["tid#Herolegend2_602"]="她少女时期结识了好朋友小琴，小琴面容姣好，但是愿意和平凡的她一起玩耍，这让她十分感动，直到父亲把自己许配给镇上的一个帅气青年，小琴变得不太对劲，在一次两人出去游玩，小琴把她推下山崖，她摔断了脊椎，永远无法站立，小琴却嫁给了帅气青年人。",
	["tid#Herolegend2_603"]="随着柳念逐渐长大，老夫妻发现这个孩子有些奇怪。首先，她的头发从小便是一尘不染的雪白。其次，这孩子从小就不会哭也不会笑，脸上甚至没有任何情绪的表现。老夫妻以为她是患了什么奇怪的病，带着她四处求医，却丝毫没有效果。好在天山除了这些以外，其他方面都和正常孩子一样，加上十分乖巧懂事，慢慢的老夫妻也就不在意了。",
	["tid#Herolegend2_604"]="孤僻的人总是更容易受到奚落和排挤，刘异整日沉默寡言，举止又似乎异于常人，便很容易受到村里几个恶霸的“关照”。父母也并不会为他撑腰，只会觉得这个孩子给家里带来了更多麻烦。没有人可以说话的时候，刘异就会去到山里，独自冥想，一坐就是几个时辰。他觉得自己能感知到冰雪，似乎和它们有什么奇异的联系。并且随着冥想时间的增长，这种联系也越来越紧密。雪落得最大的那天，他在冥想时脑海里出现了一个声音，召唤他前往雪山的最高处——缥缈峰。",
	["tid#Herolegend2_605"]="周今鸣很晚才开始说话讲话，家里人一直都以为不过是她有些痴傻迟钝，说话慢吞罢了。可那一日，当两位哥哥的老师在提问的时候，面对两个支支吾吾的哥哥，在一旁的她倒是顺口答了出来。族长听闻此事，才让周今鸣也有机会正式开始读书习武，不过也只是作为两位哥哥的伴读而已。",
	["tid#Herolegend2_691"]="暂缺",
	["tid#Herolegend2_692"]="暂缺",
	["tid#Herolegend2_693"]="暂缺",
	["tid#Herolegend2_694"]="暂缺",
	["tid#Herolegend2_695"]="暂缺",
	["tid#Herolegend2_701"]="幼时的韩云溪因而十分向往外面万千风光，后来偷跑出村游玩时，结识了想夺取焚寂剑灵的欧阳少恭，并且无意泄露了乌蒙灵谷结界秘密，让乌蒙灵谷惨遭灭族。惨剧发生时，担心母亲的他闯入封印焚寂的冰炎洞里被牵连致死，其命魂四魄皆被玉横夺走。韩休宁为了守护焚寂，强行将焚寂中太子长琴的命魂四魄，连同滚滚煞气，封印在他体内。",
	["tid#Herolegend2_702"]="晴雪的母亲并非幽都住民，来自人间的她，因身体长时间承受幽都瘴气渐渐衰弱，在生下晴雪后没多久便辞世了。风家夫妇十分恩爱，晴雪的父亲因此郁郁而终。两兄妹皆由彭婆婆抚养长大，二人谨记父亲教诲，少年时的风广陌便凭借天资与努力成为娲皇神殿十巫之一，而晴雪也为担任灵女进行着各种修炼。",
	["tid#Herolegend3_101"]="自从自己被救的那一天起，林无双心中就认定了李大将军是他的救命恩人，她拒绝了李将军将她带往长安妥善安置的建议，执意要追随他返回洛阳。李大将军奈何不得，只得将她带回天策府，命她暂时女扮男装，权且作为自己帐下的一名小兵——恰好她从小到大，跟随父亲押镖，一身武艺是唯一傍身的技艺。",
	["tid#Herolegend3_102"]="王司马还年幼时，养父给了她一把烟花，王司马玩的很开心， 养父就大手一挥又买了一车给她，说第二天带她去郊外放着玩，王司马当晚激动难耐，拿着一株烧着的香，走上火车，心想着指点一只烟花，就回去乖乖睡觉，没想到失手点燃了所有的烟花。货车发生爆炸，府里霎时间烟花四起，养母大惊失色，赶紧跑去看，却发现小小的王司马，手里握着一只冷焰火，施施然，丝毫未伤的走了出来。",
	["tid#Herolegend3_103"]="坚决果断、老练机智的李延广是长安的一名提刑官。他凶猛睿智，带着强烈的正义感，对法律绝对忠诚，一把正义的铁鹰巨弩不离身侧。他既是一名耐心的猎人，也是城中大小罪犯的灾星。",
	["tid#Herolegend3_104"]="随着一天天长大成熟，她也组建了自己的帮派，孩童时的小打小闹终于变成了成人间的横冲直撞。她蛮横无理、暴虐乖戾，对拳头的热衷依然超出常人，因此总是鼻青脸肿、旧伤未愈又添新伤。但是由于从小在这个环境下生存，她很容易就摸通了黑白两道，她的势力也就越来越大，朝廷劝她归顺，劝了好几次也是没能打动李郡的内心，在她心目中现在有更重要的事情要做，她需要去往蓬莱。",
	["tid#Herolegend3_105"]="清觉对同行的清梵未有只言片语，但他已明白，他和师兄之间的距离早就已经渐行渐远；和清梵在蓬莱岛的三年很快过去，两人的武功都有了十分长足的长进，待到归往少林之时，却得知了住持已经去世的消息。但在住持弥留之际，他在遗言中授意将毕生功法传给清觉，并指定清觉成为下一任的少林大师，得知这一切的清梵无法接受这一切，和清觉大打出手，但终究落败清觉三招，愤然离开了少林。",
	["tid#Herolegend3_106"]="刘关江被首领救下后的第二天，曾回到过当初丢下弟弟的地方。他的心中还抱有一丝幻想，会不会…也有人会救下弟弟呢？会不会…那头狼也饿的没有力气了，没办法吃掉弟弟呢？会不会…弟弟还活着呢？但回答他的，只有一滩污渍，和汹涌而来的悔恨和羞耻。",
	["tid#Herolegend3_107"]="对于灭门之仇，老兵从未提起，燕云飞也从不主动提起复仇二字，他只是习武更加刻苦，终成大器，由老兵引荐，通过试炼后成为了长孙忘情手下玄甲军的一名将士，取得了燕云刀真传。",
	["tid#Herolegend3_108"]="天师门原本属于道法中的正一派，主修符箓雷法，但是年轻的张昊表现出了对炼丹的极大兴趣，但这是老天师绝不容许的，对老天师来说这些“旁门左道”会导致张昊主业荒废，于是在一次砸烂了张昊偷偷私藏的炼丹炉后，一气之下将他赶出了龙虎山。但老天师可能不知道，张昊并未荒废过天师雷法，他的符箓水平早已不俗，五雷符咒更是捻熟于心，且极善推演，观星推背也不在话下。",
	["tid#Herolegend3_109"]="恭默守静，伺机而动\n禹海莲的眼前就是她埋伏已久的敌人，这场收割她已等待多时，等她拿走他们的令牌，禹海莲就可以名正言顺的完成哥哥的遗愿--成为一名优秀的急先锋。她在敌人们帐篷旁的高树已经纹丝不动的趴了将近三个时辰，可是她依然保持神志专注，眼神凌冽，手中握着自己那把破空弓，毫不懈怠的瞄准帐篷里那个举着行军水壶的身影。",
	["tid#Herolegend3_110"]="暂缺",
	["tid#Herolegend3_111"]="从蓬莱岛回来之后，她领悟了新的技巧，“隐身”，便是将自己的行踪与气息遮蔽在敌人的盲点之处，在回故乡的路上，她遇到了为了应对叛乱，地方豪杰募集的兵马，公孙雨也加入了他们的队伍。在营地的篝火之间，她会为大家跳起自己最爱的舞蹈，为的是焕发将士们对待叛军必胜的决心。",
	["tid#Herolegend3_114"]="暂缺",
	["tid#Herolegend3_115"]="蓬莱回来之后，他似乎能够听懂战鹰的语言，也正是因为这个原因，再多次以身涉险的战斗中，他被战鹰的鸣啼所救。毋庸置疑，他就是最强的飞鹰战士！",
	["tid#Herolegend3_181"]="也许是造化弄人，天命不均。郭惊涛为了山庄发展，决定与川蜀唐门联姻，迎娶唐门之主唐雪枫之女唐明玉为妻。联姻也代表着两家结盟。然而，唐明玉却与名剑公子姜承影私奔，令郭惊涛丢光了颜面，也破坏了他重振神刀的计划。于是他一怒之下，派出弟子阻截姜承影，以致于此事在江湖上闹得沸沸扬扬。正当事情愈演愈烈之际，郭惊涛的行动遭到了父亲郭风骨的阻止，唐门的唐老太太也出面，事情才得以解决，郭惊涛虽心有不忿，也曾上门阻止，但终是无可奈何，只得作罢。",
	["tid#Herolegend3_182"]="14岁的杨素素终于明白了父母不开心的原因，因为接连四五十年渭水发灾，村子里的收成仅仅够糊口，根本不够拿出去卖钱，村里有个老人突然说起了河伯娶妻的事情，说如果把杨素素祭献给河伯可能就会缓解现在的饥荒，杨素素的父亲听闻这件事当场气得过世，母亲则重病在床，杨素素在祭祀仪式上被恩人救出来逃走。",
	["tid#Herolegend3_183"]="萧不语的枪法像是上天给他的财富，从蓬莱回来之后更是精准又沉稳，他不会苛求高等军衔，他只求多消灭哪怕一个叛军。土炮事件后萧不语赶忙回家，结果发现母亲不见了，父亲随后回来，二人追出去发现母亲被抓做俘虏。",
	["tid#Herolegend3_184"]="蓬莱回来之后，他似乎能够听懂战鹰的语言，也正是因为这个原因，再多次以身涉险的战斗中，他被战鹰的鸣啼所救。毋庸置疑，他就是最强的飞鹰战士！",
	["tid#Herolegend3_191"]="暂缺",
	["tid#Herolegend3_192"]="暂缺",
	["tid#Herolegend3_193"]="暂缺",
	["tid#Herolegend3_194"]="暂缺",
	["tid#Herolegend3_195"]="暂缺",
	["tid#Herolegend3_201"]="小时候和林良骏一起出门玩，他总是玩的一身脏回家，林良骏呢，怎么出门就怎么回家，干干净净，从来不跟韦壮武一起下河摸鱼，不趟泥潭，不偷煤块，小的时候他以为林良骏是胆子小，后来才觉得，他不是胆子小，而是讨厌变得不体面。",
	["tid#Herolegend3_202"]="那时候他在江湖上的威望一时无两，很多不服气的人都来找他较量，他只能跑到蓬莱躲着，这一躲就是四五年，回来后逐渐有了自己的势力，但此时江湖上已经又冒出了新的大游侠……",
	["tid#Herolegend3_203"]="此时结识一名江湖异客，对失意的他倾囊相授，传授了一身惊世骇俗的绝顶功夫，从此刑伯严一名，名震江湖，许多江湖侠客慕名而来，比试一番。",
	["tid#Herolegend3_205"]="靳辰洋的武功算是大器晚成，从那天开始决定潜心练武开始，靳辰洋就心无旁骛的修行自己的武学，在同年级的姑娘出嫁之时，靳辰洋却越来越对武学痴心，以至于方圆几十里的小伙子听说有这么一个奇女子都纷纷不敢接近，这可急坏了靳辰洋的父母，但她自己却不以为然。长时间和动物们打交道让她得以把动物的体态和自己的武学融会贯通，在功夫小成那天，靳辰洋决定独自背起行囊向父母作别，只身一人踏入了江湖。",
	["tid#Herolegend3_206"]="那是一次上元，大街上人头攒动，沈念挽着尹小荷沿着河边赏着花灯，不时还指指这边的花灯好看，那边的小吃闻起来很香。突然一个红衣的女子与她擦肩而过，不禁使得她一阵恍然，尹小荷关切地问她怎么了，沈念显示沉默了一阵，紧接着又恢复了笑容，说好像是看到了另一个不同的自己，可能只是眼花了。谁知说者无意，听者有心，尹小荷清楚的知道郭岩是有两个女儿的，并且他们是一对孪生子。尹小荷后来一路无话，也让沈念感到奇怪，看着表情凝重的养母，沈念忍不住问起了原因。于是，从来都无忧无虑的丐帮小公主开始有了自己的忧愁之事。",
	["tid#Herolegend3_207"]="最后一次下山之前，师父给了他一块玉佩，告诉了他的身世。下山之后，他循着师父给的地址找到了那个小镇，但那里已经因为一场海啸变为了汪洋。宁不凡又在附近打听了许久，父母的消息却一无所获，宁不凡只能无奈的选择放弃。但从此之后，他的腰间便常挂着那块玉佩，期望能遇到一个奇迹。",
	["tid#Herolegend3_208"]="辛晓风下山历练了三年，三年期间，她体会到了世间种种的情绪，遇到了形形色色的人，但最为关键的，是他遇到了宁不凡。两个人一起在大陆上游历了两年。慢慢的，辛晓风心中产生了一种从未体会过的情绪，不同于和师父之间的亲情，也不同与和师姐妹之间的友情，是一种会让她的心加速跳动的情绪。而这种情绪，只会在和宁不凡在一起的时候出现。但还未等她想明白这份情感，她却突然收到了师父的传书，说师门有难，要他赶快回来。辛晓风只好将这种情绪暂且压下，匆匆返回了妙法庵，连和宁不凡道别都来不及。",
	["tid#Herolegend3_210"]="家族由于担忧年幼的吕沛杰早夭，所以不让他出门，吕沛杰的童年都是在院子里跟着爷爷奶奶过的，跟爷爷学二胡。只是大家都瞎子瞎子的叫他，让他很难受。",
	["tid#Herolegend3_211"]="况候智把隐居的地方选在了一处山崖上。这是一处几乎无立足之地的绝壁，从上到下，平整的仿佛被一柄大斧劈过一般。他在这处山崖上开凿了一个山洞，隐居其中。不知过了多久之后，洞门口飘落了一张纸，似乎是一个女孩的遗书。仔细看过之后，况候智摇了摇头，那遗书中所写的诸般痛苦，在如今的他看来就如同浮云一般不值一提。正准备将遗书丢落之时，一道身影却从崖上坠落。况候智于心不忍，将女孩托起，送回了崖上，并在遗书背面写下了一段话，放在昏迷的女孩身边。从此之后，崖上时不时会有好茶伴随着纸条送下来，开心的时候，况候智也会替他们解答一些问题，隐居的日子，倒也多了一些趣味。",
	["tid#Herolegend3_212"]="谢云流出逃之后，吴清霄自然而然地成为了纯阳的大弟子，而且因为吕洞宾受伤之后，纯阳上下也皆为吴清霄在日夜打理。后来吴清霄接任纯阳掌教，一直谨遵吕祖的教诲，无论是对待师弟师妹还是弟子，均一视同仁，赏罚分明，极有威严却又不失慈祥和蔼，于是纯阳在他的打理下，理所当然的成为了武林中的中流砥柱。且吴清霄本人宽厚中肯，武学造诣也深不可测，其声名在武林之中多为人称道，纯阳宫也成为了令人肃然起敬甚至举足轻重的大门派。",
	["tid#Herolegend3_213"]="在外邦人眼中，他是功夫的代言人，可惜他只是小时候跟家里请来的师傅练过，为了自己的“虚荣心”为了不虚此名，他回国后在研究炸药配方的同时，努力习武，结合武艺和自己的炸药，倒也发明出了专属于自己独门独派的一种功夫。",
	["tid#Herolegend3_281"]="客栈的掌柜十分喜欢接济流落江湖的可怜人，焦渝钦便是如此来到客栈的。掌柜的虽然相貌凶恶，却心地善良，所谓一手快刀，其实是用来削羊肉的，经过掌柜手的羊肉，片的是干干净净，骨头上不留一丝肉渣。可龙门这个地方毕竟是凶恶之地，想要生存下来，不放出些噱头终究是不行的。因此，焦渝钦便跟着客栈掌柜学会了不少功夫。",
	["tid#Herolegend3_282"]="吕沛杰自称是云游四方的侠客，但是胡大壮觉得他更像是个一路卖艺的可疑人物。吕沛杰看中胡大壮朴实的心性和超人的臂力，认为他值得一交，于是把他介绍给了志同道合的其他几人，胡大壮第一次拥有了朋友，起码胡大壮自己是这么觉得。",
	["tid#Herolegend3_283"]="这是一方明净的居室，墙上挂着新鲜的丁香，它被一双纤手撷下来放入掌心。橘红色的身影小鹿般跳出房门，停在院内。旋即一条白蛇从草丛内爬出，来到少女脚下。\n「嘶嘶，欧阳慧，我猜这次是玉兰花。」\n「答~错~了！是丁香哦！」\n「嘶嘶…那这次惩罚是什么？」\n「惩罚你陪我出一趟西域！」\n「不行，你师父会生气的，他太可怕了。」\n「咱们现在就走，他追不上的。你呀，就老实跟着吧~」",
	["tid#Herolegend3_291"]="暂缺",
	["tid#Herolegend3_292"]="暂缺",
	["tid#Herolegend3_293"]="暂缺",
	["tid#Herolegend3_294"]="暂缺",
	["tid#Herolegend3_295"]="暂缺",
	["tid#Herolegend3_301"]="张景奇是什么时候察觉到自己已经老了呢？是在他发觉有些自己年轻时候能做到的事现在做不到了。比如说背起已经成年的赵心音，比如度过眼前这片沼泽。上一次来到这里时还是三十多岁，现在已经五十了。眼前的泥潭无论如何是过不去了，刚走了两步，腿就像在泥里扎了根一样，怎么都拔不起啊。看着赵心音毫不停滞的步伐，他又一次感叹——老了啊！不过啊，老了就老了吧，会有人代替我继续走下去的。说着，他看向了赵心音……",
	["tid#Herolegend3_302"]="初遇李清秋是买簪子没带钱被扣下了，李清秋救场，她反咬一口说李清秋诬陷自己，要李清秋请客吃饭，结果李清秋同意了，郭香香点了好多好多吃的，然后又没吃几口就走了，李清秋在后面打包这个打包那个，很憨厚的样子让郭香香有点动心。所以郭香香最后偷偷把簪子留给了李清秋。",
	["tid#Herolegend3_304"]="来往花坊的江湖豪客，观赏歌舞的间隙之间，总是论起一位年轻的得道大师，苏婉仪听来也颇有些好奇，于是就多听了一些。听说这法师号“清觉”，年纪轻轻，前些年得了老大师的衣钵，可谓一朝顿悟，于是往来各地宣讲智慧法理，其道理往往使人茅塞顿开，深受教诲。原本苏婉仪也只是当作传闻，权当是乏味的日常里听个乐子。但是后来外出遭遇一个魔人挟持人质，却见一个修行者出现舍己救人，而他正是传闻中的清觉。苏婉仪随后将他带到花坊疗伤，期间清觉说到与这魔人师兄的过往，令苏婉仪深受触动，随后清觉留信不告而别，苏婉仪心有戚戚焉。",
	["tid#Herolegend3_305"]="从小家人们就对她的超常能力表示惊叹，其中有善意的，更多的则是恶意……各种试探和考验令她烦不胜烦。于是她找到了一个最好的解决方法——每当有人傻乎乎的来挑事儿的时候，就随手扔出一个不知道几年前做出来的机关玩具，在他们一惊一乍时快快溜走……于是不知不觉间她的房间里堆满了各种看似奇妙但是实际上都是样子货的机关傀儡。形影不离的代步道具【非攻】也是顺手而为的造物之一，不过为了应付纠缠不休的俗人们，她也会兴之所至的给非攻安装一些无伤大雅的小武器，比如火箭飞拳【碎玉】和投网机【天罗】",
	["tid#Herolegend3_306"]="在官场中又过了几年之后，姜笑川的仕途陷入了瓶颈，而且他发现有一方贪腐势力在朝中盘根错节，大肆卖官鬻爵，结党营私。几番上书，皇帝却已然不管不问，姜笑川为江山社稷感到痛心，便试着借助江湖的力量来对付此人。",
	["tid#Herolegend3_307"]="唯独一事却是他未曾料到：中唐之时，天下乞丐多属丐帮所属，巴蜀一带自然也不例外。姜承影走家过户，钱财过手，他生得个金童之貌，讨起饭来自然占了天大的便宜，却是不知暗地里早已抢了多少乞丐的饭碗。终有一日被三两小丐围住，胁迫之下，姜承影倔强，却是不愿加入丐帮，被打得口齿裂伤，颜面青肿，不知吃了多少老拳。当日他每走一家皆有小丐挡门，如此两日，滴水不尽，六月初七又逢天降大雨，他脾气虽大，身子却再也挨不住，神志也渐浑沌了。",
	["tid#Herolegend3_308"]="上天似乎十分眷顾这个孤身一人的小家伙，安排了一次意外的相遇，使得周湘君成为了小滔滔的引导人，果不其然周湘君看到了滔滔的真正实力，他表示非常赏识。周湘君对滔滔提出的问题和她自己提出的一样多，不过二人很快变得密不可分。他成为了她的导师，而她则追随着他的理想。在训练场上，滔滔是无价的陪练对手——因为她是周湘君手下唯一一个敢于真正对他出手的人。她从来都不会谄媚奉承，经常用孩子一般的天真无邪质疑他的决定，似乎她根本就不知道自己应该乖乖遵从命令。",
	["tid#Herolegend3_309"]="周湘君本身退隐后做了教书先生，不再打拳，可他教的学生家里来了强盗，周湘君过去用烟袋锅一拨，就把一绿林好汉的刀给下了，再一点又撂倒一个，三下五除二，几下子就把绿林好汉都打倒了。又用捆家丁的绳子把他们一个个都给捆上了。",
	["tid#Herolegend3_310"]="其实筱九早就注意到史春莲了，最开始她只是听森林中的动物说，有一位与众不同的女猎手。那个女猎手只捕猎年迈的动物，从不屠宰幼崽。且对待猎物也保持着敬畏和怜悯。筱九虽然不喜欢猎人，但对史春莲这样的还是很好奇的。于是便开始偷偷的观察她，观察了许久之后，她觉得史春莲确实和其他猎人不一样，也慢慢的对她产生了好感。",
	["tid#Herolegend3_311"]="成年之后皇室为他指婚了公主，只是不久公主便病逝，随后他的婚事便没了音信，只是他心不在此，他参加完公主葬礼后去往了蓬莱，归来后，碰到了自己这辈子的真爱。",
	["tid#Herolegend3_312"]="因为一直生活在山庄里，史春莲很少吃到点心。小时候只有在过生日时，父母才会用兽皮从镇上换回来一些，当作史春莲的生日礼物。带着筱九一起闯江湖的时候，史春莲第一次见到如此精致又好吃的点心，于是带着筱九大吃了一顿，吃完之后才发现没有带钱，还是路过的一位好心的姐姐付的钱。",
	["tid#Herolegend3_383"]="一年过去，他遭遇的敌人越来越多了，他开始趁着清醒的时间全力地投入到琴技的修习中，姑苏慕容有琴剑双绝，但慕容清月只专取琴艺。也是这一年他遇到了姜笑川派来追猎自己的刘关江，清醒的时候，他知道刘关江从远方来，是自己新认识的“朋友”，发呆的时候，他不知道的是，八卦对他的身世越是了解，就越是动了恻隐之心。",
	["tid#Herolegend3_386"]="从蓬莱回来之后的段徵言，敛去一身锋芒，成了一个人畜无害温润如玉的公子，父亲临终前，跟段徵言说了一句话，影响了段徵言后半生：“君子以俭德辟难”。",
	["tid#Herolegend3_387"]="作为“造物”诞生的冉无名对世间生命拥有无尽的敬畏和感动，同时赞叹天地的威严与奥妙，时刻充满敬畏之心。如果可以，绝不害人性命。但是，极端敌视践踏生命尊严的行为，如果通过演算得出没有更生希望的结论，那么它并不介意为天地万物净化这些垃圾。",
	["tid#Herolegend3_391"]="暂缺",
	["tid#Herolegend3_392"]="暂缺",
	["tid#Herolegend3_393"]="暂缺",
	["tid#Herolegend3_394"]="暂缺",
	["tid#Herolegend3_395"]="暂缺",
	["tid#Herolegend3_401"]="然而，后来天后临朝，登基之后迫害李姓宗室，翟冬玄也无端受到牵连，那一日他躲过官兵追捕一路潜逃回去，可是家中的情景却让他悲痛欲绝，他终究是来迟了一步。",
	["tid#Herolegend3_402"]="年幼的阿岚听闻有人欺负圣蝎门，小小的脸上却显现出大大的怒气，掏出自己的毒蝎子和小毒蛇，也参与了战争，“圣蝎门下被人欺负了呢，咱们五仙教虽然不打算欺负旁人，可若有人要欺负咱们，那也是决计不能，赤眼龙王，你既然有胆量欺压了阿岚我的门下，就准备承受蝎之毒焰吧！蝎子，可是睚眦必报的！”",
	["tid#Herolegend3_403"]="当祥颖韬剃秃了脑袋，扮作一个和尚躲避六扇司的追捕之时，曾经遇到了自己的劲敌李延广。那次是祥颖韬第一次这么近距离地，看着将自己赢得一无所有的对手。他在李延广的眼神里看不到任何情感的波动，锋利，深邃，似乎能将他的灵魂都吸纳其中，瞬间堕入无间无常之地。好在，这拙劣的伪装竟然救了自己一命，待李延广走后，他的头上瞬间汗如雨注，从厚重的粗麻衣服上浸透了出来。",
	["tid#Herolegend3_404"]="就这样又过了十年，'陆十一'依旧是十一，他见识过那个所谓“拾”的人实力，分明不是自己的对手，为什么自己成不了十。终于有一天他忍无可忍，决定亲自挑战一下这个天罗第十位的高手。可是他的挑战状却被拒绝了，于是他不顾凌峰楼的规定，硬是要跟他较量一番争个高低。",
	["tid#Herolegend3_405"]="小王爷今天很开心，因为手下刚抓回来了一个叫赵心音的美女。他刚才只是进门时匆匆撇了一眼，魂就已经被勾走了。迫不及待就让手下把美女抬到了自己房中。小王爷进到房中，迫不及待地解开绳子，布袋中的赵心音探出了头来。瞬间，小王爷就觉得他之前遇到的女人如同尘土般平庸。即便他深得当今皇上的宠爱，坐拥一大块封地，却还是第一次见到如此美艳出尘的女人。特别是她那一头的白发，给她的美艳平添了一丝妖邪，简直要把人的魂都够勾了去。小王爷心痒难耐，赶紧将美女放到了床上，吹熄了蜡烛……第二天，仆人们打开房门，却发现小王爷在房中没了气息，桌子上还放着一张字条“君者不君，其命该绝！”",
	["tid#Herolegend3_406"]="由于常年被禁闭在唐家堡内，百无聊赖的唐明月在等待姐姐的来信之际，只好研究起了唐门之中的机关术。唐明月从来不知道自己其实对机关术有着过人的天赋，因此原本只是用来打发时间的活计，却让唐明月逐渐成为了唐门中机关术的佼佼者。唐明月通过机关术制造的机关小动物惟妙惟肖，倒也成了逗自己烦闷的新宠，她做了好多机关鸢鸟，希望有一天可以乘坐一只大大的机关鸢飞离这里。为了报答帮自己送信的唐门弟子，她也会帮他们制作一些更好用的弩机，凡是经过她手的弩机，威力也是强了数倍。",
	["tid#Herolegend3_407"]="阁主当然不能眼睁睁地看着自己门派的翘楚就这么被他人轻而易举的带走，而且，自己门派的绝学也绝不能成为他人门派的武器。但是，阁主已然忌惮天罗十人的背后之人，也便是凌峰楼的楼主，天忍教宗凌雪寒的可怕。",
	["tid#Herolegend3_409"]="秦飞雪十分有武学天分，体格也强过寻常女子，性格豪爽大气，颇有些男子气，倒是与巨侠十分相像。正因如此，秦飞雪每每与巨侠在一起时，常被郭香香取笑，说飞雪姐姐更像是飞雪兄长，跟父亲在一起时倒更像是一对亲父子。",
	["tid#Herolegend3_410"]="这便是许久之后陆小贝从江湖中听说的“大光明寺之变”，但她知道，那天从大光明寺冲出来的，不只父亲一人。她只记得房门突然便被推开，陆小贝已经看到了门外阶上挤满了人，那些都是教中的叔叔伯伯们，他们一身月白色的袍子大多上都染了许多红色，外面的风雨声呼啸着传进来，她这才知道雨已经下得这般大了，六年过去了，陆小贝还是很难想像，她会如此突兀地踏上逃亡之路。",
	["tid#Herolegend3_411"]="上天似乎十分眷顾这个孤身一人的小家伙，安排了一次意外的相遇，使得周湘君成为了小滔滔的引导人，果不其然周湘君看到了滔滔的真正实力，他表示非常赏识。周湘君对滔滔提出的问题和她自己提出的一样多，不过二人很快变得密不可分。他成为了她的导师，而她则追随着他的理想。在训练场上，滔滔是无价的陪练对手——因为她是周湘君手下唯一一个敢于真正对他出手的人。她从来都不会谄媚奉承，经常用孩子一般的天真无邪质疑他的决定，似乎她根本就不知道自己应该乖乖遵从命令。",
	["tid#Herolegend3_412"]="来蓬莱的路上碰到的前辈，都跟他讲，他练就的这些至寒至阴的武功会让他万劫不复，需要留一些火毒相抗衡，可他不服，他决心要赢过天命，于是他到蓬莱走了一遭，彻底摆脱了火毒，也成就了天霜拳。",
	["tid#Herolegend3_413"]="神水宫本不是一个单纯由女子组成的门派，不过在玄水姬在继任宫主之位后，她驱逐了门内所有的男子，她说，男子便如世间的尘土，让她厌恶，而女子如水，正是神水本源。而此时，玄水姬神功大成，可谓独步天下，不可一世。",
	["tid#Herolegend3_481"]="张超很快的开始嫉妒起了张景奇的天赋，因此他变得比之前更努力更刻苦，他事事争先一定要比过张景奇才会觉得内心安稳。直到一次，在接待一个病人时，他激进的疗法差一点儿就导致了一场悲剧，好在张景奇及时的阻拦和补救，才挽回了局势。",
	["tid#Herolegend3_484"]="可是年轻的男孩太过胆怯，在东窗事发之后，否认了和宋英男的一切，宋英男心中充满了失望，而封建的村子容不得这种不清不白的行为，宋英男只能独自承受这一切，被驱逐出了渔村。离开渔村后，宋英男万念俱灰，曾经认为是勇敢的代表的男孩，却原来是一个懦夫，她流着泪走向大海，六神无主之时竟然没发现自己已经走到了水深之处，突然一个巨浪袭来将她卷入海中。",
	["tid#Herolegend3_485"]="师父逝世后他离开了寺里，却发现了一群气势汹汹的土匪，他寻找机会混进了土匪路经的一个小村落里，那一夜，土匪到村里抢掠，村里人吓得四散而逃，最后只有一个小姑娘躲在摩波旬身后寻求帮助。",
	["tid#Herolegend3_491"]="暂缺",
	["tid#Herolegend3_492"]="暂缺",
	["tid#Herolegend3_493"]="暂缺",
	["tid#Herolegend3_494"]="暂缺",
	["tid#Herolegend3_495"]="暂缺",
	["tid#Herolegend3_501"]="有一天少林来了一个姑娘，他误打误撞和姑娘撞了个满怀，可这一撞，将他原本藏了多年的凡心一下子给撞了出来。听闻这姑娘是长安一位巨侠家的小姐，姑娘也是随着这位巨侠来到少林商讨一些李知傲不知道的事情。然而姑娘似乎并没有在意这位打扫院落的小和尚，直到她走后，李知傲开始变得怅然若失，郁郁寡欢。",
	["tid#Herolegend3_502"]="与天下所有双子一样，姐弟二人拥有超过常人的默契和心电感应，姐弟演奏的曲目，总能二人最理想的时候昂扬向上，也能在最完美的时候弹拨下休止的音符。",
	["tid#Herolegend3_503"]="不知从什么时候开始，逸心的信渐渐少了，偶尔的几封信里，语气也是鲜有的凝重。只言片语之中，句芒得知蜀山卷入了庙堂纷争，小师弟梁铮雨非同一般的身份，让整个门派被置入了漩涡的中心。云隐岛得益于句芒所带来的充沛灵力，在得到逸心的传授之后，渐渐后来居上，如今已成为比蜀山实力更强的修仙之地。既是足以庇护蜀山安稳，句芒当即向逸心送去了“论道大会”的邀请，邀他与小师弟一道前来。若他愿意，也可让小师弟久居一段时日，直至风浪之后。",
	["tid#Herolegend3_504"]="霍紫凝冒着生命得危险将千年何首乌采下，正当她要将何首乌送至母亲嘴边时，多日不见的父亲从隐蔽处跑出，一把抢走了她的药材，并宣称要将它卖给太守重症的小妾。母亲在身亡的前一刻，掏出了最后一件刺绣——给霍紫凝的一个荷包，里面有一滴以母亲的心头血凝成的琥珀。",
	["tid#Herolegend3_505"]="但是逃跑中并不是顺利的，养父母勾结富绅，派出富绅豢养的浮浪子们四处追捕着她，就在她要被抓回去时，遇到了一个路见不平的年轻男子，无处可去的萧春风也对眼前的人心生向往，便拜其为师。",
	["tid#Herolegend3_506"]="而周文浩却有自己的打算，在服下神丹后，周文浩发现自己已然四方无敌，不管是教会自己武学的师傅还是别的小有名气的侠客，周文浩只消三两下就能将对方击败制服。觉得时机已到的父亲决定向周文浩诉出自己的报仇大业，这个满心以为儿子会协助自己计划的中年人却意外的受到了斩钉截铁的拒绝——如今的周文浩只想去为自己而活，神功在身的他不愿成为父亲的道具，扬名立万，称霸江湖，让周文浩之名威震四海这样远大的目标在周文浩看来要比区区复仇远大得多。气急败坏的父亲觉得自己这一生的大计竟然在此折戟，竟以周文浩母亲的性命相挟要周文浩必须为自己执行计划，而周文浩却逃离了家庭，此生之后只为唯我独尊。",
	["tid#Herolegend3_507"]="因为对武学产生好奇，开始参与早课操练的小师弟，终于开始与中师兄们熟路起来。不过，因为饱读诗书的梁钲雨说话总是文绉绉的，又喜欢与师兄们讲些先贤经学，因此被师兄们冠以“小夫子”的称号。一开始梁钲雨觉得师兄们是在讥笑自己，特别不喜欢师兄们这么叫自己，到后来发现这些师兄也并非恶意，且随着自己与师兄们熟络，也发现师兄们十分照顾自己这个小师弟，并且也因为梁钲雨的讲学，每个人变化良多，也渐渐地习惯甚至会乐意听到师兄们这么称呼自己。",
	["tid#Herolegend3_508"]="在江湖人心中，唐伯虎是公认的“风流才子”，但这位才子第一次动真情，还是在青龙寺偶遇了一个姑娘。那日他去寺中进香，与姑娘擦肩而过，一见钟情，而姑娘匆忙离去时遗落一物，正是他的《伯虎诗集》。唐寅心中暗喜，当晚为姑娘写了首诗，并辗转多日打听到姑娘住处前去表白。但姑娘说自己心悦于江南第一才子，并规劝他，不要拿唐伯虎的诗来冒牌。莫名被拒后，唐寅心中五味杂陈，唯一欣慰的是，自己的诗确实流传得很快。",
	["tid#Herolegend3_591"]="暂缺",
	["tid#Herolegend3_592"]="暂缺",
	["tid#Herolegend3_593"]="暂缺",
	["tid#Herolegend3_594"]="暂缺",
	["tid#Herolegend3_595"]="暂缺",
	["tid#Herolegend3_607"]="为人正直的求伯君没有想到，天忍教的结盟只是障眼法，这个江湖之中，还有他意想不到的人心险恶。潜伏于金山派多年后，天忍教开始显露出野心。他们模仿着金山武学的精髓，“创造”了几乎一模一样的“凌绝剑式”，对外却说是自己的独门绝学，于江湖之中大肆宣扬。金山派一向行事低调，渐渐地，世人只知凌绝剑式威力无双，而金山弟子行走江湖，却反会被当作模仿者。本应独享盛名的金山派，却因此而遭遇了空前的危机。",
	["tid#Herolegend3_606"]="一年清明，正值汉藏法学兼武学交流之际，鸠摩罗从师之命，与一众师兄共赴中原。既为求学，也为扬藏法洪威。自幼被命运偏爱的鸠摩罗，认为这次也能在圣人的指示下，决胜中原。然而这一次，圣人之灵没有告诉他如何取胜，只是留下了一句话，「归元性无二，方便有多门」。向来悟性极高的鸠摩罗第一次感受到困惑。一路上他都在想，这句话，究竟应当作何解。",
	["tid#Herolegend3_602"]="父亲不忍心让女儿卧床不起，于是就穷尽毕生之力，也在她的天才思路协作之下，为女儿打造了一辆非常精密的轮椅，这台轮椅的动力，驱动，无人可知父亲对此付出的心血，她自己是知道的，可是在心里深处，她又无法原谅小琴，于是她开始憎恨年轻貌美的姑娘，也憎恨只看容貌的无知青年小伙子。",
	["tid#Herolegend3_603"]="柳念稍长一些的时候，收养自己的老夫妻突然病倒了。听闻天山之巅的天池里生长着一种雪莲，食用其莲子可以治疗百病，于是天山便前往寻找。没人知道一个看起来弱不经风的小姑娘是如何穿越风雪取到雪莲的，老夫妇病果然如传言中一样，被柳念带回的雪莲治好。然而待二人病愈却发现自己的养女早已不辞而别。",
	["tid#Herolegend3_604"]="登上缥缈峰后，刘异遇到了两只凶猛的异兽。体型与狼相仿，毛发上凝结着冰霜，闪着幽幽的寒光。年幼的刘异对凶猛的攻击招架不及，慌乱中躲进了一个山洞。在山洞的最深处，他看到千年玄冰封存着一本秘籍，正是灵鹫宫失落的绝学“生死符”。一旁另有一封手书，记载着灵鹫宫从鼎盛一时到逐渐没落的始末。信上说，前宫主将秘籍封存于此，以待下一个有机缘与天赋的人寻得，复兴灵鹫宫。而这个受到指引的后人，就是刘异。",
	["tid#Herolegend3_605"]="少年时期，三兄妹随业师开始精研家族武学。出师之日，业师欲将武学秘籍《三分归元》传与其中一人。在比武试炼时，大哥、二哥皆莫名发狂、然后得怪病而亡。家族查之未果，秘籍也旋即落到周今鸣手中。她一跃成为复兴家族的曙光。在她的建议下，世家开始韬光养晦，低调行事。",
	["tid#Herolegend3_691"]="暂缺",
	["tid#Herolegend3_692"]="暂缺",
	["tid#Herolegend3_693"]="暂缺",
	["tid#Herolegend3_694"]="暂缺",
	["tid#Herolegend3_695"]="暂缺",
	["tid#Herolegend3_701"]="韩云溪死而复生，成为乌蒙灵谷灭族之灾下唯一的幸存者，不过因为魂魄的缺失，失去了一些记忆，忘记了灭族之灾究竟是怎样发生，怎样结束的。小云溪亲手将族人们的遗体搬入冰炎洞下层，痛哭失声却又难以追回，只能寄望于未来某日能够让大家重返世间。",
	["tid#Herolegend3_702"]="后来，因焚寂封剑之事，风广陌被派往人间乌蒙灵谷，从此一去不回。长大后的晴雪奉女娲之命，去往人界寻找兄长踪迹，阴差阳错见到了携带焚寂的百里屠苏，也因此成为了与众人结伴寻找线索的缘由。",
	["tid#Herolegend4_101"]="殊不知这名小兵，却在后来出征西域的战斗中屡立奇功，林无双凭借着出神入化的身法，乔装易容数次摸进敌营，于睡梦中取敌酋首级，令敌军闻风丧胆，都知道唐军中有一名善于潜伏的女战士，不禁人人自危，军心涣散。林无双的扰敌行动有力地配合着天策军的正面进攻，使得唐军很快地平定了西域的叛乱。",
	["tid#Herolegend4_102"]="王司马惊人的创造能力很小的时候就展现了出来，她很担心总是外出抓坏蛋的养父发生危险，于是自己制作了老虎雷，装在锦囊里交给了养父，奶声奶气的告诉养父，遇到危险的时候可以把这个扔出去，可以保护自己。养父不以为然，却像宝贝一样带在身边，权当是小女儿的一个念想。只是没想到，在一次围剿山匪的过程中，他与山匪头子在地堡中狭路相逢，可手中没有兵器，慌张中扔出小女儿的锦囊，竟然将山匪头子炸的四仰八叉！",
	["tid#Herolegend4_103"]="李延广被誉为长安最顶尖的提刑官，同时也是让这座城市真正摆脱地下隐秘犯罪的最有希望的人选。他经常和锦衣司李郡联手执行任务，以冷静和沉着弥补自己搭档的鲁莽天性。虽然他背后的铁鹰巨弩独一无二，但他最强大的武器其实是他过人的智谋，总是能设下天罗地网，迎接任何傻到敢在长安作案的不法之徒。",
	["tid#Herolegend4_104"]="蓬莱回来之后，李郡就更加声势压人，不详之谷的其他黑帮也不曾对李郡下手，他们都觉得李郡的存在是有必要的。直到有一天，李郡来到一个据说是外地人策划的一次触犯宵禁的深夜狂欢，听说了老朋友李延广亲自抓人，凑近一看，心里凛然，这个女子跟自己有着一模一样的脸，找到李延广，深夜探监，与王司马认了亲，李郡从未见过王司马，但是她有一种姐姐的本能，这种本能让她自己非常动容，她认为这种感情就是她现在需要完善的人格，可就在这时候，王司马摔下一个惊天雷，一走了之。这一晚之后，李郡变成了锦衣卫，带上遮挡面容的斗笠，拿起枷锁，决意将王司马追捕回来。",
	["tid#Herolegend4_105"]="清觉成为了少林建立以来最为年轻的一位大师，他四处讲学，宣扬智慧，同时也不忘潜心修炼，精进武艺。在行走江湖的这几年中，清觉行侠仗义，打响了少林的名号。在一次宣讲中，慷慨的清觉将门派的斋饭广发给附近的受灾百姓，这份善举被花间派的苏婉仪所见，然而恪守清规的清觉从来不近女色，他似乎没能看见在茫茫人海中那个貌若天仙的女子，在清觉的心中，无论是枯槁老者抑或是妙龄少女，对他而言皆是需要善待的苍生。",
	["tid#Herolegend4_106"]="刘关江和慕容清月的第一次相遇，是在一次任务中。当时他的任务是盗走一位琴艺大师珍藏的琴谱。虽然不知道首领要这个琴谱有什么用，但他唯一所能做的就是服从命令。那是他唯一一次任务失败，或许也不算是失败，因为那本就是一场骗局。虽然在察觉到不对的一瞬间他就已经准备逃离，但还是没能逃脱他们早已设下的圈套。其实凭刘关江的本领，虽然无法对抗这些人，但要跑还是没有问题的。但偏生在这个时候，窜出了一个笨蛋。那个笨蛋一边说着一些大义凛然的废话，一边冲向人群。他本想趁着这阵骚乱逃跑，但看着那个陷入苦战的笨蛋，看着穷凶极恶的敌人，他却突然想到了小时候，想到了弟弟和那只双眼泛红的狼。鬼使神差的，他也冲了上去，和那个笨蛋一起冲出了埋伏。那时候他还没有意识到，从那天开始，他就已经被这个笨蛋缠上了。",
	["tid#Herolegend4_107"]="燕云飞平日不苟言笑，话少严肃，从小如此，长大更显得凌厉沉稳，颇有将领之风。他作战有素，勇于除敌，每每率兵出击，都要除尽全部敌人，遇到欺负妇孺的贼寇，他更是不留一丝情面，不知是否与他惨痛的童年经历有关。据说他每次临战前，都抱着绝命的心态，一心想要多击败一个敌寇。",
	["tid#Herolegend4_108"]="张昊年幼的时候，曾见过一个负剑的道人来龙虎山问道，那人号称“纯阳子”，带着两个小道童。那两个小道童便是吴清霄与谢云流，在纯阳子与老天师论道的几日，张昊带着这两个小道童游遍了龙虎山的各处美景。不过天生聪慧的张昊也旁听了父亲与纯阳子的论道，也从那时开始，他觉得这全真道法里的内修与炼丹，也是很有意思的东西。",
	["tid#Herolegend4_109"]="速战速决，当机立断\n当然，作为一名优秀的暗司隐卫，她绝不会放弃任何一个射击目标的机会，当目标人物出现后，她会在短时间内，摒弃其他感官，专注于对目标的瞄准，一旦发现目标的安全隐患，顾不上得意，她会立即搭箭射击，不留任何情面。就算目标的亲人孩子在身边，也绝不会考虑那些类似恻隐之心的东西。",
	["tid#Herolegend4_110"]="暂缺",
	["tid#Herolegend4_111"]="反叛军的占领行为动摇了刚刚经历过动乱，因而百姓才从夹缝中获得的片刻平宁。在将士们与叛军们拼死搏杀的时刻，公孙雨方才展现出她舞蹈真正的可怕之处——孔雀花翎，刀尖之舞，飘然羽落，赤染遍地……",
	["tid#Herolegend4_114"]="暂缺",
	["tid#Herolegend4_115"]="在加入军营之后，神机营的萧不语是他最尊敬的男子，不善言辞的他，除了陪伴自己的雄鹰，萧不语是他少有的说话对象，同样的，萧不语亦是他军人身份的楷模。",
	["tid#Herolegend4_181"]="彼时名剑来到山庄，与神刀门讨要之前与郭浮云交手重伤的姜承威，并要强行闯入山庄，完全无视山庄禁制，并出手打伤多名神刀弟子。面对对方强硬的态度，郭惊涛屡劝名剑公子姜承新未果，但对方依旧咄咄逼人。终于郭惊涛忍无可忍，逼退姜承新，姜承新也不甘示弱，于是二人交战良久，致使姜承新身中三百余刀陷入昏迷。随后，神刀将名剑来人统统遣送回了江南。尽管郭惊涛也觉得似乎有些冲动，但是他坚信自己没有做错，他必须捍卫神刀的威严！",
	["tid#Herolegend4_182"]="杨素素离开村子之后，得知病重的母亲去世，悄悄溜回村子将母亲安葬，不想在半途被村民发现，村民集体对她谩骂导致杨素素觉醒了力量，但由于不会控制而误伤了一部分村民，杨素素内心难以平静遂去往蓬莱，这年杨素素18岁，后来她就没再老过。",
	["tid#Herolegend4_183"]="父亲打算带着萧不语去营救母亲，可惜重兵把守下父亲让萧不语等在墙外，不多时父亲似乎带着母亲到了门口，萧不语欢喜之际，发现守卫军出现在父母身后，萧不语眼睁睁看着父母被击毙",
	["tid#Herolegend4_184"]="在加入军营之后，神机营的萧不语是他最尊敬的男子，不善言辞的他，除了陪伴自己的雄鹰，萧不语是他少有的说话对象，同样的，萧不语亦是他军人身份的楷模。",
	["tid#Herolegend4_191"]="暂缺",
	["tid#Herolegend4_192"]="暂缺",
	["tid#Herolegend4_193"]="暂缺",
	["tid#Herolegend4_194"]="暂缺",
	["tid#Herolegend4_195"]="暂缺",
	["tid#Herolegend4_201"]="韦壮武好像有一种属性点，叫做自带降智功效，他的这种傻呵呵的性格似乎有很强的感染性。他一直都很想养一只猫，却在偶然去山上玩的时候认识了一只老虎。因为总是去撸这只大“猫”，因此跟山上的野兽关系很好。韦壮武一直想把自己山上的“朋友”介绍给自己的好兄弟林良骏，不过林良骏嫌弃他身上的毛，也总是婉拒他的邀请。",
	["tid#Herolegend4_202"]="在蓬莱岛之旅当中，意外结识一个了年轻的侠客，他早已在中原之时就对此人深有耳闻，竟没想到可以在这里遇到。原本他一直固执的认为此等所谓行侠仗义，不过都是虚名尔尔，甚至是欺世盗名之人，于是对他的态度充满了轻佻与不屑。",
	["tid#Herolegend4_203"]="名声一大，关于他的流言蜚语多了起来，他对这些深感不屑，故昭告天下退出江湖。只做一个暗地里帮人惩奸除恶的隐士游侠。",
	["tid#Herolegend4_205"]="靳辰洋行走江湖这几年仗义行侠着实也结下了不少仇家，缘是这靳辰洋对恶人从不痛下毒手，最多就是用拳头教训一顿然后扭送官府，久而久之，这群对靳辰洋意图报仇的恶人就纠集起来，打算打闹这次比武招亲，再不济也能让靳辰洋出丑声名扫地。几个大汉也不顾规矩一拥而上，靳辰洋独木难支节节败退，正当情况危急之时，那位路过的白衣侠客又出手相助，帮着靳辰洋两人共同将歹人打退。歹人虽走，台下的观众却齐声喝彩起哄，要这白衣少侠同靳辰洋比划比划。白衣侠客碍于面子一时下不来台，靳辰洋却总觉得来人面熟，竟也邀请对方较量一番，白衣侠客无奈答应，两人就在台上拉开了架势。",
	["tid#Herolegend4_206"]="沈念从小到大一直没有遭遇过什么大的挫折，养母尹小荷对她的照顾可以说是无微不至，不过沈念长大的过程中，身边也没有什么其他的女性，更没有女孩儿玩伴，多的是丐帮的糙汉子。加上，沈念对武功的喜爱，从小就爱打打闹闹，以至于后来活脱脱成了一个直爽的女汉子。她能与帮中腕力最强的壮汉角力，帮里数一数二的高手，沈念也能跟他们斗得有来有回，甚至取胜。尹小荷身为一个女子丝毫不觉得沈念这样有什么不妥，反而每次看到活泼的沈念，眼里都满是喜爱。",
	["tid#Herolegend4_207"]="每当想起辛晓风，宁不凡的嘴角总是忍不住扬起。那姑娘拥有和他一样的眼睛，也能看见人心的颜色。但和他不同的是，面对黑色，辛晓风的选择是将其转化为白色，而她也真的做到了。起初，他只是远远的看着辛晓风，默默的保护着她。直到有一天，一场突如其来的大雨将两人关在同一个屋檐之下，他们才说出了第一句话……那之后，两人便一起在江湖中游历，关系也越来越好。但是好景不长，两人相伴了两年之后，辛晓风却突然不告而别，只留下一封“师门召唤”的书信，甚至连师门的地址都没有。",
	["tid#Herolegend4_208"]="下山之后，辛晓风接触到了很多新奇的东西，其中有一样让她尤为感兴趣——厨艺。庵中的清苦日子里，她从不知道原来食物还可以做的这般精致。于是她开始学着做饭，但既然是学习，就难免失败，而她又讨厌浪费食物，于是……失败的作品就都进到了宁不凡的肚子里。好在她学的很快，不多久，宁不凡就从原本的煎熬变为了享受。",
	["tid#Herolegend4_210"]="吕沛杰青年时候为了强健体魄学习了剑术，爷爷去世后他就带着二胡逃了出去，因为二胡给了他半个视觉，所以他一路寻到了蓬莱岛，想要获得更高层次的点悟。",
	["tid#Herolegend4_211"]="闭关恰满一个甲子的时候，山崖上来了一个有趣的家伙。别人来问问题，都是拿一根长绳送下来，但这下子，竟然把绳子系在腰间，爬了下来。又观察了一会儿，原来这小子竟然不是来问问题的，是来采药的。况候智顿时有了兴趣，这世间竟有为了采药连命都不要的人，真是有趣。也恰好况候智的棋瘾犯了，便把那小子叫到了洞中。那小子的棋艺虽然一般，但是很有潜力，不过稍加点拨，就已经能和自己走上几个回合了。况候智很高兴，话也就多了起来。他知道这小子叫张景奇，想要收集天下间所有的药方和病症。这种东西在他的脑子中可是多不胜数，于是便随手给他写了几副，张景奇如获至宝，恳请况候智把所有的药方都交给他。况候智便和他做了个约定：张景奇每和自己下一局棋，就告诉他一个药方，若是有一天张景奇赢了，就把所有的药方都告诉他。",
	["tid#Herolegend4_212"]="吴清霄一直想把师兄的当年之事跟武林解释清楚，遂力邀各大派名宿前来寇岛宫中神武遗迹处秘密会面，奈何有人从中作梗，秘书五大门派诬陷谢云流欲借机伤害吴掌门。五大门派遂决定先行探查虚实。诸位侠士进入宫中神武遗迹，遇到歹人派来暗算吴清霄的东瀛忍者。歹人还欲嫁祸谢云流，力图搅起中原内乱从而坐收渔翁之利。谢云流误以为吴清霄与各大门派不忘当年仇怨仍要将之赶尽灭绝，不禁大怒，力战众人。五大门派弟子则以为谢云流欲如传闻一般暗算吴掌门。双方各执一词，此番一战，恐误会已经越来越深。",
	["tid#Herolegend4_213"]="喻扬超其实和王司马不认识，两个人只能算是笔友，虽说是笔友但是从不写信，互相放自己制造的烟花作为通信。",
	["tid#Herolegend4_281"]="只可惜，这片沙漠里的绿洲终究禁不住风沙的持续侵蚀，终于有一天，一伙悍匪入侵了店里，掌柜的平时一些唬人的小手段终究是吓不住这些真恶人，为了保护焦渝钦，掌柜的受了很重的伤，后来也撒手人寰了。掌柜的临终前，将客栈托付给了焦渝钦，希望她能守住这家店。",
	["tid#Herolegend4_282"]="宁不凡总是想拉胡大壮下水，一起成为饮中豪杰，不过比起或辛辣或酸甜的不明液体，胡大壮还是对辛晓风小姐姐做的美味更感兴趣，虽然量总是很少，不过娘可不会做这么精致的菜肴。",
	["tid#Herolegend4_283"]="从西域金城到长安万年县，马程十五日。\n而对于富有传奇色彩的欧阳慧和她的宠物蛇来说，需要两个月。\n风沙弥漫，寸步难行，失策了……绿水青山，沿路繁华，真够劲！\n万年县当日所有的通缉令被某人凌晨全部揭下了。\n揭榜人？没找着。",
	["tid#Herolegend4_291"]="暂缺",
	["tid#Herolegend4_292"]="暂缺",
	["tid#Herolegend4_293"]="暂缺",
	["tid#Herolegend4_294"]="暂缺",
	["tid#Herolegend4_295"]="暂缺",
	["tid#Herolegend4_301"]="夜深人静时，张景奇的思绪总是会被拽回17年前，那是他第一次遇到赵心音，也是他第一次感受到了什么叫无能为力……那年他38岁，意气风发，自喻这天下间已经没有他治不好的病症，所以当有人向他说起“病村”时，他没有犹豫就去了。所谓“病村”，其实是大陆中部一个不知名的小村庄，不久前，村庄中爆发了一种奇怪的瘟疫，这种瘟疫十分凶猛，受传染者一天之内就会发病，一周内就会因病致亡。冬末的一天，张景奇到达了这里，冰雪覆盖下，整个村子仿若一个没有生机的人间炼狱。起初，张景奇还是很自信，认为凭借自己的医术，一定能治好这种瘟疫，但渐渐的，他体会到了绝望。他在“病村”中待了一周，一周内，他翻遍了所有的药方，试过了每一种药草，却还是对这种瘟疫无能为力，只能眼看着身边的人一个个去世，最后只剩一一个八岁的小男孩，这个小男孩已经感染了三天了……绝望之中，张景奇想到了最后一个办法——蓬莱。于是他带上了小男孩，爬上宛如天堑的蓬莱。似乎是神迹一般，从蓬莱上下来之后，小男孩的病神奇的痊愈了。自己也好像突然开窍了一般，很顺利的就想出了治疗瘟疫的药方。开春之时，原本肆虐的瘟疫已经在大陆上消失了。在此之后，他收养了这个小男孩，并为他取名为赵心音……",
	["tid#Herolegend4_302"]="第二次见到李清秋是李清秋在被一个地痞流氓找茬，郭香香正抱着一捧莲蓬子吃的开心，看到之后躲在一边，用莲蓬子当暗器暗中帮助李清秋获胜。",
	["tid#Herolegend4_304"]="花间派自公孙大娘起便以歌舞名动天下，如今更是如此，然而人多了便生出是非。探花门刑伯严一日来坊中听歌赏舞，正当歌舞正兴之时，金钱帮的黄荣华突然现身，非要当场与刑伯严一教高下。这黄荣华出手动辄“山崩海啸”、“天翻地覆”，一些不懂武功的商人一时惶恐，纷纷要逃离这花间派。黄荣华不断地叫嚣着挑衅邢伯严，眼看就要动起手来，苏婉仪及时出现，说道既然要比试，在花间派的地盘上就要以花间派的方式比较，素闻金帮主歌喉动人，不如在此比试唱歌当如何。黄荣华虽然确实有唱歌癖好，但也有自知之名，当着坊中各界的面，便也只好作罢。",
	["tid#Herolegend4_305"]="家族家主一直感叹自己才能不足，三个儿子也是守成之辈，家族三代无人，败落就在眼前……直到她的诞生，是的，从诞生开始，这个神奇的小丫头就让家主看到了希望——传说中的家祖出生时的异象和这个女婴何其相似！从那天起家主再也没有感叹过家族无人，但是他也没有制止家中对她的中伤和敌视，因为宝剑锋从磨砺出，玉不琢不成器。",
	["tid#Herolegend4_306"]="姜笑川遇见小刘关江的时候，刘关江正背着弟弟找吃的，他看上了刘关江的根骨，他培养刘关江多年，终于也长成一代豪侠。对于姜笑川而言，刘关江就像自己的儿子一般，也希望他能够继任他的事业，只可惜刘关江更向往自由的江湖，对仕途无感，最终离开了姜笑川的身边，看着刘关江离开的背影，姜笑川难过了很久。",
	["tid#Herolegend4_307"]="倔强的姜承影昏迷后，被丐帮9岁的小姑娘沈念发现了，领回了家中，沈念也不知道姜承影竟然是名剑山庄的小公子，她自己又是小姐性子，自然是很快就忘记了领回的小男孩，姜承影在被小珠忘记的那段时间里过的非常清苦，饿得前胸贴后背，后来有一日他饿得眼冒金星，沈念蹦跳着拿着糖饼出现在后院，他二话没说过去就抢，还咬伤了沈念的手，沈念终于想起了自己领回家的这个小可怜，不仅没有责罚他，还好吃好喝的照顾他，听说他家在江南，更是承诺，等自己攒够钱，就送他回江南。自此二人形影不离，过了一段朝夕相伴的童年时光。",
	["tid#Herolegend4_308"]="一直有人问滔滔，你为什么不换掉笨重的船锚，换一个更加趁手的兵器呢？滔滔是这样回答的：兵器都是征服意志的固化代表，只是形状不同，本质上没有任何区别，如果不拿船锚，她更愿意拎着一条大鲨鱼打架，因为她相信，她自己的意志，是无可替代，也无法被代表的！",
	["tid#Herolegend4_309"]="某一日去包子铺吃包子的周湘君，本以为又是稀疏平常的一天，结果却在今天看到有个孩子吃了三十屉包子没给钱，于是他将她领回家了，而那个孩子就是滔滔。",
	["tid#Herolegend4_310"]="其实史春莲对外面的世界也不是很清楚，毕竟她也只去过周边的一些村镇，但她一贯喜欢摆出无所不知的姐姐做派，面对小妹妹的提问总是不好意思说不知道，于是就瞎编了许多。等到两人真的到了外面的时候，也闹了不少笑话；",
	["tid#Herolegend4_311"]="他毫不在意郭香香对自己戏弄，因为他似乎能够一眼看出郭香香姑娘的心意，郭香香是绝对不会加害自己的。他也似乎总能察觉到郭香香会出现在自己的身边，就像是上天派遣在自己身边的仙子。",
	["tid#Herolegend4_312"]="一次史春莲又去找筱九，但到了约定地点才发现筱九不在，只有一封信，信上说自己是族中的圣女，成年之后要被送往圣树，从此常伴在圣树身边，一步都不能离开。史春莲知道后，赶到了筱九的族中，大闹了一场，不由分说就带走了筱九。之后族中派了人来带回筱九，史春莲就带着筱九在江湖各处躲避。",
	["tid#Herolegend4_383"]="时间一晃过去了小半年，姜笑川见刘关江迟迟未归，恐生变动，于是加派了潜伏者前来料理此事。刘关江觉察后，当晚来到慕容清月房间，见慕容清月又在发呆，于是气急的抓住慕容清月的肩膀摇晃，要他不要在装痴呆了，说自己马上就要走了，走之前想再听他弹一曲。慕容清月的眼神慢慢聚焦，抱起琴，弹了首高山流水。刘关江定定的看了他一会儿，走出去，击退了追来的追兵。",
	["tid#Herolegend4_386"]="段徵言与李清秋的相遇似乎是段徵言命中注定的一段相互成就的经历，李清秋大条而原始，段徵言精算而温和，二人相辅相成，作为朋友他们能够将双方的缺点中和，作为知己，他们深知双方的缺憾。",
	["tid#Herolegend4_387"]="以天外异石的庞大能源为后盾，天机时刻都在对自己进行优化和升级，他的仿生装甲拥有超强的自我恢复能力，但是硬度并不强，这是为了保持一个最接近人类的外形，一方面是为了减少不必要的麻烦，另一个天机自身不愿意承认的理由是天机对于人类的憧憬。另外摸起来是温的是因为天机通过外壳进行核心散热刻意保持人类体温近似温度，战斗中因为演算原因和出力提升，通常都会高于常人，但是一旦到达巅峰，甚至能达到滴水化气的地步。",
	["tid#Herolegend4_391"]="暂缺",
	["tid#Herolegend4_392"]="暂缺",
	["tid#Herolegend4_393"]="暂缺",
	["tid#Herolegend4_394"]="暂缺",
	["tid#Herolegend4_395"]="暂缺",
	["tid#Herolegend4_401"]="翟冬玄已经忘记自己是怎么逃出来的了，他将已故的妻子安放在自己修建的陵墓之中，原本他自己也想就此陪着心爱的妻子长眠于此的。可是他看着眼前的妻子，他害怕自己一旦闭上眼睛就再也看不到她了……",
	["tid#Herolegend4_402"]="此战之后，长老们看着满天的蝴蝶和满地的毒蝎毒蛇，不可置信的望向一旁数虫子的阿岚，暗下决心。那天之后，阿岚的生活看起来和平时没什么区别，却其实已经丧失了自由，不能看想看的书，不能炼想炼的毒，不能平白无故捉弄教众，也再不能获得欢笑。",
	["tid#Herolegend4_403"]="祥颖韬刚决定为姜笑川效力不久，姜笑川就把他带到了两个人面前。这两个人就是张超和朱英杰，姜笑川说从此之后他们三个人就一起行动，他们的任务都是一样的。祥颖韬虽然很不待见这两个古怪的家伙，但他却不得不承认，这两个人在某些方面还是很有用的。毕竟，一切都是为了变强。",
	["tid#Herolegend4_404"]="然而，令“陆十一”没想到的是，他因为僭越与私斗，遭到了凌峰楼的江湖通缉，至于他那天究竟有没有胜过那个“拾”已经不重要了。后来他为了躲避凌峰楼的眼线东奔西走，好在他清楚凌峰楼的所有手段，然而他也因此变得疑神疑鬼，变得更加偏执。",
	["tid#Herolegend4_405"]="那书生跪在衙门口已经三天了，仍没有人出来。鸣冤鼓捶破了，嗓子喊哑了，精神也已经濒临崩溃，但“青天大老爷”却仍旧不肯接他的案子，因为他要状告的是小王爷。看热闹的人围了一圈，却没有一个人上前帮忙。只是低头说着“算了吧，得罪那个瘟神可没好下场。”“可怜啊，又一个好姑娘被那个混蛋糟蹋了。”“听说那姑娘回来之后就上吊了，辛亏救的及时保住了一条命，现在还在医馆躺着呢。”人群私语着，如同蝉鸣般聒噪。蓦的，人群中走出了一个人影，身段娇柔，仿若一个女子，但着装却是男性。那人走到书生面前，低语了几句后站起身来。“妻守节，夫不弃。你们可活。”说罢就离开了。不久之后，小王爷去世的消息就在城中传开了。",
	["tid#Herolegend4_406"]="唐明月幼年时候的一次暴雨，正在闲坐听雨的唐明月猛然看到门楣之下突然窜出一条细小的毒蛇。从不知道畏惧的唐明月便信手将那毒蛇拿在了手里，她非常喜欢那种冰凉却又丝滑的触感。那小蛇好像也不怕唐明月，一蛇一人像是两个彼此吸引的灵魂相互交缠在一起，彼此获取着对方的活着的生命的气息。那小蛇盯着唐明月缓缓地盘绕在唐明月地手指上，幽幽地吐着蛇信。唐明月对这条小蛇喜欢地不得了，将这条小蛇养了很久，但是直到某一天，小蛇再也不见了。唐明月明白，那条蛇其实就是自己，她已经去游历山河了，而自我的身体却困在这唐家堡里。",
	["tid#Herolegend4_407"]="于是，阁主便谎称朱英杰患了疯病，难以承蒙凌峰楼的招揽。可过了几年，终究是纸里包不住火，有一个长老看出了事情的端倪，他为了获得凌峰楼的承诺出卖了老阁主的苦心筹谋……后来随着老阁主的去世，朱英杰不想违背老阁主的意愿，于是从合欢阁逃了出来。",
	["tid#Herolegend4_409"]="秦飞雪成人之后，也做过坊间的武侯，也常与不良人打些交道，后来巨侠进了大理寺，也与李延广与李郡等人结成好友。只不过，秦飞雪一直心在江湖，无意当差为官，始终婉拒了李延广邀请他加入锦衣卫司的邀请。",
	["tid#Herolegend4_410"]="明教长安中伏，江湖各个与明教积怨的门派势力闻讯纷纷中途出手，光明寺一役后半日之内，明教中土各大分舵皆被摧毁，那时的陆小贝还小，许多事还不明了，许久之后，当她在域外与父亲重逢，得知了带着她万里漂泊的七叔便是“长风万里”卫七之时，才知道卫氏轻功，向来号称天下无双，“长风万里”卫栖梧，本就是夜走千家，劫富济贫的侠盗，一路上无数的艰险，若是只有卫七一人，早可走得无影无踪，如今仔细寻思，卫栖梧平凡的面容，却是天下最能令她安心温暖。",
	["tid#Herolegend4_411"]="一直有人问滔滔，你为什么不换掉笨重的船锚，换一个更加趁手的兵器呢？滔滔是这样回答的：兵器都是征服意志的固化代表，只是形状不同，本质上没有任何区别，如果不拿船锚，她更愿意拎着一条大鲨鱼打架，因为她相信，她自己的意志，是无可替代，也无法被代表的！",
	["tid#Herolegend4_412"]="为人武功高强，颇有城府，机关算尽设计五岳并派，不能暗谋，便是明攻，务要得手，是个不择手段向目标迈进的人。",
	["tid#Herolegend4_413"]="神水宫宫主只爱女子，仿佛是那时江湖中的不传之秘，不过没人知道，这宫主却也爱上过一个男子。那男子出身落英轩，行踪成谜，却有一副柔美面容。原本厌恶男子的玄水姬却对他难以自拔，只可惜，飞花无情，落红无意，小小的天池自是缚不住那人的步履，自此神水宫仿佛是失了神一般。",
	["tid#Herolegend4_481"]="因为这件事，父亲对张景奇更加看重了，张超觉得有些自责，也觉得父亲对自己非常的失望，于是他离开了永阳镇开始了流浪。但是他没有放弃与张景奇争个高低，他决定从现在开始另辟蹊径。",
	["tid#Herolegend4_484"]="宋英男在大海中缓缓下沉，可是在下沉的过程中她却后悔了，她觉得如果就这样失去了生命，那自己又算什么呢？自己又何尝不是怯懦之人呢？只是，宋英男不会游泳，要如何升出水面呢，此时胸腔中的空气已经很少了，濒死的感觉和汹涌的情绪交织起来，却让宋英男迸发了强烈的求生欲望，也让她获得了海的力量。宋英男挥动手臂生出海浪，摆动双腿形成拥有动力的漩涡，将宋英男高高推出水面。",
	["tid#Herolegend4_485"]="生平没有被指望过的摩波旬忽然一下感觉血气上涌，似乎是师父的血脉起了作用，他爆发了潜藏十几年的力量，夺过土匪首领的刀，把一帮土匪打得片甲不留。官兵来了之后，那个小姑娘似乎是被吓坏了，跟官兵说是摩波旬是凶手，说他做了这一切，于是摩波旬被捕入狱。",
	["tid#Herolegend4_491"]="暂缺",
	["tid#Herolegend4_492"]="暂缺",
	["tid#Herolegend4_493"]="暂缺",
	["tid#Herolegend4_494"]="暂缺",
	["tid#Herolegend4_495"]="暂缺",
	["tid#Herolegend4_501"]="父亲看出来了儿子身上的端倪，于是与大师商讨了几番，让李知傲还俗下山去了。下山之后，李知傲便苦苦寻找那个姑娘，其间经历了不少神奇的经历，不过随着他的内功也渐渐大涨，在江湖上有了一些名气。",
	["tid#Herolegend4_502"]="就像月亮在最黑暗的夜晚照亮大地，双子总是能在战争纷扰的地方带给人们最最直接的抚慰，如果说恶魔天生能够蛊惑人心，那么昆仑双子就像圣贤童子一样能够疗愈人间。",
	["tid#Herolegend4_503"]="梁铮雨很喜欢清净的云隐岛，也经常捧着一本书在一棵参天古木下，一坐就是几个时辰。每每此时，也是句芒与逸心促膝长谈之时。逸心将梁铮雨的身世，连同一些信中不能尽言的前因后果一并告诉了句芒。中原实力雄厚之人比比皆是，但逸心下意识地更愿信任这个仅有数面之缘、一直靠书信维持联系的兄长。但后来，在梁铮雨的坚持下，逸心还是带他回到了蜀山。虽然没帮上忙，但因与逸心结识而懂得了兄弟情谊的句芒觉得，这样的结局，似乎也不错。",
	["tid#Herolegend4_504"]="贴心佩戴红琥珀的霍紫凝有了非凡的武力与得以重生的天赋，她铭记母亲的恩情，并将母亲的慈悲以自己的方式传达到世间角落。霍紫凝也因此受到许多平民家庭的喜爱。但同时，她也在一直寻觅父亲的踪迹。她一直等待着那一天的到来。",
	["tid#Herolegend4_505"]="在日积月累中，逍遥逐渐倾心于其师父。但她原生家庭原因导致她对于情爱之事体会甚少，总感觉自己在和师父斗智斗勇。而处于世俗束缚中的师父明白逍遥的心意后，却无法坦然面对，故而留书一封，离开了萧春风。",
	["tid#Herolegend4_506"]="年轻的周文浩很快就凭借着一身本领广招门客，意图复兴当年祖上时鼎盛的家门，而他本人便能成为一方之主，从而号令诸多门众称霸武林。在周文浩的势力极速扩张时，终于引起了江湖中其他势力的注意，在阳谋和阴谋中，周文浩就在这样凶险的江湖里厮战成长，逐渐也成长为老谋深算的权谋家。",
	["tid#Herolegend4_507"]="数年后，梁钲雨竟已武功大成，然而蜀山长老们也隐隐觉得将梁钲雨庇护于蜀山不是长久之计，虽然尘间庙堂早已天翻地覆，可新任者为保地位稳固，依旧在寻找梁钲雨。梁钲雨的身份似乎不言而喻了，因此大师兄提议蜀山到云隐岛论道之时可借口将梁钲雨藏身与此，云隐岛远离中原，定是小师弟继续避世隐居的好地方。",
	["tid#Herolegend4_508"]="那段时间，天忍教似已打探到风声，暗暗追查他的下落，唐寅不便表明身份，只能暗中关注姑娘。但天忍教的消息远比他想象得灵通，他的一举一动都落在了探子眼里，并随即制定了新的计划。天忍教忌惮他的武功，不敢正面对决，便索性劫走姑娘，作为人质要挟他。当他再次去找姑娘时，发现已人去楼空，只有一张天忍教的字条，约他三日后郊外相见。",
	["tid#Herolegend4_591"]="暂缺",
	["tid#Herolegend4_592"]="暂缺",
	["tid#Herolegend4_593"]="暂缺",
	["tid#Herolegend4_594"]="暂缺",
	["tid#Herolegend4_595"]="暂缺",
	["tid#Herolegend4_607"]="面对来自整个江湖的压力，求伯君没有退缩，他开始闭关修炼，带着十几个同门一起，苦心钻研，寻找金山派的出路。虽然世间有诸多纷扰，但他坚信，实力才是证明自己的最好方式。一年后，天忍教接到了来自金山的战书，在江湖中传得沸沸扬扬。那一战，求伯君在整个江湖的瞩目下，以金山的剑法，击败了天忍的凌绝剑式。他将天忍教假意结盟，却背后暗算的阴谋公之于众，赢回了金山的清正之誉。无数次夜以继日的艰辛，终于在这一刻得到了证明。",
	["tid#Herolegend4_606"]="直到进入少室山，见到同样意气风发的清觉时，鸠摩罗感受到，此生的宿敌便是此人了。那一次，鸠摩罗与清觉有了一场针尖对麦芒的决斗。最终胜负不了了之，世人皆以为平局。 此后，二人又比拼了无数次，从法学到武学，皆是平分秋色，从未决出过真正的赢家。所谓劲敌，大约莫过于此。",
	["tid#Herolegend4_602"]="现在，她可以驱动轮椅，很轻松地翻越矮小的山丘，甚至通过自己的改进，轮椅也可以载着她渡过河流，渐渐地，她在轮椅上增加了很多能够摄人心魄的内容，这样常年的生活，使她的内心变得阴暗孤僻，直到有一天，邪极坊的人找上门来，她得知自己的父亲是邪极坊的机关师，她知道，自己的价值终于要得到重视了。",
	["tid#Herolegend4_603"]="当柳念遇到筱九时，她早已在中原闯荡多年，江湖也早有了她的冰山雪莲鬼见愁的名声，然而筱九与同行的史春莲却并不怕她的样子。原本柳念对此二人也毫不在意，然而筱九身边的飞雪白猫似乎激起了她的兴趣，也就不自觉地随他们同行了很久。",
	["tid#Herolegend4_604"]="刘异意识到，自己自幼与冰雪的联系，冥想时脑海里的声音，种种异象，答案都在这个山洞里。“生死符”能以真气驭动冰雪、化气成冰，威力胜于世间各种暗器。只是，修炼此功需有非凡的意念之力，人心皆有杂念，欲达此心境，便要付出些代价。刘异在山洞中苦修了一月有余，最终以毁去双目、再不见世间纷扰为代价，练成了灵鹫绝学。走出山洞后，两只异兽如驯服的家犬般伏身在他面前，从此他便再不是那小村庄中的孤僻少年，而是将再一次叱咤江湖的——灵鹫宫主。",
	["tid#Herolegend4_605"]="家族族长，也就是周今鸣的生父，很快就因为这个女儿在权术与武学方面的飞速发展，而想当然的忘记了长子与次子的事情。在一个雨夜，他与周今鸣把酒言欢，畅谈未来的光明前景。可第二天，族长便感染了非常严重的风寒，很多郎中都束手无策只能看着族长撒手人寰。掌握了家族大半部亲信的周今鸣，隐秘的宣告了族长离世的事情。她一步步靠着自己的计划，走上了带领世家复兴的高位。",
	["tid#Herolegend4_691"]="暂缺",
	["tid#Herolegend4_692"]="暂缺",
	["tid#Herolegend4_693"]="暂缺",
	["tid#Herolegend4_694"]="暂缺",
	["tid#Herolegend4_695"]="暂缺",
	["tid#Herolegend4_701"]="后来，在某次煞气发作之时，为紫胤真人所救，于是小云溪便带着凶剑焚寂拜入紫胤真人所在的昆仑山天墉城门下，并更名改姓。在天墉城，由于百里屠苏体内煞气之故，紫胤真人故而不让他与其他弟子有过多接触。不过屠苏在剑术方面极具天赋，因为幼年的遭遇，他总是无时不刻地遭受自我内心的谴责，习剑之后将执剑在手视为一种安定内心的力量，练剑刻苦到近于苛刻。",
	["tid#Herolegend4_702"]="虽然只又数月的短暂相处，风晴雪与百里屠苏二人的命运却早已紧紧相连，二人彼此间也是相知相惜。晴雪为救屠苏不惧禁闭十年的惩戒，私自将众人带入幽都，也在幽都对屠苏表明心意，放弃灵女之愿，决心天涯相伴，至死不悔，二人从此成为眷属。",
	["tid#Herolegend5_101"]="李将军班师回朝，向皇帝如实禀报林无双的经历。皇帝勤政开明，非但没有因林无双是女子而动怒，反而龙心大悦，于金殿前亲自召见林无双，当面奖赏于她，称林无双为“奇女子”也，以一介女子取敌酋首级，扬我大唐天威于异域，特命册封林无双为“宣威将军”。",
	["tid#Herolegend5_102"]="王司马的养父是王都的大军阀家，有谋略又武艺高强，只是可惜的是，并没有登上蓬莱，获得点悟，养父数次前往，均无功而返。每次去云隐岛蓬莱，都要去将近两个月，小王司马很依恋爸爸，也很奇怪为什么每次爸爸都离开自己两个月，某次她跟着爸爸一起出发，半路饿的不行了才被爸爸发现，只好带着她一起上路，没想到最终却成就了小王司马的点悟！！",
	["tid#Herolegend5_103"]="要说李延广最强的武器，倒是他的智慧和正义感。他以父母为学习的榜样，而他的父母也潜移默化地教他明辨是非的道理。虽然家族在皇室中的教育地位让他们的生活富足殷实，但他的母亲却时时警告他，中原江湖充满了诱惑，镀金裹糖的花言巧语可能会令最仁慈的心也变得冷酷无情。李延广并没有将母亲的警告放在心上，因为长安对他来说是一座无比美丽的城市。每当去过四海八荒上其他地方，他都会更加珍惜故乡的秩序井然。",
	["tid#Herolegend5_104"]="李郡曾经想过要找到自己的亲生父母，可是不详之谷每天都有那么多被遗弃的孩子，她无从下手，或许这就是命运吧，有些人犹如无根草，一开始就没有根，也不必去寻根。",
	["tid#Herolegend5_105"]="苏婉仪怎么也想不到，自己竟会对一个不食人间烟火的和尚动了心思——同样的，清觉也想不到，自己一个少林的出家之人，终究是要在这滚滚红尘中惹上一段情丝。在那个月黑风高之夜，有人对花间派的姑娘们动了歹念，胆大包天的一伙劫匪闯入花间派便要劫人。喊打声和火光惊扰了在附近夜读经典的清觉，清觉二话不说便赶往花间派，也顾不得自己少林门人的身份将来犯歹徒三下五除二地尽数击退，待到苏婉仪赶来时，恰巧遇见已然解决了歹人的清觉，她一眼便认出面前这小僧正是自己数日前见过的讲学和尚，问得了法号后，便目送着清觉匆匆消失在了夜色之中。",
	["tid#Herolegend5_106"]="刘关江很少记得自己的任务对象，因为这些已故之人早已无关紧要。但唯有那么几场惊心动魄的战斗，让忍不住回味。最近的一次应该是那个住在深山中的老琴师。虽然武力不怎么样，但是他的琴音却有一种很神奇的魔力，让人一听到就精神恍惚，连站都站不稳。好在无数次任务中锻炼出的狠厉救了他，他果断咬破自己的舌尖，疼痛感瞬间让他清醒了过来，也仅是这一瞬间的清醒，便足以让他击破老琴师的音障。琴声陡然而止，一根琴弦猛然挣断，发出一声无力的悲鸣。刘关江从腰间取下一颗狼牙放在老琴师身边，那来自他这辈子遇到过的最强的对手，也象征着对老琴师的尊敬……刘关江正沉浸在回忆中时，耳边突然传来首领的声音。首领递过来一张画像，那是他下一个任务对象——慕容清月。",
	["tid#Herolegend5_107"]="一次围剿贼军的行动上，他燕云飞带领的玄甲军与林无双所在的天策军站在了同一战线，他钢铁般的内心在看到林无双的那一刻，忽然有了漏跳一拍的感觉，转念间，战胜归去，皇帝暗中撮合这对未嫁未娶的年轻将领，燕云飞面上不表，内心却纠结万分……",
	["tid#Herolegend5_108"]="起初的摘星阁确实是靠着张昊观星推背演算出来的情报，不过这样的效率太低了，远远达不到开门做生意的地步。他尝试了很多办法，用推算的重要情报来收买人心，笼络人脉，但是一直不见起色。直到有一天，他想到可以利用遍布天下的乞丐来获取情报。于是他带着一箱子的钱找到丐帮的沈念来谈合作，可没想到的是，这个丐帮姑娘只是说跟她比这个，要比得过才能合作，说着她打开了一坛冒着辛辣气味的水饮。那一日张昊喝的不省人事，一向精明的他也不知道为什么同意了这荒唐的提议，但是好在对方答应了合作的要求，为摘星阁的初建奠定了基础。",
	["tid#Herolegend5_109"]="手足之情，切莫忘记\n哥哥救了她，却失去了自己的生命，她继承了哥哥的弓，也要继承哥哥的意志，将哥哥的人生也完美的过下去，禹海莲永远忘不了，哥哥最后挡在自己身前时候的背影，也不会忘记哥哥在自己怀里过世的时候，脸上的带着希冀的眼神，那种神情，现在年幼的禹海莲还无法理解。可是她将带着这份希冀继续走下去，等待着能跟哥哥共鸣的那一天。\n",
	["tid#Herolegend5_110"]="暂缺",
	["tid#Herolegend5_111"]="没有人能清楚知道她的踪迹，她可能会随时随地出现在任何一个她仇敌的面前，舞动起绰约的身姿，华丽的如同鲜艳羽毛的衣袂却暗藏着刀尖，刺入她目标的喉咙之上。",
	["tid#Herolegend5_114"]="暂缺",
	["tid#Herolegend5_115"]="然而，加入军营毕竟是部落与朝廷之间的盟约，这是他身为“天鹰”不得不履行的职责，方剑斌他自己却无时不刻地渴望着自由，他时刻希望自己也能如同雄鹰一样翱翔在苍天之下，无拘无束。总有人看着他盯着蓝天发呆，旁人以为他可能时刻都在通过他的战鹰在视察着前方的敌情，只有萧不语知道，他只是看蓝天而已。",
	["tid#Herolegend5_181"]="神机营萧不语，在一次对北方入侵者的反击中，由于营中遭遇对方偷袭，很多辎重与武器遭到破坏，不得已向神刀门求助。然而此时的神刀门，依旧陷于内忧外患当中，难以提供帮助。但是如今已经掌权的郭惊涛心里却另有打算，于是他私下会见了萧不语，表示愿意帮助神机营和所属大营。萧不语非常感谢郭惊涛大义之举，于是郭惊涛私下购置了一批粮草，并从山庄的刀库中调去了一部分武器，送到了神机营。所幸，支援及时，神机营取得了大捷，萧不语非常感激郭惊涛，并承诺将来一定报答郭惊涛的恩情。",
	["tid#Herolegend5_182"]="在蓬莱的经历，是杨素素最刻骨铭心的经历，她认识了能够影响她一生轨迹的人，也经历了足以改变她人生的事，蓬莱之旅促使一朵被厚厚命运裹挟的花朵，冲破所有的桎梏，怒放开来。",
	["tid#Herolegend5_183"]="萧不语此后接过了父亲留下的猎枪，苦练枪法。战争带走了萧不语宁静的生活，也带走了他幸福安稳的家庭生活。敌军的到来使得萧不语获得了与之前大不相同的人生目标，从军。",
	["tid#Herolegend5_184"]="然而，加入军营毕竟是部落与朝廷之间的盟约，这是他身为“天鹰”不得不履行的职责，方剑斌他自己却无时不刻地渴望着自由，他时刻希望自己也能如同雄鹰一样翱翔在苍天之下，无拘无束。总有人看着他盯着蓝天发呆，旁人以为他可能时刻都在通过他的战鹰在视察着前方的敌情，只有萧不语知道，他只是看蓝天而已。",
	["tid#Herolegend5_191"]="暂缺",
	["tid#Herolegend5_192"]="暂缺",
	["tid#Herolegend5_193"]="暂缺",
	["tid#Herolegend5_194"]="暂缺",
	["tid#Herolegend5_195"]="暂缺",
	["tid#Herolegend5_201"]="原本林良骏希望韦壮武成年之后能帮自己自家的镖局做镖师的，然而韦壮武却认为自己莽撞，也不喜欢拘束，更不在乎体面，就算给自己的好兄弟做镖师，也只会搞砸的事情，也会因此让二人决裂。因此他在一日清晨离开了家乡去了一座山里，听说那里的人都很凶狠，去到那里说不定才是适合自己的地方。",
	["tid#Herolegend5_202"]="终于有一天，在一场交手之中，二人有了交手的机会，但是对方实力的稳健与功力的雄厚，是黄荣华始料未及的，但这并没有让金钱对他的印象有什么好的改观，直到他失手差点毙命之时，刑伯严居然出手搭救，黄荣华终于开始陷入了自我怀疑。",
	["tid#Herolegend5_203"]="他其实并不想和黄荣华做过多的斗争，他有信心能打得过黄荣华，但是在另一方面他也敬爱这个对手，他觉得这个黄荣华的存在也是他存在的一部分意义。",
	["tid#Herolegend5_205"]="白衣剑客和靳辰洋交手数十合，两人你来我往斗了个旗鼓相当，却也在这见招拆招的比试里生出些许惺惺相惜之感；靳辰洋本就对面前这少年怀有几分感激之情，如今随着以武相会更觉心意相通，一个摆拳甩过正撩起那白衣剑客的面纱，靳辰洋这才认出，那白衣少年的模样正是当年在客栈落难时对自己出手相救的少侠；靳辰洋想着自己要不要故意卖个空当让这英俊少侠赢了比试也赢娶个自己，怎料这少侠却先卖了个破绽，三两合就败下阵来连招呼都不打便遁走了，落得靳辰洋自己在台上怅然若失，后来通过消息灵通的江湖人士打听方才得知，那位白衣少侠正是宁不凡，怕是早已心有所属，感叹有缘无分吧。",
	["tid#Herolegend5_206"]="在沈念常来的一间客栈里，她将手中的杯子推给了身前一袭白衣的官家女子，那女子也不客气摘下斗笠放在一边，拿起杯子来扇风闻了闻，便起杯痛饮，呼一声“好！”。这一身英气的白衣女正是官家大名鼎鼎的锦衣卫，李郡。就在一时三刻之前，李郡追捕一名轻功了得的采花大盗，李郡虽然一手傲人的锁刀功，无奈轻功稍逊一筹，好在沈念也注意此贼良久，关键时候一掌拍出……李郡很感激沈念仗义出手，可没想到倒是沈念直言多谢官家制服此贼，非要请她吃一杯。如此觥筹之间，二人意气相投，相聊甚欢，都说出彼此夙愿，竟没想到二人都在找一个孪生姊妹，二人因而更加惺惺相惜了。",
	["tid#Herolegend5_207"]="宁不凡很少告诉别人，他能够看出人心的颜色。只要他仔细的观察一个人，就会有一层雾气从那人身上浮现。善良的人是白色，邪恶的人是黑色，越善良的人，白色越浓郁，越邪恶的人，黑色越浓郁。但他却从未见过赵心音身上的那种颜色，那是一种非黑非白，宛如枯槁一般的灰。宁不凡很好奇，便主动接近了赵心音。虽然赵心音的性格有些恶劣，但经过宁不凡的努力，两人还是成为了朋友。不过也仅限于偶尔一起喝一杯，很少深入的谈过。一次醺醺然后宁不凡想增进一下两人的关系，便开玩笑的对赵心音说“你这张脸啊，即便是个男人，怕还是会有人爱上你。”谁知道赵心音一下子变了脸色，一伸手便震碎了宁不凡心脏周围的经脉。幸好宁不凡天生与常人不同，心脏长在右边，才侥幸生还。但即便如此，他还是昏死了一整天才醒，之后他便再也没有找到过赵心音的行踪。",
	["tid#Herolegend5_208"]="虽然辛晓风已经在接到传书的时候立刻往回赶，但回到妙法庵的时候已经晚了。曾经的一起生活的师姐妹全都躺在地上，生死不知，地面上满是赤色痕迹。还未来的及救治，就听得后殿传来了一声惨叫，赶过去时，正看见师父在一位中年男子的面前缓缓倒下。突然遭到如此大的打击，辛晓风的情绪在一瞬间崩溃，满头的黑色长发突然急速变长，如同利箭一般射向四周。中年男人挥剑砍向发丝，剑却如同豆腐一般被切断。最后，辛晓风逼退了青城，自己却也被周围宛如钢丝一般的头发困住，无法离开后殿。被困在妙法庵中的时间，辛晓风渐渐明白了自己对宁不凡的感情，也越来越思念宁不凡。但越是思念，头发就长，最后整座妙法庵中都充满了锋利又坚韧的发丝，任何人都无法进入。",
	["tid#Herolegend5_210"]="吕沛杰从蓬莱岛回来之后觉醒了通透世界，通透世界是指他通过二胡声音共振获得身边事物的方位和移动方向，还可以收集敌人的敌意然后全部释放出去，对对手进行恐吓。",
	["tid#Herolegend5_211"]="算算时间，今年张景奇也该来了吧。这几十年这小子的棋艺进步的可真快，已经能和自己下的有来有回了，说不定还真有机会赢自己一局呢。况候智这样想着，却没有等来张景奇……又过了三个月，张景奇才姗姗来迟，脸上却不再有往日的兴奋。况候智心中稍一盘算，便有了答案，他推算的果然没错，这小子的徒弟果然还是救不回来啊。下棋的时候，张景奇始终心不在焉，被况候智打得七零八落。\n况候智叹了一口气“不下了，没意思。”\n张景奇：“我错了吗？”况候智摇了摇头。\n张景奇：“他错了吗？”况候智还是摇头。\n张景奇：“既然都没错，为什么会这样？”况候智叹了一口，递上一张纸。\n“回去吧，到了上面再看。”回到崖上，张景奇展开了手中的纸，上面写着“一年后来找我。”",
	["tid#Herolegend5_212"]="谢云流出逃的事情发生后，一开始，尽管吕洞宾常常劝慰吴清霄要宽容，但他仍无法接受师兄打伤师父的事实。可日子一长，吴清霄想师兄在外漂流肯定也受了不少苦，又想当时那种情况如果换成自己，只怕多半也是如此反应。自那以后，吴清霄便开始私下寻找谢云流，希望他能够和纯阳教冰释前嫌，并重新回到纯阳。但是谁想这世间种种阴差阳错，再加上后来发生的神武遗迹的误会，让谢云流的回来成为一种奢望。后来纯阳弟子经常看到掌教独自在论剑台上舞着一套不曾见过的古怪剑法，但是看起来招式之间颇有些拙劣，又像是双人的剑舞缺了一个人。",
	["tid#Herolegend5_213"]="在水路不发达的年代战胜了晕船而出国读书的他可谓非常勤奋了，也是当时西域人眼里的学霸。",
	["tid#Herolegend5_281"]="于是那日起，焦渝钦成了这间店的掌柜，她践守着答应掌柜的事情，努力将客栈修好继续经营着，同样的，她依然在这里接济着各个路过的落魄的可怜人。不过比起前掌柜，焦渝钦学会了跟恶人们打交道，也在不停练习着从掌柜那里学来的飞刀功夫，成了龙门一颗鲜红的明珠。",
	["tid#Herolegend5_282"]="左寒修实在是太可怕了，眼神一扫胡大壮就感觉自己背筋发硬头都扭不动，还好宁不凡在这种时候总是恰到好处的过来解围。胡大壮看不懂两人之间的机锋，但是直觉告诉他最好离这个阴鸷的大叔远一点。",
	["tid#Herolegend5_283"]="黑袍丢了徒弟和一条灵蛇，不疾不徐地写了一封慢信，寄往了万年县。\n两个月后，它静静搁在一坪棋盘面前，信角被一枚黑子压制，黑子匍匐在一位精神奕奕的年轻人面前。\n「飞鹰，是不是信中所提之人揭的万年县榜？」\n「咕咕！」\n「受人之托，真是麻烦。走吧，你的食物来了。」",
	["tid#Herolegend5_291"]="暂缺",
	["tid#Herolegend5_292"]="暂缺",
	["tid#Herolegend5_293"]="暂缺",
	["tid#Herolegend5_294"]="暂缺",
	["tid#Herolegend5_295"]="暂缺",
	["tid#Herolegend5_301"]="张景奇一直觉得自己可以把赵心音导回正途，直到三个月前……他终于在一个小镇上遇到了赵心音。\n张景奇：“孩子，回头吧，只要你认错，我还是……”\n赵心音：“师父啊师父，我本就没有错，为何要认错？为何要回头？”\n张景奇：“你你你，你忘了我对你的教导了吗？”\n赵心音：“当然，师父的教导，我可一直都记着呢，济世救人……”\n张景奇：“既然都记得，那为何还要做这种事？”\n赵心音：“师父啊师父，您的眼光终究还是太狭隘了啊，“济世救人”这四个字，您到底只是做到救人，但我，可是在救世啊。”\n赵心音：“看看如今这个世道吧，天者不天，地者不地，君者不君，亲者不亲，师者……不师！您还看不出来吗？这个世界生病了啊，而这些人，就是病因！我要拯救这个世界，消除病因是理所当然的！”\n张景奇：“孽徒！一派胡言！”\n…………\n从那天起，张景奇知道了，已经太晚了……",
	["tid#Herolegend5_302"]="她由于从小生活环境优越，父母为人正直，所以她接受的教育让她成长为一个非常善良的女孩，遇到了残疾人会倾囊相助，但是冰雪聪明的她，也能准确分别来者是不是骗子。",
	["tid#Herolegend5_304"]="一次，坊中姐妹受辱，对方仗着手中势力，率众无理闹事。花坊中的小七狷狂磊落，快意恩仇，行事全凭好恶，面对这样的事情，小七当然对其愤而殴之。小七闯了祸，对方自然是要来寻仇的，那时的场面不可谓不危机，对方率部前来，声称要让花间派付出代价，似乎是要一举夷平了花间派。此时苏婉仪挺身而出，翻身跃入人群，起舞般瞬间击败几名寻仇者，自己却全身而退回到花坊前，说道，胆敢闯入花坊者，下场便如这般。寻仇者这边却一时间方寸大乱，鼠窜离开。此后花间派在江湖中威名大震，几年内再无人敢来此寻仇，但遗憾的是小七还是离开了花间派。",
	["tid#Herolegend5_305"]="被墨家一族封印了数百年的天机不断演算、不断进化成了与人无异的“异类”，虽然对外界的知识一无所知，但是它超常的计算力和丰富的感性让郑可可觉得它比自己更像一个人。惊叹于天机作为一个“生命”的完美的同时，也不平于它将被家族永生永世压榨摄取的命运。虽然即使不像郑可可这么聪明也能预见到等待着她的是来自家族全体的雷霆之怒，但是她仍然释放了天机——她所认可的唯一的朋友",
	["tid#Herolegend5_306"]="姜笑川与江湖人无间合作，成功铲除了朝中的罪恶势力，因此姜笑川在江湖中一直名望颇高，也遭到了奸佞余党的嫉恨。在经历几次恶党的报复之后，姜笑川终于决定拜托一些江湖朋友教他一些武艺防身，却没想到自己颇有天赋，不出几年也卓有小成。",
	["tid#Herolegend5_307"]="天宝二年姜承影重返名剑，姜家全家上下一片欢腾，姜大小姐天宝元年离家，名剑弟子遍寻江湖不得，念及她身患之症，不免心下忐忑，此时五少爷一去十一载，安然归来，风神俊郎，才华出众，实乃名剑大喜之事，此事也是当年江湖人俱都津津乐道之事。",
	["tid#Herolegend5_308"]="滔滔时常会想念老渔民，她相信老渔民只是化作了海面上那多如波光粼粼般海浪里的其中一朵，在变幻莫测的海洋上感受平静和凶猛，也等待着她自己的灵魂变强变得更加勇敢！",
	["tid#Herolegend5_309"]="他觉得滔滔这么能吃绝对有输出口，不然不可能这么大的能量无从消耗，于是让滔滔打自己一拳，滔滔年幼，还真不怕他，给了周湘君一大拳，周湘君纹丝未动，却感受到了滔滔这拳中所蕴含的信念和能量。因此周湘君下定决心收她为徒。",
	["tid#Herolegend5_310"]="筱九遇见飞雪的时候是在万灵树，那时她刚从上一任圣女那里学习回来，一出门就看到它蹲在面前。筱九刚准备伸手逗一逗它，它就直接跳到了自己的怀里，并且怎么都不愿意离开筱九，筱九只好带它回家。从此之后，这只小猫就一直跟着筱九。",
	["tid#Herolegend5_311"]="在蓬莱的历练期间，他结识了段徵言，他十分羡慕段徵言渊博的学识与温润如玉的性格，因为这正是他欠缺的，他总觉得自己勇武过头，缺乏了一点智慧，因此总是愿意听段徵言讲一些学问上的东西，虽然他不大能够完全理解。",
	["tid#Herolegend5_312"]="不知道为什么，史春莲跟柳念一直不对付。因为柳念一直对谁都冷冰冰的，跟她说话也总是爱答不理，而且看筱九的眼神总是有些奇怪。但筱九却很喜欢柳念，还说带着柳念一起，她本以为柳念会拒绝，但柳念却出人意料的答应了。",
	["tid#Herolegend5_383"]="慕容清月二十二岁，他在呆滞中的时间开始变得越来越短，随着他第一次做到全退来敌，他坚定的意志和信心也于梦中生效，他越来越快的击退所有的敌人。旁人看来，大公子却是有些更加呆傻了，一头散发垂在坚定的玉面旁，却偶尔在浑噩中伴随着微笑的慕容清月，不知不觉中得了“疯子大爷”的称号。",
	["tid#Herolegend5_386"]="这一段生死之交源于段徵言家的一个变故，段徵言青年丧父，由于父母伉俪情深，母亲因父亲的过世大受打击，整日消沉，虽说段徵言对待旁的事都十分游刃有余，可偏偏遇到这种家务事他却不知道如何处理，疏于安慰母亲，导致母亲神志迷茫间失踪，李清秋与段徵言外出寻找，终于在几条街外的集市找到，危急时刻母亲就要被马车撞倒，李清秋挺身而出一把捞起段徵言之母，却差点因此受伤。李清秋不以为意，而段徵言将其称为生死之交。",
	["tid#Herolegend5_387"]="冉无名的核心演算装置藏在“天外异石”中，在漫长的岁月里一点点地用天地灵气、周围的机关零件重新构筑、修复、升级了自己的身体，直到天机楼的动力室到来了意外的不速之客——墨家，他才知道原来时间已经过了一千年。因为父亲认知中的墨氏一族早已被风化为烟尘，所以冉无名自己将任务设为完成，从使命中解脱的天机在墨家的帮助下逃离了天机楼。面对千年后，也是拥有真正自我后首次接触到的天地，天机心潮澎湃，准备听从自己来自核心深处的呼唤，前往蓬莱……",
	["tid#Herolegend5_391"]="暂缺",
	["tid#Herolegend5_392"]="暂缺",
	["tid#Herolegend5_393"]="暂缺",
	["tid#Herolegend5_394"]="暂缺",
	["tid#Herolegend5_395"]="暂缺",
	["tid#Herolegend5_401"]="翟冬玄按照妻子的模样，利用自己高超的木匠技艺，制作了一个人形傀儡，他离开藏身的陵墓，带着他的“妻子”开始浪迹天涯，他相信迟早有一天，他一定能找到真正的重生之法，让妻子重现于世。",
	["tid#Herolegend5_402"]="阿岚就这样在禁锢之下成长，长成了一个亭亭玉立的少女，由于自年幼就很少有人与她接触，所以她的外形成长了，可是内心还是那个懵懂而不知残忍和残酷为何物的小女孩，只是她也不觉得这有何不妥，整日与自己的蝴蝶小蛇什么的玩玩，倒也不错。",
	["tid#Herolegend5_403"]="从姜笑川口中，祥颖韬知道了蓬莱的力量，也终于明白了自己为什么输给了李延广。他很不甘心，央求姜笑川带他去蓬莱，姜笑川答应了。从蓬莱下来之后，祥颖韬获得了比之前要强百倍的力量，假如哪天他再次面对李延广时，似乎也有了能够战胜他的信心。",
	["tid#Herolegend5_404"]="后来“陆十一”逃去了蓬莱，似乎他在蓬莱遇到了什么改变他命运轨迹的人，待他回到中原之后便直登崆峒山，化名陆尘子，成了崆峒的客座长老。后来，原本没落的崆峒在他的帮助下，逐渐在江湖间又有了些声名，也让凌峰楼注意到了这一点，而学会了崆峒七伤拳的陆尘子似乎也在不再害怕天罗的高手们了。",
	["tid#Herolegend5_405"]="赵心音曾经有过一个朋友，那家伙是个三流剑客，总是爱开着一些不着调的玩笑，每每兴起便弹剑而歌，唱的别提有多难听了。但赵心音觉得他不错，因为作为一个剑客来说，他对剑的态度还不错。但可惜的是，在一次迷迷糊糊间却说了胡话，那是他所不能忍受的话所以……赵心音愤而离去，之后赵心音便再也没有交过朋友。",
	["tid#Herolegend5_406"]="在唐明月的机关术逐渐成熟之后，唐明月制造了一条小蛇，取名“小游”，便是那条出走的小蛇。唐明月倾尽了她学到的机关术，不停的对小游进行改装，直到这条机关蛇在外表看来与真蛇无异，同样冰冷的触感，同样可以绕在人的臂膀之间，同样可以幽幽地吐着蛇信。堡中所有人，包括在机关术上颇有造诣的唐门长老也对这条机关蛇啧啧称奇。但是，只有唐明月自己明白，她只是打造了一具躯壳，或许有一天，她终究可以把灵魂灌注在这具躯壳里，直到那一刻，才是真正完成她的时候。",
	["tid#Herolegend5_407"]="然而，独身一人的朱英杰完全难以抵挡凌峰楼的追踪，为了对抗强大的凌峰楼，他去了一个更强大的组织来对抗凌峰楼的骚扰——万象楼。也在万象楼的帮助下，朱英杰回到合欢阁惩治了出卖老阁主的叛徒长老，并推举了当初保护自己的大长老为新阁主，自己则如同之前游荡在后山时的那样继续在江湖间当一个疯道人。他似乎更享受那种疯疯癫癫不用在意其他的生活。",
	["tid#Herolegend5_409"]="巨侠辞官之后，一家人离开了长安前往了川蜀，而秦飞雪虽然也离开了长安却并未一同度过剑门关。秦飞雪从小便听了很多巨侠年轻时四处行侠仗义的事情，本就心在江湖的她于是打算独自在江湖间闯荡一番。后来她常在黄河之间四处行侠仗义，关中飞雪刀的名号也逐渐在江湖间响亮了起来。",
	["tid#Herolegend5_410"]="这是她与卫栖梧的第一次会面，其后那段时光中所经历的一切她都记得出奇的清晰，圣教在大光明寺中折了许多好手，但还是有不少人拼了出来。不过，整个长安已经成为一张专为明教这条大鱼撒下的大网，他们冲出家门的一刻面对的便是荆棘之路。数年来，她全心随爹爹修习《圣火典》，教中大小事务悉心过问，便是想令明教可早日重返中原，她便也可早日见到七叔。",
	["tid#Herolegend5_411"]="滔滔时常会想念老渔民，她相信老渔民只是化作了海面上那多如波光粼粼般海浪里的其中一朵，在变幻莫测的海洋上感受平静和凶猛，也等待着她自己的灵魂变强变得更加勇敢！",
	["tid#Herolegend5_412"]="穷尽一生都在对自己严格要求，想要做到精益求精，从来没有过享乐的时间，所以也不知道为什么其他的人需要放松。",
	["tid#Herolegend5_413"]="沉寂多年的神水宫，如今似乎在江湖上又有了声响，那些不熟悉神水宫的人，也开始逐渐回忆起当年神水宫强势时的可怕。传闻神水宫主已经离开了天池，只为了冥冥于世的那抹魅影。",
	["tid#Herolegend5_481"]="后来，结识了姜笑川的张超加入了星宿派，听闻这一派的化功大法的修炼之道很适合开辟他新的研究道路。传闻中，此门功法可通过一门天星奇鼎凝练蛊虫来提升实力，张超便按照这一法门，成功地开启了真正属于他的世界的大门。",
	["tid#Herolegend5_484"]="宋英男成为了海上的豪杰海侠，劫富济贫，路过的海贼黑商，她拍打海浪惩治他们递交官府并令其交出财宝，送到海边来慰劳年老的赶海人。也偷偷往小孩的鱼篓里放进难捉的珍贵海货，还会捡起沉在海底，渔民们丢失的贵重物品。",
	["tid#Herolegend5_485"]="摩波旬在牢内积极表现，后签订奴役契约成为砍头的刽子手，却更助长了他暴虐的性格，数年后那个小姑娘恢复心智，他终于从奴役的契约中解脱。他出狱后，便再去了一次蓬莱，只是这次，他碰上的是韦绝……",
	["tid#Herolegend5_491"]="暂缺",
	["tid#Herolegend5_492"]="暂缺",
	["tid#Herolegend5_493"]="暂缺",
	["tid#Herolegend5_494"]="暂缺",
	["tid#Herolegend5_495"]="暂缺",
	["tid#Herolegend5_501"]="然而十年过去了，长安去也去了，却并未找到那位姑娘，听闻那个巨侠原本在京中任职，不过后来觉得居于庙堂难以行侠天下，于是便辞官游侠去了。知道人不在长安，李知傲便没了方向，只好继续闯荡，后来误打误撞上了武当山，全心研习武学，希望有一天自己仗义诛魔时还能遇到这位姑娘。",
	["tid#Herolegend5_502"]="姐弟二人一起，就是人间太平与祥和的希望，光明与信仰将他们连在一起。就算有朝一日天各一方，他们也能长相厮守——两人的灵魂轻触着帷幕两端，遥遥万里，却又不可思议地触手可及。",
	["tid#Herolegend5_503"]="中原向来是消息灵通的地方，仅仅一次隐秘的相会，就让云隐岛引起了某些人的“重视”。之后的几年内，一向安宁的云隐岛经常有一些可疑的人到访，与此同时，逸心的消息也越来越少。终于有一天，句芒决定动身前往中原打探消息，却没想到，刚好目睹了天罗围攻蜀山的惨状。他拼尽全力救下了梁铮雨，却从此再没能忘记，逸心至死未曾瞑目、仍望向师弟的那双眼睛。",
	["tid#Herolegend5_504"]="然而，父亲好像自从那一次夺走何首乌后，便在人间蒸发了一般，无论如何，也寻不到他的踪迹。后来她一路寻找一路治病救人，在江湖间也逐渐声名鹊起。受到她善良心地感召的人们自发地组建起了慈航教，为的就是救治更多的穷苦人。不少江湖人也知此事后，也纷纷来求助，并且不惜投下重金，只不过霍紫凝面对那些金银并不动心，依旧以救治穷苦人为主。",
	["tid#Herolegend5_505"]="逍遥无法接受师父的离开，三次被人抛弃的经历折磨透了这个本应该幸福快乐的女孩。逍遥“被迫”失去了所有记忆，用武功为自己创造了幸福的记忆，在记忆里，她有家有朋友，她的师父在远处等着她……",
	["tid#Herolegend5_506"]="天龙门的强势很快便震惊了整个武林，原本周文浩对自己的过去并不在意，因为他只看重自己光明的未来，过去对于他来说不过可以随意丢弃的烟尘。然而，他的强大却始终让那些伤害过他和他家族的人感到惴惴不安，整日惶惶不可终日，于是那些担心自己遭到株连的人，便将这些人主动送到了周文浩面前。周文浩看着他们一言不发，似乎都提不起什么兴趣，然而那些人却各自忏悔起来，大哭着向周文浩认错饶命，甚至有些立下誓言自废武功，只求周文浩放过他们。最后，看着眼前荒唐的景象，周文浩只是大笑离去，再也没有过问过他们的事情。",
	["tid#Herolegend5_507"]="起先梁钲雨不清楚师兄和长老带自己前往云隐岛的原因，只是从几个师兄那里了解到云隐岛是个比蜀山还厉害一些的修道之地，因为远在海上又长年为浓雾所笼罩。就如同那片浓雾那般，懵懵懂懂地跟着大师兄和长老登上了云隐岛，看到师兄与一位身材高大的粗狂男子交谈后，才得知师兄要将自己留在云隐岛上，并拜托自己的兄长来照顾他。只不过，看到小师弟落寞的背影与云隐岛的寂寥，在小师弟几经要求之下，大师兄还是将梁钲雨带了回去。",
	["tid#Herolegend5_508"]="既是天忍已经出手，唐寅猜到，千里之外，家中一定也已被牵制。几年来他广交好友，看似是文人之约，实则正是为了这一刻。三日后，他只身前去赴约，“霸王枪”重出江湖，将敌人尽数歼灭。而后召集几个挚友的世家兵力，快马兼程，赶回家乡回援。临行前，他给姑娘留了一封信，讲清一切始末和自己的身份，相约一月后回城相见。",
	["tid#Herolegend5_591"]="暂缺",
	["tid#Herolegend5_592"]="暂缺",
	["tid#Herolegend5_593"]="暂缺",
	["tid#Herolegend5_594"]="暂缺",
	["tid#Herolegend5_595"]="暂缺",
	["tid#Herolegend5_607"]="阴谋被揭穿后，天忍教仍不死心。一计不成，他们便想到了以数量取胜、“壮大”门派声势的对策。他们暗中制作金山剑谱的手抄本，以天忍教的名义，招揽寒门之子，将他们纳入自己门下。这些门徒或因心术不正、或因走投无路，纷纷被蛊惑而来，天忍教再次与江湖之中声名渐起，成了金山派不容小觑的威胁。他们甚至打着“和平共处”的旗号，想要招揽求伯君为他们效命，但此时求伯君已看清了他们的嘴脸，毅然拒绝了他们。",
	["tid#Herolegend5_606"]="鸠摩罗与清觉的纠葛一直延续了很多年。渐渐地，鸠摩罗从懵懂僧人成为了藏传大师，早年的锐气也已在游历中得到洗刷与打磨。江湖纷扰众多，虽有满腹思索与深刻见地，鸠摩罗却始终无法真正做到扬藏法之威。更何况，还有如清觉一般的人，处处“牵制”。鸠摩罗决定回到桑耶寺，向佛祖寻求答案。",
	["tid#Herolegend5_602"]="邪极坊的人做梦也想不到，他们带回了怎样的一个仿佛从无间地狱带来的可怕恶鬼。吕珂在几年之间逐渐依靠着从父亲那里学来的机关术，制造了大量的傀儡。然后在某一天夜里，邪极坊的其他人全部消失了，几年之后他们似乎又回来了，作为傀儡，吕珂的傀儡。",
	["tid#Herolegend5_603"]="三人后来一起登上了蓬莱岛，在某一个晚上，三个人围坐在篝火旁，筱九和史春莲在一边说笑、打闹，飞雪蜷缩在天山怀中，舒服的打着哈欠。不知不觉间，天山的心中涌出了一股暖流，嘴角也不自觉的勾起了一个弧度。筱九两人玩闹累了，转身来看柳念时，忍不住的惊呼出声。“你笑了！”",
	["tid#Herolegend5_604"]="虽然目不能视，但刘异的意念与感知之力，却让他比常人“看”得更加清明一些。比如回到村庄后，想欺他眼盲的恶霸流氓，还未能近身，便已被震出几尺之外。刘异从一个备受欺凌的少年，变成了人人敬之、畏之的世外高人。他继承了前宫主的遗愿，在缥缈峰重建灵鹫宫，俯瞰雪山之下的众生。同时，作为练成绝世之功的交换，他也将接受前宫主留给他的使命，去了结灵鹫宫一桩陈年恩怨——找到“寒冰掌”的后人，然后击败他。",
	["tid#Herolegend5_605"]="十数年过去，她已然拥有了想要的财富、土地和手下。但是天下会并未停滞于此，她一直渴望的，是更远更大的前方，是更高更有诱惑力的地位……她总是相信，她就是天命之人，是承接大事的人，之前不是便有一个武周，那其后怎么就不能有一个执掌天下的天下会呢？彼时彼刻，今日今时，玄凤必将赳鸣于天下。",
	["tid#Herolegend5_691"]="暂缺",
	["tid#Herolegend5_692"]="暂缺",
	["tid#Herolegend5_693"]="暂缺",
	["tid#Herolegend5_694"]="暂缺",
	["tid#Herolegend5_695"]="暂缺",
	["tid#Herolegend5_701"]="十年后，他为寻找灭族仇人而离开了天墉城。再次遇上别有用心、深藏不露的欧阳少恭，为求起死回生的灵药，百里屠苏与欧阳少恭同行，并在游历时结识了风晴雪、方兰生、襄铃、红玉、尹千觞等人。在众人陪伴之下经历旅途种种，百里屠苏渐渐敞开了封闭的心扉，而且与晴雪之间也产生了一种微妙的感情。经过铁柱观的不离、乌蒙灵谷的不弃，屠苏晴雪二人在地界幽都终成眷属。然而还没来得及相守，为了亲手断绝与太子长琴、欧阳少恭之间的宿命因缘，为了给族人报仇，也为了挽救苍生性命，他选择解开体内煞气的封印与少恭一战。",
	["tid#Herolegend5_702"]="后来，由于欧阳少恭的威胁，屠苏不得不提前解开封印。最终，在晴雪的怀中，屠苏化作永世无法轮回的荒魂，晴雪则以玉横收纳屠苏灵魂。晴雪始终相信她可以寻找到重生之法令自己的苏苏重生。之后，她更是舍弃轮回，以漫长孤独的生命踏上旅途，只为寻找一丝重生的渺茫希望。",
	["tid#herolegend6_101"]="林无双镇守天门关之际，听闻太原有奇书出世，随即一封密件送来——她需要去会一会一名江湖人。所谓奇书便是那传说中的《开元典论》，据暗门隐卫与锦衣司的联合情报，持有此书的人身边有朝廷的人跟着，且此人心性也不会有何危害社稷的事情，不过那些虎视眈眈的觊觎中原的胡人却不是如此，这次书交于江湖人之手终究是贻害无穷。",
	["tid#herolegend6_102"]="曾经越狱后的王司马也算是好好在江湖上快活了几日，彼时的江湖也算是被这个小魔头搅的天翻地覆，无人不知一个“烟火教头”的恶名女子。只可惜，至少对她来说很可惜，她被一名白衣女子抓了起来。这白衣女子便是近来在长安附近享有盛名的白衣不良人——李郡，也就是王司马的亲姐姐。后来的后来，在李郡的强力控制和安排下，王司马被迫招安加入了红夷军，从此江湖上少了个“烟火教头”，却多了一个让寻常恶人闻风丧胆的红衣女“魔头”。",
	["tid#herolegend6_103"]="近来长安因“花鬼索命”一案，令李延广焦头烂额，不少要员莫名殒命但毫无其他的线索，且受害者之间也并无特殊关联。那段时间，京兆府连连下达通牒要求尽快结案，以免圣人不悦。李延广从未觉得查案可以如此棘手，那一日他再次接到报案，说天福楼再次出了命案。",
	["tid#herolegend6_104"]="江湖上，万象楼开始兴风作乱，如何解决这万象楼是近来困扰锦衣司上下的核心问题，尽管联合暗门隐卫与遍布江湖之上的暗桩拿到了很多情报，但一直没有什么实际进展。另有一桩，这东海的匪患盘踞连年得不到解决，正当李郡奉命去调查近海州县为何连年剿匪不力之时，却听闻一个来自蓬莱的江湖人诛杀了东海倭匪的贼首。",
	["tid#herolegend6_105"]="有几日，少林开坛讲经，清觉突然有些烦闷便下山转转。这种烦闷的感觉让他很熟悉，仿佛回到了清梵师兄离开少林的日子。二来也是，听闻小沙弥说道，近来少室山，凌霄洞附近有一些生面孔出没，清觉下山也是想看看是否有什么贼人来犯少林。果不其然，达摩洞内有人悉悉索索说着什么，因为有小沙弥之言在前，清觉以为是歹人，便出手对付，却不想眼前的人并不是什么坏人，这人自称来自蓬莱，不过是感怀少林武功高深，这里又是达摩祖师坐化之地，方才来参拜一番。",
	["tid#herolegend6_106"]="自姜笑川身边离开之后，刘关江接受了朝廷招揽，成为了一名暗桩，开始与暗门隐卫的公孙雨开始有所接触，他开始了他下一步的计划，扳倒那颗残忍吸取江湖与庙堂的双根巨树。公孙雨作为桥梁，刘关江作为锦衣司的暗桩，为锦衣司提供了很多关键的关于姜笑川的情报。",
	["tid#herolegend6_107"]="北方的胡人们又开始不安生了起来，燕云飞也从没有懈怠过一分，因此同在附近守关的神策军，其耽于享乐的作风和散漫的军纪让他十分气愤却又无可奈何。后来，临近陇右的弟兄带回一个江湖人来，说是受朝中姜大人之托，来护卫他一段时间。",
	["tid#herolegend6_108"]="老天师当初其实不是想要真的将张昊赶出天师门，只不过是天师门内的老顽固们，自恃甚高，认为祖上传下的五雷咒决，不容动摇，且天师门一贯清修不愿招惹江湖纷争，张昊的活跃举动并不能被这些长老们容忍。老天师一直在默默的关注着张昊的动向，在他筹建摘星阁之时，暗中提供了很多帮助。后来，由于摘星阁的情报生意让江湖中的一些组织眼红，曾一度遭到围攻与威胁，也是老天师在默默化解危机。后来老天师羽化，弥留之际连喊着张昊的小名，只可惜自从张昊下山之后，父子二人便再也没有见过一面。",
	["tid#herolegend6_109"]="身为暗门隐卫的成员，这些年来一直负责盯着江湖上那支新兴势力万象楼，以至于她一直追踪的天龙门下落也放了下来。可是自从东海发生了一位蓬莱青年只身荡平匪患之事，上头便派她前往盯紧了这个蓬莱人。",
	["tid#herolegend6_110"]="暂缺",
	["tid#herolegend6_111"]="后来，公孙雨所在的自编军通过募兵加入了朝廷，公孙雨也因特殊的才能进入了暗门隐卫，公孙雨也十分享受她呆在暗门隐卫的日子。无论是铲除朝中奸佞抑或是诛灭江湖上的恶瘤，这都是公孙雨最擅长做的事情，不过公孙雨也渐渐意识到，此暗门隐卫真正的掌控者是超乎朝廷之上的可怕组织，不过这些似乎也并无关紧要。",
	["tid#herolegend6_114"]="暂缺",
	["tid#herolegend6_115"]="曾有一年，吐蕃大军兵临西陲边关，由于吐蕃出兵神速，以及一支神策军支援怠慢，几经危机差点陷于敌手。正当危急时刻，方剑斌率族人组成的天鹰部，犹如天降神兵驰援此关。虽说天鹰部人数不多，都是天鹰族人，但是他们可以利用自己的伙伴战鹰精准击破敌军的各个重要部分，尤其是方剑斌，他利用战鹰突袭敌人后方，直接狙破对方将领，成功化解了此次危机。此事之后，方剑斌被一个神秘人接见，加入了暗门隐卫。",
	["tid#herolegend6_181"]="暂缺",
	["tid#herolegend6_182"]="暂缺",
	["tid#herolegend6_183"]="暂缺",
	["tid#herolegend6_184"]="曾有一年，吐蕃大军兵临西陲边关，由于吐蕃出兵神速，以及一支神策军支援怠慢，几经危机差点陷于敌手。正当危急时刻，方剑斌率族人组成的天鹰部，犹如天降神兵驰援此关。虽说天鹰部人数不多，都是天鹰族人，但是他们可以利用自己的伙伴战鹰精准击破敌军的各个重要部分，尤其是方剑斌，他利用战鹰突袭敌人后方，直接狙破对方将领，成功化解了此次危机。此事之后，方剑斌被一个神秘人接见，加入了暗门隐卫。",
	["tid#herolegend6_191"]="暂缺",
	["tid#herolegend6_192"]="暂缺",
	["tid#herolegend6_193"]="暂缺",
	["tid#herolegend6_194"]="暂缺",
	["tid#herolegend6_195"]="暂缺",
	["tid#herolegend6_201"]="在凶恶的地方当然要最凶恶的人才行，可是韦壮武却靠着一身本事与特殊的特性误打误撞成了梁山泊的大头领。原本穷凶极恶的匪窝成了替天行道的绿林好汉，山上的恶人们都被韦壮武一身本事所折服。可这韦壮武却是个甩手掌柜，非要去蓬莱见识更厉害的家伙，却无意结识了金钱帮的黄荣华，俩人一拍即合不断找人切磋，而他们自己却一直决不出胜负。",
	["tid#herolegend6_202"]="近今年来新兴起的万象楼，听说其门派之首韦绝武功独步天下，争强好胜的黄荣华自然不想放过一个跟这样的高手对决的机会，然而这韦绝行踪己其诡秘，难以捉摸。终于有一日他得知韦绝登上蓬莱的消息，因此黄荣华也立刻赶往蓬莱，却有幸看到蓬莱发生的一场惊世骇俗的“玄素之战”。",
	["tid#herolegend6_203"]="尔后江湖中兴起一个恶人谷，听闻其名也不知其所以，倘若真是恶人集结，这位探花郎也有心除之，故而刑探花亲自前往恶人谷一探，却意外与那心胸豁然的谷主结为好友。原来这恶人谷不过是个诨名，其间多数也不过是为所谓“名门正派”所排斥的“异类”罢了。刑探花往来恶人谷几次，倒也觉得这地方无所拘束，反而能放下很多负担。",
	["tid#herolegend6_205"]="靳辰洋自打闯荡江湖以来，四处行侠仗义，倒是也小有名号，怎奈江湖经验尚浅加上姿色过人，让不少觊觎她美色的人起了歹心。某天路过偏远客栈的形意在此打尖，怎料下酒菜里被掌柜的下了迷药，危难之际，幸得一路过的白衣剑客出手相助才幸免于难。迷迷糊糊的形意没能看清相助来人的面庞，却也坚定了自己继续行侠仗义，痛打采花贼的决心，在那之后的形意凡事也多了个心眼，在行走江湖的时日里慢慢成熟。",
	["tid#herolegend6_206"]="说起丐帮在江水一带均有势力，更与蜀中唐门历代交好，一直是兄弟帮派。不过西边崛起的拜火明教一直在拓展自己的势力不断东进，让丐唐两帮一直颇有不满，于是沈念便自告奋勇要与唐门的人一起就打探打探这个明教。然而沈念与唐门的唐明月一同的行动却被一个蓬莱少侠给阻止了，言说这一切都是阴谋不要再继续下去了。虽然沈念感到很奇怪，但从这个人眼睛里看得出来，他并没有说谎。",
	["tid#herolegend6_207"]="在上一次论剑大会之前，江湖中的剑客几乎都认为，剑招学的越多越好，直到那个男人的出现。上届论剑大会上，一个叫“宁不凡”的男人突然出现。在这之前，根本就没有人听说过这个家伙，报上来的师门也是闻所未闻，更可笑的是，那男人说他只会三式剑招。众人本以为只是个初出茅庐的愣头青，却没想到，他那看似简单的招式却无比玄妙，大部分人在他手里都撑不过两招。最后，还是上一届魁首出手，才跟他堪堪战了个平手。自此之后，江湖上便盛传“法不贵多而贵精”的说法。",
	["tid#herolegend6_208"]="一年后，妙法庵外来了一个拿着酒壶的剑客，正是宁不凡。自从和辛晓风分别之后，他四处打听，终于找到了妙法庵。宁不凡抽出了剑，使出了一式“赤子”砍向发丝。剑与发丝之间发出了金铁交击的声音，却毫发无损。宁不凡又使出了第二式“剑心”，依旧没有用。最后，宁不凡用处了第三式“红尘”，终于砍断了发丝。发丝断裂的一瞬间，后殿中的恒山便感觉到了宁不凡，同时也忘记了一些和宁不凡的记忆。但宁不凡并不知道这些“情丝”就是恒山的情感，只是为了救出辛晓风，将一根根发丝尽数砍断。最终，他在后殿见到了辛晓风，但辛晓风也忘却和宁不凡在一起的记忆和情感。辛晓风成了六根清净的菩萨，宁不凡成了逍遥江湖的剑侠……",
	["tid#herolegend6_210"]="蓬莱归来的吕沛杰依靠着新开悟的自创功法，开始在江湖之间游荡，他很奇怪，凭借着神功心眼，他自觉与普通人无异，然而他人却总是有意无意的施与他恩惠。然而骄傲的他非常厌恶把他当作弱者的人们，因而他依然觉得自己是如此的孤独。",
	["tid#herolegend6_211"]="江湖皆知，神游天下的鬼谷先生云游四海，也算尽天下，很多人自命不凡的人都想找到这位鬼谷先生知道自己今后能否功成名就，震烁江湖。后来况候智游历蓬莱，曾遇到一位勤勉刻苦的年轻人，被其纠缠一番，只好一算，算罢他盯着眼前的年轻人看了半晌，缓缓从口中念出二十八个字，便是“蓬山暗涌波涛起，九州撼地众山移。本来孤峰独沐月，一片飞云蔽寒息”……",
	["tid#herolegend6_212"]="传纯阳子曾赠书与当今圣人，而此书正是《典论》之下，当初吕祖赠书圣人之后，将原本存于纯阳宫中，此书与晋王府所藏《典论》之上并称天下两本奇书，得之者可得天下。万象楼韦绝觊觎此书许久，前来抢夺，致使纯阳上下陷入苦战。虽查觉韦绝动向，九天天华君前来助阵，但万象楼已然人多势众，多方高手连番进攻，局势再次由盛转衰。",
	["tid#herolegend6_213"]="然而回中原的遇到的事情改变了喻扬超的所有想法。因为遭遇胡人沙匪，随行的仆人被害，从西域带回来的玻璃工具与其他货物也一并被抢，那些重的抬不走的东西便全部被这些野蛮人毁坏了。所幸喻扬超依靠着傍身的霹雳弹逃出了生天。",
	["tid#herolegend6_281"]="暂缺",
	["tid#herolegend6_282"]="暂缺",
	["tid#herolegend6_283"]="暂缺",
	["tid#herolegend6_291"]="暂缺",
	["tid#herolegend6_292"]="暂缺",
	["tid#herolegend6_293"]="暂缺",
	["tid#herolegend6_294"]="暂缺",
	["tid#herolegend6_295"]="暂缺",
	["tid#herolegend6_301"]="年轻时的药王不仅医者仁心，更有一副侠义心肠。与郭巨侠的相识，便是源自一次行侠仗义。那时郭巨侠还是一个满腔热血的剑客，路遇一伙水贼正要出手，却见一人抢先攻上了贼船，正是采药路过的药王。药王不仅擅医术，亦是精通武学，毕竟若这世道有恙，也是要医上一医的。虽是初次相识，药王与郭巨侠却仿佛心意相通，一招一式间，配合得如多年故交般默契，所谓知音，大抵莫过于此。得益于彼此之间的默契，二人以少胜多，将一船水匪尽数歼灭，只可惜留下一孤儿，至亲被贼人所害，孤苦无依。郭巨侠将她收在身边，悉心教养，而每当想起那场酣战，也总会生出对药王的相惜之意。",
	["tid#herolegend6_302"]="自郭香香记事起，身边就有一个名叫秦飞雪的师姐。那些年幼时的心事，都在一个个月明星稀的夜晚，和着从父亲房中偷来的酒，融在了姐妹之间的交谈中。秦飞雪第一次执行任务那晚，郭香香照例在屋顶等她，但却见师姐神情落寞，良久无语。那一晚，郭香香知道了秦飞雪的身世，也知道父亲安排剿匪的任务给她，正是为了让她得报身世之仇。一夜无眠之后，秦飞雪收到了一把吹毛断发的长刀，正是郭香香赠与她的生辰礼物，也便是数年之后闻名江湖的——“飞雪刀”。",
	["tid#herolegend6_304"]="舞者虽当俏丽，但花间派亦有一套独创剑法，柔中带刚，气势不输江湖男儿。苏婉仪资质上乘，武学之道如舞艺一般手到擒来，却唯有一招久难练成，便是霓裳羽衣剑法。武功之于苏婉仪，一向是有坚韧心智便可练成，却唯有霓裳羽衣剑法，无论如何苦练，终是欠些火候。这一直是苏婉仪的心头之扰，直到花间派来了一位稀客——东海少侠。不同于坊内姐妹之间的过招，与他交手时，心境仿佛也有些许变得澄澈。一向厌恶男子的苏婉仪，心底难得对他生出了一丝敬意。",
	["tid#herolegend6_305"]="心思缜密如墨家，从来信奉推演、计算之道，在她眼里，世间万物都可用特定的规律推算出来。所以遇见天机之前，她从不相信有“感情”这种模棱两可的东西存在。世人道人心难测，无非是太过愚蠢，推演不出结论罢了。但与天机相处久了，内心却有些许波动，似乎超出了逻辑的范畴。大概是尚未被证明的规则吧，墨家这样想着，并把这些波动记录下来，以待日后论证。",
	["tid#herolegend6_306"]="当江湖中出现了蓬莱少主的名声时，姜笑川知道，能制约韦绝的人出现了。江湖中善恶分立，却也维持着一种微妙的平衡；而心性纯善兼武功卓绝的蓬莱少主来到中原，注定会掀起不小的波澜。为了试探他，姜笑川安排了一场相逢。多年官场生涯，让他足以不着痕迹地与蓬莱少主“偶遇”，并游走于几人之间，丝毫未惹得任何怀疑。而他也终于得出了自己想要的结论——此子可用。",
	["tid#herolegend6_307"]="身为名剑山庄五公子，姜承影阅剑无数，却想不到也有一日会为剑所惑。一夜之间，山庄上下皆失了心智，近乎疯癫，若非恰逢东海少侠游访至此，只怕将是一场灭门之灾。东海少侠唤醒姜承影，并很快从混乱的线索中抽丝剥茧，将矛头指向山庄风云鹤长老的“天问剑”。姜承影视蓬莱少侠为贵客，邀他留在山庄，一同主持大局。",
	["tid#herolegend6_308"]="滔滔的世界很单纯，喜欢的东西有两个，一是食物，二是师父。至于东海少侠嘛……既是师父的朋友，也算来者是客吧。只是这少侠好像有什么灾祸体质，前脚刚来，后脚山庄的叛徒叶寻欢就到了。为了不让师父的《大道归一决》被抢走，滔滔使出了全身的力气将他打跑，东海少侠也英勇地帮了个忙，算是派上点用场。只是叶寻欢落荒而逃后，滔滔有点懊恼——敌人很弱，好像也不用费那么大力嘛。",
	["tid#herolegend6_309"]="退隐蓬莱后，心境淡泊的周湘君被一人吸引了注意，便是本应接任岛主之位的蓬莱少主。蓬莱与世无争，世外桃源般的生活向来被中原所羡慕，而生来便享有这种安逸的蓬莱少主，却一心向往中原的纷争。从他身上，周湘君像是看到了当年离家的自己。作为岛主的门客和至交，本应顺应岛主的意思劝说于他，但周湘君却下意识地愿意相信这个少年。为了试探、也为了相助，周湘君布下了蕴含江湖万象的“太极奇阵”，当少年以一己之力破阵而出时，周湘君内心便更加笃定，中原之上，定有这蓬莱少主的一番天地。",
	["tid#herolegend6_310"]="游历江湖时也曾听过东海少侠的盛名，但无法想到的是，初次相见竟是被当作“贼人”刀剑相向。彼时史春莲之父身染重病，只有神鹿鹿茸方可根治病症。幸而筱九与万灵心意相通，得神鹿相助解此困局；却不想落在东海少侠眼里，成了谋害神鹿的歹人。筱九也并不知东海少侠的来头，只当他是见利忘义的狩猎者，硬是阴错阳差地打了一架。",
	["tid#herolegend6_311"]="李清秋天生神力，虽未继承爵位，在江湖之中却素有“勇武候”之美称。因而当江湖中出了一个气力与自己齐名的蓬莱少主时，李清秋一直想找他一较高下。霸王擂前终于寻得机会切磋时，他发现这少侠的力道与自己的强横之力不同，虽不显山露水，却刚柔并济，令人难以压制。纵是以力量见长的自己，也与他打了个平手。一战过后，许久未逢对手的李清秋生出了久违的好胜心，只待擂台之上酣战一场，一决胜负。",
	["tid#herolegend6_312"]="离开山林后，史春莲与筱九在江湖上四处闯荡，也结交了不少好友。路过抚琴台时，便被慕容清月的琴声与花间苏婉仪的舞所吸引，驻足流连。舞乐声中，恍然有一人前来搭话，定睛看去，正是江湖闻名的东海少侠。因慕容清月琴弦无故而断，难以再闻绝世之曲，原本萍水相逢的一众人便同心合力，欲寻鹿筋修复琴弦。史春莲自幼出众的狩猎之能倒是派上了用场，不多时便寻得猎物，解了眼下困境。第二天悠扬的琴声再次响起，自幼与山野为伴的史春莲觉得，自己也是风雅了一次。",
	["tid#herolegend6_383"]="暂缺",
	["tid#herolegend6_386"]="暂缺",
	["tid#herolegend6_387"]="暂缺",
	["tid#herolegend6_391"]="暂缺",
	["tid#herolegend6_392"]="暂缺",
	["tid#herolegend6_393"]="暂缺",
	["tid#herolegend6_394"]="暂缺",
	["tid#herolegend6_395"]="暂缺",
	["tid#herolegend6_401"]="翟冬玄并不知道如何“重生”或者“永生”，只是随着内心的信念，一路追寻下去。有一天，他终于看到了一线希望——蓬莱。江湖传闻，蓬莱所居皆为仙人，不仅与天地同寿，更可让死人复生。虽没有人亲自证实过，但为了深爱的妻子，翟冬玄仍决心一试。",
	["tid#herolegend6_402"]="阿岚做事没什么拘束，想到什么便去做了，毕竟人生苦短，要活得尽兴才不枉此生。所以蓬莱少侠来到五圣教时，在好奇心的驱使下，阿岚决定试探一番。五圣特有的毒菌伞，误食会使人陷入幻境，举止异常，不知看着心境澄澈的蓬莱少侠，是否也会有人心另一面呢——这样想着，阿岚在晚宴中悄悄做了手脚。令她失望的是，这位少侠的意志并非虚谈，即使在幻境之中，也没留下什么把柄。不过无妨，阿岚已发现了他另一个弱点——晚宴前对山歌时，如此歌喉，还真是让人不敢恭维啊。",
	["tid#herolegend6_403"]="还未及与李延广再次相逢，祥颖韬便在一次任务中先遭遇了李延广的搭档。姜笑川盯上的新目标——蓬莱少主身边，跟着的正是与李延广关系甚密的锦衣卫。所以祥颖韬在这次任务中特别卖力，给他们制造麻烦时，也比对其它目标多一些“关照”。不仅是为了完成姜笑川的任务，或许，也为了给当年的自己一个交代。",
	["tid#herolegend6_404"]="陆尘子性情阴鹜，好胜心却极强。替韦绝办事不只是为了利益，更是一次次任务中，看着所谓“高手”亡于己手，那种莫名的愉悦感。如今的陆尘子，已不再在意什么凌峰楼的“拾”，他的下一个目标，是与韦绝齐名的蓬莱少主。陆尘子坚信，江湖名声不等于实力，只要自己出手，无论何人，都能手到擒来。",
	["tid#herolegend6_405"]="见惯了世间的私心杂念，赵心音觉得，人心不过如此。善良的人只是没机会接触更大的诱惑，极致的利益面前，任何人都会剥下伪装，原形毕露。所以当听闻蓬莱少主心性纯善时，赵心音内心也不置可否。为了验证自己的想法，赵心音决定以秘籍《武经》为饵，试他一试。当然，《武经》是被动过手脚的。内页的奇药足以致命，是否有资格活下去，就要看那少侠心性如何了。",
	["tid#herolegend6_406"]="唐门与丐帮联手歼灭明教的事情，江湖中人尽皆知，但只有唐门弟子自己清楚，这只是唐家堡的障眼法。事实上唐门早已和韦绝暗中通信，韦绝的每一次计谋，都少不了他们参与其中。唐明月执行着自己的每一个任务，无所谓喜悲，相比于被禁锢在堡内的日子，这只不过是另一种身不由己罢了。人从来难按自己的心意而活，就像眼下的江湖，无法像人们想象的邪不压正一样。唐明月抱着这样的想法，直到遇到那个蓬莱的少年。看着他周旋于江湖纷争之中，虽不是百战百胜，但眼里的光从未消失。唐明月觉得，这处处桎梏的江湖，似乎要迎来一种挣脱束缚的力量。",
	["tid#herolegend6_407"]="朱英杰觉得自己的一生，就是命运开的一场玩笑。明明身怀过人天赋，如今却要靠装疯卖傻生活。姜笑川最近分外关注一个人——江湖中的蓬莱少主，作为万象阁手下，朱英杰自然也便对他多留意几分。让他想不通的是，明明都与常人不同，明明都是天赋异禀，为何生于蓬莱那般清澈之地，便能成为万人敬重的大侠，命运如自己，便只能在罅隙中生存。出于私心，也因为万象楼的任务，朱英杰开始有意无意地给这位少侠制造麻烦。",
	["tid#herolegend6_409"]="在听闻神刀门重启扬刀大会之后，作为飞雪刀当然要前往与江湖各路豪侠切磋一番，抱着这样的想法，秦飞雪果断接下了扬刀大会的名帖。原本秦飞雪与浪无痕一战令人叹为观止，秦飞雪拔得头筹已经是探囊取物之事，却不想遭人暗算，无法全力迎战败下阵来，后来方知是神刀叛徒设计夺刀，好在前来游历的东海大侠出手，顺利解决危机，也因此与这位蓬莱少侠结识。",
	["tid#herolegend6_410"]="虽说明教与蓬莱少主势不两立，但陆小贝知晓，眼下能倚仗的也只有他了。明教圣女不谈情爱，自己却为一书生出逃，明教布下天罗地网，江湖各大门派静观其变，只怕也只有眼前这个少侠，有可能伸出援手了。虽非良计，但为了救那书生……当时本是为了从暗袭之中脱身，不得已藏进了他的房间，却不想他竟留自己养伤，整日嘘寒问暖。自幼时流亡起，便再难领略到此种温情，自然难免心动。此时他因自己被擒，纵是下下策，只要能救他，也无妨一试。陆小贝暗下决心，决定向蓬莱少侠开口求助。",
	["tid#herolegend6_411"]="滔滔的世界很单纯，喜欢的东西有两个，一是食物，二是师父。至于东海少侠嘛……既是师父的朋友，也算来者是客吧。只是这少侠好像有什么灾祸体质，前脚刚来，后脚山庄的叛徒叶寻欢就到了。为了不让师父的《大道归一决》被抢走，滔滔使出了全身的力气将他打跑，东海少侠也英勇地帮了个忙，算是派上点用场。只是叶寻欢落荒而逃后，滔滔有点懊恼——敌人很弱，好像也不用费那么大力嘛。",
	["tid#herolegend6_412"]="重返中原的左寒修开始变得不可一世，受阴寒武功的影响，人也阴狠狡诈，他用尽机关设计一统三山五岳，就只是想听到整个武林称赞他的强大而已。所以当蓬莱少主的声名盛过他时，他感受到自尊受到了侵犯。而这直接触及到了他的底线，从那时起，他开始对蓬莱少侠“倍加关注”。",
	["tid#herolegend6_413"]="对于蓬莱所谓的绝世武学，玄水姬一向不屑一顾。神水宫武功自成一派，集女子阴柔之力，练成于水下，因剑走偏锋，江湖中也是无人能够匹敌。所以在整个江湖对蓬莱心心念念、穷尽所能寻找前往蓬莱之法时，玄水姬也不为所动。她甚至觉得，同样是绝学，为何不能让蓬莱拜倒在自己脚下。但有一天，高傲的玄水姬改变了想法，打破了自己“不入蓬莱”的誓言。因为她得到了一个消息——赵心音去了蓬莱岛。",
	["tid#herolegend6_481"]="暂缺",
	["tid#herolegend6_484"]="暂缺",
	["tid#herolegend6_485"]="暂缺",
	["tid#herolegend6_491"]="暂缺",
	["tid#herolegend6_492"]="暂缺",
	["tid#herolegend6_493"]="暂缺",
	["tid#herolegend6_494"]="暂缺",
	["tid#herolegend6_495"]="暂缺",
	["tid#herolegend6_501"]="行走江湖之际，李知傲到处都能听到巨侠的事迹。无论于庙堂还是于江湖，巨侠的名号都如雷贯耳，是俯仰无愧于天地的、真正的侠者。既然心上人是巨侠之女，李知傲也开始更加勤勉，期待有朝一日重遇，能与心上人并肩。怀着这样的想法，李知傲行侠仗义，某天无意中救下了一个姑娘。那姑娘看着飒爽强势，实则头脑简单得很，在客栈里大大咧咧地和人交朋友，却险些被下了迷药。将她救下后，李知傲有些放心不下。都说本性难移，以这姑娘的性子难免再遇上什么祸端，李知傲一路暗中护送，替她解决了三四个想要“复仇”的恶霸，终于见她安全回了家。",
	["tid#herolegend6_502"]="然而，世界上最不缺的，便是伤痛与忧愁。随着逐渐深入地涉足这个江湖，姐弟二人发现，凡俗之乐音难以尽愈世间之苦痛，听闻蓬莱岛有仙乐《水云谣》，他们便踏上了寻访的道路。殊不知，《水云谣》百年前尘封于蓬莱岛，亦在静候圣童降临，方可重现世间。",
	["tid#herolegend6_503"]="几日后，云隐岛也发生变故。先前形迹可疑的人都是来自中原的影卫，当夜一齐动手，意图覆灭云隐岛。正当全岛惊慌失措之时，一白衣男子有如天神从天而降，几招之内，就让敌人全部退去。这一晚，便是句芒与天华君的初识。天华君赏识句芒神力，邀请他加入“九天”，一同维护江湖安稳；而近日历经种种变故之后，句芒心中也恰有此意，便不假思索地应允了天华君。自此之后，云隐的“春神”，成了九天的“云天君”。",
	["tid#herolegend6_504"]="有人视霍紫凝如活菩萨，便自有人视她作眼中钉。一些无良的官吏独揽药材坐地起价，坐收渔利，但霍紫凝用最廉价的草药也能救人性命，且对穷苦人从不收钱，大大地阻断了他们的财路。那些贪官以蛊惑人心为由，对她进行追捕，霍紫凝在逃亡的路上偶遇了赵心音。赵心音认出了她的红琥珀，那是一个母亲曾千辛万苦找到他，求他以秘术制作的，只为保女儿平安无忧。为这难得的母慈子孝，赵心音向霍紫凝指了一条避世的明路——蓬莱。",
	["tid#herolegend6_505"]="然而萧春风虚假的记忆中却有一丝真实，她的师父，也就是九天天华君，确实一直都在默默地关注着她，只是种种原因他永远不能出现在她的面前。而萧春风的直觉也总是惊人的准确，那一次她前往蓬莱，在蓬莱对外的码头集市上与师父擦身而过，那一瞬间天华君百感交集，而萧春风也似感到了什么，连忙四向张望，却早也不见那一袭白衣的身影。",
	["tid#herolegend6_506"]="当韦绝踏入天龙门之时，周文浩笑着让所有严阵以待的部众全部散开，说纵使他万象楼有天大的本事，也不敢就这么单枪匹马地直接冲入天龙的大门，也没人可以这么做。不想韦绝却一言不发，只是盯着周文浩，同时周文浩眼中依然充满了不屑，就这么僵持了许久。",
	["tid#herolegend6_507"]="“我要拿起师兄们的剑，既然一把剑不足以捍卫蜀山，我便操弄一千把剑” ——实际上大师兄一直没有告诉小师弟将他留在蜀山的真实原因，因为这个小师弟并不清楚自己的身世。后来一连几年都相安无事，一直抱有侥幸的大师兄也以为可以一直这样下去了……可谁曾想梁钲雨的仇人与天忍凌峰楼勾结，派出天罗十大高手围攻蜀山，师兄们为了保护小师弟尽数牺牲，梁钲雨以气御动数柄已故师兄们的剑，也只是勉强击退来人，直到九天宗赶来支援，才解决蜀山被围困之事，只不过从此世间再无唤他一声“小夫子”的人了。",
	["tid#Herolegend6_508"]="得益于日渐精进的武功和两年来的筹谋，唐寅终以手中之枪粉碎了天忍教的阴谋，了结了多年来的恩怨。而后回到江南，如愿得获佳人芳心，一时间被传为一桩佳话。唐家向来未行不义之举，只因树大招风，便被天忍教觊觎，习惯了闲云野鹤的唐寅对这种江湖恩怨感到厌倦，待一切事了，便带着心上人隐居去了蓬莱。",
	["tid#herolegend6_591"]="暂缺",
	["tid#herolegend6_592"]="暂缺",
	["tid#herolegend6_593"]="暂缺",
	["tid#herolegend6_594"]="暂缺",
	["tid#herolegend6_595"]="暂缺",
	["tid#herolegend6_607"]="随着这场闹剧愈演愈烈，求伯君意识到，自己肩负的，已不只是金山派的名誉，更是整个江湖的公道。几年来和天忍教交手各有胜负，而天忍教又擅长混淆视听，如此以往，这种黑白不分的局势，不知会毁去多少后生的前途。为了得到更强的力量，彻底击碎天忍教的阴谋，求伯君当机立断，只身出海去往武学的至臻之地——蓬莱。",
	["tid#herolegend6_606"]="圣人给鸠摩罗的答案，仍是多年前的那句话——「归元性无二，方便有多门」。多年来，鸠摩罗在法学方面已颇有所成，却唯有这句话，始终参悟不透。他不明白，自己游历多年，许多事已看得通透，却不知还有何执念未解，才致使一叶障目，心境不得清明。为了历练自己的心性，他决定前往世外之境——蓬莱。",
	["tid#herolegend6_602"]="昔日的经历郁结于心，让吕珂有了极强的控制欲。她越来越觉得，人心都是污浊、险恶的，需要自己去“矫正”一番。而傀儡虽不像常人一样心存恶念，却也无法如她所想，完全受她操控。直到有一天，邪极坊来了一个名叫魏途殊的少年。借助魏途殊的意念之力，吕珂得以操纵更多的傀儡，使它们按她的意愿行动。几年之内，邪极坊也逐渐壮大，吕珂有了越来越多的“属下”。",
	["tid#herolegend6_603"]="然而天下无不散的宴席，柳念终究还有着自己的使命要做，于是从蓬山归来后暂且与二人分道扬镳。她苦苦游荡在江湖之中一直都在寻找自己的宿敌，不过她的实力还是引起了江湖上其他势力的注意，其中之一便是九天。柳念清楚，自己的宿敌便藏身于幽冥宗，但是想要对付整个幽冥宗，只靠自己形单影只肯定是不行的，而且她也不想让筱九与史姑娘他们牵扯其中。",
	["tid#herolegend6_604"]="在缥缈峰的山洞里，刘异从那封手书中得知了灵鹫宫没落的真相。当年江湖之中，与“生死符”齐名的，还有一至寒之功“寒冰掌”。于至阴至寒之外，更有几分邪气，令人难以捉摸。昔日灵鹫宫主与之一战，竟落得两败俱伤的境地，虽说不致使绝学失传，却再也没能拾回灵鹫的盛名。这桩恩怨尘封了多年，最终便交到了刘异的手上。重建灵鹫宫后，刘异派出眼线打探，很快得到了江湖中有人被寒冰掌所伤的消息。但令他感到意外的是，修成此功的人，竟是五岳盟主。",
	["tid#herolegend6_605"]="可江湖之大远未有周今鸣想的那般容易，天龙门、恶人谷、万象楼、凌峰阁乃至一统三山五岳的嵩山派，其头领掌事者各个都不是可以轻易对付的角色，更有甚者还有一个神秘莫测的九天。可是再度蛰伏的决策是周今鸣决计无法做出的。",
	["tid#herolegend6_691"]="暂缺",
	["tid#herolegend6_692"]="暂缺",
	["tid#herolegend6_693"]="暂缺",
	["tid#herolegend6_694"]="暂缺",
	["tid#herolegend6_695"]="暂缺",
	["tid#Herolegend6_701"]="决战之后，他用最后的余力送走众人，唤来黑龙悭臾，完成了悭臾与太子长琴远古之约，然后在晴雪怀里，化为永世无法轮回的荒魂。不过不愿意就此放弃的风晴雪，将百里屠苏的魂魄以玉横吸纳留存。后来晴雪为了寻找重生之法，以放弃轮回为代价，换取长久寿命，在人间孤独寻觅一丝重生屠苏的渺茫希望。",
	["tid#Herolegend6_702"]="得到漫长寿命的晴雪，为了令自己的恋人重活一世，辗转来到了魔域，为的是寻求能够承载荒魂的辟邪之骨。多年来，晴雪居于天鹿城，已经与辟邪族成为朋友。她用自己擅长的疗伤之术救治了许多辟邪，甚至为辟邪王玄戈延缓致命之伤的发作。得到天鹿城信任的晴雪也得到了辟邪王的承诺，似乎多年来的夙愿终于能够实现。",
	["tid#herolegend7_101"]="不过令林无双出乎意料的是，锦衣司之上的“那位”却并没有要求令林无双前去收回此书，而是传递另一个情报，要求这位江湖人前往纯阳宫拿取另一部奇书。林无双从来不质疑命令，只会坚决地执行，很快接触了这名江湖人，却不想意外通过他的帮助，揪出了潜藏于军中多时的胡人间谍。然而……她也发现了自己失散多年的兄长，竟然投靠了胡人。",
	["tid#herolegend7_102"]="虽然王司马表面上疯疯癫癫，但是内心也有自己衡量世界的一套标准。彼时红夷军被借调说要前往少林围追所谓的叛军，并且持令之人将一支天机营暂时归于王司马手下归她调遣。然而这所谓的“叛军”正是被各方陷害的忠良家眷，因此王司马便以游戏玩闹的方式暗中保护了他们，并且她终于见识到了让她姐姐近来时常关注的那个蓬莱少侠，果真是个有趣的家伙，怪不得姐姐的信中总是提及。",
	["tid#herolegend7_103"]="天福楼他见到了一个相貌不凡的男子，听周遭人说这便是近些日子在江湖颇有些声望的荡寇东海大侠，盘踞东海多年的倭国海盗就是他除掉的。原本李延广觉得这年轻人不过是欺世盗名之人，夸夸其谈罢了，却不想这“花鬼索命”一案正是靠着这东海大侠才得以解决，李延广开始觉得眼前这个人似乎有些郭巨侠的风范。",
	["tid#herolegend7_104"]="东海匪患一事当然不能就这么让他过去，因此李郡奉司丞之命，前往调查一下此事，并且带上了陆司监的小女儿小遥出去见识一下江湖世面。这一见，倒也结实这名初出蓬莱的憨直小子——那名只身荡平东海倭贼的东海少侠，一番试探之后，李郡觉得，这样的少年英雄说不定能成为扳倒万象楼的关键人物。",
	["tid#herolegend7_105"]="达摩洞一事，清觉突然意识到自己之所以烦闷，大概便是自己修行的不足，也算怀揣着愧疚，听闻面前的二人来少林也是一番虔诚，也算是一番善缘，于是邀请二人前往寺中参加辨经法会。可是，等他们来到大殿之前，却看到一群天竺人正在作乱，随意殴打在场的善男信女，而为首的正是他早已多年不见的师兄清梵——尽管对方称自己早已更名摩波旬。在新结识的蓬莱少侠的帮助下，清觉最终将前来作乱的胡僧妖人统统逐出少林，然而如今清梵师兄的模样与所作所为却让他久久不能忘怀。",
	["tid#herolegend7_106"]="关于枫华谷一事，刘关江很早便将收集到的明教情报递交了出去，然而听闻那锦衣司的司卫李郡并未阻止姜笑川与万象楼筹谋扩大明教势力范围，削弱中原武林势力的计划。不过好在后来的浩气盟一事中，他紧急向九天求助，才将情报递送给一名所谓荡寇东海侠的年轻人手里。",
	["tid#herolegend7_107"]="所幸有这江湖人相助，燕云飞总算揪出了眼皮底下的胡人内奸，正是出自身后的广武城内，却不想那胡人逃脱竟然被神策军的轻易放走，气急的燕云飞一拳将毫无原则的神策军头领击倒。原本与江湖少侠的配合下总算追踪到了拿走玄甲布防图的胡人，却不想落入对方的陷阱。好在有古代守关的将军冥冥之中的庇护粉碎了胡人的阴谋。",
	["tid#herolegend7_108"]="虽然在江湖中的声明，有些人认为如今的张天师不过是一个情报贩子罢了，然而就是这样的大商人，却也做一些让人出乎意料的事情。曾有玄甲军麾下有一支忠勇的薛家军，后来却被权臣陷害，流落各地，便是这张天师在接济忠良家眷，帮助他们前往长安讨一个公道。也是如此，他在长安见到了同样帮助过薛家军的东海少侠，并帮助其解决了一桩困扰长安良久的凶杀奇案。却不想，因此他反而在朝中也发展了一些眼线。",
	["tid#herolegend7_109"]="原本她以为，不过是处理一个小问题而已，然而连续的追踪让她意识到她一直观察的人十分不简单，先是东海霸王擂，江湖群侠纷纷前往，她也不清楚为何一个初出茅庐的年轻人可以有这么大的号召力，不过她后来注意到万象楼的人也有所行动，她方才意识到她一直奉命监视的人绝不简单。",
	["tid#herolegend7_110"]="暂缺",
	["tid#herolegend7_111"]="十二连环坞水贼联合之事，看来地方官府早已无力惩治，乃至于江湖中的正派人士也开始着手想办法对付这支水路巨蠹。暗门隐卫自然不能袖手旁观，因此最适合处理此事的人便是公孙雨，公孙雨来到连环坞，得知瓦解水贼的关键便是那连环坞的总舵主。然而她计划行进的过程中，一位暗司关注已久的蓬莱少侠出现在她的眼前，本以为他会干扰自己的计划，但是机敏的公孙雨还是以自己的方式顺利解决了此事。",
	["tid#herolegend7_114"]="暂缺",
	["tid#herolegend7_115"]="在从蓬莱归来之时，方剑斌曾路过侠客岛，彼时侠客岛上早已有了周湘君设立的太极迷阵，专门试炼天下习武之人。刚刚有所开悟的方剑斌当然不能放过这个测试自己的机会，因此他立刻参与了试炼。然而，这迷阵的难度出乎了他的预料，这阵中的机关傀儡配合江湖迷阵，让他几次陷入险境。因此后来他每年都会来尝试挑战一次此迷阵，直到一次遇到一位从蓬莱到此的青年，几番互帮互助也算投缘。只是他因公离开不久，便听说这迷阵被破，却也有几分遗憾没有亲眼见识到有人破阵。",
	["tid#herolegend7_181"]="暂缺",
	["tid#herolegend7_182"]="暂缺",
	["tid#herolegend7_183"]="暂缺",
	["tid#herolegend7_184"]="在从蓬莱归来之时，方剑斌曾路过侠客岛，彼时侠客岛上早已有了周湘君设立的太极迷阵，专门试炼天下习武之人。刚刚有所开悟的方剑斌当然不能放过这个测试自己的机会，因此他立刻参与了试炼。然而，这迷阵的难度出乎了他的预料，这阵中的机关傀儡配合江湖迷阵，让他几次陷入险境。因此后来他每年都会来尝试挑战一次此迷阵，直到一次遇到一位从蓬莱到此的青年，几番互帮互助也算投缘。只是他因公离开不久，便听说这迷阵被破，却也有几分遗憾没有亲眼见识到有人破阵。",
	["tid#herolegend7_191"]="暂缺",
	["tid#herolegend7_192"]="暂缺",
	["tid#herolegend7_193"]="暂缺",
	["tid#herolegend7_194"]="暂缺",
	["tid#herolegend7_195"]="暂缺",
	["tid#herolegend7_201"]="韦壮武与黄荣华听闻太极门周宗师从蓬莱归来，于是打算一起前往找他比试，在湘君山庄附近落脚之时却发现近地五十里无下榻之处，一经大厅方才知道是自己儿时发小要举办东海霸王擂，将附近的旅店客栈全部包场。与林良骏相见并未有他心目中那般场景，这幼年好友做惯了商人，如今也不过一套假意客套的做派，不过倒也结识了一个东海少侠，想起他在蓬莱之时却并未见过如此厉害的青年，想着有一天一定再去蓬莱与人讨教。",
	["tid#herolegend7_202"]="“玄素之战”中，“素”便是白衣天华君，“玄”则是黑衣韦绝，从韦绝的身手中看得出来，自己可能不是对方的对手，而这件事一直让他耿耿于怀，直到见识到了一时间沸沸扬扬的一个要出岛的蓬莱年轻人。从天华君口中得知，这年轻人便是鬼谷预言中的“韦绝克星”，想必与这“韦绝克星”对决要是赢了，那就说说明自己能够胜过韦绝了吧。于是黄荣华便去趁那年轻人离岛之前与之一战，只可惜并未胜过，黄荣华只好感叹江湖风云真是要变天了。",
	["tid#herolegend7_203"]="但随着恶人谷名头鹊起，却引起了其他门派的忌惮与敌视，恶人谷内也开始风云变换起来。一次刑探花听闻恶人谷谷主要举办赏刀大会，然而作为好友并未知会自己此事，邢伯严便觉得事情有所蹊跷。等来到之时，却得知宝刀被盗，如今谷主最怀疑的便是一个从蓬莱来的年轻人。了解谷主的刑探花知道谷主做事不会如此草率，于是亲自调查一番才得知真相。",
	["tid#herolegend7_205"]="靳辰洋经离几件事之后便一直对那白衣剑士念念不忘，只可惜再入江湖游历多年也毫无所获，后来路过龙门之时，却在一间客栈口中听到过些白衣剑客的事迹，从一个食客口中得知，有一白衣剑客正欲上贼人山寨只身剿匪，靳辰洋听闻此事便立即赶往追寻。",
	["tid#herolegend7_206"]="然而，尽管她们的调查因为受到阻止而不了了之，可是丐唐与明教在枫华谷的混战依旧难以避免，尽管在先前少侠的帮助下避免了覆灭的危机，但是却又遭到红衣教的袭击。所幸几人采取围魏救赵之计，转而去袭击红衣圣坛荻花宫才再次破局，然而也就是这荻花宫一事，沈念终于见到了自己的亲妹妹月华，此时的月华不知为何对红衣教如此死心塌地，于是拜托少侠将妹妹带回。可惜的是，红衣教阿萨辛出现带走了妹妹，沈念也只好将思念继续留在心里了。",
	["tid#herolegend7_207"]="不过宁不凡的剑法虽然绝妙不过也不是已然毫无对手可言了，一次华山论剑台上，来一个手执黑剑的古怪人。宁不凡听过他的名号，也听说过他的剑法也早就超然入圣。所以，宁不凡败在他手上，也并没有觉得有多么懊恼，不过令他没想到的是，剑圣与他对决之时，竟然还无意留下一些剑意，只是这些剑意便让后来登上论剑台的华山弟子感到彻骨的肃杀。也正是这几道剑意竟然还能让拜访的传闻的中蓬莱少侠意外受伤。宁不凡知道自己以后的剑法想要达到至臻的境界，便是先要将此剑意化解不可了。",
	["tid#herolegend7_208"]="遥想当初，辛晓风初次见到宁不凡的时候，是在一个雨天。那是他正在一个屋檐下避雨，宁不凡却走了进来，一边喝酒一边说些蹩脚的玩笑话。恒山觉得这人甚是有趣，便和他聊了起来。宁不凡大自己两岁，便说什么“即使行走江湖，便都是兄弟姐妹。”硬要叫自己小师妹，恒山本就不在乎这些，便也依了他。这人连灌了好几口酒，看起来很是高兴，临走时还送了她一把伞。恒山很疑惑，这个人明明有伞，为什么还要在这里避雨呢？",
	["tid#herolegend7_210"]="直到一天，他听到一个吵吵闹闹的声音出现在自己身边，这人如同自来熟一般，总是自说自话，也总是带着一身陈酿的味道挥发不尽，可是吕沛杰却不厌恶此人，因为身边的人似乎并没有将他当作是弱者。对方说，自己身上的颜色很有意思，非黑非白，像是一种混沌，吕沛杰说他没见过黑白，也不知道什么是混沌。直到一次，吕沛杰拉起二胡，对方就会说他此时拉的某种曲调是什么颜色的感觉，这一刹那，吕沛杰好像知道颜色是什么了。",
	["tid#herolegend7_211"]="鬼谷先生算到此人今后乃是江湖大患，但天道有常也不好过多干预，后来太极门周宗师求助，帮他在毗邻蓬莱的侠客岛设立太极迷阵，以试炼天下有志侠客，又留下神犀诀功法供有缘的侠客参详。之后他一直在等一个年轻的蓬莱人出岛来解决深埋江湖的祸患，也便是他口中的那片“飞云”，正所谓“天玄地命未详参，决弈黑白镇河川。难料天华拂云落，蓬山此去几时还。”正是那年轻人的判词。",
	["tid#herolegend7_212"]="纯阳剑阵在万象楼久攻之下，开始有所松动，千钧一发之刻，有一个仗剑的年轻侠客前来助阵，终于使得天华君腾出手来专心对付韦绝，这才挽回了纯阳的颓势，成功击退来犯的万象楼。吴清霄得知此人正是天华君之前所说的蓬莱少侠，同样少年英气，天纵之才，恍惚间吴清霄从这位少侠身上看到了师兄的影子。吴清霄不禁感慨，方才与那万象楼部众陷于苦战无助之时，想到的正是希望此刻有师兄助阵，而来的人又与师兄那么相像。吴清霄有些恍惚，也自觉有些失礼，后来也留得少侠在纯阳中逗留数日。",
	["tid#herolegend7_213"]="后来喻扬超听闻蓬莱是武学圣地，因此特地拜会，领悟到一套适合自己霹雳弹的更强的武艺，而后弃商从武，毅然决然前往西域都护府剿灭胡人沙匪。被沙匪洗劫的经历，让他觉得不将这些恶人除尽，不管多少技艺货物都无法正常流通，而自己不管学了多少东西也只会被这些野蛮人摧毁，而对付这些野蛮人也必须以眼还眼才行。",
	["tid#herolegend7_281"]="暂缺",
	["tid#herolegend7_282"]="暂缺",
	["tid#herolegend7_283"]="暂缺",
	["tid#herolegend7_291"]="暂缺",
	["tid#herolegend7_292"]="暂缺",
	["tid#herolegend7_293"]="暂缺",
	["tid#herolegend7_294"]="暂缺",
	["tid#herolegend7_295"]="暂缺",
	["tid#herolegend7_301"]="听闻江湖中出了一个东海少侠，药王便起了好奇之心。药王知悉经脉之道，自然知晓常人之力终有穷尽。而东海少侠武功卓绝，非凡人所能企及，对于他的体质，药王始终想一睹为快。但当他终于站在面前时，却一道引来了孽徒赵心音。尘封多年不愿触及的记忆涌入，药王也无心再多留眼前这些人片刻。但那少侠经脉之中流动的真气让他觉得，蓬莱岛天外有天，若有时机，似乎该去探寻一番了。",
	["tid#herolegend7_302"]="郭香香游历江湖，最大的困惑就是随便遇到一个侠客，都是郭巨侠的仰慕者。但她没有想到的是，连中原之外的蓬莱，也已熟知郭巨侠的事迹。当蓬莱少主在她面前说出“想成为郭巨侠一样的人”时，一心想闯出名堂的郭香香竟不知该自豪还是该失望。但相处下来，见这少侠身手卓绝，倒是与巨侠年轻时的英姿有几分相似。郭香香想着，那就祝他梦想成真吧，只可惜他未来的女儿，要和自己有一样烦恼了。",
	["tid#herolegend7_304"]="如公孙大娘所言，霓裳羽衣剑法须有情爱之意方可练成，但江湖从来不乏登徒子，花间派姐妹又多为情所伤，苏婉仪看在眼里，自然对世间男子难有好感。但蓬莱少侠给她的感觉，似乎和旁人有些许不同。他好像并不在意容貌声色，而是透过皮相，直接看入人的内心。他直接点出了苏婉仪的症结所在，又在晚宴之上解了花坊之围，苏婉仪看到，在这个少年眼里，舞坊的温香软玉并非“舞娘”，而是一个个有血有肉的“人”。那一刻苏婉仪感到，内心的三尺寒冰，渐渐开始松动了。",
	["tid#herolegend7_305"]="在墨家眼里，东海少侠有点头脑简单，却一开口就问住了她。得知她内心的疑虑，他问她，“数字可有穷极？何以为证？”墨家只道数字永无止尽，无以为证，人尽皆知。对面的人便露出得逞的笑容，“感情亦是如此。无需论证，只要相信，它便在。”如此谬论，墨家第一次听闻，却暗暗记了下来。虽无法苟同，但在她眼里，这世界已越来越有趣了。",
	["tid#herolegend7_306"]="相传得《开元典论》之人可得天下，试探清蓬莱少主的实力后，姜笑川决定让他获得此籍，破一破江湖的僵局。利用自己的官职身份，他轻松取得了锦衣卫小跟班的信任，修密书于她，骗她将东海少侠引致秘籍所在之处。《开元典论》世间瞩目，如今被世外高人所得，那么韦绝，乃至大半个江湖，只怕都不会太平了。",
	["tid#herolegend7_307"]="在姜承影的记忆中，风云鹤长老备受敬重、风光无限，而当东海少侠破了天问幻境时，才看到他背后那不堪的过往。身为外姓弟子，自幼备受冷落，唯一亲近的曲师姐也被冠以“包庇”的罪名，落寞而死。天问剑，是惑人之剑，复仇之剑，亦是终其一生，对命运不公的一句泣血追问。东海少侠破解幻境，风云鹤自尽而亡，而姜承影也终于意识到，内门弟子的选拔与治理之法，终究是要改改了。",
	["tid#herolegend7_308"]="坏人就是坏人，师父说的果然没错。在叶寻欢偷偷潜入碧生阁，还放陷阱暗害自己时，滔滔内心这样念叨着。还好蓬莱少侠及时赶到，看他先前武功不赖的样子，碧生阁的秘籍当是有救了。滔滔昏昏沉沉地睡去，至于此后叶寻欢与少侠的争斗、和师父的及时赶到，都一概不知了，只知道一觉醒来便已天下太平，师父云游归来，又可以一起去吃好吃的了。",
	["tid#herolegend7_309"]="在周湘君的众多徒弟中，虽有滔滔这样的得意弟子，但也难免会出一两个逆徒。当他第一眼见到叶寻欢时，便从他的眼中看出了野心。分明资质平平却偏要挑战一流剑客，被打得奄奄一息，直勾勾的眼神里仍投射出阴鹜与欲望。周湘君救下他，带回山庄收为弟子，本以为能让他成为普通但善良的侠客，但当他以“不受重视”为由叛变师门、投入万象楼时，周湘君才知道，自己终究是失败了。虽然万象楼与太极门眼下尚无纠葛，但他知道，师徒反目的戏码，迟早有一日会在自己的山庄中上演。",
	["tid#herolegend7_310"]="虽然闹了不小的误会，但好在东海少侠知错就改，倾力相助救回了神鹿，筱九便决定，不再与他计较了。况且在他身上，筱九感应到一颗如圣灵般澄澈的内心，这是在离开圣地之后，在人类身上从未见到过的。虽然短暂的相逢转瞬即逝，告别后筱九便随史春莲前往万兽庄救急，但日后江湖总还会相遇的吧，筱九时常这样想着。",
	["tid#herolegend7_311"]="虽然不善言辞，但李清秋的心中，最重要的位置，一直是留给郭香香的。只可惜几次相遇都匆匆而过，李清秋希望，自己能做的，不只是替她解围、请她吃饭那么简单。郭香香是郭巨侠的女儿，要吸引她的注意，还得有过人之处才行。怀着这样的想法，李清秋开始倍加关注霸王擂，并暗暗努力。第二次与蓬莱少主相遇，武功的较量依旧不相上下，但少侠的小跟班不停追问郭香香的事情，却扰乱了他的心绪。原来江湖之中早有自己与她的传闻，不知来日擂台之上，她是否会有所期待呢……更加期盼比赛的李清秋，开始时常陷入这样的沉思。",
	["tid#herolegend7_312"]="万兽庄狩猎素来恪守原则，在江湖之上颇负盛名。但不想再次与东海少侠相遇，史春莲却被当作了觊觎神鹿的歹毒之辈。因贼人挑拨，东海少侠误将向神鹿求助的史春莲当作歹人，害神鹿被盗，亦险些误了她求药的大事。虽愤慨有之、不甘有之，但东海少侠毕竟行侠仗义，将功补过救回了神鹿，向来直爽的史春莲也很快放下了心结。虽是一场误会，但所幸得以善终，也因这段小小的插曲，结下了一段江湖情谊。",
	["tid#herolegend7_383"]="暂缺",
	["tid#herolegend7_386"]="暂缺",
	["tid#herolegend7_387"]="暂缺",
	["tid#herolegend7_391"]="暂缺",
	["tid#herolegend7_392"]="暂缺",
	["tid#herolegend7_393"]="暂缺",
	["tid#herolegend7_394"]="暂缺",
	["tid#herolegend7_395"]="暂缺",
	["tid#herolegend7_401"]="与此同时，蓬莱少主来到中原的消息也传遍了江湖。相传这位少侠根骨清奇，武学心法中原罕见，俨然世外高人，更是无形中证实了对蓬莱的猜想。从陵墓出来后，翟冬玄带着“妻子”四处云游，也一路暗中查探蓬莱少侠的消息。当“东海大侠”的名声越来越响时，翟冬玄决定，前去向他寻求复生之法。",
	["tid#herolegend7_402"]="江湖中人提到苗疆，大多都是谈毒色变。但从前的五毒教并无害人之举，直到出现了“天一”邪教。阿岚小时候，就听过海棠长老不满于江湖偏见、欲炼“毒傀儡”复仇，让天下畏惧于己的言论，但她没想到，遭到五圣的反对后，她竟真的反叛成立了“天一教”，又在此时杀回到自己人头上。幸而那东海少侠及时预警，又想出了应对之策，倒也是个热心人。虽然在他的帮助下，天一教暂时被击退，但眼前“毒傀儡”的惨状让阿岚预见到，五圣教与天一教之战，已是近在眼前了。",
	["tid#herolegend7_403"]="在金水镇与蓬莱少主相遇时，祥颖韬精心设置了一个陷阱。利用金水河特殊的地形，将蓬莱少侠与他的锦衣卫小跟班分别困在两个水库里，当水漫进来时，只有一个人能够逃生。蓬莱少侠是姜笑川的一枚棋子，早已有了要留活口的“特赦”，但他身边几个随从的命运，就全凭祥颖韬拿捏了。能借蓬莱少主之手多除去一个障碍，祥颖韬自以为高明得很，却没有想到，即使在最后关头，少侠仍没有选择放弃同伴。祥颖韬再次感受到挫败，一如当年面对李延广之时。他意识到，自己的策略应该变一变了。",
	["tid#herolegend7_404"]="多年的江湖生涯使得陆尘子消息异常灵通，得知蓬莱少侠与玄甲赵副将通信，便来了一招偷梁换柱，先潜入玄甲制服副将，再伪造信件引他前来。只是计划虽滴水不漏，这位少侠的功力却在他意料之外。这是陆尘子第一次失手。虽然重创蓬莱少主，已足以令江湖唏嘘，但对陆尘子来说，这并不是他想要的结果。难得一见的劲敌让他感到莫名的亢奋，他笃信在下一次计划中，定能胜他几招。",
	["tid#herolegend7_405"]="不出赵心音所料，当自己用计让谷外的老人中毒后，热心的少侠果然行侠仗义，找上门来求助。《武经》集各派武功之大成，且不提获之可叱咤江湖，就说这蓬莱少主“武痴”的性子，也未见得能经得住诱惑。赵心音等着看一场好戏，却未成想，他当真将《武经》完好封入秘境，未曾翻开半页。看来人心之事，到底仍有例外。虽说计划落空，但这颗不同于世间的至善之心，却提起了赵心音的兴致。",
	["tid#herolegend7_406"]="接到父亲的命令时，唐明月内心有些犹豫。——诛杀蓬莱少主，眼下对唐门而言，似乎确是明智的选择。蓬莱少主身中剧毒，情形尚不明朗，韦绝只手遮天，眼见这江湖就是他一人的天下。唐门素来对韦绝尽心尽力，此时若拿下诛杀劲敌的首功，日后在江湖的地位，不言而喻。但唐明月内心却一直觉得，那个少年会赢。即使他现在身在低谷，这种想法也从未磨灭过。关于他的记忆，和心底那个向往自由的自己渐渐重合，唐明月决定，要随自己的意愿活一次。违抗父亲的命令，或许拯救不了江湖，但是，能拯救内心最真实的自己。",
	["tid#herolegend7_407"]="朱英杰喜欢混乱，或许因为自己一直活在混乱之中。所以但凡有能制造乱象的机会，必定会有他的身影。他没有什么坚定的立场，如今帮助韦绝对付蓬莱少主，也是一如既往地享受破坏秩序的快感。但他发现，这少侠虽为人正派，却也不是什么循规蹈矩、安安分分的人。若有一日他能掀起什么风浪，朱英杰倒也不介意与他为伍，给这个江湖再添一点波澜。",
	["tid#herolegend7_409"]="在见识了蓬莱少侠的武艺之后，秦飞雪深感自己在武学造诣上的不足，她看到了自己与真正的高手之间还有非常大的差距，因此决定前往蓬莱，那片武学的圣土好好磨练一下自己。她希望自己也能自蓬山归来之后获得蜕变，能够成为像义父一样的“为国为民”的“侠之大者”。",
	["tid#herolegend7_410"]="明教圣坛戒备森严，纵使身为昔日圣女，未与教主、长老合力，想从密牢救人也绝非易事。但幸好这次找对了人，看着遭自己几次暗算的蓬莱少侠仍尽心尽力救人，陆小贝想，这人说是天赋异禀，其实和那书生一样傻，日后，还是不要与他为难了吧。不过想来也是没有什么机会了——此番远走高飞，权当还自己安宁，种种江湖纷争，便随它去吧。",
	["tid#herolegend7_411"]="坏人就是坏人，师父说的果然没错。在叶寻欢偷偷潜入碧生阁，还放陷阱暗害自己时，滔滔内心这样念叨着。还好蓬莱少侠及时赶到，看他先前武功不赖的样子，碧生阁的秘籍当是有救了。滔滔昏昏沉沉地睡去，至于此后叶寻欢与少侠的争斗、和师父的及时赶到，都一概不知了，只知道一觉醒来便已天下太平，师父云游归来，又可以一起去吃好吃的了。",
	["tid#herolegend7_412"]="左寒修看准了蓬莱少侠“武痴”的性子，欲以《寒冰诀》为饵，诱他“精进武学”。寒冰诀为至寒之功，与蓬莱天霜诀有三分相似，只是邪气更盛，常惑人心智，令人万劫不复。若蓬莱少主为“精进蓬莱武学”的心思所诱，修习寒冰诀的“精华”，则身败名裂之日便不远矣，左寒修之心结亦当可解。在此念头的驱使下，左寒修开始了一场精心的布局。",
	["tid#herolegend7_413"]="从蓬莱回来的玄水姬并没有如愿找到赵心音，功力却变得更加强大。因早年遇人不淑、厌恶男人，神水宫早已下了禁止与男人私会的禁令，但玄水姬在蓬莱的这段时间里，却难免有弟子偷偷违令，亦不乏有人为情所伤。后来那些“野男人”都受到了玄水姬的教训，玄水姬也更加笃定，那些表面光鲜的风流侠客，都是内心龌龊，天理难容。所以当江湖的又一个新秀——蓬莱少侠出现时，她对他也并没有什么好印象。无论为神水奇功与蓬莱绝学的较量，还是为了给这家伙一个教训，玄水姬都希望有一天，他能败在自己手上。",
	["tid#herolegend7_481"]="暂缺",
	["tid#herolegend7_484"]="暂缺",
	["tid#herolegend7_485"]="暂缺",
	["tid#herolegend7_491"]="暂缺",
	["tid#herolegend7_492"]="暂缺",
	["tid#herolegend7_493"]="暂缺",
	["tid#herolegend7_494"]="暂缺",
	["tid#herolegend7_495"]="暂缺",
	["tid#herolegend7_501"]="不出李知傲所料，正当他以为自己可以安心离开时，姑娘那边又出了乱子。比武招亲却给自己惹上麻烦这种事情，倒颇为符合她的性格。来者仍是先前窥探已久的几个恶霸，看来这姑娘终归江湖阅历过浅，太容易结仇。再次出手解决了麻烦后，李知傲与姑娘交手，以过招引导她，强横之外，更要留意敌方后手。没想到一来一回，倒是打了个不相上下。交手间，姑娘效仿世间生灵的功法引起了他的兴致，但眼见她有意相让，李知傲也不愿多生事端，最终匆匆收招，悄然离去。",
	["tid#herolegend7_502"]="从蓬莱得到点悟后，姐弟二人携仙乐而归，世间苦难，也等来了他们的救赎。江湖中渐渐有了传闻，心念善良之人，可得圣子庇佑，一生无忧。感念于蓬莱的馈赠，当蓬莱少主初次踏入江湖之时，姐弟俩曾为他奏起乐音，赠予他最纯净的心境；集昆仑圣童与蓬莱仙乐之力，护他不染俗世尘埃。",
	["tid#herolegend7_503"]="加入九天之后，句芒仍会暗中关注蜀山，也会出手帮梁铮雨除去一些障碍。这个让逸心牵挂至最后一刻的小师弟，此时也成了他心里的挂念。在追查蜀山被围攻的真相时，“凌峰楼”这个名字走进了他的视野。天罗十大高手的画像，渐渐和当年蜀山内那些身影重合，同时他也发现，这些人和天华君近日关注的一桩事情也有关联。这次他们的目标，似乎是初入中原的蓬莱少主。云天君句芒决定，与天华君联手，夺回这个江湖失落已久的正义。",
	["tid#herolegend7_504"]="从蓬莱回还后，得益于蓬莱绝学，霍紫凝不仅医术更加精进，亦有了更加深厚的功力。她惩治了曾经那些官吏，将药材从他们手中取回，给了医馆和更多需要它们的人。此后，她继续云游四方，将从蓬莱习得的医术连同慈悲之心一起，带向更多地方。",
	["tid#herolegend7_505"]="可是萧春风的追寻终究是盲目的，她在江湖游荡，一路行侠仗义，美好记忆让她看起来有些不食人间烟火，无论来人抱有多大的恶意与敌视，她也只是一副懵懂的样子，所以她接人待物永远春风满面。因此在普通人看来，她就是一个将美好散布在江湖各处的仙子。",
	["tid#herolegend7_506"]="后来江湖上盛传黑衣韦绝独闯天龙门，与天龙门门主有一场惊天动地的对决，但是没人清楚这场比试具体是怎么展开的，因为在场的人，周文浩都让他们永远闭上了嘴。不过后来，一时风生云起的天龙门锐气大减，反倒是那韦绝借此之事声名鹊起，一时风头无两，不知多少门派前往攀附。周文浩永远无法忘记那日的耻辱，暗暗发誓只要有与那韦绝为敌的，都可以是他反击的助力。后来他听闻蓬莱有一少侠来到中原，号称“韦绝克星”，周文浩因此立即注意到此人，他自觉可以借助这蓬莱少侠的力气，除掉自己的心头大患！",
	["tid#herolegend7_507"]="历经此事的梁钲雨，沉心修炼，并阅尽了琅嬛阁中的秘籍。他将师兄们的佩剑加以改造通通戴在身上，真气御动之时便如同翱翔剑翼，并结合蜀山功法自成一套惊人的武功，在长老们看来，这是继已经不在的大弟子之后有一个能够继承蜀山的弟子。然而长老们却因为他的来历与之前蜀山被围之时耿耿于怀，不可将梁钲雨提拔为首席弟子。不过，梁钲雨并无心于此，一日清晨，梁钲雨带着剑翼离开了蜀山，誓要追查当日围攻蜀山的真凶。",
	["tid#Herolegend7_508"]="然而江湖纷争从来不饶人，不久后，韦绝和万象楼便猖狂于江湖，名门之后都接到了集聚江湖，共商大计的密信。对于重归江湖，唐寅开始有些犹豫，但思及往日于江南纵酒而歌的日子，想到如此美景或落于他人之手，终是于心不忍，启程回了中原。他不知道，沉寂多时之后，那一刻在他心上人的眼里，当年的盖世英雄，终是回来了。",
	["tid#herolegend7_591"]="暂缺",
	["tid#herolegend7_592"]="暂缺",
	["tid#herolegend7_593"]="暂缺",
	["tid#herolegend7_594"]="暂缺",
	["tid#herolegend7_595"]="暂缺",
	["tid#herolegend7_607"]="蓬山归来的求伯君，一举荡平了天忍教所有的阴谋，此盛举被江湖人称“君之传奇”。随后不久，求伯君便决定退隐江湖，将掌门之位传于可靠的金山后辈。至于求伯君隐退的原因，江湖上也是众说纷纭，有人说求伯君经年勤勉于武学身体总有些损伤，与天忍一决之后，身体状况便大不如前，隐退也是无奈之举；然而也有人说，求伯君在蓬莱之间有所开悟，如今心境平和，自己的使命也已经完成，更想如闲云野鹤浪荡于江湖之中。不过究竟为何，世人也只是纷纭猜测，唯独留下的江湖传奇，永远传颂于武林之间。",
	["tid#herolegend7_606"]="在蓬莱得到点悟后，鸠摩罗的智慧更加精进，藏传大师之名也愈发之响了。他深信这是佛对自己的恩赐，亦是藏传法学终将闻名于天下的指示。他来到了儿时的树下，再次看到了当年的影子。依旧是熟悉的情形，但影子这次没再说话，而是像一位故交一样，与他并肩而立。于是他知道，这世间有些道理，终是要靠他自己去领悟了。",
	["tid#herolegend7_602"]="邪极坊逐渐变成令吕珂满意的“净土”，但她并不满足于此。随着魏途殊功力的增长，吕珂的野心也越来越大，她想要建立一个再没有虚伪与邪恶的、“纯善”的世界。凡人见识浅薄，她就借助意念之力，将自己的心智“赐予”他们；那些心术不正、难以拯救的，就助他们“重生”。中原之地，在吕珂眼里已过于污浊，她要寻找一方世外净土，来容纳自己的“至善”天下。于是有一天，她和魏途殊一道去了蓬莱。",
	["tid#herolegend7_603"]="柳念暂且答应了九天的诉求，但并未正式加入，后来九天有一事相托，有信称昆仑山上有一柄神剑“九尺寒冰”烛阴现世，此剑妖邪无比绝不可让其落入江湖。因此柳念只当是加入九天的投名状，于是只身前往昆仑，却遭遇了九天关注的另外一人，一个自蓬山而来的青年人柳念也不知道从什么时候开始，也不太会排斥一个陌生人的接近了，也许破冰之后，那年的天雪鬼见愁已经开始融化了。她与那蓬莱少侠合作，解决了烛阴之事，此后道别，便向着九天而去了。",
	["tid#herolegend7_604"]="刘异不知道左寒修是否已知晓自己的存在，但他知道，想胜过这位劲敌，便要做出周全的准备。寒冰掌威力非同寻常，但邪气极易反噬，刘异原本的计划便是以此为筹码，攻其弱点，令其自取灭亡。但从眼线报来的消息来看，左寒修却丝毫没有被邪气所攻的迹象，甚至因为体质特殊，与蚀骨的寒气形成了某种微妙的平衡。刘异于缥缈峰顶冥想了一个昼夜，终于悟得天机，得知这一切与“蓬莱”有关。当晚，他便踏上了前往蓬莱的路。",
	["tid#herolegend7_605"]="可自东海有青鸾初鸣，周今鸣似乎看到一潭死水的江湖似乎又有什么转机，相传从不出海的蓬莱人居然有一个青年才俊来到了中原，也听闻那人正是所谓万象楼的韦绝的命中克星。周今鸣觉得机会也许就在现在，她需要找机会好好把握这个蓬莱少侠，才有机会机会击败她所有的武林上的敌人。",
	["tid#herolegend7_691"]="暂缺",
	["tid#herolegend7_692"]="暂缺",
	["tid#herolegend7_693"]="暂缺",
	["tid#herolegend7_694"]="暂缺",
	["tid#herolegend7_695"]="暂缺",
	["tid#Herolegend7_701"]="晴雪历经九百年的追寻，机缘巧合得到妖兽辟邪的“辟邪之骨”，此骨可塑造躯体，承载所有魂魄，包括荒魂。她寻求女娲以牵引之术将屠苏的荒魂载于辟邪之骨上，让屠苏得以重生。重生的屠苏可以像正常人一样长大，虽魂魄历经漫漫时光后，失却了过往记忆，但重生的屠苏仍喜欢上了晴雪。而且，他与焚寂之间的某种联系，也正渐渐帮助屠苏恢复着过往记忆。最后，和晴雪在改名为桃花乡的桃花谷，相守彼此最后的一世。",
	["tid#Herolegend7_702"]="后来玄戈亡故，晴雪拿到玄戈遗留的辟邪之骨。然后不久之后，发生变故，天鹿城因遭遇魔物的攻击而伤亡惨重，与天鹿城早已结下深厚友谊的晴雪决定留下来帮助辟邪族。这期间，由于时常委托常往来人间的新辟邪王北洛从人间收集药材，也与北洛有过几番交谈。数年后，晴雪回到人间，并使用辟邪骨让屠苏获得重生。最后，她与屠苏一起，在改名为桃花乡的桃花谷相守彼此最后一世。",
	["tid#Herolife_101"]="十年前，十七岁的林无双替父出征，成为当朝首位女将军，自此之后，江海肃清，外敌莫敢来犯。林将军之威名，纵是当朝天子，也要让她几分。她的长枪之下，从未有过败绩。因为在她背后，守护的是整个庙堂、江湖，更是那猎猎旌旗的归宿——天策府。",
	["tid#Herolife_102"]="王司马记事以来第一个春节她看到了放烟花，从此对这种令人着迷的火药类产品迷恋的不可救药，她开始学习制作烟花和炮仗，长大后，跟着养父来到了火药房，开始研究炸弹，可惜一直没有什么大的贡献。但突然某一天，她制造了一系列炸药和新式爆破武器，获得了父亲与上流社会的赞扬，年轻的王司马似乎找到了人生的目标一样每天沉迷于研制新式火药。",
	["tid#Herolife_103"]="如今身为长安六扇门衙司司丞的李延广，是让长安乃至整个京畿道的宵小之辈不敢轻易造次的可怕角色，经他之手的疑难案件也都能全部解决，可谓是守望长安震慑宵小的夜枭。",
	["tid#Herolife_104"]="在李郡十岁之前，她还打不过那些比她高大很多的孩子，但是那些坏孩子都会说李郡的坏话，欺负她的人，她怎么会放过呢？李郡有的是鬼办法将这些孩子制服，她设计陷阱将这些孩子绑在树上，锁在没人的茅房里，总之，李郡总有办法在实力相差巨大的时候将对方制服！",
	["tid#Herolife_105"]="清觉襁褓之中便被穷苦的父母送来了坐忘山，住持也没多想便收了下来，不过为断了孩子红尘只留了孩子生辰并未留下俗名。清觉有一个年纪相仿的师兄，二人一起修行长大，不过与有些急躁的师兄不同的是清觉从小就是个悲天悯人的孩子，他总是不忍看到任何生命在他眼前消逝，因此就连他窗前的小盆栽都被他精心呵护的很好。",
	["tid#Herolife_106"]="刘关江出生在一座名为“破落镇”的小城中，父母是城中再普通不过的老百姓，日子也过的普通得不能再普通。八岁那年，破落镇遭遇了一场大旱，作物颗粒无收，灾民哀鸿遍野。刘关江的父母也在这场旱灾中去世了，只留下他和年仅四岁的弟弟挣扎求生。刘关江从那场旱灾中活了下来，但等待他的，却是另一场炼狱。捡他回来的那个人是潜行者组织的首领。之后的日子中，刘关江最终被塑造成了一个没有感情，只听自己命令的做事机器。",
	["tid#Herolife_107"]="燕云飞出生在一个小商贩家庭，在一场战役后痛失双亲，被一名燕姓老兵捡回抚养，他始终没能放下过往，成长为一个心中仍有暗影的战场王者，不过正是这份过往中产生的决心，让他在平日里不贪图享乐，在失意之时有内心的一份坚守。",
	["tid#Herolife_108"]="原为龙虎山天师门少门主，却从小无心修行，在山下独自创办摘星阁，自称手可摘星，通达仙人指路，笼络信徒，专门收集买卖四方情报。以至于江湖上无论大小门派，甚至朝廷想要的情报，都可在摘星阁获得。不过后来，天师门老门主去世，作为长子的张昊不得回到天师门继承门主之位。",
	["tid#Herolife_109"]="禹海莲出生在军人家庭，所有一切都遵循着家族和这个家族的信仰而进行着，她和哥哥在母亲体质最好的时候相继降生，按部就班的进行着本应该变幻莫测的人生，毕竟，这个家族信奉的是，秩序为上。六岁那年，她送八岁的哥哥参加特训，她在心里暗暗决定，等到八岁那年，也要像哥哥一样胸前系着大红花，骑上高头大马，追寻哥哥的脚步。后来，她和哥哥一样出色，两个人在十五岁左右就被调到兵部的特动营，担任急先锋。",
	["tid#Herolife_110"]="暂缺",
	["tid#Herolife_111"]="她的命运，就是在刀锋与凋零之间跳舞，她的出生代表着古老信仰的重新降临。",
	["tid#Herolife_114"]="暂缺",
	["tid#Herolife_115"]="方剑斌出生在与鹰为伴的部落当中，他们这个部落世代会培养优秀的兽兵斥候来支援朝廷战争。族人善于驾驭性情猛烈的猛禽雄鹰，不仅能够使其为己所用，还能与鹰这类野禽培养出默契和羁绊。",
	["tid#Herolife_181"]="北境之地距长安千里，常有异族蠢蠢欲动，朝廷却救援不及。有人自发组织了一支队伍护卫乡土，就是后来的“神刀门”。郭惊涛是神刀门第一任“少将军”，在他的治理下，神刀军威，甚至能与禁军媲美。此后北境安宁数载，将士扬刀之时，便有太平盛世如约而至。",
	["tid#Herolife_182"]="江湖中相传移花宫中住了一位仙女，仙子曼妙，气若幽兰，不知道多少痴情的男子对她心生向往，只可惜此生都难见一面，她便是移花宫的杨素素。",
	["tid#Herolife_183"]="萧不语出生在一座一直以来都非常和平的边缘村落，直到记事之前，都是十分宁静的村子，萧不语的父亲是一个猎人，家里除了正常的农活以外，还可以靠打兔子卖野味和皮毛来赚一些外快。萧不语小的时候总是模仿父亲，只不过他用的是弹弓。",
	["tid#Herolife_184"]="方剑斌出生在与鹰为伴的部落当中，他们这个部落世代会培养优秀的兽兵斥候来支援朝廷战争。族人善于驾驭性情猛烈的猛禽雄鹰，不仅能够使其为己所用，还能与鹰这类野禽培养出默契和羁绊。",
	["tid#Herolife_191"]="暂缺",
	["tid#Herolife_192"]="暂缺",
	["tid#Herolife_193"]="暂缺",
	["tid#Herolife_194"]="暂缺",
	["tid#Herolife_195"]="暂缺",
	["tid#Herolife_201"]="韦壮武家里世代都是屠猪的，而韦壮武仿佛天生凶煞，也天生神力，很小的时候就可以帮父母宰猪了，年幼的他也问过父母，为什么要宰猪，父母没读过书就告诉他，不要问那么多为什么，单纯的韦壮武山就以为凡事都没有什么为什么。",
	["tid#Herolife_202"]="江湖上有一位以脾气暴躁见长的古怪大叔，他武器非比寻常，是一对金环，为了变得更强，也是到处随人比武，凡是江湖上有点名气的门派，他都一一挑战了一遍，不过此人粗暴却也仗义，往往让那些江湖侠士哭笑不得又爱又恨。",
	["tid#Herolife_203"]="刑伯严出生在文官世家，历代缨鼎，显赫已极，三代中就中过七次进士，只可惜没中过状元，到了刑伯严这一代，其父亲膝下两位少爷更是天资绝顶，才气纵横，他老人家将希望全部寄托在两位公子身上，只望他们能中个状元，来弥补自己的缺陷。",
	["tid#Herolife_205"]="靳辰洋本是某个府上的千金小姐，因为姿色不错本是要进宫被选为秀女的，怎奈那年偶遇一个颇有江湖威望的算命先生，先生掐指一算，说是这丫头若是闯荡江湖必能大有作为，靳辰洋的父母尽管舍不得女儿，却也信了这半仙的话，没让靳辰洋进宫，还从小就开始习武。",
	["tid#Herolife_206"]="在她之前，流落街头的乞儿在世人眼里命如草芥、不值一提。她十八岁那年，整个江湖都对她一手建立的丐帮敬畏三分。从衣衫褴褛到名震江湖，她找到了自己的人生，也让天下乞丐找回了尊严。这一切，都源于名剑山庄门前，有人对她说的一句话：“人无贵贱，再难，也要走出自己的路来。”",
	["tid#Herolife_207"]="宁不凡出生在一个海边的小镇上，父母在镇上经营着一家客栈。宁不凡出生后不久，镇上来了一位奇怪的老人，老人对宁不凡的父母说，这孩子与他有缘，要带走他，教他剑法。起初，父母只当这老头是个疯子，把他赶了出去。约莫半个月后的一个晚上，老人又一次来到了客栈，和宁不凡的父母谈了很久。没有人知道他们谈了些什么，只知道第二天天亮之后，老头就带着华山离开了，宁不凡的父母虽然眼含热泪却也没有阻止。",
	["tid#Herolife_208"]="辛晓风的母亲本是妙法庵的一名尼姑，也是庵中住持师太的得意弟子。但却因为与庵中的一位男香客有染而被赶出了山门，几个月后的冬天，住持师太出门扫雪，却突然在庵门口发现了一个尚在襁褓中的女孩，这个人就是辛晓风。师太当然明白这是怎么一回事，但还是于心不忍，将女孩带回了寺中。",
	["tid#Herolife_210"]="吕沛杰的出生似乎打破了一个诅咒却也似乎带着别的诅咒，他天生失明，谁也不清楚他究竟是如何在弱肉强食的江湖中幸存下来的，但是如今江湖上听到他的名号，恶人们无不感到胆寒，不知道哪个夜里，突然魔音入耳就是他们的生命的尽头。",
	["tid#Herolife_211"]="况候智的父母两人从小一起长大，青梅竹马，两小无猜。待到父母都成年，正要完婚之际，父亲家却因为得罪了一位权贵而家道中落。母亲家不但没有帮忙，反而落井下石，撕毁了婚约。况候智的父亲又气又恼，竟生了一场大病，一命呜呼。母亲也是悲愤不已，欲跳河殉情而去。众人将其救下后送往救治，大夫却发现她已经身怀六甲。得知这个消息后，母亲不再自寻短见，而是离开了这个冷血的家族，自己一个人养育况候智。",
	["tid#Herolife_212"]="纯阳宫对旁人来说，是可望而不可即的清修之地，但对吴清霄来说，却是家一样的归宿。他从小性情淡漠，似乎没什么事能惊起他的喜怒，在俗人看来他是个怪胎，但被送进纯阳宫后，却因心思清净，很快有了几乎可与掌门并肩的修为。如今，纯阳宫面无表情、一心向道的清霄道长，已在江湖中颇负盛名。",
	["tid#Herolife_213"]="喻扬超为人博爱，交友广泛，他希望自己的智慧、才能、慷慨得到大家的认同，他是那种需要以多多的鼓励、多多的赞扬为能量的人，有时他显得很虚荣，并且不能克服虚荣。",
	["tid#Herolife_281"]="龙门寨是什么地方，江湖人大都心知肚明，所谓雁过拔毛也不过如此，如此凶恶之地，却也有个奇女子可以在此与无数盘根错节的江湖势力轻松周旋，她便是焦渝钦。",
	["tid#Herolife_282"]="胡大壮从小就是个善于为他人着想的人。因为控制不住自己的力气经常弄坏家里的东西，虽然没有被父母责打，但是也变得非常老实，凡事小心翼翼。5岁就开始帮家里干农活，一个人可以顶3个人，但是比起他的饭量，家里还是入不敷出，随着弟妹一个个出生长大，父母的压力越来越大，但是他们什么也没抱怨过。",
	["tid#Herolife_283"]="欧阳慧出生在西域的富商家庭，是商人的独女。自诞生时起就受到许多喜爱，在庭院中举行周岁抓阄仪式时，溜到了路旁，随手抓起了一条小蛇，爱不释手。仆人们窃窃私语，以为不祥。从小行事古怪，也不怎么与同龄的小朋友一起玩。富商曾带领他前往西域各镇增长见闻，然而却时常不见踪影。下人们曾经举烛漫山遍野找她，最终在一处湖边找到与蛇群低语的白驼。",
	["tid#Herolife_291"]="暂缺",
	["tid#Herolife_292"]="暂缺",
	["tid#Herolife_293"]="暂缺",
	["tid#Herolife_294"]="暂缺",
	["tid#Herolife_295"]="暂缺",
	["tid#Herolife_301"]="张景奇已经55岁了，他在大陆上已经游历了25年，25年间，他的足迹遍布了大陆上的每一个国家，收集了数万种的草药和数千种的病症及对应的药方，他的医书即将完成了。但他却没想到，一场祸端却因他而起。17年前，他收养了一个孤儿，并取名为赵心音。之后的时间，他带着赵心音在大陆上游历，待他如同儿子一般，教他医术。",
	["tid#Herolife_302"]="郭香香的父母是当世著名的大侠，父亲是有名的捕头，母亲秀外慧中，家里家外一把手，是江湖有名的神仙眷侣。而她从小生活在这样的光环之下，其实压力非常大，到哪里都会被介绍成，大侠的女儿，女侠的女儿。当然，这些压力也使得她从小要背负很大的期望去学习，去练武。论武艺和文化，其实身边同龄女孩子很少能有超过她的。",
	["tid#Herolife_304"]="花间派收容天下孤女，苏婉仪亦是其中之一。自记事起，花间派就是她唯一的温暖，因此，当有足够的武艺傍身之时，她也立誓要守护好这里。坊间姐妹都在她的教导下习武，各个身手不凡。世人皆知，花间派女子柔弱如水，但很少有人知道，她们，亦可随时成为一柄利剑。",
	["tid#Herolife_305"]="出生于机关学世家，作为三房的幼女诞生。出生时眼神明亮、从不哭闹被暗地里称为怪胎。半岁就会说话，过目不忘，举一反三……种种超常行为让她和其他人格格不入。随着年龄增长她自己也意识到了和他人的区别，这种冷淡她反而甘之如饴，因为不用整天面对这些愚蠢的凡人……",
	["tid#Herolife_306"]="表面上他不过是一个柔弱的仕人，谦谦君子，平易近人，姜笑川官品并不算高，然而似乎所有的官员对他都礼数齐备。也许只有桃花坞与万象楼的人才知道他的真面目——庙堂之上他翻云覆雨，江湖之中他播撒混沌，他高深莫测，没有人知道他究竟想要什么。",
	["tid#Herolife_307"]="名剑山庄浮沉多年，却在姜承影出生那年一鸣惊人，成为名门。他出生时天降异象，流星从夜空划过，三日后山庄于论剑大会拔得头筹。众人皆视他为福星降世，十余年勤学苦练之后，他也理所当然地继任了家主之位。世人羡他一世顺风顺水，却无人知晓，十年前与沈念相遇后，他的内心，便注定埋下了一桩遗憾。",
	["tid#Herolife_308"]="没人知道小海沙滔滔为何被独自留在沿海沙滩的深处。当时她还是个襁褓中的婴儿，独自坐在覆满珊瑚的礁石上，身上盖着褴褛的破布，哭喊声回荡在海面上，毫无疑问，这声哭喊引来了她的养父，一个老渔民。老渔民中年丧子，妻子在孩子去世后郁郁寡欢，不久也离开了人世，突然发现一个小姑娘出现在自己人生最灰暗的时刻，就果断的收养了她，将自己全部的爱和见识都给了滔滔。",
	["tid#Herolife_309"]="周湘君的父亲是开武馆的，于是他近水楼台可以每日习武，只不过武馆内的师父大多练习强硬的体术，父亲也是这种体术的集大成者，周湘君家族世代习武，均是大师，到了周湘君这一代，已经是第八世。",
	["tid#Herolife_310"]="筱九生在一个很古老的家族，这个家族一直相信万物有灵，敬畏且热爱着世间的一切生命。几百年前，家族为了躲避江湖中的一场祸事，举族搬迁到了云梦山的深处，从此与世隔绝。筱九的父亲是家族的族长，按照惯例，筱九一出生便注定了圣女的身份。",
	["tid#Herolife_311"]="父亲是国家皇室重用的谋士，以精于算计著称，功在朝廷，在家中排行老二，大哥是朝廷中的大学士，他的额娘更是皇室宠妃的表妹。所以他家可以说得上是家世显赫，只是李清秋出生后幼年时期反而傻呵呵的，没有很多父亲和哥哥的聪明影子。",
	["tid#Herolife_312"]="史春莲的父亲是山庄中狩猎队的队长，偶尔也会带着小万兽一起去，耳濡目染之下，史春莲也逐渐喜欢上了打猎。在一次打猎的过程中，狩猎队在一棵大树旁遇到了一匹被鬣狗围攻的母狼，但奇怪的是，无论鬣狗怎么攻击母狼，母狼都没有从树边离开半步。待狩猎队赶走鬣狗后才发现原因——在那个树的树洞里，有一只刚断奶的小狼。史春莲被眼前的情形震惊了，那一天她明白了，原来野兽也是有灵性的。",
	["tid#Herolife_383"]="姑苏慕容清月，听声辨位、诛心于无形，江湖之中无人不晓。在生命的前十八年，他都在山谷之中，整日与琴声为伴。除了师父，再没见过他人。但有一天，他还是踏进了波澜诡谲的江湖。因为师父给了他一把绿绮琴，在那上面，有他父母的秘密……",
	["tid#Herolife_386"]="段徵言出生于一个开饭馆的家庭，父亲经营茶馆生意貌比潘安，母亲是镇上知名的秀女，可谓神仙眷侣，羡煞人也。故段徵言从小生活环境算得上优渥轻松，又因段徵言从小长相文气清秀，父亲请了最好的老师教他做人习武做学问。",
	["tid#Herolife_387"]="以一大块“天外异石”为核心，穷尽“父亲”11年时间打造的，拥有最强演算能力的自走型机关人。初时没有自我，在外敌来袭中被紧急启动，虽然按照基本程式消灭了所有外敌，但是“父亲”也受到了致命伤。",
	["tid#Herolife_391"]="暂缺",
	["tid#Herolife_392"]="暂缺",
	["tid#Herolife_393"]="暂缺",
	["tid#Herolife_394"]="暂缺",
	["tid#Herolife_395"]="暂缺",
	["tid#Herolife_401"]="凡人永生是不知道多少凡人梦寐以求的事情，可普通人不过是血肉之躯，终究会腐朽破败，可江湖中却有一人，似乎突破了凡人的限制。",
	["tid#Herolife_402"]="自幼时起，阿岚就是五圣教一等一的用药高手。她炼的蛊，纵是功力深她十余载的师兄师姐也自叹不如。她隐居于深山之中，很少有人见过她的真面目。江湖人说，当皎月悬于圣山之上时，寻着蓝色蝴蝶的去向，或许，能寻觅到她的踪迹。",
	["tid#Herolife_403"]="江湖上很多人都听过金刚祥颖韬的大名，传闻此人年纪轻轻就从父亲手下接管了山寨，凭着自己的本事让寨子逐渐壮大。不过他后来遇到了此生最大的劲敌，寨子破了后便流落在了江湖。",
	["tid#Herolife_404"]="陆尘子历来都是独行江湖的古怪人，他阴沉偏执，让人难以接近，也同样让人捉摸不透。江湖传闻，他喜欢对着自己的目标念自己新作的诗，诗中内容已经传的不大清了，不过江湖上凡是知晓此事的人，大概谁也不想听到他的诗吧。",
	["tid#Herolife_405"]="赵心音小时候，村子中突发了一场瘟疫。没人知道瘟疫的源头在哪，因为这场瘟疫凶猛得让人根本来不及反应。没过多久，村子的人就全被感染了，甚至开始向着周边的村镇蔓延。一周之后，事情出现了转机，一个名叫张景奇的男人来到了村子，说要治愈这场瘟疫。已经失去父母的赵心音莫名的相信眼前这个男人，他在这个男人身上看到了活下去的希望。",
	["tid#Herolife_406"]="唐门最初是一个普通的江湖世家，但只在川蜀一带出没。他们善用暗器，神出鬼没，让当地人惊恐不已。贞观之治，国家太平，百姓安居乐业，当潜行者已经不能满足唐家的日常需要。唐家为了继续生存便开始涉足商业，并从此不断壮大。唐门的名气也开始越传越大。唐明月就是如今门主唐雪枫的小女儿。",
	["tid#Herolife_407"]="相闻江湖的乡野之间，游荡着一个疯道人，总是说着让人摸不着头脑的疯言疯语，操着一身稀奇古怪的武功，很少有人愿意与他多说几句。",
	["tid#Herolife_409"]="是为关中郭巨侠的养女，一手飞雪行无踪，打遍关中无敌手，继承巨侠衣钵，常在黄河间行侠仗义。",
	["tid#Herolife_410"]="她有着不同于中原女子的绝世容貌，和她出身于异域的母亲一样。曾经她对此引以为豪，直到一场江湖动乱中，一群人叫喊着“异类”闯进她的家里，若非明教出手相助，险些家破人亡。那一刻，她明白了“非我族类，其心必异”，也明白了，自己注定不属于中原。几年后，中原少了一个绝色美人，而西域的明教之中，多了一个来自中原的“圣女”。",
	["tid#Herolife_411"]="没人知道小海沙滔滔为何被独自留在沿海沙滩的深处。当时她还是个襁褓中的婴儿，独自坐在覆满珊瑚的礁石上，身上盖着褴褛的破布，哭喊声回荡在海面上，毫无疑问，这声哭喊引来了她的养父，一个老渔民。老渔民中年丧子，妻子在孩子去世后郁郁寡欢，不久也离开了人世，突然发现一个小姑娘出现在自己人生最灰暗的时刻，就果断的收养了她，将自己全部的爱和见识都给了滔滔。",
	["tid#Herolife_412"]="左寒修经历过常人难以忍受的童年，但是经受住考验的他在成长到一个无人能及的境地之后，他变得孤傲，阴狠，狡诈，为了达到目的无所不用其极，他已经变得不可一世，也许他孤独的生命从童年的悲惨经历起，就从未结束。",
	["tid#Herolife_413"]="神水宫并非是一个江湖人尽皆知的门派，不过但凡对神水宫有所耳闻的人，都知晓神水宫宫主的可怕之处。传言中，她法相庄严，只是靠近便令人屏息股栗，神魂飞跃，宫主光华照人，让人不敢仰视。",
	["tid#Herolife_481"]="天下之大，有医术高超之人，便有反其道而行之人，星宿派的张超绝对是让江湖人闻之色变的可怕角色，他曾与药王张景奇齐名并立，却在某一天突然从江湖间消失，而当他在此回归江湖之时，便使得整个江湖都蒙上了一层迷乱的颜色。",
	["tid#Herolife_484"]="宋英男长成少女的时候，认识了一个海边少年，后来两个人相恋，宋英男还发现年轻的自己似乎有了身孕，只是村子里的人太过保守，她失去了自己的孩子，还被村子驱逐。宋英男失去孩子后，她缓缓走入海洋，想要自溺身亡，可是似乎海洋选择给她另一种人生，她获得了海洋的力量，成为了周边渔村闻风丧胆的神秘海上女侠，她强大又独立，劫富济贫，并且捡起海底那些渔民遗落的物件归还他们。",
	["tid#Herolife_485"]="摩波旬与师弟结伴去往蓬莱，指望自己能够出息一点，以后能够多学一些多做一些，能够成为师父另一个依靠。结果只有师弟获得点悟，此时内心已经十分崩溃，只是师弟不懂，只以为他是失落。不料回来后，师父被害，将血脉分为两份传给他俩。",
	["tid#Herolife_491"]="暂缺",
	["tid#Herolife_492"]="暂缺",
	["tid#Herolife_493"]="暂缺",
	["tid#Herolife_494"]="暂缺",
	["tid#Herolife_495"]="暂缺",
	["tid#Herolife_501"]="李知傲是如今武当掌门，也是武林中无人不知的一个奇特怪才，一身高深的内家拳总是让对手难以捉摸，一身至阳罡气，可以击透任何护具。他总是会将道德挂在嘴边，与其打败敌人，他更希望以德服人。",
	["tid#Herolife_502"]="昆仑山常年白雪皑皑，中秋之夜，连绵的雪山深处升起皎白的月亮，山中昆仑派一名产妇正经历痛苦的分娩。今夜是罕见的月偏食，半个月亮洁白明亮，另外半个却好似隐在云中。随着两声婴儿啼哭，昆仑派诞生了有建立以来第一对双子姐弟。",
	["tid#Herolife_503"]="他的诞生，是似乎从云隐岛拥有四季，就开始了，他最知道这座岛需要怎么样长短的四季和昼夜，他沉睡在岛屿的风息和溪流中，感受这时间，引领着日月的变迁。 ",
	["tid#Herolife_504"]="相传有人仅靠渡人真气则可生死人，肉白骨，那人便是慈航教的霍紫凝。虽说传文之中多有夸张的杜撰，不过霍紫凝确实有神奇的功法可以疗非常人可疗之伤，慈航教的山门前也是总是有无数的江湖人前来求助。",
	["tid#Herolife_505"]="都说逍遥派的萧春风是位降临人间的绰约仙子，她人如其名总是带着一身盎然的春意，让所有见过的她的人都很难产生什么恶念。然而她似乎总是在赶路，也从来不会在同一个地方多呆上几日，似乎一直都在寻找什么。",
	["tid#Herolife_506"]="周文浩的家门在祖上时曾是风光无两的武林大家，其势力最为鼎盛之时大有一统武林之势。谁能料想在一个雨夜，天龙门中的重要人士竟被一位神秘的蒙面隐者几乎全数击垮，因此周文浩的父亲从小就对他严加管教，督促其习练武学，希望重焕家族荣光。",
	["tid#Herolife_507"]="蜀山派一直都是江湖中最为神秘得门派，很多人都认为那不过是一个寻仙问道的地方。实际上不过蜀山掌门避世修行，不愿沾惹世间江湖纷扰罢了。不过仍有习武者穿过蜀山重重的浓雾，一睹过蜀山派惊人的武学技艺。",
	["tid#Herolife_508"]="凌烟阁二十四功臣莒国公唐俭后人、唐家小公子，不仅靠着一身家传“霸王枪”的武艺闻名于天下，诗作画作亦能堪称世间双绝，其为人做派风流潇洒，常为江湖人所称道。",
	["tid#Herolife_591"]="暂缺",
	["tid#Herolife_592"]="暂缺",
	["tid#Herolife_593"]="暂缺",
	["tid#Herolife_594"]="暂缺",
	["tid#Herolife_595"]="暂缺",
	["tid#Herolife_607"]="金山派一直是江湖中为人称道的世家门派，传奇的掌门人求伯君，乃是江湖中一个传奇人物，他务实温良，刻苦修炼，自创独门绝学，一度被武林人敬仰。",
	["tid#Herolife_606"]="若说江湖中能有一人与清觉齐名，那便是藏传大师鸠摩罗。传闻鸠摩罗为龙树菩萨转世，自幼能接受圣人之灵的指示，深谙真谛。自从他来到中原，藏传法学便在人们的视野中，占据了举足轻重的位置。",
	["tid#Herolife_602"]="邪极坊是一个生人莫近的恐怖地方——那里日夜传来吱呀的机关振动的声音，仿佛有无数的傀儡在不停歇的制造着什么。而它们的主人，吕珂，永远都是一个谜一般的可怖人物，总是牵动着肉眼难辨的丝线，操纵着自己的造物。",
	["tid#Herolife_603"]="江湖传闻中的冰山剑客，相传她的脸上从未有过一丝涟漪，似乎是个没有感情的人。但江湖人知道的是，绝对不要去轻易招惹这个冷若冰霜的美人，因为对于她来说，取人性命似乎就与在路边折一朵花一样自然。",
	["tid#Herolife_604"]="在遥远的雪山，一向有着关于灵鹫宫的传闻。相传他们自冰雪中而生，与雪山心意相通，能以心念驾驭冰雪，更能将世间万物凝为寒冰。从未有人见过他们的真容，就在众人以为一切只是传说的时候，新一任宫主刘异，已暗中酝酿了一场动荡江湖的波澜。",
	["tid#Herolife_605"]="天下会如今唯一的家主——周今鸣，狠辣绝决，江湖上人人谈之色变。虽然她从来不多言语，可就是一个眼神，便总能让人如坠冰窟，两股战战。如今天下会的势力也在她的操纵下越加繁盛，江湖也由于她的缘故逐渐变得冷酷起来。",
	["tid#Herolife_691"]="暂缺",
	["tid#Herolife_692"]="暂缺",
	["tid#Herolife_693"]="暂缺",
	["tid#Herolife_694"]="暂缺",
	["tid#Herolife_695"]="暂缺",
	["tid#Herolife_701"]="原名韩云溪，太子长琴半身。幼时经历灭族之灾，本来已死去，但因体内被封进了太子长琴一半魂魄而得以死而复生。身怀凶剑焚寂的煞气，在某次煞气发作中被紫胤真人所救，后拜入昆仑山天墉城，以“屠绝鬼气，苏醒人魂”之意更名为“百里屠苏”。十年后，他为寻找灭族仇人而离开天墉城，踏上了漫漫征途。",
	["tid#Herolife_702"]="来自幽暗无边的地界，心却明媚如旭日暖阳。奉命寻兄而来到人间，邂逅百里屠苏，陷入了焚寂的宿命纠葛。后与百里屠苏相知相爱。然而，百里屠苏化为永世无法轮回的荒魂，她为寻找重生之法，放弃自己的轮回，换取下长久的寿命，在人间执着不悔地寻觅了九百年。最后，与重生后的屠苏回到桃花谷相守 。",
