	["tid#Heronature_101"]="一如既往的耿直， 追求秩序和正义，聪慧，",
	["tid#Heronature_102"]="神经质，疯癫，偏执，有自我正义感",
	["tid#Heronature_103"]="坚决果断、老练机智 带着强烈的正义感，对法律绝对忠诚",
	["tid#Heronature_104"]="粗鲁，莽撞，没有理性，拥有绝对的执行力，别管你咋解释先把你铐起来再说！！",
	["tid#Heronature_105"]="专注 坚毅 ",
	["tid#Heronature_106"]="表面是一个无情无义，对组织绝对忠诚的战斗工具，但其实对自己的弟弟一直心有愧疚，渴望救赎",
	["tid#Heronature_107"]="放纵恣意、直爽豪放、明朗透彻、心胸广阔博大兼有点厚脸皮，优点：深情",
	["tid#Heronature_108"]="满腹经纶的商人",
	["tid#Heronature_109"]="并不是非常稳重，但是是那种一夜之间成长起来的那种，突然有了担当的那种成熟，被动催熟",
	["tid#Heronature_110"]="暂缺",
	["tid#Heronature_111"]="暂缺",
	["tid#Heronature_114"]="暂缺",
	["tid#Heronature_115"]="率真，爱恨分明，新觉敏锐，做事沉着思想优越，但过于压抑不善表达，有些孤独感。",
	["tid#Heronature_181"]="勇敢无畏，为了国家可以无限冲锋陷阵",
	["tid#Heronature_182"]="有着美丽的容貌设定，本人并不觉得自己很好看，反而觉得自己很丑陋因此才会被他人远离，讨厌在镜子里看到自己的相貌。",
	["tid#Heronature_183"]="沉默，说话单句觉不超过十个字。",
	["tid#Heronature_184"]="率真，爱恨分明，新觉敏锐，做事沉着思想优越，但过于压抑不善表达，有些孤独感。",
	["tid#Heronature_191"]="暂缺",
	["tid#Heronature_192"]="暂缺",
	["tid#Heronature_193"]="暂缺",
	["tid#Heronature_194"]="暂缺",
	["tid#Heronature_195"]="暂缺",
	["tid#Heronature_201"]="非常容易冲动，非常容易上头，但是下头也很快，做过一次的错事就会从中吸取经验教训",
	["tid#Heronature_202"]="冷静沉稳行只若浮云不惊落木，自认为是武林第一，在自我实力这一块自大又狂妄的老头。",
	["tid#Heronature_203"]="心胸宽阔，潇洒。",
	["tid#Heronature_205"]="心有猛虎，细嗅蔷薇，敢爱敢恨，充满正义感，对自己的武功很有自信",
	["tid#Heronature_206"]="因聪明伶俐却又玉一般纯洁剔透，锄强扶弱，信守承诺",
	["tid#Heronature_207"]="看似放荡不羁，随性逍遥，实则善恶分明，乐于助人。是那种嘴上说着“真麻烦”但还是会去帮忙的人。",
	["tid#Heronature_208"]="温柔善良，慈悲心肠，向菩萨一样喜欢帮助别人。善于倾听别人的烦恼并排忧解惑。",
	["tid#Heronature_210"]="暂缺",
	["tid#Heronature_211"]="充满智慧的老顽童。活得很久，见得很多。时而像个孩子一样，风趣幽默又喜欢开玩笑，时而又像个诸事通透的世外高人，对一切事情都很淡然，会说出一些蕴藏深意的话。",
	["tid#Heronature_212"]="其实是一个挺爷们的人，出于证明自己并不娘，也干过不少行侠仗义打抱不平的事情，但是他洁癖，所以还是显得很娘比如打架都会离得很远，是为了不让血，溅到自己身上，每天回家在家门口会擦鞋底子那种。",
	["tid#Heronature_213"]="性格外露，性格开朗，热情柔和，欢快活泼",
	["tid#Heronature_281"]="追求利益的土匪山贼，迷恋皮相的痴情小女儿，非常好色。一个最接地气，贪财好色却又有江湖豪气的泼辣女子",
	["tid#Heronature_282"]="天真浪漫的乡下小子，因为饭量太大又没有那么多地可种，为了减小家里的负担外出闯荡。是个虽然心眼少，但是习惯性替人考虑的善良的人。被欺负一般也不会反抗，因为自己力气太大可能会出人命。但是真正触动自己底线的时候生气非常可怕，立刻狂战士化。喜欢小动物",
	["tid#Heronature_283"]="暂缺",
	["tid#Heronature_291"]="暂缺",
