	["tid#Heronature_295"]="暂缺",
	["tid#Heronature_301"]="严谨、正派，以济世救人为己任。讲究有救无类，只要能够救人性命，即便对方是为祸一方的恶霸也照救不误；",
	["tid#Heronature_302"]="看似八面玲珑，对所有人一视同仁、不歧视身材矮小之人、与动物们都相处甚好、极少生气。",
	["tid#Heronature_304"]="顽皮可爱，有一种小女子的机灵。既有南方女儿的心思灵动，狡黠慧捷，又兼北国女子的率直坦然，虽是隐者，却心地善良",
	["tid#Heronature_305"]="暂缺",
	["tid#Heronature_306"]="暂缺",
	["tid#Heronature_307"]="性格沉稳 上进，有领导能力",
	["tid#Heronature_308"]="大多数时候是自信傲慢的态度，无药可救的自我中心性格，实际上志向坚定，重义理人情，充满母性温柔的女孩",
	["tid#Heronature_309"]="他以毕生精力钻研武学，醉心拳道，讷于言而敏于行，成就威名后仍淡泊依旧，不为浮华虚荣所累",
	["tid#Heronature_310"]="暂缺",
	["tid#Heronature_311"]="踏实，内敛，",
	["tid#Heronature_312"]="很要强、很有责任心，一副很强势的大姐姐形象，但其实很善良，很喜欢照顾人；",
	["tid#Heronature_383"]="表面一副游戏人间，对什么都无所谓的态度，其实内心善良质朴，对自己所追寻的事物有着异乎寻常的执著。",
	["tid#Heronature_386"]="才雄气逸，雅姿舒朗，任逸不羁，儒雅慷慨，方正自重",
	["tid#Heronature_387"]="暂缺",
	["tid#Heronature_391"]="暂缺",
	["tid#Heronature_392"]="暂缺",
	["tid#Heronature_393"]="暂缺",
	["tid#Heronature_394"]="暂缺",
	["tid#Heronature_395"]="暂缺",
	["tid#Heronature_401"]="就是常见的大反派性格，偏执而狂妄，跟普通读书人不一样的是，他觉得自己拥有学识，拥有权力，拥有幸福的家庭，就理应拥有永生。",
	["tid#Heronature_402"]="一分为二的月亮，有着光明的一面和阴暗的一面。她端详着月亮下的手：皎洁的白月亮下，是玉琢的手；昏暗的红月亮下，是被染红的手。",
	["tid#Heronature_403"]="暴躁、冲动、易怒、嗜赌如命",
	["tid#Heronature_404"]="暂缺",
	["tid#Heronature_405"]="暂缺",
	["tid#Heronature_406"]="个性特立独行，自我封闭，高傲，不善言辞，傲娇",
	["tid#Heronature_407"]="暂缺",
	["tid#Heronature_409"]="暂缺",
	["tid#Heronature_410"]="有仇必报，其他不详。",
	["tid#Heronature_411"]="大多数时候是自信傲慢的态度，无药可救的自我中心性格，实际上志向坚定，重义理人情，充满母性温柔的女孩",
	["tid#Heronature_412"]="为了达到目的不择手段的有信念的人。",
	["tid#Heronature_481"]="亦正亦邪，扭曲的正义。认为如今的世界得了病，偏离本道的人就是病因，打败这些人，就能治好这个世界。",
	["tid#Heronature_484"]="以前还挺俏皮可爱的，失去孩子之后巨鲸变得越来越独立，越来越强大，变得果断，独立而坚强，当然作为女性，这些体现出来都是酷。",
