	["tid#itemDes5266"]="使用后可获得：核心自选卡*1、元宝*1888、招募令*10，公测用相同应用商店下载游戏，且用相同账号登录可通过邮件继承本礼包。",
	["tid#itemDes5267"]="开启后可获得：顶级群攻侠客自选卡（紫+）、内测专属公测福利。",
	["tid#itemDes5269"]="招募和全民铸剑活动掉落，可用于明星好礼兑换奖励。",
	["tid#itemDes5270"]="招募和全民铸剑活动掉落，可用于明星好礼兑换奖励。",
	["tid#itemDes5271"]="开启后可以获得以下奖励。",
	["tid#itemDes90001"]="少侠每天可领取一次十连抽，持续10天。",
	["tid#itemDes90002"]="新手少侠提升等级即可以领取豪华大奖",
	["tid#itemDes99001"]="赠予阿闲可以提升10点好感度。",
	["tid#itemDes99002"]="赠予阿闲可以提升198点好感度。",
	["tid#itemDes99003"]="赠予阿闲可以提升328点好感度。",
	["tid#itemDes99004"]="赠予阿闲可以提升648点好感度。",
	["tid#itemDes99005"]="赠予阿闲可以提升648点好感度。",
	["tid#itemDes300001"]="琴师泛舟松江、遇渔夫醉歌所作，曲调闲逸，有笑傲烟云之意。",
	["tid#itemDes300002"]="渭城惜别之曲，曲调纯朴、沉郁，对友人的深情皆凝于音韵之中。",
	["tid#itemDes300003"]="献祭之乐，尽述上界仙真生活情状，曲调飘渺，音节闲雅，使人悠然神往。",
	["tid#itemDes300004"]="流传自楚国的古乐曲，旋律清新流畅，重现万物向荣的初春景象。情调高雅，能相和者甚少。",
	["tid#itemDes300005"]="传闻为嵇康于清夜抚琴，神明感其音律所授。曲调意境深远、抑扬顿挫；细心聆听，自有神奇之韵。",
	["tid#itemDes301001"]="琴作连珠式，表面涂黑漆，玉徽、玉轸、玉足均细刻篆字。琴身有草书云“春雷”。",
	["tid#itemDes301002"]="琴作凤势式，黑漆，纯鹿角灰胎，紫檀岳尾。奏之乐音清脆，悦耳动听。",
	["tid#itemDes301003"]="琴作连珠式，为杉木所斫，紫檀岳尾，白玉轸润若凝脂，雅致清丽。有琴铭曰：“高山玉留，空谷金声”。",
	["tid#itemDes301004"]="琴作神农式，取上等桐木，为名匠所斫。色黄质松，庄严贵重。龙池具隶书铭文：“巨壑迎秋，寒江印月。”",
	["tid#itemDes301005"]="琴作伏羲式，梧桐作面，杉木为底。世间珍品，琴音如鸣于九霄，因而得铭文曰：“超迹苍霄，逍遥太极”。",
	["tid#itemDes302001"]="手卷式组画，所绘五头牛或行或立，神态迥异，如活物般栩栩如生。",
	["tid#itemDes302002"]="工笔设色画，以细腻的手法绘女子捣练缝衣之景，颇具生趣。",
	["tid#itemDes302003"]="粗绢本设色画，以工笔重彩绘仕女赏花之景，另有白鹤、辛夷点缀其间。用笔细劲有神，流动多姿。",
	["tid#itemDes302004"]="绢本设色画，以精细的线描再现虢国夫人盛装出行之情形。用线圆润秀劲，设色典雅富丽，雍容之风跃然纸上。",
	["tid#itemDes302005"]="流传自东晋的画作长卷，画面奇幻绚丽，描绘了人神之间真挚纯洁的爱情。富浪漫悲戚之神韵，是为“画绝”。",
	["tid#itemDes303001"]="适合初学书画者所用，内有硬毫、炭墨、麻纸、石砚，简单实用，一应俱全。",
	["tid#itemDes303002"]="常为文人墨客所用，有软毫、漆烟墨、蔡侯纸、圈足砚，精致美观，深受青睐。",
	["tid#itemDes303003"]="专为皇室与太学所用，有玉管宣笔、徽墨、宣纸、辟雍砚，名贵异常，稀世难求。",
	["tid#itemDes303004"]="玉料为管，质地细润，上雕勾云纹。笔锋以鹿毫为心，兔毫为外披，行笔有入木三分之效。",
	["tid#itemDes303005"]="以青釉和白釉制成，圆形，周边环如水帘的蹄形足。为长乐公主常用之砚，颇为珍贵。",
	["tid#itemDes304001"]="王右军与友人往来之信函，笔风平和自然，笔势委婉含蓄，简淡怡然。",
	["tid#itemDes304002"]="行书书帖，由首句“长风”得名。笔意洒脱，有晋人之超然神韵。",
	["tid#itemDes304003"]="奉敕之作，庄重而严肃。字形随势赋形，左右结构作相背之势，气象庄严。全碑匀整疏朗，气韵萧然。",
	["tid#itemDes304004"]="颜真卿所书神道碑。藏锋、驻笔变化多端，运笔方圆兼施、曲直响应，笔法宽绰舒展，已达至臻之境。",
	["tid#itemDes304005"]="王右军于兰亭雅集所作，行笔出神入化、天机错落；点画行云流水，如有神明相助，是为书中极品。",
	["tid#itemDes305001"]="铸造兵器的常见材料，在山中即可开采到。表面呈银白色，化而为粉呈黑色，较为坚固。",
	["tid#itemDes305002"]="韧度与延展性较好的材料，可大量开采。耐腐蚀、耐磨损，颇为实用。",
	["tid#itemDes305003"]="珍贵矿石之一，色浅、明亮。韧度当属上乘，更兼外形精美，可为兵器增色不少。",
	["tid#itemDes305004"]="始于黄金，精纯无杂质，实属稀世珍品。色泽焕然，鲜明耀眼，击之声若龙吟，可铸绝世之兵。",
	["tid#itemDes305005"]="于天石之中提炼而成，属天外来物，世间难求。色玄黑、泛红，铸兵刃削铁如泥、刀剑不入，实为天下罕有。",
	["tid#itemDes306001"]="以苎麻纺织而成的平纹布。色泽清秀，边缩平整。为市井中常见之布料。",
	["tid#itemDes306002"]="洁白轻柔的轻纱，适作舞衣、披帛。轻如无物，极称女子婀娜之姿。",
	["tid#itemDes306003"]="产于蜀地之彩锦，工艺精湛，图案华美。外观瑰丽多彩，花纹精细高雅。",
	["tid#itemDes306004"]="越州纹彩绢帛，薄如蝉翼，柔如流云，似美人之冰肌玉质。摇曳生姿，恍如微风初动。",
	["tid#itemDes306005"]="产于南海之绢帛，传闻为鲛人所织。花清地白、锦空匀齐，美丽动人，似神来之笔。",
	["tid#itemDes307001"]="以珠翠和金银合制而成的簪钗，有流苏相称。",
	["tid#itemDes307002"]="圆环状玉器，通体圆整光洁，上雕勾云纹。玉质温润，云纹错落有致，繁而不乱。",
	["tid#itemDes307003"]="玉制腰饰，温润而泽。以羊脂白玉雕琢而成，垂之如坠，锐而不害，有如君子之德。",
	["tid#itemDes307004"]="素胎陶器，流传自商代，价值不菲。胎质纯净细腻，器表以浅浮雕饰曲折纹。制作精致，素雅美观。",
	["tid#itemDes307005"]="流传自商周的青铜礼器，颇为贵重。铸工精细，森严庄重，用于祭祀，传闻可通天地、感鬼神。",
	["tid#itemDes308001"]="民间常见医书，为张仲景广采众方所作。",
	["tid#itemDes308002"]="食疗方书，集录饮食治疗之方，可用于平素生活之中。",
	["tid#itemDes308003"]="分五十二题记述了百余种疾病的治疗方法。内服外治兼具，辅以敷贴、药浴之法，是为医术名作。",
	["tid#itemDes308004"]="名医孙思邈所撰典籍，记述诊病察色之法。因“救人一命贵如千金”，故而得名。",
	["tid#itemDes308005"]="相传为黄帝所作，因以为名。以阴阳五行之法记述人体之“道”，是为天人相应，可谓医者立身之本。",
	["tid#itemDes309001"]="味甘，性微温；归脾、肺经。用于气虚乏力、自汗，疮口久不愈合。",
	["tid#itemDes309002"]="味甘、辛，性温；归肝、心、脾经。用于血虚萎黄，眩晕心悸；亦可活血通经。",
	["tid#itemDes309003"]="味甘，平；归肺、肾经。补肾益肺，止血化痰。可医久咳虚喘，劳嗽痰血；为平补气血之佳品。",
	["tid#itemDes309004"]="鹿未骨化而带茸毛的幼角，乃名贵药材。性温而不燥，可生精益血、补髓健骨，被视作药中瑰宝。",
	["tid#itemDes309005"]="滋补之药，极为珍贵。性温，味甘、微苦，可大补元气、生津安神，被誉为“百草之王”。",
	["tid#itemDes310001"]="茶余饭后之甜食，红枣入蜜酿制而成，口感细腻，酸甜软糯。",
	["tid#itemDes310002"]="上元节特制美食，小巧玲珑、晶莹光洁。食之香甜可口，亦有“团圆”之美好寓意。",
	["tid#itemDes310003"]="以花露入馅，浸于酒酿汤底，糯米之清爽辅以花酿之芬芳，沁人心脾，醇香诱人。",
	["tid#itemDes310004"]="虢国夫人厨吏所制，香糯美味，食之唇齿留香。兼以消水肿、解热毒之功效，颇受贵族青睐。",
	["tid#itemDes310005"]="鱼肉洁白如玉，齑料色泽金黄，辅以香柔花穗、蜂蜜草，望之颜色夺目，食之鲜美异常，美味奇绝，不负盛名。",
	["tid#itemDes311001"]="刚刚采下的新鲜蔬菜，可直接食用，亦可入菜烹调。",
	["tid#itemDes311002"]="去骨鸡肉，看起来光滑鲜嫩。可用于蒸食、煮食、炖汤，味道鲜美。",
	["tid#itemDes311003"]="上等牛肉，入菜、入汤皆宜。肉质紧致，宜寒冬食用，可暖胃散寒。兼具食用、养生之效，尤为珍贵。",
	["tid#itemDes311004"]="新鲜的节肢动物，身上有壳，腹部有很多环节。头部有长短触角各一对，胸部的脚第一对最大，末端像钳子。生活在水里，种类很多，可食。",
	["tid#itemDes311005"]="名贵的海珍品之一，因稀有而异常珍贵。可明目退翳、清热平肝、滋阴壮阳，素有“软黄金”之称。",
	["tid#itemDes320001"]="打开可以随机获得一个侠客蓝色好感度道具。【各种道具获得概率相同】",
	["tid#itemDes320002"]="打开可以随机获得一个侠客紫色好感度道具。【各种道具获得概率相同】",
	["tid#itemDes320003"]="打开可以随机获得一个侠客橙色好感度道具。【各种道具获得概率相同】",
	["tid#itemDes320004"]="打开可以随机获得一个侠客红色好感度道具。【各种道具获得概率相同】",
	["tid#itemDes320005"]="打开可以随机获得一个侠客白色好感度道具。【各种道具获得概率相同】",
