	["tid#MysticBuffDes_10001"]="每次普攻削弱被击中的敌对目标攻击力1%，最多削弱20%，削弱效果维持到战斗结束（如果3秒之内再受到普攻，效果就会叠加，如多个侠客装备也会同时叠加）",
	["tid#MysticBuffDes_10002"]="如绝技是护盾、恢复等祝福类技能，则额外给被祝福的目标中随机一人提高30%防御力，持续时间5秒。",
	["tid#MysticBuffDes_10003"]="在绝技释放结束后，开始结算，判断绝技击中目标数量，并给自己上一个吸收伤害的盾，每击中一个目标护盾吸收血量提高8%，护盾最多叠加5层，持续时间4秒",
	["tid#MysticBuffDes_20001"]="每次普攻削弱被击中的敌对目标攻击力1%和暴击值2，攻击力最多削弱30%，暴击值最多削弱60，削弱效果持续到战斗结束（如果3秒之内再受到普攻，效果就会叠加，如多个侠客装备也会同时叠加）",
	["tid#MysticBuffDes_20002"]="如绝技是护盾、恢复等祝福类技能，则额外给被祝福目标中的随机一人提高40%防御力同时增加抗暴击值30，持续时间6秒",
	["tid#MysticBuffDes_20003"]="在绝技释放结束后，开始结算，判断绝技命中目标数量，并给自己上一个吸收伤害的盾，每击中一个目标，护盾吸收血量提高10%并且血量恢复10%，护盾最多叠加5层持续时间6秒，血量最多恢复50%",
	["tid#MysticBuffDes_30001"]="每次普攻削弱被击中的敌对目标攻击力2%，暴击值3，攻击力最多削弱40%，暴击值最多削弱90，并且在每次普攻的同时恢复自身2%的血量，削弱时间叠加到战斗结束（如果3秒之再受到普攻效果就叠加，多个侠客装备也会同时叠加）；",
	["tid#MysticBuffDes_30002"]="如绝技是护盾、恢复等祝福类技能，则额外给被祝福目标中的随机两人提高50%防御力，增加抗暴击值40、坚韧值提高100，持续时间8秒",
	["tid#MysticBuffDes_30003"]="绝技在释放结束后，开始结算，判断绝技命中目标的数量，并给自己上一个吸收伤害的盾，每击中一个目标，护盾吸收血量提高15%并且恢复15%血量和5点内力，护盾最多叠加5层持续时间8秒，血量最多恢复75%，内力最多恢复25点",
	["tid#MysticBuffDes_10004"]="绝技攻击敌对目标时判断击中数量，如数量为1，则眩晕1秒",
