	["tid#MysticBuffDes_10006"]="技能攻击敌对目标时判断其身上是否有回血增益效果，如有则驱散其中1个，最多同时驱散2个目标。秘籍效果每10秒生效一次",
	["tid#MysticBuffDes_20004"]="绝技攻击敌对目标时判断击中数量，如数量为1，则眩晕2秒",
	["tid#MysticBuffDes_20005"]="绝技攻击敌对目标时判断其身上是否有裂伤、中毒负面效果，如有则负面效果的伤害立刻触发，如有多个则触发2次伤害，一次绝技最多触发3个敌对目标身上的效果",
	["tid#MysticBuffDes_20006"]="技能攻击敌对目标时判断其身上是否有回血、护盾增益效果，如有则驱散其中2个，最多同时驱散2个目标。秘籍效果每9秒生效一次",
	["tid#MysticBuffDes_30004"]="绝技攻击敌对目标时判断击中数量，如数量为1，并且判断目标血量如低于30%则立刻斩杀，如高于30%则眩晕3秒",
