	["tid#MysticDes_1011"]="江湖中最普通的拳脚秘籍，上至七十岁老人，下至七岁孩童都可以学习。",
	["tid#MysticDes_1022"]="在樱花绽放之时以樱花花瓣做颜料撰写的秘籍，传说练此功在花瓣落地前就能到达任意想去的地方。",
	["tid#MysticDes_1033"]="世外高人在闲暇之余，根据此生对于轻功的理解撰写的养身心经。",
	["tid#MysticDes_1044"]="数百年前项羽鼎盛时期身边的文臣撰写的心得。内含刀法剑法各种单刃兵器使用心得，(主要是刀）",
	["tid#MysticDes_1051"]="江湖中流传较为广泛的武学秘籍，学之可以强身健体，不惧虎豹豺狼。",
	["tid#MysticDes_1062"]="来自前年雪山昆仑的传世秘籍，传说练此功可以踏雪而行不留脚印。",
	["tid#MysticDes_1073"]="魏晋时期某科学天文家在学习武功后写下了此书，习得后可观天象而修真气。",
	["tid#MysticDes_1084"]="狂刀门建立自己门派之后花高价请画师画的秘籍，具体武功跟狂刀关系不大，主要是唬人用的。",
	["tid#MysticDes_1091"]="来自世外凡境【蓬莱】的御风秘籍，传闻上古殷商族后裔传承下来的。",
	["tid#MysticDes_1102"]="不知哪位高人撰写的身法秘籍，已经被埋葬在落枫山谷上百年，得起心法可以冯虚御风。",
	["tid#MysticDes_1113"]="源于明教的传世秘籍，一般人拿着也没啥用，因为西域文字没人能看懂。",
	["tid#MysticDes_1124"]="传说有一个混世魔王，耍的一双好战锤，看似毫无章法，但身边的一些练武人将其记录了下来。",
	["tid#MysticDes_1131"]="世上第九十九名领略凌波微步的人撰写出来的，精粹了前人经验。",
	["tid#MysticDes_1142"]="传说春秋时期有一名练武奇才不走寻常路，专门修炼轻功，撰写的秘籍可以摄人心魄。",
	["tid#MysticDes_1153"]="唐代天策军根据上百场战役总结出的心得，其中蕴藏无尽战意，看完特别想打仗。",
	["tid#MysticDes_1164"]="传说练此剑法，使用出的绝招能够召唤天边落日孤霞般的剑气，由此可见是十分珍贵的秘籍了。",
	["tid#MysticDes_2011"]="普通门派的典藏级秘籍，只要参透其中奥妙，可以轻易跻身江湖一流高手的行列。",
	["tid#MysticDes_2012"]="普通门派的典藏级秘籍，只要参透其中奥妙，可以轻易跻身江湖一流高手的行列。",
	["tid#MysticDes_2023"]="传说这本心法通篇只阐述了四句经诗的道理--“ 春来草自青，事去心常空。若人会此意，万事豁然通。 ”",
	["tid#MysticDes_2024"]="传说这本心法通篇只阐述了四句经诗的道理--“ 春来草自青，事去心常空。若人会此意，万事豁然通。 ”",
	["tid#MysticDes_2031"]="内含“快慢十七路”，“狂风快剑”，“回风落雁”等经典剑法，少侠来一本吧，买不了吃亏买不了上当。",
	["tid#MysticDes_2032"]="内含“快慢十七路”，“狂风快剑”，“回风落雁”等经典剑法，少侠来一本吧，买不了吃亏买不了上当。",
	["tid#MysticDes_2043"]="当年名震江湖的辟邪剑法其实还有一本内功心经，使用此法之人个个动作迅捷诡异，外间无人得知其招法的名目，只知道其招式乃匪夷所思。",
	["tid#MysticDes_2044"]="当年名震江湖的辟邪剑法其实还有一本内功心经，使用此法之人个个动作迅捷诡异，外间无人得知其招法的名目，只知道其招式乃匪夷所思。",
	["tid#MysticDes_2051"]="招招威力无穷，招式简明而劲力精深，精要之处全在运劲发力，凭强猛取胜，每出一掌均有排山倒海之力。",
	["tid#MysticDes_2052"]="招招威力无穷，招式简明而劲力精深，精要之处全在运劲发力，凭强猛取胜，每出一掌均有排山倒海之力。",
	["tid#MysticDes_2063"]="此棍术单、双头并用，多以双头为主，带有条子棍的运行技法和特点，有降龙伏虎之威。其套路风格宽大舒展，步法轻灵，结构严谨。",
	["tid#MysticDes_2064"]="此棍术单、双头并用，多以双头为主，带有条子棍的运行技法和特点，有降龙伏虎之威。其套路风格宽大舒展，步法轻灵，结构严谨。",
	["tid#MysticDes_2071"]="是形意拳法的衍生拳法套路，有青龙白虎朱雀玄武四种形态，变幻莫测，威力无穷。",
	["tid#MysticDes_2072"]="是形意拳法的衍生拳法套路，有青龙白虎朱雀玄武四种形态，变幻莫测，威力无穷。",
	["tid#MysticDes_2083"]="其中蕴含千变万化的九转逍遥诀和万剑不克的九转金身决，得其要领者可轻而易举称霸武林。",
	["tid#MysticDes_2084"]="其中蕴含千变万化的九转逍遥诀和万剑不克的九转金身决，得其要领者可轻而易举称霸武林。",
	["tid#MysticDes_2091"]="对于先天对于武术剑法不是很在行的练武者有很大帮助，可以提高天赋潜能，如果遇到千万要好好珍惜。",
	["tid#MysticDes_2092"]="对于先天对于武术剑法不是很在行的练武者有很大帮助，可以提高天赋潜能，如果遇到千万要好好珍惜。",
	["tid#MysticDes_2103"]="对于先天对于武术剑法不是很在行的练武者有很大帮助，可以提高天赋潜能，如果遇到千万要好好珍惜。",
	["tid#MysticDes_2104"]="对于先天对于武术剑法不是很在行的练武者有很大帮助，可以提高天赋潜能，如果遇到千万要好好珍惜。",
	["tid#MysticDes_3011"]="天下武功出少林，少林的镇派之宝之一，修炼后净化经脉，使修炼的武功达到大成",
	["tid#MysticDes_3012"]="天下武功出少林，少林的镇派之宝之一，修炼后净化经脉，使修炼的武功达到大成",
	["tid#MysticDes_3013"]="天下武功出少林，少林的镇派之宝之一，修炼后净化经脉，使修炼的武功达到大成",
	["tid#MysticDes_3021"]="当大侠觉得武功已经没有什么可以进修的时候，可以找这本书进化一下自己的上限，对于突破瓶颈大有裨益。",
	["tid#MysticDes_3023"]="当大侠觉得武功已经没有什么可以进修的时候，可以找这本书进化一下自己的上限，对于突破瓶颈大有裨益。",
	["tid#MysticDes_3024"]="当大侠觉得武功已经没有什么可以进修的时候，可以找这本书进化一下自己的上限，对于突破瓶颈大有裨益。",
	["tid#MysticDes_3031"]="少林珍藏的秘籍，曾有好事者闹着让少林将其拿出来分享给世人，到后来无数次武林大会都不曾见过其真面目。",
	["tid#MysticDes_3032"]="少林珍藏的秘籍，曾有好事者闹着让少林将其拿出来分享给世人，到后来无数次武林大会都不曾见过其真面目。",
	["tid#MysticDes_3034"]="少林珍藏的秘籍，曾有好事者闹着让少林将其拿出来分享给世人，到后来无数次武林大会都不曾见过其真面目。",
	["tid#MysticDes_3042"]="这本秘籍可了不得，珍稀的程度是，只要拿到这本秘籍就能感觉到武功平步青云身体身轻如燕的地步。",
	["tid#MysticDes_3043"]="这本秘籍可了不得，珍稀的程度是，只要拿到这本秘籍就能感觉到武功平步青云身体身轻如燕的地步。",
	["tid#MysticDes_3044"]="这本秘籍可了不得，珍稀的程度是，只要拿到这本秘籍就能感觉到武功平步青云身体身轻如燕的地步。",
	["tid#MysticDes_3051"]="是江湖中各大高手会为了这本秘籍展开腥风血雨的争斗的级别了，具体里面写的内容，暂时还无从得知。",
	["tid#MysticDes_3052"]="是江湖中各大高手会为了这本秘籍展开腥风血雨的争斗的级别了，具体里面写的内容，暂时还无从得知。",
	["tid#MysticDes_3053"]="是江湖中各大高手会为了这本秘籍展开腥风血雨的争斗的级别了，具体里面写的内容，暂时还无从得知。",
	["tid#MysticDes_3061"]="少林绝技之一，较为常见的少林外功功法，棍式威猛，气势刚强。",
	["tid#MysticDes_3072"]="隶属九阴真经的外功功法，使用时五指发劲，无坚不破，摧敌首脑，如穿腐土。",
	["tid#MysticDes_3083"]="能够逆转真气，将至刚转为至柔，化水成冰变成强大暗器的阴玄功法。",
	["tid#MysticDes_3094"]="相传为某一高手将自身三门绝学合而为一的高超武学，以致三元流转生生不息。",
	["tid#MysticDes_3101"]="为少林七十二绝技之一，所谓“佛祖拈花，迦叶一笑”，讲究内外兼修，可伤人于无形。",
	["tid#MysticDes_4011"]="少林至强的内功绝学，凡研习之人，如同易筋洗髓，武功大成，是江湖中人人梦寐已久的武学宝典。",
	["tid#MysticDes_4012"]="少林至强的内功绝学，凡研习之人，如同易筋洗髓，武功大成，是江湖中人人梦寐已久的武学宝典。",
	["tid#MysticDes_4013"]="少林至强的内功绝学，凡研习之人，如同易筋洗髓，武功大成，是江湖中人人梦寐已久的武学宝典。",
	["tid#MysticDes_4014"]="少林至强的内功绝学，凡研习之人，如同易筋洗髓，武功大成，是江湖中人人梦寐已久的武学宝典。",
	["tid#MysticDes_4021"]="从道藏经文衍生出的惊世绝学，至柔方达至强，无坚不摧，无坚不破，是武林至高的内功绝学之一。",
	["tid#MysticDes_4022"]="从道藏经文衍生出的惊世绝学，至柔方达至强，无坚不摧，无坚不破，是武林至高的内功绝学之一。",
	["tid#MysticDes_4023"]="从道藏经文衍生出的惊世绝学，至柔方达至强，无坚不摧，无坚不破，是武林至高的内功绝学之一。",
	["tid#MysticDes_4024"]="从道藏经文衍生出的惊世绝学，至柔方达至强，无坚不摧，无坚不破，是武林至高的内功绝学之一。",
	["tid#MysticDes_4031"]="无形无相，无迹可寻，是故小无相，相传此门内功变化神奇，只要通晓别人招式，便可模仿别人绝学。",
	["tid#MysticDes_4032"]="无形无相，无迹可寻，是故小无相，相传此门内功变化神奇，只要通晓别人招式，便可模仿别人绝学。",
	["tid#MysticDes_4033"]="无形无相，无迹可寻，是故小无相，相传此门内功变化神奇，只要通晓别人招式，便可模仿别人绝学。",
	["tid#MysticDes_4034"]="无形无相，无迹可寻，是故小无相，相传此门内功变化神奇，只要通晓别人招式，便可模仿别人绝学。",
	["tid#MysticDes_4041"]="至刚至阳的内功绝学，研习者自能生出氤氲紫气，内息不竭无穷无尽，还能成就金刚不坏之躯，融会天下武学。",
	["tid#MysticDes_4042"]="至刚至阳的内功绝学，研习者自能生出氤氲紫气，内息不竭无穷无尽，还能成就金刚不坏之躯，融会天下武学。",
	["tid#MysticDes_4043"]="至刚至阳的内功绝学，研习者自能生出氤氲紫气，内息不竭无穷无尽，还能成就金刚不坏之躯，融会天下武学。",
	["tid#MysticDes_4044"]="至刚至阳的内功绝学，研习者自能生出氤氲紫气，内息不竭无穷无尽，还能成就金刚不坏之躯，融会天下武学。",
	["tid#MysticDes_4051"]="穷发之北有冥海者，天池也，此无上功法可化天下武功为己所用，便如同北冥之大，巨舟鲲鹏无所不容。",
	["tid#MysticDes_4052"]="穷发之北有冥海者，天池也，此无上功法可化天下武功为己所用，便如同北冥之大，巨舟鲲鹏无所不容。",
	["tid#MysticDes_4053"]="穷发之北有冥海者，天池也，此无上功法可化天下武功为己所用，便如同北冥之大，巨舟鲲鹏无所不容。",
	["tid#MysticDes_4054"]="穷发之北有冥海者，天池也，此无上功法可化天下武功为己所用，便如同北冥之大，巨舟鲲鹏无所不容。",
	["tid#MysticDes_4061"]="源自波斯山中老人的神秘功法，本身是一项极其巧妙地法门，能够发挥研习者自身所储的所有潜力。",
	["tid#MysticDes_4062"]="源自波斯山中老人的神秘功法，本身是一项极其巧妙地法门，能够发挥研习者自身所储的所有潜力。",
	["tid#MysticDes_4063"]="源自波斯山中老人的神秘功法，本身是一项极其巧妙地法门，能够发挥研习者自身所储的所有潜力。",
	["tid#MysticDes_4064"]="源自波斯山中老人的神秘功法，本身是一项极其巧妙地法门，能够发挥研习者自身所储的所有潜力。",
	["tid#MysticDes_4071"]="是为一门十分凶险却又十分强大的绝学功法，可吸取对手的内力，却又有内力反噬之害。",
	["tid#MysticDes_4072"]="是为一门十分凶险却又十分强大的绝学功法，可吸取对手的内力，却又有内力反噬之害。",
	["tid#MysticDes_4073"]="是为一门十分凶险却又十分强大的绝学功法，可吸取对手的内力，却又有内力反噬之害。",
	["tid#MysticDes_4074"]="是为一门十分凶险却又十分强大的绝学功法，可吸取对手的内力，却又有内力反噬之害。",
	["tid#MysticDes_4081"]="太初有道，道法自然，众妙之门，玄之又玄，研习者可以开启心智，了解宇宙大观，致使研习者的武功威力无穷。",
	["tid#MysticDes_4082"]="太初有道，道法自然，众妙之门，玄之又玄，研习者可以开启心智，了解宇宙大观，致使研习者的武功威力无穷。",
	["tid#MysticDes_4083"]="太初有道，道法自然，众妙之门，玄之又玄，研习者可以开启心智，了解宇宙大观，致使研习者的武功威力无穷。",
	["tid#MysticDes_4084"]="太初有道，道法自然，众妙之门，玄之又玄，研习者可以开启心智，了解宇宙大观，致使研习者的武功威力无穷。",
	["tid#MysticDes_5011"]="江湖中最普通的拳脚秘籍，上至七十岁老人，下至七岁孩童都可以学习。",
	["tid#MysticDes_5021"]="江湖中流传较为广泛的武学秘籍，学之可以强身健体，不惧虎豹豺狼。",
	["tid#MysticDes_5031"]="来自世外凡境【蓬莱】的御风秘籍，传闻上古殷商族后裔传承下来的。",
	["tid#MysticDes_6011"]="世上第九十九名领略凌波微步的人撰写出来的，精粹了前人经验。",
	["tid#MysticDes_6021"]="在樱花绽放之时以樱花花瓣做颜料撰写的秘籍，传说练此功在花瓣落地前就能到达任意想去的地方。",
	["tid#MysticDes_6031"]="来自前年雪山昆仑的传世秘籍，传说练此功可以踏雪而行不留脚印。",
	["tid#MysticDes_6042"]="不知哪位高人撰写的身法秘籍，已经被埋葬在落枫山谷上百年，得起心法可以冯虚御风。",
	["tid#MysticDes_6052"]="传说春秋时期有一名练武奇才不走寻常路，专门修炼轻功，撰写的秘籍可以摄人心魄。",
	["tid#MysticDes_6062"]="世外高人在闲暇之余，根据此生对于轻功的理解撰写的养身心经。",
	["tid#MysticDes_7011"]="数百年前项羽鼎盛时期身边的文臣撰写的心得。内含刀法剑法各种单刃兵器使用心得，(主要是刀）",
	["tid#MysticDes_7021"]="狂刀门建立自己门派之后花高价请画师画的秘籍，具体武功跟狂刀关系不大，主要是唬人用的。",
	["tid#MysticDes_7031"]="传说练此剑法，使用出的绝招能够召唤天边落日孤霞般的剑气，由此可见是十分珍贵的秘籍了。",
	["tid#MysticDes_7041"]="源于明教的传世秘籍，一般人拿着也没啥用，因为西域文字没人能看懂。",
	["tid#MysticDes_7051"]="唐代天策军根据上百场战役总结出的心得，其中蕴藏无尽战意，看完特别想打仗。",
	["tid#MysticDes_7061"]="魏晋时期某科学天文家在学习武功后写下了此书，习得后可观天象而修真气。",
	["tid#MysticDes_7072"]="普通门派的典藏级秘籍，只要参透其中奥妙，可以轻易跻身江湖一流高手的行列。",
	["tid#MysticDes_7082"]="传说这本心法通篇只阐述了四句经诗的道理--“ 春来草自青，事去心常空。若人会此意，万事豁然通。 ”",
	["tid#MysticDes_7092"]="内含“快慢十七路”，“狂风快剑”，“回风落雁”等经典剑法，少侠来一本吧，买不了吃亏买不了上当。",
	["tid#MysticDes_7102"]="当年名震江湖的辟邪剑法其实还有一本内功心经，使用此法之人个个动作迅捷诡异，外间无人得知其招法的名目，只知道其招式乃匪夷所思。",
	["tid#MysticDes_7112"]="对于先天对于武术剑法不是很在行的练武者有很大帮助，可以提高天赋潜能，如果遇到千万要好好珍惜。",
	["tid#MysticDes_7122"]="招招威力无穷，招式简明而劲力精深，精要之处全在运劲发力，凭强猛取胜，每出一掌均有排山倒海之力。",
	["tid#MysticDes_8011"]="少林绝技之一，较为常见的少林外功功法，棍式威猛，气势刚强。",
	["tid#MysticDes_8021"]="隶属九阴真经的外功功法，使用时五指发劲，无坚不破，摧敌首脑，如穿腐土。",
	["tid#MysticDes_8031"]="能够逆转真气，将至刚转为至柔，化水成冰变成强大暗器的阴玄功法。",
	["tid#MysticDes_8041"]="相传为某一高手将自身三门绝学合而为一的高超武学，以致三元流转生生不息。",
	["tid#MysticDes_8051"]="为少林七十二绝技之一，所谓“佛祖拈花，迦叶一笑”，讲究内外兼修，可伤人于无形。",
	["tid#MysticDes_8061"]="此棍术单、双头并用，多以双头为主，带有条子棍的运行技法和特点，有降龙伏虎之威。其套路风格宽大舒展，步法轻灵，结构严谨。",
	["tid#MysticDes_8072"]="少林寺珍藏的秘籍，曾有好事者闹着让少林寺将其拿出来分享给世人，到后来无数次武林大会都不曾见过其真面目。",
	["tid#MysticDes_8082"]="是形意拳法的衍生拳法套路，有青龙白虎朱雀玄武四种形态，变幻莫测，威力无穷。",
	["tid#MysticDes_8092"]="当大侠觉得武功已经没有什么可以进修的时候，可以找这本书进化一下自己的上限，对于突破瓶颈大有裨益。",
	["tid#MysticDes_8102"]="这本秘籍可了不得，珍稀的程度是，只要拿到这本秘籍就能感觉到武功平步青云身体身轻如燕的地步。",
	["tid#MysticDes_8112"]="天下武功出少林，少林的镇派之宝之一，修炼后净化经脉，使修炼的武功达到大成",
	["tid#MysticDes_8122"]="是江湖中各大高手会为了这本秘籍展开腥风血雨的争斗的级别了，具体里面写的内容，暂时还无从得知。",
	["tid#MysticDes_9011"]="天下至高的内功心法，是鲜有人知的绝顶内功，研习者需心性纯良，心平气和，方能循序渐进，以致大成。",
	["tid#MysticDes_9021"]="神功无极，书载玄奇。",
	["tid#MysticDes_9031"]="太极元初，法门始祖，功法从源，是为根源之法，习此神通可达武功至臻之境。",
	["tid#MysticDes_9041"]="练气吐纳之功，大成者，内息吐纳，周身如金龙盘旋，金光焕然。",
	["tid#MysticDes_9051"]="道家所传八种绝功怪招，所谓招招致命不留余地，习之者凡人不可近。",
	["tid#MysticDes_9061"]="传自上古剑法，招式朴实却威严十足，有此剑法加持，挥舞凡铁亦如神兵。",
	["tid#MysticDes_9072"]="无形无相，无迹可寻，是故小无相，相传此门内功变化神奇，只要通晓别人招式，便可模仿别人绝学。",
	["tid#MysticDes_9082"]="太初有道，道法自然，众妙之门，玄之又玄，研习者可以开启心智，了解宇宙大观，致使研习者的武功威力无穷。",
	["tid#MysticDes_9092"]="从道藏经文衍生出的惊世绝学，至柔方达至强，无坚不摧，无坚不破，是武林至高的内功绝学之一。",
	["tid#MysticDes_9102"]="少林至强的内功绝学，凡研习之人，如同易筋洗髓，武功大成，是江湖中人人梦寐已久的武学宝典。",
	["tid#MysticDes_9112"]="至刚至阳的内功绝学，研习者自能生出氤氲紫气，内息不竭无穷无尽，还能成就金刚不坏之躯，融会天下武学。",
	["tid#MysticDes_9122"]="穷发之北有冥海者，天池也，此无上功法可化天下武功为己所用，便如同北冥之大，巨舟鲲鹏无所不容。",
	["tid#MysticDes_9132"]="是为一门十分凶险却又十分强大的绝学功法，可吸取对手的内力，却又有内力反噬之害。",
	["tid#MysticDes_9301"]="天下武功出少林，少林的镇派之宝之一，修炼后净化经脉，使修炼的武功达到大成",
	["tid#MysticDes_9302"]="是江湖中各大高手会为了这本秘籍展开腥风血雨的争斗的级别了，具体里面写的内容，暂时还无从得知。",
	["tid#MysticDes_9303"]="是为一门十分凶险却又十分强大的绝学功法，可吸取对手的内力，却又有内力反噬之害。",
	["tid#MysticDes_10001"]="催动掌力，摧毁其经脉，是为一门极其阴狠的毒辣功法。",
	["tid#MysticDes_10002"]="本是一门至高武学，招法精妙之处，须得与他人情意相通，并肩御敌放能凸显神功威力。",
	["tid#MysticDes_10003"]="佛言天女散花，花至得道者身则不落，是为有一门得道者的法门，一经催动，梵言护体，长春不坠。",
	["tid#MysticDes_20001"]="是为天师道五雷正法中的核心法门，驱邪除恶，能化解人心的恶念。",
	["tid#MysticDes_20002"]="落英谷之能人，采素问之精华独创一门功法神通，能引渡自身真气救人于水火，令渭南者容光焕发。",
	["tid#MysticDes_20003"]="此门功法可令修炼者之精气神混一儿聚于玄关一窍，是为炼精化气、练气化神、炼神返虚，以致登仙之境。",
	["tid#MysticDes_30001"]="虽是寻常的健体强身之术，但练至高深，加以心法凝练，便可使人枯木逢春，自然生机源源不绝。",
	["tid#MysticDes_30002"]="达摩所传，系少林内功之精华，内养浩然之气，外练神风铁骨，功成之后，可内气行功以意引气，气入丹田后，潜气内转，周流全身。",
	["tid#MysticDes_30003"]="武当派不传秘技，行功者可双手运转阴阳，脚踏五行之位，全身则内蕴千钧之力，无往不利，无坚不摧。",
	["tid#MysticDes_10004"]="大理段氏传世绝学，可运极内力凌空一指封人经脉，令对手无力还击。",
	["tid#MysticDes_10005"]="抽身换影，乘势借力，脱化移形，引进落空，避锋藏锐，闪转走化，以斜击正，以横破正，以巧制拙。",
	["tid#MysticDes_10006"]="此掌法顾名思义，传为昆仑仙宫内门武功，施展之时掌力绵柔，内劲却绵而不散，可消解敌人丹田之气。",
	["tid#MysticDes_20004"]="此功法乃上乘武学精义，天下任何招数武功都能变化融合到这六路折梅手当中。",
	["tid#MysticDes_20005"]="极其阴邪凶狠的武学招式，可先声夺人，觅人破绽，施展绝学可令对手如置身焦热大荒之间。",
	["tid#MysticDes_20006"]="此为《落英集霞录》集大成之心法神功，功法至臻者能化功于无形，令对手散尽元气如末春之落英。",
	["tid#MysticDes_30004"]="一声剑来呼朝宗，万古长夜自此明。",
	["tid#MysticDes_30005"]="如今天罗众首席所习的独门心法，所谓众生种种，皆为果报，受此心法内力所袭者，将现世受报业之苦。",
	["tid#MysticDes_30006"]="清心如水， 清水即心。 微风无起， 波澜不惊。 幽篁独坐， 长啸鸣琴。",
	["tid#MysticDes_604"]="测试功能，暂无",
