	["tid#MysticName_30001"]="八段锦",
	["tid#MysticName_30002"]="达摩气功",
	["tid#MysticName_30003"]="太乙五行神功",
	["tid#MysticName_10004"]="一阳指",
	["tid#MysticName_10005"]="沾衣十八跌",
	["tid#MysticName_10006"]="流仙抚云掌",
	["tid#MysticName_20004"]="天山折梅手",
	["tid#MysticName_20005"]="焦热荒经",
	["tid#MysticName_20006"]="落英神功",
	["tid#MysticName_30004"]="万剑归宗",
	["tid#MysticName_30005"]="阿鼻无间心经",
	["tid#MysticName_30006"]="太上清心诀",
	["tid#MysticName_9301"]="独孤九剑",
	["tid#MysticName_9302"]="六脉神剑",
	["tid#MysticName_9303"]="戮魂诀",
	["tid#poetry_1011"]="虎牢三英莫近前 辕门射戟盖云天",
	["tid#poetry_102"]="火药金虎视眈眈\\n  红夷轻笼夜攻城\\n疯癫不解疯癫意\\n  巧骂苍穹藐霓虹",
	["tid#poetry_103"]="生死已置九霄外\\n  英雄热血慨而慷\\n志存家国千秋业\\n  名垂青史万年长",
	["tid#poetry_1031"]="羽箭离弓云可破 长空万里俱惊弦",
	["tid#poetry_1032"]="傲骨凌寒风瑟瑟 折梅仗剑踏雪来",
	["tid#poetry_104"]="群官诞秀勿相迎\\n  欲转无多细话君\\n九死吹笛八骏列\\n  因窥藏去易消魂",
	["tid#poetry_1041"]="谁言女子不如男 建功策勋十二转",
	["tid#poetry_1042"]="身着淋漓云墨色 侠骨荡尽世间愁",
	["tid#poetry_105"]="古刹紫竹禅钟鸣\\n  降妖伏魔江湖行\\n佛音亦有豪情意\\n  天下武功出少林",
	["tid#poetry_1051"]="妙法应能平兽性 通途大道向西行",
	["tid#poetry_1052"]="妙法端坐素白莲 闻道高山圣雪间",
	["tid#poetry_1053"]="愿为世尊地藏 渡尽人间诸厄",
	["tid#poetry_106"]="八卦随舞意\\n  五音转曲新\\n乾坤既昭泰\\n  烟景含氤氲",
	["tid#poetry_107"]="歌起征思芦管怨\\n  透穿玄甲朔风寒\\n黄泉作酒酬兄弟\\n  战尽狂沙血未干",
	["tid#poetry_108"]="世间复见大威雄\\n  把定乾坤一瞬中\\n或看翡翠兰苕上\\n  未掣鲸鱼碧海中",
	["tid#poetry_1081"]="百尺竿头五两斜 此生何处不为家",
	["tid#poetry_1082"]="耐寒唯有东篱菊 金粟初开晓更清",
	["tid#poetry_109"]="林暗草惊风\\n  将军夜引弓\\n平明寻白羽\\n   没在石棱中",
	["tid#poetry_1091"]="谁将明月作边愁 玉兔毫成是素秋",
	["tid#poetry_110"]="暂缺",
	["tid#poetry_111"]="前后升沈二十年\\n  向来孤冷偶同然\\n用处纵横能杀活\\n  匣藏不肯试龙泉",
	["tid#poetry_114"]="暂缺",
	["tid#poetry_115"]="居延城外猎天骄\\n  白草连天野火烧\\n暮云空碛时驱马\\n  秋日平原好躲雕",
	["tid#poetry_181"]="刀饮霜风乱层云\\n  步踏风雷震河川\\n刀扬北漠引雷霆\\n  狂歌再起醒梦魂",
	["tid#poetry_182"]="自移红药绕阑栽\\n  粉腻香娇逐旋开\\n且与幽人充近侍\\n  莫教风雨苦相催",
	["tid#poetry_183"]="神马潜龙涌圣泉\\n  陆机兄弟驻行车\\n白发营中听早蝉\\n  天目天台倍觉惭",
	["tid#poetry_184"]="居延城外猎天骄\\n  白草连天野火烧\\n暮云空碛时驱马\\n  秋日平原好躲雕",
	["tid#poetry_1151"]="草长莺飞二月天 拂堤杨柳醉春烟",
	["tid#poetry_1152"]="飒沓流云破竹势 虔心一片君子风",
	["tid#poetry_191"]="暂缺",
	["tid#poetry_192"]="暂缺",
	["tid#poetry_193"]="暂缺",
	["tid#poetry_194"]="暂缺",
	["tid#poetry_195"]="暂缺",
	["tid#poetry_201"]="板斧一抡霸气腾\\n  旋风劲舞荡不平\\n忠肝义胆侠客色\\n  疾恶如仇壮士情",
	["tid#poetry_2011"]="自古人心分两面 一念善恶定劫缘",
	["tid#poetry_2012"]="赤子之心诚可鉴 人间正义利斧平",
	["tid#poetry_202"]="岁暮皤然一老夫\\n  十分流辈九分无\\n千金须拚豪家赏\\n  惟将歌句奉欢娱",
	["tid#poetry_2021"]="午夜长门徘徊去 银钱万两镇幽魂",
	["tid#poetry_203"]="以大地为砧板\\n  视众生为鱼肉\\n将穹苍作烘炉\\n  熔万物为白银",
	["tid#poetry_205"]="赵客缦胡缨\\n  吴钩霜雪明\\n银鞍照白马\\n  飒沓如流星",
	["tid#poetry_206"]="一壶浊酒漫疏狂\\n  逍遥不羁江湖闯\\n君山桃花凋又放\\n  归乡扬名事难双",
	["tid#poetry_2061"]="古来一曲菩萨蛮 霓裳仙舞落尘寰",
	["tid#poetry_207"]="英雄欲立异时名\\n  四体难逃五鼎烹\\n何事秦车已虀粉\\n  子房和客总全生",
	["tid#poetry_2071"]="值此晖光同相约 蓬勃春风共华年",
	["tid#poetry_2072"]="十里长亭霜满天 青丝白发度何年",
	["tid#poetry_2073"]="气若兰兮长不改 心若兰兮终不移",
	["tid#poetry_208"]="千花万卉中不妍\\n  千风万波中不颠\\n天峰岭上一轮月\\n  未知归日是何年",
	["tid#poetry_2081"]="对月形单望相互 只羡鸳鸯不羡仙",
	["tid#poetry_2082"]="珠落玉碎寒山远 薄雾朦胧烟雨中",
	["tid#poetry_210"]="洞箫响兮风生流\\n  清夜阑兮管弦遒\\n高咏祝融峰顶月\\n  此段输君第一流",
	["tid#poetry_2101"]="舞乐升平旖旎时 存亡但在一念间",
	["tid#poetry_211"]="盘崖蹙缩似灵龟\\n  鬼谷先生隐遁时\\n不独卷怀经世志\\n  白云流水是心期",
	["tid#poetry_2111"]="盘崖蹙缩似灵龟 鬼谷先生隐遁时",
	["tid#poetry_212"]="昆仑玄境山外山\\n  乾坤阴阳有洞天\\n只问真君何处有\\n  不向江湖寻剑仙",
	["tid#poetry_2121"]="承奉太乙天尊令 诛尽天下邪魔生",
	["tid#poetry_2122"]="人间日暮喧嚣尽 坐忘红尘太虚成",
	["tid#poetry_213"]="烈焰欲火凤凰生\\n  世态炎凉强者存\\n纸醉金迷又何妨\\n  贪一杯豪饮人来寐",
	["tid#poetry_214"]="荧惑冲天斗\\n  赤染玉门天\\n  流云当如是\\n  谁称火中仙",
	["tid#poetry_281"]="北境翻云鼓雷霆\\n  龙门胜韵去悠悠\\n何来意气纵横甚\\n  百事随缘莫莫休",
	["tid#poetry_282"]="运交华盖欲何求\\n  未敢翻身已碰头\\n破帽遮颜过闹市\\n  漏船载酒泛中流",
	["tid#poetry_283"]="大野凉秋皓日晶\\n  胭脂淡染一分轻\\n不识玉门关外路\\n  却逐白蛇上玉京",
	["tid#poetry_291"]="暂缺",
	["tid#poetry_292"]="暂缺",
	["tid#poetry_293"]="暂缺",
	["tid#poetry_294"]="暂缺",
	["tid#poetry_295"]="暂缺",
	["tid#poetry_301"]="救死扶伤闯险关\\n  艰辛历尽意未残\\n矢志从医言不悔\\n  一朝为病更知难",
	["tid#poetry_3011"]="慧眼明察秋毫事 轻挥铁笔洗沉冤",
	["tid#poetry_3012"]="暗夜清池泛黑莲 亦是良药渡人间",
	["tid#poetry_302"]="英雄三载谪东南\\n  二月东风始放还\\n马瘦尚嫌归路窄\\n  愿求屋上一青山",
	["tid#poetry_304"]="西子湖畔西子情\\n  楼外楼中雨霖铃\\n画廊绣舫霓裳舞\\n  小桥流水叶娉婷",
	["tid#poetry_3041"]="昔年牧童手下恩 白堤断桥赠伞情",
	["tid#poetry_3042"]="婉转婀娜樱间舞 花下眉目此传情",
	["tid#poetry_305"]="万叠云涛墨海间\\n  天机地轴共回环\\n从此更投人境外\\n  生涯应在有无间",
	["tid#poetry_3051"]="素练轻裁魂入墨 灵犀一笔尽浮生",
	["tid#poetry_3052"]="盈盈笑语映秋水 粉黛不施自有情",
	["tid#poetry_306"]="炉亭曾忆看桃花\\n  摇落江湖两鬓华\\n回思二十年间事\\n  世故困人如弄沙",
	["tid#poetry_307"]="秀水灵山隐剑踪\\n  不闻江湖铸青锋\\n逍遥此身君子意\\n  一壶温酒向长空",
	["tid#poetry_3071"]="从开一朵朝衣色 免踏尘埃看杂花",
	["tid#poetry_308"]="海旗风急惊眠起\\n  沙上行将白鹭群\\n娇娃铸铁平恶怨\\n  玲珑堪叫霸王凭",
	["tid#poetry_3081"]="盈盈一点珠红绛 凌波荡漾瞬影空",
	["tid#poetry_309"]="太极光阴忘甲子\\n  九霄云气接蓬莱\\n桑田海水今如许\\n  劳得朝猿暮鹤哀",
	["tid#poetry_3091"]="司掌夏官称火正 炎炎缙云渡南风",
	["tid#poetry_310"]="余处幽篁不见天\\n  倏来如月去如烟\\n却是能知春信息\\n  惟伴狸奴附日眠",
	["tid#poetry_3101"]="涿鹿还凭玄女策 青丘赐福降狐灵",
	["tid#poetry_311"]="五色云英生海月\\n  能饮南方赤龙血\\n为君镇日守闲窗\\n  绝胜当年映寒雪",
	["tid#poetry_3111"]="长夜将至云蔽月 清辉一缕破空来",
	["tid#poetry_312"]="角鹰初下秋草稀\\n  铁骢抛鞚去如飞\\n少年猎得平原兔\\n  马上横捎意气归",
	["tid#poetry_3121"]="东吴有女可称奇 枭姬盛名筑蛟矶",
	["tid#poetry_3122"]="万物有灵莫轻慢 神明亦可渡人间",
	["tid#poetry_3123"]="锦绘浮世一色染 拓尽飞鸟过寒川",
	["tid#poetry_313"]="梦醒月辉胧\\n  百花共愁容\\n  谁托深闺冤\\n  遥寄千山重",
	["tid#poetry_383"]="儒门有志羁风雨\\n  失鹿山河散若星\\n千古文人侠客梦\\n  肯将碧血写丹青",
	["tid#poetry_386"]="青衫磊落险峰行\\n  身服朱蛤百不侵\\n叹息佳人多婉转\\n  指尖神剑点苍星",
	["tid#poetry_387"]="一绦一褐肤如铁\\n  神为秋水眼为月\\n与物自然无恩怨\\n  青龙夭矫盘双阙",
	["tid#poetry_391"]="暂缺",
	["tid#poetry_392"]="暂缺",
	["tid#poetry_393"]="暂缺",
	["tid#poetry_394"]="暂缺",
	["tid#poetry_395"]="暂缺",
	["tid#poetry_401"]="阴火息时阳火销\\n  理分卧立顺羲爻\\n欲求不死长生诀\\n  骨里无仙不肯教",
	["tid#poetry_4011"]="道尽世间伤心事 由来看客最深情",
	["tid#poetry_402"]="蛇蝎成伴蛛成邻\\n  千蝶绕笛蛊无形\\n世人皆惧断肠物\\n  不见最毒在人心",
	["tid#poetry_4021"]="江湖红尘多纷扰 天涯何处觅逍遥",
	["tid#poetry_4022"]="圣山寒笛吹雪尽 曲落白骨生玉莲",
	["tid#poetry_403"]="兽中有人性\\n  形异遭人隔\\n人中有兽心\\n  几人能真识",
	["tid#poetry_404"]="雄光宝剑倚崆峒\\n  先斩鲸鲵渤海东\\n从来吊伐宁如此\\n  千里无烟血草红",
	["tid#poetry_405"]="风前橄榄星宿落\\n 月下桄榔羽扇开\\n静默堂中有相忆\\n 清江或遣化人来",
	["tid#poetry_406"]="一箭穿林啸西风\\n  索魂夺命瞬息中\\n鸣风耀目雀展屏\\n  暗引惊弦夺命翎",
	["tid#poetry_4061"]="缱绻蚀骨绕指柔 辗转销魂几分愁",
	["tid#poetry_407"]="千劫情缘万古期\\n  楼中萧史姓名非\\n洞天花落秋云冷\\n  肠断青鸾独自飞",
	["tid#poetry_409"]="河间飞细雪\\n  白羽荡翩鸿\\n  缘起风陵渡\\n  侠气代玲珑",
	["tid#poetry_410"]="光明圣火朝西庭\\n 生死无象寄往生\\n 日月经天焚圣火\\n 朔漠独行已忘年",
	["tid#poetry_4101"]="含烟出窑雨习习 色白花青釉色奇",
	["tid#poetry_4102"]="一袭丹朱天地暗 姮娥失色月无言",
	["tid#poetry_411"]="海旗风急惊眠起\\n  沙上行将白鹭群\\n娇娃铸铁平恶怨\\n  玲珑堪叫霸王凭",
	["tid#poetry_4111"]="盈盈一点珠红绛 凌波荡漾瞬影空",
	["tid#poetry_412"]="坐断东南战未休\\n  侠客一面总无由\\n终来暗洒清明泪\\n  祸起萧墙不尽愁",
	["tid#poetry_4121"]="鸟鸣山幽林静处\\n  正是清心苦修时",
	["tid#poetry_4122"]="自有胸中丘壑在 何妨厚土寄平生",
	["tid#poetry_414"]="飒飒飞龙势\\n  泠泠玉雪颜\\n  谁知花月色\\n  亦度夜霜寒",
	["tid#poetry_481"]="风前橄榄星宿落\\n 月下桄榔羽扇开\\n 静默堂中有相忆\\n 清江或遣化人来",
	["tid#poetry_484"]="鲸鱼跋浪沧溟开\\n  鱼没都由怯岸人\\n神女归山更不来\\n  力寡多方验斯在",
	["tid#poetry_485"]="子规走马入临安\\n  终古芳枝向此时\\n洗剑飞红为外帅\\n  秋风默随荐白衣",
	["tid#poetry_491"]="暂缺",
	["tid#poetry_492"]="暂缺",
	["tid#poetry_493"]="暂缺",
	["tid#poetry_494"]="暂缺",
	["tid#poetry_495"]="暂缺",
	["tid#poetry_501"]="紫霄掬清风\\n  孤鹜厌离声\\n  晚来独一人\\n  谁言慕长生",
	["tid#poetry_5011"]="天上瑶宫自难留 醉与人间饮不休",
	["tid#poetry_5012"]="紫霄掬清风 孤鹜厌离声",
	["tid#poetry_502"]="暂缺",
	["tid#poetry_503"]="云隐归岛四时风\\n  春华拂槛绿意生\\n  海阔沧澜波涛起\\n  东君遥上踏云腾",
	["tid#poetry_504"]="莫愁已去无穷事铁\\n  漫苦如今有限身铁\\n  东风归棹津头过铁\\n  原是慈航得度人",
	["tid#poetry_5041"]="千叶红莲高会处 几曾龙女献珠来",
	["tid#poetry_505"]="庄生齐物同归一\\n 我道同中有不同\\n 腾身洒脱尘埃去\\n 人在逍遥鼓棹中",
	["tid#poetry_5051"]="启明换日度长庚 飞仙揽月过云晴",
	["tid#poetry_5052"]="庄生齐物同归一 我道同中有不同",
	["tid#poetry_506"]="杨王灭候少英雄\\n  犹自澄思却月中\\n已得惠妃欢喜见\\n  方头笑杀曲江公",
	["tid#poetry_507"]="飞鸿踏雪泥\\n 白马步浊溪\\n 闻道青山上\\n 寻仙遇灵犀",
	["tid#poetry_508"]="吾有千杯饮\\n 风流醉花荫\\n 桃花东送水\\n 登高略沉吟",
	["tid#poetry_5061"]="斯须九重真龙出 一洗万古凡马空",
	["tid#poetry_591"]="暂缺",
	["tid#poetry_592"]="暂缺",
	["tid#poetry_593"]="暂缺",
	["tid#poetry_594"]="暂缺",
	["tid#poetry_595"]="暂缺",
	["tid#poetry_601"]="暂缺",
	["tid#poetry_602"]="且复一日葺\\n  随时具生涯\\n  虚明豁心府\\n  永使思无邪",
	["tid#poetry_6021"]="帷幄三分天下绝 辅弼人君岁已躬",
	["tid#poetry_603"]="明月出天山\\n  苍茫云海间\\n  长风几万里\\n  吹度玉门关",
	["tid#poetry_604"]="寒夜折梅静\\n  斜风落雪停\\n  薄衾难御冷\\n  白雪著无情",
	["tid#poetry_605"]="宇宙千年更帝霸\\n  春秋万世正乾坤\\n  阴阳定位纲常立\\n  于此推寻见本原",
	["tid#poetry_6051"]="谛听天命立威名 覆手翻云负天青",
	["tid#poetry_606"]="般若人间著袈裟\\n 龙树十万颂明霞\\n 缘是金轮无上法\\n 桑耶智度藏梵花",
	["tid#poetry_6061"]="盛怒手眼通日月 敢叫天人晦神威",
	["tid#poetry_608"]="暂缺残阳孤影昏\\n  天下独一门\\n  折絮风飘落\\n  月下布珏尘",
	["tid#poetry_691"]="暂缺",
	["tid#poetry_692"]="暂缺",
	["tid#poetry_693"]="暂缺",
	["tid#poetry_694"]="暂缺",
	["tid#poetry_695"]="暂缺",
	["tid#poetry_701"]="古剑铁衣映清辉\\n 百劫阎浮一念微\\n 许向长空倾碧血\\n 由他业火寸身摧",
	["tid#poetry_702"]="青丝银栉别样梳\\n 天付婆娑入画图\\n 好向寒节报花信\\n 春风一脉动幽都",
	["tid#RandomLines_1"]="飞鸟归林，\n夜尽长明。",
	["tid#RandomLines_10"]="我们还有\n多久能到？",
	["tid#RandomLines_100"]="你小时，我常给\n你念《千金方》...",
	["tid#RandomLines_1001"]="挂机奖励有累积上限\n要即时领取。",
	["tid#RandomLines_1002"]="4个势力各上1个侠客\n也可以获得强力加成",
	["tid#RandomLines_1003"]="上阵阳系侠客\n可以轻松激活强力阵容加成",
	["tid#RandomLines_1004"]="【侠客归隐】可以无损返还\n所有资源和传功消耗的侠客",
	["tid#RandomLines_1005"]="点击侠客升级边上的【重置】按钮\n可以进行【侠客归隐】和【侠客重塑】",
	["tid#RandomLines_1006"]="侠客只要没达到彩色品质\n都可以进行【侠客归隐】",
	["tid#RandomLines_1007"]="可以使用【侠客归隐】\n重新培养新侠客尝试全新阵容组合",
	["tid#RandomLines_1008"]="【侠客归隐】可以无损找回传功消耗的侠客",
	["tid#RandomLines_1009"]="在传功殿中进阶\n即可提升等级上限",
	["tid#RandomLines_101"]="昼夜寒暑，饥渴\n疲劳，一心赴救。",
	["tid#RandomLines_1010"]="未培养侠客可以放入练武场的修行栏位\n即可轻松快捷的尝试新阵容组合",
	["tid#RandomLines_1011"]="需要时间解锁的玩法\n可以在完成特定关卡后【提前解锁】",
	["tid#RandomLines_1012"]="只有【大侠】侠客才可以进阶至红品或更高品质",
	["tid#RandomLines_102"]="老东西...嗝，再\n帮我拿些喝的来。",
	["tid#RandomLines_103"]="人生如寄，\n寿无永固。",
	["tid#RandomLines_104"]="两贵不能相事，\n两贱不能相使。",
	["tid#RandomLines_105"]="你梦中之景，我已\n给你师父看过...",
	["tid#RandomLines_106"]="你师徒二人，\n哎，命数啊...",
	["tid#RandomLines_107"]="所爱之人，岂\n能无动于衷...",
	["tid#RandomLines_108"]="这罐子是放早夭婴\n孩尸骨的翁罐...",
	["tid#RandomLines_109"]="如此，小少爷\n还敢要吗？",
	["tid#RandomLines_11"]="来呀，让我看看\n你们的身手如何？",
	["tid#RandomLines_110"]="你的罐子不错，\n要多少金子？",
	["tid#RandomLines_111"]="那岂不是更妙，\n兄台请开价罢！",
	["tid#RandomLines_113"]="硫磺硝石亦可制作\n火药？当真有趣。",
	["tid#RandomLines_114"]="吾爱，我会\n拭目以待。",
	["tid#RandomLines_115"]="登上武林之巅，\n只差这场对决！",
	["tid#RandomLines_116"]="啧，鄙人能与张少\n主做什么生意？",
	["tid#RandomLines_117"]="你当真什么都\n不记得了？",
	["tid#RandomLines_118"]="首次见面，在下华\n山宁不凡，幸会！",
	["tid#RandomLines_119"]="兄台上次那一掌好\n痛！还好我命大！",
	["tid#RandomLines_12"]="与人为恶不\n如与人为善。",
	["tid#RandomLines_120"]="你好呀!半山\n腰的邻居！",
	["tid#RandomLines_121"]="这位少侠的佩剑\n我竟如此眼熟...",
	["tid#RandomLines_122"]="天下英雄，唯我\n与君，请出招！",
	["tid#RandomLines_123"]="上次那个水晶虾饺\n还有吗？呜呜。",
	["tid#RandomLines_124"]="那个老头好可怕，\n我包子都吓掉了。",
	["tid#RandomLines_125"]="小友琴声中有高轩\n飞雁、朗月垂光。",
	["tid#RandomLines_126"]="还有一丝常人难\n辨的...敌意。",
	["tid#RandomLines_127"]="道子，要不要随\n我去山下撸猫！",
	["tid#RandomLines_128"]="跟着你老黄混，\n连路都顺了！",
	["tid#RandomLines_129"]="败在你手上，我黄\n荣华也算无憾！",
	["tid#RandomLines_13"]="阿弥陀佛，\n善哉善哉。",
	["tid#RandomLines_130"]="还不尽兴！咱哥\n俩再比试一轮！",
	["tid#RandomLines_131"]="一位值得尊敬的\n对手...并不多得",
	["tid#RandomLines_132"]="你要学的是运用\n之法，而非蛮力。",
	["tid#RandomLines_133"]="学功夫?我现在\n的本事还不够吗？",
	["tid#RandomLines_134"]="我也没能料到她能\n吃三十个包子...",
	["tid#RandomLines_135"]="站住，别跑！\n我的亲妹、妹...",
	["tid#RandomLines_136"]="此案，本官心\n中已有论断！",
	["tid#RandomLines_137"]="刑狱莫重于初情，\n初情莫重于检验。",
	["tid#RandomLines_138"]="李大人，你又在\n用灵感破案吗...",
	["tid#RandomLines_139"]="今天的通缉令，\n又有活要干了。",
	["tid#RandomLines_14"]="众将士，且随我来！",
	["tid#RandomLines_140"]="你抓不到我的，\n我的好、姐、姐。",
	["tid#RandomLines_141"]="新配比十分有效！\n听，多美的爆炸!",
	["tid#RandomLines_142"]="一次只瞄准一个\n敌人的都是傻子！",
	["tid#RandomLines_143"]="司马小妹，我有个\n绝好的新配比！",
	["tid#RandomLines_144"]="炉子里的东西在炸\n你也在研究火药？",
	["tid#RandomLines_145"]="邢公子~我可不\n是什么好人~",
	["tid#RandomLines_146"]="你不是彻头彻尾\n的坏人，如果...",
	["tid#RandomLines_147"]="真想再和那个\n葫芦切磋一把。",
	["tid#RandomLines_148"]="李大侠看着笨，\n但却是个好人。",
	["tid#RandomLines_149"]="我能感觉到，\n你就在我身边...",
	["tid#RandomLines_15"]="小白蛇，你说他们\n是通缉令上的人吗？",
	["tid#RandomLines_150"]="知止而后有定，\n定而后能静。",
	["tid#RandomLines_151"]="李兄可有启发？\n又...又睡着了...",
	["tid#RandomLines_152"]="俺见不得不男不\n女的家伙，起开！",
	["tid#RandomLines_153"]="小官爷还\n记得俺吗？",
	["tid#RandomLines_154"]="不记得没事儿啊，\n黄泉路上想去吧！",
	["tid#RandomLines_155"]="动手前，先动\n你的脑子！",
	["tid#RandomLines_156"]="你是个好孩子，\n从不让我担心。",
	["tid#RandomLines_157"]="解决他，\n利落点。",
	["tid#RandomLines_158"]="张超！你那药\n里放了什么！",
	["tid#RandomLines_159"]="死胖子，去去去，\n又坏我的好事！",
	["tid#RandomLines_16"]="这里清风宜人，不如\n听我演奏一曲如何？",
	["tid#RandomLines_160"]="是你的阴气过重，\n无福消受这药喽。",
	["tid#RandomLines_161"]="我明明看着你喝\n下鸩水，怎么会...！",
	["tid#RandomLines_162"]="莲姐姐，我想\n到外面看看！",
	["tid#RandomLines_163"]="你的机关真可爱\n想摸摸飞雪吗？",
	["tid#RandomLines_164"]="倾听不用耳朵\n用心就可以！",
	["tid#RandomLines_165"]="糖葫芦是什么，\n呃...我当然知道！",
	["tid#RandomLines_166"]="你真是个厉害的小\n姑娘，和我一样！",
	["tid#RandomLines_167"]="才不孤独，还有好\n多难题等我破解！",
	["tid#RandomLines_168"]="机关小人？不是！\n那个是我的伙伴！",
	["tid#RandomLines_169"]="吾生无涯，\n而知也无涯...",
	["tid#RandomLines_17"]="哈哈哈，那\n就打个痛快！",
	["tid#RandomLines_170"]="为什么...\n创造我...",
	["tid#RandomLines_171"]="想倾听万物之声\n就像你那样..",
	["tid#RandomLines_172"]="我动手前可从\n来不放狠话。",
	["tid#RandomLines_173"]="老夫行走了一辈子，\n从来都是独来独往。",
	["tid#RandomLines_174"]="千万别忘了我们\n三个人的约定哦~",
	["tid#RandomLines_175"]="命运？本姑娘一，\n点也不相信呢。",
	["tid#RandomLines_176"]="在命运的预兆中，\n你与凋亡紧密相关。",
	["tid#RandomLines_177"]="如游藻沉浮的命运，\n却似花朵盛放。",
	["tid#RandomLines_178"]="哇，你除了蛇，还\n有蝎子蜈蚣蝴蝶！",
	["tid#RandomLines_179"]="喏，通缉令拿来\n哇，这么多？",
	["tid#RandomLines_18"]="既然这么想送命，那\n老夫就送你们一程！",
	["tid#RandomLines_180"]="好耶，又可以\n买烧麦吃了！",
	["tid#RandomLines_19"]="大口吃肉！\n惩恶打狗！",
	["tid#RandomLines_2"]="我摘了一朵红芍药，\n你要闻闻看吗？",
	["tid#RandomLines_20"]="无知者无畏，你们就\n到九泉之下好好反省吧。",
	["tid#RandomLines_21"]="瞄准——射击！",
	["tid#RandomLines_213"]="呵呵，是生意自己\n循着名声找上您。",
	["tid#RandomLines_22"]="苍鹰是我的眼，\n而你们无处可逃。",
	["tid#RandomLines_23"]="少废话，看拳！",
	["tid#RandomLines_24"]="你们这样的对手\n令我感到无趣。",
	["tid#RandomLines_25"]="长剑无眼，休要怪\n我没有手下留情呀。",
	["tid#RandomLines_26"]="梵音入耳，\n佛光护体。",
	["tid#RandomLines_27"]="玄机所现，\n天命所归。",
	["tid#RandomLines_28"]="名单上的名字，\n又少了几个……",
	["tid#RandomLines_29"]="锦衣卫办事，无关\n人等还不速速退散！",
	["tid#RandomLines_3"]="我来掩护你们，诸\n位只管冲锋便是了。",
	["tid#RandomLines_30"]="对付这些人\n就劳烦诸位了！",
	["tid#RandomLines_31"]="克敌当制先，你们\n已经失去机会了。",
	["tid#RandomLines_32"]="我猜你们一定\n是挑错了对手。",
	["tid#RandomLines_33"]="之前鲜少远离秀坊，\n此处胜景倒也宜人。",
	["tid#RandomLines_34"]="外面的天着实要\n比唐家堡的要高。",
	["tid#RandomLines_35"]="敢挡我去路\n者，纳命来！",
	["tid#RandomLines_36"]="违抗大唐律例\n者，严惩不贷。",
	["tid#RandomLines_37"]="诸君可在我身后，\n我来保护大家！",
	["tid#RandomLines_38"]="让我来炸飞他们吧！",
	["tid#RandomLines_39"]="在你们面前，我\n不过是对牛弹琴。",
	["tid#RandomLines_4"]="切不可让这些纷\n乱扰了我的道心。",
	["tid#RandomLines_40"]="我这里有两把剑，总\n有一把能对付得了你。",
	["tid#RandomLines_41"]="没事多走动走动，对\n延年益寿也是帮助的。",
	["tid#RandomLines_42"]="机甲冲锋！\n呜—呜—呜！",
	["tid#RandomLines_43"]="他化多自在，\n随我入魔来！",
	["tid#RandomLines_44"]="若随我拜火，兴\n许能饶你们一命。",
	["tid#RandomLines_45"]="腌臜之物，不如化\n作滋养世界的肥料。",
	["tid#RandomLines_46"]="跟俺猜命，你\n还不一定会输。",
	["tid#RandomLines_47"]="你闻到了吗，\n是芬芳的气息。",
	["tid#RandomLines_48"]="诸位小友可要\n手下留情呀。",
	["tid#RandomLines_49"]="累死本道爷了，几\n时才能到下个地方？",
	["tid#RandomLines_5"]="不如随我回店\n里喝几杯如何？",
	["tid#RandomLines_50"]="这里非常适合作为\n你们的埋骨之地。",
	["tid#RandomLines_51"]="你们的命本不\n值得老夫出手。",
	["tid#RandomLines_52"]="你们可曾思考过，\n自己存在的价值？",
	["tid#RandomLines_53"]="又有几个帮\n我试药的人。",
	["tid#RandomLines_54"]="飞雪不喜欢你\n们，我也不喜欢。",
	["tid#RandomLines_55"]="闻到火药的味道了\n吗？准备起飞吧！",
	["tid#RandomLines_56"]="除魔！卫道！",
	["tid#RandomLines_57"]="我来此欲普渡世人。",
	["tid#RandomLines_58"]="大师的伤可好些？\n一定要格外注意。",
	["tid#RandomLines_59"]="嗟我怀人，\n置彼周行。",
	["tid#RandomLines_6"]="打完这场架，我\n要吃十个包子！",
	["tid#RandomLines_60"]="有劳挂念，贫僧\n的伤已无大碍。",
	["tid#RandomLines_61"]="不识本心，\n学法无益。",
	["tid#RandomLines_62"]="师兄，此时回头，\n仍为时不晚。",
	["tid#RandomLines_63"]="心存正气，\n清风自来。",
	["tid#RandomLines_64"]="迷者师度，\n悟者自度。",
	["tid#RandomLines_65"]="我不需要你来\n教我怎么做！",
	["tid#RandomLines_66"]="等闲挥袂客天涯，\n我早就没有家了。",
	["tid#RandomLines_67"]="心存正气，\n行必侠义",
	["tid#RandomLines_68"]="曾为流离惯别家…\n贫道什么也没说。",
	["tid#RandomLines_69"]="哦？贵山庄建在\n华山之巅又如何…",
	["tid#RandomLines_7"]="扬刀立威，\n宵小莫走！",
	["tid#RandomLines_70"]="我不会去的，咳，\n我对老虎毛过敏。",
	["tid#RandomLines_71"]="你念叨些什么呢？我的小道长~",
	["tid#RandomLines_72"]="曾为流离惯别家，\n你也在想家吗？",
	["tid#RandomLines_73"]="胡说！，嗝——\n我...我还能喝！",
	["tid#RandomLines_74"]="哈！某人不行了！\n这局本姑娘赢！",
	["tid#RandomLines_75"]="机关百变，最\n诡谲的是贪念。",
	["tid#RandomLines_76"]="毒有千种，最\n难解的是人心。",
	["tid#RandomLines_77"]="这机关小人真精\n巧用的哪种技术？",
	["tid#RandomLines_78"]="…叮叮咚咚…",
	["tid#RandomLines_79"]="燕将军，这关外\n怎么有爆炸声？",
	["tid#RandomLines_8"]="虾蟹爬虫们，海浪\n会将你丢在沙滩上。",
	["tid#RandomLines_80"]="那是为你庆生辰\n的烟花...吓到了？",
	["tid#RandomLines_81"]="此批兵甲粮草，\n来的正是时候。",
	["tid#RandomLines_82"]="燕赵久为中原门\n户神刀理应相助。",
	["tid#RandomLines_83"]="这点辎重算\n不上什么。",
	["tid#RandomLines_84"]="你在跟我说\n话还是跟鹰？",
	["tid#RandomLines_85"]="你常常让我觉得这\n世道还不算太糟。",
	["tid#RandomLines_86"]="箭去有似\n流星落地。",
	["tid#RandomLines_87"]="有时真搞不懂\n你在想什么...",
	["tid#RandomLines_88"]="你的眼睛...\n好像我的鹰",
	["tid#RandomLines_89"]="鹰说它觉得\n你有点...吵...",
	["tid#RandomLines_9"]="不成，不成！\n我要打十个！",
	["tid#RandomLines_90"]="弓开如若\n秋月行天。",
	["tid#RandomLines_91"]="这就是名为自\n由的事物吗？",
	["tid#RandomLines_92"]="以牙还牙，\n加倍奉还。",
	["tid#RandomLines_93"]="采采卷耳，\n不盈顷筐。",
	["tid#RandomLines_94"]="如果我没救过你\n结局会不同吗...",
	["tid#RandomLines_95"]="是你？也好，我\n来送你最后一程。",
	["tid#RandomLines_96"]="高明的手段，\n精绝的舞蹈...",
	["tid#RandomLines_97"]="师父，我从\n未偏离正道。",
	["tid#RandomLines_98"]="我要救的，正\n是苍生黎民。",
	["tid#RandomLines_99"]="你居然还活着，\n呵，真是命大。",
