	["tid#SkillDes_10111"]="天策进入“无双”状态并立刻恢复最大生命值30%的生命值，无双状态下，天策受到的伤害减少50%，攻击力提升50%，且普通攻击变为范围攻击。释放该技能不会消耗内力，但进入无双状态后，内力每秒会减少125点，且攻击和受击都无法恢复内力。当内力值为0时，“无双”状态结束",
	["tid#SkillDes_10112"]="等级2:无双状态下，天策受到的伤害减少60%",
	["tid#SkillDes_10113"]="等级3:无双状态下，天策每秒减少的内力降低至100点，且攻击力提升效果提升至80%",
	["tid#SkillDes_10114"]="等级4:无双状态下，天策每秒减少的内力降低至90点，且攻击力提升效果提升至80%",
	["tid#SkillDes_10121"]="天策挥舞战戟，攻击自身周围的敌人，对其造成120%攻击力的外功伤害，释放技能时,若自身处于无双状态，则“勇战八方”的攻击范围增加",
	["tid#SkillDes_10122"]="等级2:若该技能至少击中了一名敌人，则之后释放的“勇战八方”的冷却时间会大幅度缩短",
	["tid#SkillDes_10123"]="等级3:该技能至少击中了一名敌人，则之后释放的“勇战八方”的攻击力会提升50%",
	["tid#SkillDes_10124"]="等级4:技能伤害提升至150%攻击力",
	["tid#SkillDes_10131"]="天策选中身前的一名敌人，并强制其与自己决斗5秒。决斗期间，天策对决斗目标造成的伤害提升会提升20%。且除了决斗目标之外，所有处于天策周围的敌军每过2秒都会被施加一层“威慑”状态。“威慑”状态会持续5秒，处于“威慑”状态下的敌人，对天策造成的伤害会减少10%，最多叠加3层",
	["tid#SkillDes_10132"]="等级2:决斗的持续时间提升至8秒",
	["tid#SkillDes_10133"]="等级3:若选中的敌人在决斗时间内阵亡，则天策会增加25%攻击力，持续8秒",
	["tid#SkillDes_10134"]="等级4:若选中的敌人在决斗时间内阵亡，则天策会增加30%攻击力，持续8秒",
	["tid#SkillDes_10141"]="“无双”状态持续期间，所有被天策攻击到的敌人，都会被添加一层“威慑”状态",
	["tid#SkillDes_10142"]="等级2:“无双”状态持续期间，天策击败敌人恢复的内力值提高50%",
	["tid#SkillDes_10143"]="等级3:“威慑”状态现在最多可叠加4层",
	["tid#SkillDes_10144"]="等级4:“威慑”状态现在最多叠加5层",
	["tid#SkillDes_10151"]="天策普通攻击",
	["tid#SkillDes_10211"]="红夷发射信号弹召唤远程炮队,对大范围内敌人造成共计4次内功伤害,每次100%攻击力，该技能会对破甲状态下的敌人造成更多伤害",
	["tid#SkillDes_10212"]="等级2:后续伤害逐次提高",
	["tid#SkillDes_10213"]="等级3:造成伤害的次数提升至5次",
	["tid#SkillDes_10214"]="等级4:对破甲状态下的敌人造成伤害提高",
	["tid#SkillDes_10221"]="红夷的普攻得到强化，造成120%攻击力的范围内功伤害，但每攻击两次之后，需要3秒时间重新装弹。",
	["tid#SkillDes_10222"]="等级2:现在红夷释放3次强化普攻后才会进入冷却",
	["tid#SkillDes_10223"]="等级3:装弹时间缩减为2秒",
	["tid#SkillDes_10224"]="等级4:伤害提升至150%攻击力",
	["tid#SkillDes_10231"]="红夷向敌方后排发射一枚烟雾弹，对范围内的敌人造成65%攻击力的内功伤害，并使其造成的伤害减少20%，持续5秒",
	["tid#SkillDes_10232"]="等级2:伤害提升至80%攻击力",
	["tid#SkillDes_10233"]="等级3:被命中的敌人还会额外减少30点命中",
	["tid#SkillDes_10234"]="等级4:被命中的敌人还会额外减少50点命中",
	["tid#SkillDes_10241"]="红夷造成的所有伤害都有20%的概率为命中的敌人附加1层破甲状态（破甲：防御力降低10%，持续8秒，最多可叠加5层）",
	["tid#SkillDes_10242"]="等级2:触发破甲的概率提升至25%",
	["tid#SkillDes_10243"]="等级3:触发破甲的概率提升至30%",
	["tid#SkillDes_10244"]="等级4:触发破甲的概率提升至40%",
	["tid#SkillDes_10251"]="红夷普攻说明",
	["tid#SkillDes_10311"]="六扇朝天射出8支箭矢，每支箭矢都会攻击一名随机敌方侠客，对其造成110%攻击力的外功伤害",
	["tid#SkillDes_10312"]="等级2:伤害提升至120%攻击力,若攻击的目标被施加了“悬赏”标记，则该技能对其造成的伤害必定暴击",
	["tid#SkillDes_10313"]="等级3:射出的箭矢数量提升至12支",
	["tid#SkillDes_10314"]="等级4:伤害提升至130%攻击力",
	["tid#SkillDes_10321"]="战斗中，每隔15秒，六扇会随机为一名敌军施加“悬赏”标记，持续15秒。悬赏标记会优先选择敌方后排侠客。当被施加了“悬赏”标记的目标被击败时，我方侠客会在5秒内快速回复300点内力。",
	["tid#SkillDes_10322"]="等级2:“悬赏”标记现在会永久持续",
	["tid#SkillDes_10323"]="等级3:被施加了“悬赏”标记的敌方目标，还会受到额外的25%伤害",
	["tid#SkillDes_10324"]="等级4:触发“悬赏”标记的间隔缩短至10秒",
	["tid#SkillDes_10331"]="六扇首次释放“悬赏”标记时，六扇获得30%的攻击力提升，之后每额外释放一次悬赏标记，获得的攻击提升效果便额外提升5%",
	["tid#SkillDes_10332"]="等级2:六扇首次释放“悬赏”标记时，六扇还会额外获得20点攻速提升，之后每额外释放一次悬赏，攻速便额外提升5点",
	["tid#SkillDes_10333"]="等级3:六扇首次释放“悬赏”标记时，六扇还会额外获得10%暴击伤害，之后每额外释放一次悬赏，暴击伤害便额外提升2.5%",
	["tid#SkillDes_10334"]="等级4:六扇首次释放“悬赏”标记时，六扇还会额外获得20%暴击伤害，之后每额外释放一次悬赏，暴击伤害便额外提升5%",
	["tid#SkillDes_10341"]="六扇的普通攻击会额外攻击被标记的敌人，且六扇攻击被“悬赏”标记的敌人时，造成的伤害提升20%",
	["tid#SkillDes_10342"]="等级2:造成的伤害提升至24%",
	["tid#SkillDes_10343"]="等级3:造成的伤害提升至28%",
	["tid#SkillDes_10344"]="等级4:造成的伤害提升至33%",
	["tid#SkillDes_10351"]="六扇普攻说明",
	["tid#SkillDes_10411"]="锦衣掷出锁链，束缚一名敌人3秒并对其造成多段外功伤害，束缚期间，目标无法行动，也无法闪避",
	["tid#SkillDes_10412"]="等级2:束缚时间提高至6秒，且目标将会受到束缚期间锦衣所受伤害50%的额外伤害",
	["tid#SkillDes_10413"]="等级3:束缚期间，锦衣所受伤害的50%将改为由束缚目标承担",
	["tid#SkillDes_10414"]="等级4:天威擒拿造成的多段伤害提高",
	["tid#SkillDes_10421"]="对前方敌人造成130%的外功伤害并使其眩晕2秒。",
	["tid#SkillDes_10422"]="等级2:造成的伤害提升至140%攻击力",
	["tid#SkillDes_10423"]="等级3:造成的伤害提升至150%攻击力",
	["tid#SkillDes_10424"]="等级4:眩晕时间提升至4秒",
	["tid#SkillDes_10431"]="自身攻击范围内没有敌人时，投掷锁链束缚一个敌人并将其拉至身前。该技能会优先选择对位目标",
	["tid#SkillDes_10432"]="等级2:命中后会为敌方附加1层破甲（破甲：防御力降低10%，持续8秒，最多可叠加5层）",
	["tid#SkillDes_10433"]="等级3:命中后额外使敌人造成的伤害降低5%，持续5秒",
	["tid#SkillDes_10434"]="等级4:命中后额外使敌人造成的伤害降低10%，持续5秒",
	["tid#SkillDes_10441"]="自身的普攻伤害提高20%。",
	["tid#SkillDes_10442"]="等级2:对有负面效果的目标额外造成伤害提高30%",
	["tid#SkillDes_10443"]="等级3:对有负面效果的目标额外造成伤害提高40%",
	["tid#SkillDes_10444"]="等级4:对有负面效果的目标额外造成伤害提高50%",
	["tid#SkillDes_10451"]="锦衣普攻说明",
	["tid#SkillDes_10511"]="为所有己方侠客施加一个持续8秒的护盾，抵消相当于自身攻击力500%的伤害",
	["tid#SkillDes_10512"]="等级2:护盾持续期间，己方侠客会缓慢恢复生命值，且护盾的持续时间延长至10秒",
	["tid#SkillDes_10513"]="等级3:护盾值上升至550%攻击力",
	["tid#SkillDes_10514"]="等级4:护盾值上升至600%攻击力",
	["tid#SkillDes_10521"]="少林向前方打出两掌，造成两段，每段80%攻击力的外功伤害，第二段攻击还会击倒敌人",
	["tid#SkillDes_10522"]="等级2:伤害提升至90%攻击力",
	["tid#SkillDes_10523"]="等级3:该技能每击倒一个敌人,少林便获得20%的伤害减免,持续8秒",
	["tid#SkillDes_10524"]="等级4:伤害提升至100%攻击力",
	["tid#SkillDes_10531"]="少林进入防御状态5秒，期间无法攻击和移动且会免疫所有控制效果。防御状态下，少林会获得一个护盾，抵挡相当于自身攻击力80%的伤害，若该护盾在持续时间结束前被打破，则少林会获得30%的减伤效果，持续到防御状态结束。防御期间，若内力积攒完毕，则会立即中断防御状态并释放绝技。",
	["tid#SkillDes_10532"]="等级2:防御期间，少林因受到攻击回复的内力增加200%",
	["tid#SkillDes_10533"]="等级3:护盾值提升至90%攻击力",
	["tid#SkillDes_10534"]="等级4:护盾值提升至110%攻击力",
	["tid#SkillDes_10541"]="战斗中，少林获得的所有护盾值提升10%，当自身存在护盾时，受到的伤害会减少15%",
	["tid#SkillDes_10542"]="等级2:战斗中，少林获得的所有护盾值提升20%",
	["tid#SkillDes_10543"]="等级3:伤害降低的效果提升至20%",
	["tid#SkillDes_10544"]="等级4:伤害降低的效果提升至25%",
	["tid#SkillDes_10551"]="少林普攻说明",
	["tid#SkillDes_10611"]="八卦随机攻击敌人7次，每次造成200%攻击力的外功伤害，技能释放期间自身无敌",
	["tid#SkillDes_10612"]="等级2:该技能释放期间，每次暴击都会增加一次攻击次数，至多增加8次",
	["tid#SkillDes_10613"]="等级3:基础攻击次数提升至9次",
	["tid#SkillDes_10614"]="等级4:造成的伤害提高至250%的攻击力",
	["tid#SkillDes_10621"]="瞬移至目标另一侧，对目标造成120%攻击力伤害并施加一层破甲效果，提升20%暴击率，持续5秒（破甲：防御力降低10%，持续8秒，最多可叠加5层）",
	["tid#SkillDes_10622"]="等级2:使用该技能后，获得相当于自身攻击力100%的护盾，50%闪避，持续5秒",
	["tid#SkillDes_10623"]="等级3:伤害提升至130%攻击力",
	["tid#SkillDes_10624"]="等级4:伤害提升至140%攻击力",
	["tid#SkillDes_10631"]="战斗中，每暴击4次便释放一次该技能。对目标造成多段伤害，最后一击会造成80%攻击力的外功伤害，并额外附加目标10%最大生命值的伤害",
	["tid#SkillDes_10632"]="等级2:最后一击伤害提升至90%攻击力",
	["tid#SkillDes_10633"]="等级3:最后一击附加15%最大生命值伤害",
	["tid#SkillDes_10634"]="等级4:最后一击附加18%最大生命值伤害",
	["tid#SkillDes_10641"]="八卦在攻击被施加了破甲状态的敌人时，暴击概率提升30%，每次暴击时会回复自身6%已损失生命",
	["tid#SkillDes_10642"]="等级2:每次暴击时八卦还会获得25点内力",
	["tid#SkillDes_10643"]="等级3:提高的暴击率提升至40%",
	["tid#SkillDes_10644"]="等级4:提高的暴击率提升至50%",
	["tid#SkillDes_10651"]="八卦普攻说明",
	["tid#SkillDes_10711"]="玄甲举起盾牌进入防御姿态，持续5秒。防御期间自身所受伤害降低50%，且会为身后的队友阻挡所有飞行物",
	["tid#SkillDes_10712"]="等级2:持续时间提升至7秒",
	["tid#SkillDes_10713"]="等级3:持续期间，玄甲每秒恢复已损失生命值的10%",
	["tid#SkillDes_10714"]="等级4:持续期间，自己每秒恢复已损失生命值的12%",
	["tid#SkillDes_10721"]="玄甲使用盾牌猛击身前的敌人，对其造成120%攻击力的外功伤害并使其眩晕2秒",
	["tid#SkillDes_10722"]="等级2:伤害提升至130%攻击力",
	["tid#SkillDes_10723"]="等级3:眩晕结束后该敌人在5秒内造成的伤害下降40%",
	["tid#SkillDes_10724"]="等级4:伤害提升至150%攻击力",
	["tid#SkillDes_10731"]="每场战斗一次,当布阵在后排的友军受到致命伤害时,玄甲会立即跳跃至该友军身边保护其免于阵亡,并在之后10秒内代替该友军承受一切伤害,保护期间自身免疫控制效果（无法为队友承受中毒、裂伤效果）",
	["tid#SkillDes_10732"]="等级2:触发该技能时，玄甲会立刻获得一个相当于自身攻击300%的护盾，持续10秒",
	["tid#SkillDes_10733"]="等级3:保护期间,受到的伤害降低15%",
	["tid#SkillDes_10734"]="等级4:保护期间,受到的伤害降低20%",
	["tid#SkillDes_10741"]="自身近战范围内每存在一个敌人，便获得20%的防御提升，最多提升80%",
	["tid#SkillDes_10742"]="等级2:防御力提升上限提高至100%",
	["tid#SkillDes_10743"]="等级3:自己身边的友军会获得该技能20%的效果",
