	["tid#SkillDes_10751"]="玄甲普攻说明",
	["tid#SkillDes_10811"]="天师门为自身周围的最多三名友军提供补给，使其在后续的4秒内，恢复共计240点内力。释放技能时，若自身存在丹药，则会消耗一个丹药，使恢复的内力翻倍",
	["tid#SkillDes_10812"]="等级2:友军回复的内力提高至400点  ",
	["tid#SkillDes_10813"]="等级3:友军回复的内力提高至500点，且受到该效果的友军还会获得30%的攻击提升，持续5秒     ",
	["tid#SkillDes_10814"]="等级4:受到该效果的友军还会获得35%的攻击提升，持续5秒     ",
	["tid#SkillDes_10821"]="天师门在出场时会携带三个丹药，每当自己累计受到超过最大生命值30%的伤害时，会消耗一个丹药，使自己后续受到的伤害减少100%，持续3秒。",
	["tid#SkillDes_10822"]="等级2:触发该技能后，天师门每秒会恢复已损失生命值的5%，持续3秒  ",
	["tid#SkillDes_10823"]="等级3:每场战斗第一次触发该效果时，将不再消耗丹药",
	["tid#SkillDes_10824"]="等级4:恢复生命值的效果提升提升至8%",
	["tid#SkillDes_10831"]="天师门在我方最虚弱侠客身后召唤一个药鼎，药鼎拥有天师门最大生命值30%的生命值。药鼎在场上存在期间，每秒会为周围的友军恢复40%攻击力的生命值。释放时，若自身存在丹药，则会消耗一个丹药强化药鼎，强化后的药鼎若因敌人的攻击被破坏，会立刻为附近最虚弱的友军恢复其最大生命值的30%",
	["tid#SkillDes_10832"]="等级2:药鼎的持续治疗效果提升至60%攻击力   ",
