	["tid#SkillDes_10921"]="绝张现在总是会优先攻击距离自己最远的敌人，且每重复攻击相同目标一次，便获得一层攻速提升效果，最多叠加5层。每层效果会提升自身10点攻速。该效果会在更换目标时重置",
