	["tid#SkillDes_50311"]="九天每损失相当于自身生命值10%的生命值，便会为一名最虚弱的友军恢复相当于九天攻击力的80%的生命值；释放必杀技时，九天会立即消耗当前生命值的80%转换为等额持续8秒的护盾，之后为自身施加恢复效果，使自己每秒恢复最大生命值的5%，持续10秒",
