	["tid#SkillDes_50314"]="等级4:自身恢复效果提升至12秒",
	["tid#SkillDes_50321"]="九天攻击身前范围内的敌人，对其造成200%攻击力的伤害并使其眩晕1秒，且内力回复在5秒内降低40%",
	["tid#SkillDes_50322"]="等级2:伤害提升至230%攻击力",
