	["tid#SkillDes_50324"]="等级4:伤害提升至250%",
	["tid#SkillDes_50331"]="战斗开始时，若我方除九天以外，存在金木水火阴任意一个阵营的侠客，则九天受到的伤害会减少20%，受到的治疗效果会提升10%，友方每多一个阵营，减伤效果会额外提升5%，受治疗效果额外提升5%，该效果会一直持续至战斗结束，若友方有除九天以外的阳系侠客，则该侠客会同时视为金木水火四个阵营",
	["tid#SkillDes_50332"]="等级2:减伤效果提升至30%",
	["tid#SkillDes_50333"]="等级3:受治疗效果提升至20%",
	["tid#SkillDes_50334"]="等级4:战斗开始时，若己方场上同时存在金木水火四种阵营的侠客，则九天会在战斗中持续恢复生命值，且九天受到致命伤害时,对敌方全体造成150%攻击力的伤害,并使其眩晕2秒,每场战斗最多触发一次",
	["tid#SkillDes_50341"]="为我方每个阵营随机一名侠客施加持续5秒的护盾，为其抵挡100%攻击力的伤害，若上阵的是阳阵营侠客，则该侠客可同时视为金木水火四个阵营",
	["tid#SkillDes_50342"]="等级2:战斗开始时，该技能会立刻释放一次，且护盾值额外提升50%",
	["tid#SkillDes_50343"]="等级3:护盾值提升至130%攻击力",
	["tid#SkillDes_50344"]="等级4:护盾值提升至150%攻击力",
	["tid#SkillDes_50351"]="九天普攻",
	["tid#SkillDes_50411"]="为所有己方角色随机清除一层负面状态并施加“庇佑”效果，被施加了“庇佑”效果的友军，受到的伤害减少25%，且每秒会恢复100%攻击力的生命值，持续8秒(伤害减免效果与恒山的花生万物不叠加)",
