	["tid#SkillDes_50451"]="慈航普攻",
	["tid#SkillDes_50511"]="逍遥瞬移至攻击力最高的敌方后排侠客身前，对其造成200%攻击力的伤害，并使自身进入“逍遥游”状态5秒，该状态下，逍遥的普攻会变为近战范围伤害。进入“逍遥游”状态时，逍遥会立即回满内力且不再减少和增加。“逍遥游”状态下再次释放时，逍遥会消耗所有内力释放“鲲鹏击”，对大范围内的敌人造成200%攻击力的伤害，之后瞬移回原本所在的位置。释放完“鲲鹏击”后，“逍遥游”状态会立即结束",
	["tid#SkillDes_50512"]="等级2:释放“鲲鹏击”时，会附加“逍遥游”期间所造成伤害量30%的额外伤害",
	["tid#SkillDes_50513"]="等级3:“鲲鹏击”伤害提升至220%攻击力",
