	["tid#SkillDes_50521"]="在敌方最密集区域引发范围爆炸，造成180%攻击力的伤害，释放时若自身处于“逍遥游”状态，则爆炸范围变为以自身为中心",
	["tid#SkillDes_50522"]="等级2:自身处于”逍遥游“状态下时，该技能冷却时间降低50%",
	["tid#SkillDes_50523"]="等级3:伤害提升至200%攻击力",
	["tid#SkillDes_50524"]="等级4:伤害提升至220%攻击力",
	["tid#SkillDes_50531"]="战斗开始时，逍遥会立刻获得200点内力,“逍遥游”状态持续期间，逍遥会保留最少1点血量，且不会死亡",
	["tid#SkillDes_50532"]="等级2:战斗开始时，逍遥会立刻获得250点内力,“逍遥游”效果结束时，逍遥会恢复10%最大生命值",
	["tid#SkillDes_50533"]="等级3:战斗开始时，逍遥会立刻获得300点内力,“逍遥游”效果结束时，逍遥会恢复15%最大生命值",
	["tid#SkillDes_50534"]="等级4:战斗开始时，逍遥会立刻获得350点内力,“逍遥游”效果结束时，逍遥会恢复20%最大生命值",
	["tid#SkillDes_50541"]="“逍遥游”状态持续期间，所有被逍遥攻击命中的敌人，都会被施加一层“玄冥”效果，被施加了“玄冥”效果的敌人，受到的治疗效果降低50%，玄冥效果持续5秒，无法叠加",
	["tid#SkillDes_50542"]="等级2:“逍遥游”状态持续期间，逍遥每次攻击和受到攻击，都获得3%的攻击力和防御力提升，该效果最多提升30%的攻击和防御，且会在“逍遥游”状态结束时消失",
	["tid#SkillDes_50543"]="等级3:玄冥效果提升为受到治疗效果降低100%",
