	["tid#SkillDes_50551"]="逍遥普攻",
	["tid#SkillDes_50611"]="主动效果：立即进入“御龙”状态10秒，并立即恢复已损失生命值33%的生命,御龙状态下，天龙会获得33%的伤害减免和50%的伤害提升，且普通攻击会变为范围伤害,'御龙'状态时不可再次释放御龙诀\n被动效果：每普攻一次下一次普攻会得到升级，第一次升级时会对敌人造成打断效果，第二次升级时会降低敌人20%防御，持续5秒，最多叠加2次，两次升级后，普攻升级效果会重置",
