	["tid#SkillDes_50813"]="等级3:释放时若自身枪头少于2个，则该技能会获得强化，造成的伤害会提升100%，若强化后的技能成功击杀了敌人，则会立即恢复5根枪头",
	["tid#SkillDes_50814"]="等级4:伤害提升至400%攻击力,回马枪每消耗一个枪头,恢复自身100%攻击力的血量",
