	["tid#SkillDes_50824"]="等级4:累计收到80%伤害时，最多消耗4个枪头,每消耗1个枪头获得伤害减免20%，持续8秒",
	["tid#SkillDes_50831"]="霸王枪向前扔出长枪，长枪向前旋转并攻击路径上的所有敌人，长枪会在达到最远距离后返回，对敌人造成两段，每段160%攻击力的伤害，释放时若自身拥有“枪头”，则技能的伤害提升20%并提升攻击范围",
