	["tid#SkillDes_50841"]="霸王枪高速旋转长枪攻击周围敌人，对每个敌人造成共计100%攻击力的伤害，旋转期间霸王枪免疫控制，且受到的伤害减少50%，释放时若自身存在“枪头”，则再施展出一记横扫，对身前大范围内的敌人造成200%攻击力的伤害",
