	["tid#SkillDes_60223"]="等级3:我方首个侠客被击败时，邪极还会获得其攻击、防御属性值的20%，一直持续到战斗结束",
	["tid#SkillDes_60224"]="等级4:每层“邪灵”效果获得的伤害提升提高至6%",
	["tid#SkillDes_60231"]="邪极操控傀儡，对前方范围内的所有单位造成200%攻击力的伤害，若当自身的“邪灵”效果累计了2层以上，则该技能的伤害范围会得到提升，当场上有侠客死亡时，邪极会立刻释放一次该技能",
	["tid#SkillDes_60232"]="等级2:释放该技能后，邪极会获得持续5秒的20点加速",
	["tid#SkillDes_60233"]="等级3:当自身的“邪灵”效果累计了5层及以上时，该技能造成的伤害效果额外提升25%",
	["tid#SkillDes_60234"]="等级4:伤害提升至220%攻击力",
	["tid#SkillDes_60241"]="邪极受到致死伤害时，邪极会使用傀儡灵火抵消本次伤害并无敌1秒，之后会恢复自身5%最大血量，每个拥有灵火的傀儡在一场战斗中仅可抵消一次伤害",
	["tid#SkillDes_60242"]="等级2:当“邪灵”层数达到3层时,邪极会额外获得一个傀儡灵火",
	["tid#SkillDes_60243"]="等级3:当“邪灵”层数达到5层时,邪极会额外获得一个傀儡灵火",
	["tid#SkillDes_60244"]="等级4:恢复的血量提升至10%最大血量",
	["tid#SkillDes_60251"]="邪极普攻",
	["tid#SkillDes_60311"]="天山召唤数把飞剑，先将敌人禁锢，随后对其造成7段伤害，前6段每次造成100%攻击力的伤害，最后一段会造成200%攻击力的伤害且必定暴击",
	["tid#SkillDes_60312"]="等级2:若该技能成功击败了敌人，则天山会提升20%的暴击率，持续5秒",
	["tid#SkillDes_60313"]="等级3:最后一击的伤害提升至250%攻击",
	["tid#SkillDes_60314"]="等级4:若该技能成功击败了敌人，则天山会额外获得300点内力",
	["tid#SkillDes_60321"]="战斗开始时，天山会禁锢与自己位置相对的敌人并瞬移至其身后，对其造成300%攻击力的伤害，并使其沉默3秒，本场战斗中，天山总会优先攻击该敌人",
	["tid#SkillDes_60322"]="等级2:伤害提升至350%攻击力",
	["tid#SkillDes_60323"]="等级3:沉默的时间提升至5秒",
	["tid#SkillDes_60324"]="等级4:伤害提升至400%攻击力",
	["tid#SkillDes_60331"]="战斗开始后2秒，天山会飞上天空，期间无法被选为攻击和技能目标。当天山击败了一位敌方侠客后，会落回地面5秒，之后会重新飞回天上。当我方侠客仅剩天山一人时，天山会落回地面，并不再飞回天上。当天山处于天上时，普通攻击会变为召唤飞剑，对敌人造成140%攻击力的伤害",
	["tid#SkillDes_60332"]="等级2:伤害提升至160%攻击力",
	["tid#SkillDes_60333"]="等级3:击败敌人后落地的时间缩短至4秒",
	["tid#SkillDes_60334"]="等级4:伤害提升至180%攻击力",
	["tid#SkillDes_60341"]="战斗中，当天山参与击败了一位敌方侠客后，会获得10%的攻击力和20点攻速提升，该效果会持续到战斗结束",
	["tid#SkillDes_60342"]="等级2:攻击力提升至15%,攻击速度提升至30点",
	["tid#SkillDes_60343"]="等级3:当天山参与击败了3个及3个以上敌方侠客时，会额外获得20点生命吸取，该效果会一直持续到战斗结束",
	["tid#SkillDes_60344"]="等级4:攻击力提升至20%,攻击速度提升至40点",
	["tid#SkillDes_60351"]="天山普攻",
	["tid#SkillDes_60411"]="灵鹫释放寒冰攻击全体敌人造成三次160%攻击力的伤害，且使敌人速度降低40点,持续5秒",
	["tid#SkillDes_60412"]="等级2:冰锥在攻击施加了印记的敌人时，造成的伤害提升20%",
	["tid#SkillDes_60413"]="等级3:伤害提升至180%攻击力",
	["tid#SkillDes_60414"]="等级4:伤害提升至200%攻击力",
	["tid#SkillDes_60421"]="战斗开始后，灵鹫会召唤两条冰犬，冰犬拥有灵鹫30%的属性。之后战斗时间每过去15秒，灵鹫便会重新召唤一条冰犬，若没有冰犬死亡，则灵鹫会重新召唤一条冰犬代替现有的冰犬",
	["tid#SkillDes_60422"]="等级2:冰犬首次死亡时，灵鹫会获得30%的攻击提升，之后每额外死亡一只冰犬，攻击力还会额外提升5%，最多额外提升30%，攻击提升效果会一直持续到战斗结束",
	["tid#SkillDes_60423"]="等级3:冰犬死亡时,降低周围敌方侠客15%攻速,持续8秒",
	["tid#SkillDes_60424"]="等级4:冰犬死亡时,额外对周围敌方侠客附加一个印记,重新召唤冰犬所需的时间缩短至10秒",
	["tid#SkillDes_60431"]="灵鹫为自己和己方召唤单位附加寒冰气息，使其攻击速度提升60点,持续5秒，持续期间每有一个己方召唤单位死亡，攻击速度还会额外提升10点，最多额外提升60点",
	["tid#SkillDes_60432"]="等级2:持续时间提升至8秒",
	["tid#SkillDes_60433"]="等级3:己方阴系队友会获得该技能攻速提升效果的一半",
	["tid#SkillDes_60434"]="等级4:己方阴系队友也会获得相同的攻速提升效果",
	["tid#SkillDes_60441"]="冰犬在攻击目标时会为其附加一个印记，灵鹫的普攻和技能在命中被施加了印记的敌人时，会引爆该印记，使本次伤害必定暴击，且额外附加100%攻击力的真实伤害，同一侠客的每10秒可被引爆一次印记",
	["tid#SkillDes_60442"]="等级2:当灵鹫受到致命伤害时，会立即献祭一条冰犬，使自己无敌2秒，并恢复20%最大生命值的生命，每场战斗仅能触发一次",
	["tid#SkillDes_60443"]="等级3:附加的真实伤害提升至120%攻击力",
	["tid#SkillDes_60444"]="等级4:同一目标的印记触发间隔减少至8秒",
	["tid#SkillDes_60451"]="灵鹫普攻",
	["tid#SkillDes_60511"]="天下会压制一名敌人5秒，压制期间，天下会会持续嘲讽附近敌人并获得15%伤害减免，压制期间，双方都无法攻击和移动。当压制双方的一方受到攻击时，另一方也会受到相同的攻击效果，该技能会优先选择突入我方阵营中的敌方侠客",
	["tid#SkillDes_60512"]="等级2:若敌人在压制期间阵亡，则天下会会立刻恢复15%最大生命值的生命值",
