	["tid#SkillDes_900121"]="进入防御状态5秒，期间自己无法攻击，且受到的伤害减少50%，防御状态受到近战攻击时，对攻击者造成100%自身攻击力的伤害",
	["tid#SkillDes_900131"]="进入防御姿态5秒，期间自己无法攻击，并在身体周围形成一层护盾，护盾可抵御200%自身攻击力的伤害，若防御姿态结束时护盾未被打破，则护盾会爆炸，对周围造成200%攻击力的伤害。",
	["tid#SkillDes_900141"]="玄武之躯：每损失一定的生命值，便叠加一层攻击强化效果，强化效果叠加至10、20、50层时，首领都会陷入8秒的虚弱状态，虚弱状态下，首领受到的伤害增加50%，虚弱状态结束时，首领会获得额外的强化效果：\n10层时：受到的物理伤害减少20%\n20层时：自身受到的物理伤害减少30%；\n50层时：自身受到的物理伤害减少50%，且每次受到物理伤害时会对攻击者造成一次200%攻击力的伤害   ",
