	["tid#SkillDes_900222"]="太阴开场时制造一片永久紫火海，每2.5秒添加1层＂死亡灼烧＂（最多5层），每层＂死亡灼烧＂每秒造成15%攻击力伤害",
	["tid#SkillDes_900223"]="太阴开场时制造一片永久紫火海，每2.5秒添加1层＂死亡灼烧＂（最多5层），每层＂死亡灼烧＂每秒造成15%攻击力伤害",
	["tid#SkillDes_900231"]="强壮的姿态让太阴攻击迟缓，但是强大的威势让太阴的普通攻击波及全部侠客",
