	["tid#RandomLines_4001"]="侠客脚下的箭头会一直\n指向出口位置",
	["tid#RandomLines_4002"]="只有击败挡路的敌人才\n能继续前进",
	["tid#RandomLines_4003"]="找到出口时可以开启本\n层全部地图",
	["tid#RandomLines_4004"]="距离目标地点过远时侠\n客会使用轻功瞬间到达",
	["tid#RandomLines_4005"]="狐仙商人会贩卖强力装备",
	["tid#RandomLines_4006"]="可以雇佣佣兵充实自己\n的战斗力",
	["tid#RandomLines_4007"]="可以使用【碾压】秒杀\n乌合之众",
	["tid#RandomLines_4008"]="当附近有宝箱时侠客头\n上会出现【！】",
	["tid#RandomLines_4009"]="通关闯王宝藏将获得额\n外奖励",
	["tid#RandomLines_4010"]="闯王宝藏每次进入都会\n随机生成地形",
	["tid#FateDes_1"]="九霄龙吟惊天变/n风云际会浅水游",
	["tid#FateDes_109"]="烽火连城今犹在/n埋骨何须寻青山",
	["tid#FateDes_207"]="傲世疏狂缥缈客/n红尘侠胆剑孤魂",
	["tid#FateDes_304"]="霓裳起舞情殇已/n芝心拂渡俏伶人",
	["tid#FateDes_305"]="灵机天罗技终朽/n兼爱非攻义长存",
	["tid#FateDes_406"]="玲珑金雀毒门锁/n暗流沓野寻光明",
	["tid#FateDes_501"]="玄天真武帝星降/n执剑诛魔证凡心",
	["tid#FateDes_502"]="灵光月影魂牵绊/n仙乐避尘济世人",
	["tid#FateDes_506"]="千秋霸业应命起/n十万阎罗为吾生",
	["tid#FateDes_605"]="宇宙千年更帝霸/n万世高歌正乾坤",
	["tid#FateDes_607"]="十年功成山河梦/n一朝回首少年情",
	["tid#FateDes_103"]="凌人盛气明秋毫/n行遍八荒忆乡音",
	["tid#FateDes_106"]="煞影绝灭横刀去/n急行千里难觅形",
	["tid#FateDes_201"]="酒肉桃花谈笑去/n谁道真我不英雄",
	["tid#FateDes_203"]="红尘富贵无牵挂/n逸趣游侠坊市间",
	["tid#FateDes_208"]="红尘一斩青丝尽/n从此空门潜修行",
	["tid#FateDes_310"]="娇心难耐红尘扰/n行云飞絮纵青笙",
	["tid#FateDes_401"]="半生兢业家门破/n云游难平亡妻魂",
	["tid#FateDes_402"]="怡颜蜜口玲珑蝎/n毒引千蝶锈蚀心",
	["tid#FateDes_504"]="炽诚孝心情可鉴/n蓬莱归还慈悲心",
	["tid#FateDes_505"]="莫叹归处无归处/n自是逍遥任逍遥",
	["tid#FateDes_507"]="庙堂夫子离云岛/n凌光剑翼录恩仇",
	["tid#FateDes_508"]="雅资疏朗冰雪性/n任逸不羁万卷荣",
	["tid#FateDes_602"]="芳华梦碎寻净土/n幽途冥助摄人心",
	["tid#FateDes_603"]="悲喜难遂情根浅/n道似难违命定劫",
	["tid#FateDes_604"]="缥缈峰顶缘际运/n冰犬伴盲渡蓬莱",
	["tid#FateDes_606"]="禅心已作沾泥絮/n不逐春风上下狂",
	["tid#FateDes_108"]="商贾丽人处处网/n丹符缠身自在游",
	["tid#FateDes_211"]="星罗棋布盘根错/n一梦沧海已耄耋",
	["tid#FateDes_403"]="神通大力知无敌/n尽逐睚眦流八荒",
	["tid#FateDes_411"]="潇洒坠地生平愿/n不知风雨亦是晴",
	["tid#FateDes_412"]="阴火冷彻寒凌绝/n穷奇千里告乾坤",
	["tid#FateDes_503"]="春生秋雨丰城野/n骤风明觉苍穹狂",
	["tid#FateDes_101"]="燕山胡骑鸣啾啾/n疾驰千山还故乡",
	["tid#FateDes_115"]="剑翎钩爪目如电/n利吻新淬龙泉锋",
	["tid#FateDes_210"]="盲眼镜净无纤瑕/n绕篱欹石自沉音",
	["tid#FateDes_212"]="波澜不惊平心阔/n三清像前叩长生",
	["tid#FateDes_407"]="花开堪折直须折/n莫待无花空折枝",
	["tid#FateDes_410"]="雨垂圣火星楼野/n风度万里逸荣殊",
	["tid#FateDes_701"]="点星剑魄绝鬼气/n赤鸟天翔醒人魂",
	["tid#FateDes_702"]="中皇山晴闻初雪/n绯月寒星云稍轻",
	["tid#FateStarDes_1"]="天生贵胄/n其命<color=#e7c478>紫微</color>",
	["tid#FateStarDes_2"]="千变无常/n其命<color=#e7c478>贪狼</color>",
	["tid#FateStarDes_3"]="暗星中正/n其命<color=#e7c478>巨门</color>",
	["tid#FateStarDes_4"]="独峰孤傲/n其命<color=#e7c478>廉贞</color>",
	["tid#FateStarDes_5"]="坚锋利刃/n其命<color=#e7c478>武曲</color>",
	["tid#FateStarDes_6"]="无惧无畏/n其命<color=#e7c478>破军</color>",
	["tid#FateStarDes_7"]="伤音戮则/n其命<color=#e7c478>七杀</color>",
	["tid#FateStarDes_8"]="文韬武略/n其命<color=#e7c478>天相</color>",
	["tid#FateStarDes_9"]="和润福德/n其命<color=#e7c478>天同</color>",
	["tid#FateStarDes_10"]="大智通慧/n其命<color=#e7c478>天机</color>",
	["tid#FateStarDes_11"]="直善益寿/n其命<color=#e7c478>天梁</color>",
	["tid#FateStarDes_12"]="四方无拘/n其命<color=#e7c478>天府</color>",
	["tid#FateStarDes_13"]="赤胆忠肠/n其命<color=#e7c478>太阳</color>",
	["tid#FateStarDes_14"]="怀谷幽玄/n其命<color=#e7c478>太阴</color>",
	["tid#haogandutips_1"]="好感度等级不足，暂无属性加成",
	["tid#haogandutips_2"]="暂无侠客喜爱的物品",
	["tid#haogandutips_3"]="挂机和参加苗疆觅宝产出\n可赠送给喜欢%s的侠客\n好感度增加%d",
	["tid#haogandutips_4"]="1）将侠客喜爱的物品送给他可以提升好感度；\n2）当好感度等级升级时，侠客属性提升；\n3）随着好感度等级提升，会解锁侠客的部分语音和传记；\n4）获得语音后会在侠客界面随机播放；\n5）当好感度满级时则不能再升级。",
	["tid#haogandutips_5"]="%d级以上增加好感度递减",
	["tid#haogandutips_6"]="缺少该侠客喜爱的礼物",
	["tid#haogandutips_7"]="暂无侠客可赠送",
	["tid#haogandutips_8"]="侠客羁绊系统未开启，需将其提升至%s品阶",
