	["tid#treasure_tips_1"]="升级所需的修炼结晶不足，请提升侠客历史品阶至红以上可获得",
	["tid#treasure_tips_2"]="%s正在被使用",
	["tid#treasure_tips_3"]="1.每个大侠在首次升至红色品阶或以上时都会获得修炼结晶，达到的品阶越高修炼结晶获得越多；\n2.根据大侠的天赋高低获得的修炼结晶数量不等，天赋越高获得的结晶越多，阴阳阵营的大侠因为修行更加困难所以获得的结晶更多；\n3.修炼结晶可用于升级上古遗物；\n4.上古遗物对指定侠客有属性加成，每个上古遗物带来的属性加成不同；\n5.上古遗物每次升级都会提升属性和技能加成。",
	["tid#treasure_des_tips_10101"]="相传为道家宝扇，此扇有七种名贵奇鸟尾翎装点故名七禽，扇骨之上可有无名真人所撰神功心决，时常默读可使内息通达，神功渐成。",
